def solve(observation):
    grid = observation['data']
    n = len(grid)

    # Find valid positions for each row (not blocked and not adjacent diagonally to other stars)
    # We'll use constraint propagation and backtracking with forward checking

    # Precompute valid cells (not black)
    valid = [[grid[r][c] != 'B' for c in range(n)] for r in range(n)]

    # For each row, find columns where a star can be placed
    def get_valid_cols(row, placed_cols, placed_rows):
        """Get valid columns for a star in given row, considering current placements."""
        valid_cols = []
        for c in range(n):
            if not valid[row][c]:
                continue
            if c in placed_cols:
                continue
            # Check diagonal conflicts with existing stars
            conflict = False
            for pr, pc in zip(placed_rows, placed_cols):
                if abs(pr - row) == 1 and abs(pc - c) == 1:  # diagonal adjacency
                    conflict = True
                    break
                if abs(pr - row) <= 1 and abs(pc - c) <= 1:  # any adjacency including diagonal
                    if pr != row or pc != c:
                        if abs(pr - row) <= 1 and abs(pc - c) <= 1:
                            # Check if they touch (including diagonally)
                            if max(abs(pr - row), abs(pc - c)) == 1:
                                conflict = True
                                break
            if not conflict:
                valid_cols.append(c)
        return valid_cols

    # Constraint propagation: find forced placements
    def propagate(remaining_rows, available_cols, placed_rows, placed_cols):
        """Apply constraint propagation to find forced moves."""
        changed = True
        while changed:
            changed = False
            # For each remaining row, check if only one valid column
            for r in list(remaining_rows):
                valid_cols = []
                for c in available_cols:
                    if not valid[r][c]:
                        continue
                    # Check diagonal conflicts with placed stars
                    conflict = False
                    for pr, pc in zip(placed_rows, placed_cols):
                        if max(abs(pr - r), abs(pc - c)) == 1:  # adjacent including diagonal
                            conflict = True
                            break
                    if not conflict:
                        valid_cols.append(c)

                if len(valid_cols) == 0:
                    return None  # No valid placement
                if len(valid_cols) == 1:
                    # Forced placement
                    c = valid_cols[0]
                    # Check this doesn't create conflicts
                    for pr, pc in zip(placed_rows, placed_cols):
                        if max(abs(pr - r), abs(pc - c)) == 1:
                            return None

                    placed_rows = placed_rows + (r,)
                    placed_cols = placed_cols + (c,)
                    remaining_rows = remaining_rows - {r}
                    available_cols = available_cols - {c}
                    changed = True
                    break

            # Check columns too (each column needs exactly one star)
            for c in list(available_cols):
                valid_rows = []
                for r in remaining_rows:
                    if not valid[r][c]:
                        continue
                    conflict = False
                    for pr, pc in zip(placed_rows, placed_cols):
                        if max(abs(pr - r), abs(pc - c)) == 1:
                            conflict = True
                            break
                    if not conflict:
                        valid_rows.append(r)

                if len(valid_rows) == 0:
                    return None
                if len(valid_rows) == 1:
                    r = valid_rows[0]
                    for pr, pc in zip(placed_rows, placed_cols):
                        if max(abs(pr - r), abs(pc - c)) == 1:
                            return None

                    placed_rows = placed_rows + (r,)
                    placed_cols = placed_cols + (c,)
                    remaining_rows = remaining_rows - {r}
                    available_cols = available_cols - {c}
                    changed = True
                    break

        return (remaining_rows, available_cols, placed_rows, placed_cols)

    # Backtracking solver with constraint propagation
    def backtrack(remaining_rows, available_cols, placed_rows, placed_cols):
        if not remaining_rows:
            return (placed_rows, placed_cols)

        # Apply constraint propagation
        result = propagate(remaining_rows, available_cols, placed_rows, placed_cols)
        if result is None:
            return None

        rem_rows, av_cols, pl_rows, pl_cols = result

        if not rem_rows:
            return (pl_rows, pl_cols)

        # Choose row with minimum remaining values (MRV heuristic)
        best_row = None
        best_options = None
        best_count = float('inf')

        for r in rem_rows:
            options = []
            for c in av_cols:
                if not valid[r][c]:
                    continue
                conflict = False
                for pr, pc in zip(pl_rows, pl_cols):
                    if max(abs(pr - r), abs(pc - c)) == 1:
                        conflict = True
                        break
                if not conflict:
                    options.append(c)

            if len(options) < best_count:
                best_count = len(options)
                best_row = r
                best_options = options
                if best_count == 0:
                    return None

        if best_count == 0:
            return None

        # Try each option
        for c in best_options:
            new_pl_rows = pl_rows + (best_row,)
            new_pl_cols = pl_cols + (c,)
            new_rem_rows = rem_rows - {best_row}
            new_av_cols = av_cols - {c}

            result = backtrack(new_rem_rows, new_av_cols, new_pl_rows, new_pl_cols)
            if result is not None:
                return result

        return None

    # Start solving
    all_rows = set(range(n))
    all_cols = set(range(n))

    solution = backtrack(all_rows, all_cols, (), ())

    if solution is None:
        return "No Solution"

    rows, cols = solution

    # Build result grid
    result = [[None for _ in range(n)] for _ in range(n)]
    for r, c in zip(rows, cols):
        result[r][c] = 'S'

    return result

