        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbors.append((nr, nc))
        return neighbors

    # For each numbered cell, track its unknown neighbors
    num_neighbors = {}  # (r,c) -> list of unknown neighbors
    for r, c, val in numbered:
        num_neighbors[(r, c)] = [n for n in get_neighbors(r, c) if n in unknown]

    # Initialize state: mines and safe cells
    mines = set()
    safe = set()  # unknown cells that are definitely not mines

    # Constraint propagation
    changed = True
    while changed:
        changed = False

        for r, c, val in numbered:
            if (r, c) not in num_neighbors:
                continue

            unk = [n for n in num_neighbors[(r, c)] if n not in mines and n not in safe]
            already_mines = len([n for n in num_neighbors[(r, c)] if n in mines])
            remaining = val - already_mines

            # If remaining == 0, all unknown are safe
            if remaining == 0:
                for n in unk:
                    if n not in safe:
                        safe.add(n)
                        changed = True

            # If remaining == len(unk), all unknown are mines
            elif remaining == len(unk) and remaining > 0:
                for n in unk:
                    if n not in mines:
                        mines.add(n)
                        changed = True

            # If remaining < 0 or remaining > len(unk), contradiction
            if remaining < 0 or remaining > len(unk):
                return "No Solution"

    # Check if all numbered cells are satisfied
    def is_satisfied():
        for r, c, val in numbered:
            cnt = sum(1 for n in get_neighbors(r, c) if n in mines)
            if cnt != val:
