        return True

    # If satisfied and no unknowns left, we're done
    remaining_unknown = unknown - mines - safe
    if len(remaining_unknown) == 0:
        if is_satisfied():
            return format_result(mines, rows, cols)
        else:
            return "No Solution"

    # Need to search on remaining unknowns
    # Sort by constraint tightness for efficiency
    remaining_list = sorted(remaining_unknown, key=lambda x: len([n for n in get_neighbors(x[0], x[1]) 
                                                                  if (n[0], n[1]) in [(nr, nc) for nr, nc, _ in numbered]]), reverse=True)

    # Backtracking search with constraint checking
    def backtrack(idx, current_mines, current_safe):
        if idx == len(remaining_list):
            # Check all constraints
            for r, c, val in numbered:
                cnt = sum(1 for n in get_neighbors(r, c) if n in current_mines or n in mines)
                if cnt != val:
                    return None
            return current_mines

        cell = remaining_list[idx]

        # Try mine
        new_mines = set(current_mines)
        new_mines.add(cell)

        # Check constraints early
        valid = True
        for r, c, val in numbered:
            unk_neighbors = [n for n in num_neighbors.get((r, c), []) if n not in mines and n not in safe]
            mine_neighbors = [n for n in unk_neighbors if n in new_mines]
            remaining_neighbors = [n for n in unk_neighbors if n not in new_mines and n not in current_safe]

            already = len([n for n in get_neighbors(r, c) if n in mines]) + len(mine_neighbors)
            if already > val:
                valid = False
                break
            # If even if all remaining are mines, can't reach val
            if already + len(remaining_neighbors) < val:
                valid = False
                break

        if valid:
            result = backtrack(idx + 1, new_mines, current_safe)
            if result is not None:
                return result

        # Try safe
        new_safe = set(current_safe)
        new_safe.add(cell)

        valid = True
        for r, c, val in numbered:
            unk_neighbors = [n for n in num_neighbors.get((r, c), []) if n not in mines and n not in safe]
            mine_neighbors = [n for n in unk_neighbors if n in new_mines]
            remaining_neighbors = [n for n in unk_neighbors if n not in new_mines and n not in new_safe]

            already = len([n for n in get_neighbors(r, c) if n in mines]) + len(mine_neighbors)
            if already > val:
                valid = False
                break
            if already + len(remaining_neighbors) < val:
                valid = False
                break

        if valid:
            result = backtrack(idx + 1, current_mines, new_safe)
            if result is not None:
                return result

        return None

    result = backtrack(0, set(), set())
    if result is None:
