    final_mines = mines | result
    return format_result(final_mines, rows, cols)

def format_result(mines, rows, cols):
    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if (r, c) in mines:
                row.append('F')
            else:
                row.append(None)
