from collections import deque

def solve(observation):
    grid = observation['data']
    n = len(grid)

    # Initialize with clues
    colors = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] is not None:
                colors[r][c] = grid[r][c]

    # Precompute neighbors
    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    # Check 2x2 constraint
    def check_2x2(colors):
        for r in range(n-1):
            for c in range(n-1):
                cells = [colors[r][c], colors[r][c+1], colors[r+1][c], colors[r+1][c+1]]
                if None not in cells:
                    if all(x == 'B' for x in cells) or all(x == 'W' for x in cells):
                        return False
        return True

    # Check if current partial state can satisfy 2x2
    def valid_partial(colors):
        for r in range(n-1):
            for c in range(n-1):
                cells = [colors[r][c], colors[r][c+1], colors[r+1][c], colors[r+1][c+1]]
                non_none = [x for x in cells if x is not None]
                if len(non_none) == 4:
                    if all(x == 'B' for x in non_none) or all(x == 'W' for x in non_none):
                        return False
                # Early pruning: if 3 same colors and 1 unknown, the unknown must be different
                if len(non_none) == 3:
                    if all(x == 'B' for x in non_none):
                        # The None must be W, but we can't set it yet, just check consistency
                        pass
        return True

    # Find connected components using BFS
    def get_component(colors, start_r, start_c, color):
        if colors[start_r][start_c] != color:
            return set()
        visited = set()
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        while queue:
            r, c = queue.popleft()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and colors[nr][nc] == color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return visited

    # Check connectivity constraint (all filled cells of each color must be connected)
    def check_connectivity(colors):
        black_cells = [(r, c) for r in range(n) for c in range(n) if colors[r][c] == 'B']
        white_cells = [(r, c) for r in range(n) for c in range(n) if colors[r][c] == 'W']

        if len(black_cells) > 0:
            comp = get_component(colors, black_cells[0][0], black_cells[0][1], 'B')
            if len(comp) != len(black_cells):
                return False

        if len(white_cells) > 0:
            comp = get_component(colors, white_cells[0][0], white_cells[0][1], 'W')
            if len(comp) != len(white_cells):
                return False

        return True

    # Check if a color can reach all cells of that color (for partial check)
    def can_reach_all(colors, color):
        cells = [(r, c) for r in range(n) for c in range(n) if colors[r][c] == color]
        if len(cells) <= 1:
            return True
        # BFS from first cell, can pass through same color or None (potential same color)
        visited = set()
        queue = deque([cells[0]])
        visited.add(cells[0])
        while queue:
            r, c = queue.popleft()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and colors[nr][nc] in (color, None):
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        # Check if all color cells are reachable
        return all((r, c) in visited for r, c in cells)

    # Check if partial state is potentially valid
    def is_valid_partial(colors):
        if not valid_partial(colors):
            return False
        # Quick connectivity check: each color's cells must be potentially connected
        if not can_reach_all(colors, 'B'):
            return False
        if not can_reach_all(colors, 'W'):
            return False
        return True

    # Check if complete solution is valid
    def is_complete_valid(colors):
        if not check_2x2(colors):
            return False
        if not check_connectivity(colors):
            return False
        return True

    # Find empty cell
    def find_empty(colors):
        for r in range(n):
            for c in range(n):
                if colors[r][c] is None:
                    return r, c
        return None

    # Constraint propagation: deduce forced moves
    def propagate(colors):
        changed = True
        while changed:
            changed = False
            for r in range(n):
                for c in range(n):
                    if colors[r][c] is not None:
                        continue

                    # Try both colors and see which are valid
                    valid_colors = []
                    for test_color in ['B', 'W']:
                        colors[r][c] = test_color
                        if is_valid_partial(colors):
                            valid_colors.append(test_color)
                        colors[r][c] = None

                    if len(valid_colors) == 0:
                        return False  # Contradiction
                    if len(valid_colors) == 1:
                        colors[r][c] = valid_colors[0]
                        changed = True
        return True

    # Main solver with backtracking
    def backtrack(colors):
        # Propagate constraints first
        colors_copy = [row[:] for row in colors]
        if not propagate(colors_copy):
            return None

        empty = find_empty(colors_copy)
        if empty is None:
            # Complete
            if is_complete_valid(colors_copy):
                return colors_copy
            return None

        r, c = empty

        # Try both colors, prefer the one that appears more constrained
        for color in ['B', 'W']:
            colors_copy[r][c] = color
            if is_valid_partial(colors_copy):
                result = backtrack(colors_copy)
                if result is not None:
                    return result
            colors_copy[r][c] = None

        return None

    result = backtrack(colors)
    if result is None:
        return "No Solution"
    return result

