OBSERVATION = {'data': [[None, None, None, None], [2, None, None, None], [None, None, None, None], [None, None, None, None]], 'adjacent': [[0.0, 0.5], [0.0, 2.5], [0.5, 0.0], [0.5, 2.0], [1.0, 1.5], [1.5, 1.0], [1.5, 3.0], [2.0, 0.5], [2.0, 2.5], [2.5, 0.0], [2.5, 2.0], [3.0, 1.5]]}

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    n = len(data)

    # Parse adjacency constraints
    # horizontal_adj[r][c] = True if dot between (r,c) and (r,c+1)
    # vertical_adj[r][c] = True if dot between (r,c) and (r+1,c)
    horizontal_adj = [[False] * (n-1) for _ in range(n)]
    vertical_adj = [[False] * n for _ in range(n-1)]

    for coord in adjacent:
        r, c = coord
        if r == int(r):  # horizontal gap: (row, col+0.5)
            row = int(r)
            col = int(c - 0.5)
            if 0 <= row < n and 0 <= col < n-1:
                horizontal_adj[row][col] = True
        else:  # vertical gap: (row+0.5, col)
            row = int(r - 0.5)
            col = int(c)
            if 0 <= row < n-1 and 0 <= col < n:
                vertical_adj[row][col] = True

    # Initialize domains: possible values for each cell
    domains = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    # Apply given clues
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def get_neighbors(r, c):
        """Get all orthogonal neighbors with their adjacency constraint"""
        neighbors = []
        # Up
        if r > 0:
            is_adj = vertical_adj[r-1][c]
            neighbors.append((r-1, c, is_adj))
        # Down
        if r < n-1:
            is_adj = vertical_adj[r][c]
            neighbors.append((r+1, c, is_adj))
        # Left
        if c > 0:
            is_adj = horizontal_adj[r][c-1]
            neighbors.append((r, c-1, is_adj))
        # Right
        if c < n-1:
            is_adj = horizontal_adj[r][c]
            neighbors.append((r, c+1, is_adj))
        return neighbors

    def propagate(domains):
        """Constraint propagation using AC-3 style algorithm"""
        changed = True
        while changed:
            changed = False

            for r in range(n):
                for c in range(n):
                    if len(domains[r][c]) == 0:
                        return False  # Contradiction

                    for nr, nc, is_adj in get_neighbors(r, c):
                        # Constraint: if adjacent cells, values must be consecutive
                        # if not adjacent, values must NOT be consecutive
                        new_domain = set()
                        for v in domains[r][c]:
                            valid = False
                            for nv in domains[nr][nc]:
                                diff = abs(v - nv)
                                if is_adj:
                                    if diff == 1:
                                        valid = True
                                        break
                                else:
                                    if diff != 1:
                                        valid = True
                                        break
                            if valid:
                                new_domain.add(v)

                        if len(new_domain) < len(domains[r][c]):
                            domains[r][c] = new_domain
                            changed = True
                            if len(new_domain) == 0:
                                return False

            # Row/column uniqueness constraints (Latin square)
            for r in range(n):
                # If a value is fixed in a row, remove from others
                fixed = [(c, list(domains[r][c])[0]) for c in range(n) if len(domains[r][c]) == 1]
                for c, val in fixed:
                    for oc in range(n):
                        if oc != c and val in domains[r][oc]:
                            if len(domains[r][oc]) == 1:
                                return False
                            domains[r][oc].discard(val)
                            changed = True

            for c in range(n):
                # If a value is fixed in a column, remove from others
                fixed = [(r, list(domains[r][c])[0]) for r in range(n) if len(domains[r][c]) == 1]
                for r, val in fixed:
                    for or_ in range(n):
                        if or_ != r and val in domains[or_][c]:
                            if len(domains[or_][c]) == 1:
                                return False
                            domains[or_][c].discard(val)
                            changed = True

        return True

    def copy_domains(d):
        return [[set(cell) for cell in row] for row in d]

    def is_complete(d):
        return all(len(d[r][c]) == 1 for r in range(n) for c in range(n))

    def get_solution(d):
        return [[list(d[r][c])[0] for c in range(n)] for r in range(n)]

    def select_unassigned(d):
        # MRV heuristic: select cell with smallest domain > 1
        min_size = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                size = len(d[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best = (r, c)
        return best

    def check_consistency(d):
        # Check all constraints are satisfied for assigned cells
        for r in range(n):
            for c in range(n):
                if len(d[r][c]) != 1:
                    continue
                v = list(d[r][c])[0]
                for nr, nc, is_adj in get_neighbors(r, c):
                    if len(d[nr][nc]) != 1:
                        continue
                    nv = list(d[nr][nc])[0]
                    diff = abs(v - nv)
                    if is_adj and diff != 1:
                        return False
                    if not is_adj and diff == 1:
                        return False

        # Check no duplicates in rows/columns for assigned cells
        for r in range(n):
            seen = set()
            for c in range(n):
                if len(d[r][c]) == 1:
                    v = list(d[r][c])[0]
                    if v in seen:
                        return False
                    seen.add(v)

        for c in range(n):
            seen = set()
            for r in range(n):
                if len(d[r][c]) == 1:
                    v = list(d[r][c])[0]
                    if v in seen:
                        return False
                    seen.add(v)

        return True

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    # Backtracking search
    def backtrack(d):
        if is_complete(d):
            return get_solution(d)

        var = select_unassigned(d)
        if var is None:
            return None

        r, c = var

        # Try values in order
        for val in sorted(d[r][c]):
            new_d = copy_domains(d)
            new_d[r][c] = {val}

            if not propagate(new_d):
                continue

            if not check_consistency(new_d):
                continue

            result = backtrack(new_d)
            if result is not None:
                return result

        return None

    result = backtrack(domains)
    if result is None:
        return "No Solution"
    return result

