def solve(observation):
    data = observation['data']
    n = len(data)

    # Initialize grid with known values
    grid = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            grid[r][c] = data[r][c]

    # Helper functions
    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < n

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc):
                yield (nr, nc)

    def check_2x2(grid, r, c, color):
        """Check if placing color at (r,c) creates invalid 2x2"""
        # Check all 2x2 squares containing (r,c)
        for dr in [0, -1]:
            for dc in [0, -1]:
                tr, tc = r + dr, c + dc
                if tr < 0 or tc < 0 or tr + 1 >= n or tc + 1 >= n:
                    continue
                cells = [(tr, tc), (tr, tc+1), (tr+1, tc), (tr+1, tc+1)]
                colors = []
                for cr, cc in cells:
                    if cr == r and cc == c:
                        colors.append(color)
                    else:
                        colors.append(grid[cr][cc])
                if all(c == 'B' for c in colors) or all(c == 'W' for c in colors):
                    return False
        return True

    def count_component(grid, start_r, start_c, target_color):
        """Count size of connected component"""
        if grid[start_r][start_c] != target_color:
            return 0
        visited = set()
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        while queue:
            r, c = queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == target_color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited)

    def is_connected(grid, color):
        """Check if all cells of given color form one connected component"""
        cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
        if len(cells) <= 1:
            return True
        visited = set()
        queue = deque([cells[0]])
        visited.add(cells[0])
        while queue:
            r, c = queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == len(cells)

    def is_valid_partial(grid):
        """Check if current partial grid can still lead to valid solution"""
        # Check no invalid 2x2 formed by known cells
        for r in range(n-1):
            for c in range(n-1):
                cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                vals = [grid[cr][cc] for cr, cc in cells]
                if all(v == 'B' for v in vals if v is not None):
                    if sum(1 for v in vals if v is not None) == 4:
                        return False
                if all(v == 'W' for v in vals if v is not None):
                    if sum(1 for v in vals if v is not None) == 4:
                        return False

        # Check connectivity constraints for partial grid
        # Black cells must be potentially connected
        black_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 'B']
        if len(black_cells) > 0:
            # Check if black cells are in same component ignoring unknowns
            visited = set()
            queue = deque([black_cells[0]])
            visited.add(black_cells[0])
            while queue:
                r, c = queue.popleft()
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in visited and grid[nr][nc] != 'W':
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            for r, c in black_cells:
                if (r, c) not in visited:
                    return False

        # White cells must be potentially connected
        white_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 'W']
        if len(white_cells) > 0:
            visited = set()
            queue = deque([white_cells[0]])
            visited.add(white_cells[0])
            while queue:
                r, c = queue.popleft()
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in visited and grid[nr][nc] != 'B':
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            for r, c in white_cells:
                if (r, c) not in visited:
                    return False

        return True

    def is_complete_valid(grid):
        """Check if complete grid satisfies all constraints"""
        # All cells filled
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    return False

        # No 2x2 monochromatic
        for r in range(n-1):
            for c in range(n-1):
                cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                vals = [grid[cr][cc] for cr, cc in cells]
                if all(v == 'B' for v in vals) or all(v == 'W' for v in vals):
                    return False

        # Both colors connected
        if not is_connected(grid, 'B'):
            return False
        if not is_connected(grid, 'W'):
            return False

        return True

    def copy_grid(grid):
        return [row[:] for row in grid]

    # Constraint propagation: deduce forced cells
    def propagate(grid):
        changed = True
        while changed:
            changed = False
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is not None:
                        continue

                    # Try both colors
                    valid_b = check_2x2(grid, r, c, 'B')
                    valid_w = check_2x2(grid, r, c, 'W')

                    if valid_b and not valid_w:
                        grid[r][c] = 'B'
                        changed = True
                    elif valid_w and not valid_b:
                        grid[r][c] = 'W'
                        changed = True

            # Check for cells forced by connectivity
            # If a region is isolated, fill the gap
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is not None:
                        continue

                    # Check if this cell bridges black components
                    grid[r][c] = 'W'
                    black_ok_w = is_valid_partial(grid)
                    grid[r][c] = 'B'
                    black_ok_b = is_valid_partial(grid)
                    grid[r][c] = None

                    if black_ok_b and not black_ok_w:
                        grid[r][c] = 'B'
                        changed = True
                    elif black_ok_w and not black_ok_b:
                        grid[r][c] = 'W'
                        changed = True

        return grid

    # Main solving with backtracking
    def solve_recursive(grid):
        # Propagate constraints
        grid = propagate(copy_grid(grid))

        if not is_valid_partial(grid):
            return None

        if is_complete_valid(grid):
            return grid

        # Find next unassigned cell with minimum remaining values
        best_cell = None
        best_options = []
        for r in range(n):
            for c in range(n):
                if grid[r][c] is not None:
                    continue

                options = []
                for color in ['B', 'W']:
                    if check_2x2(grid, r, c, color):
                        grid[r][c] = color
                        if is_valid_partial(grid):
                            options.append(color)
                        grid[r][c] = None

                if len(options) == 0:
                    return None

                if best_cell is None or len(options) < len(best_options):
                    best_cell = (r, c)
                    best_options = options
                    if len(options) == 1:
                        break
            if best_cell and len(best_options) == 1:
                break

        if best_cell is None:
            return None

        r, c = best_cell
        for color in best_options:
            new_grid = copy_grid(grid)
            new_grid[r][c] = color
            result = solve_recursive(new_grid)
            if result is not None:
                return result

        return None

    result = solve_recursive(grid)
    if result is None:
        return "No Solution"

    return result

