from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)

    # Initialize grid: 0=unknown, 1=black, 2=white
    grid = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] == 'B':
                grid[r][c] = 1
            elif data[r][c] == 'W':
                grid[r][c] = 2

    # Precompute neighbors
    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    # Check 2x2 constraint
    def check_2x2(gr):
        for r in range(n-1):
            for c in range(n-1):
                cells = [gr[r][c], gr[r+1][c], gr[r][c+1], gr[r+1][c+1]]
                if 0 not in cells:
                    if all(x==1 for x in cells) or all(x==2 for x in cells):
                        return False
        return True

    # Check if color can be placed without violating 2x2
    def can_place(gr, r, c, color):
        gr[r][c] = color
        res = check_2x2(gr)
        gr[r][c] = 0
        return res

    # Find connected components using BFS
    def get_components(gr, color):
        visited = [[False]*n for _ in range(n)]
        comps = []
        for r in range(n):
            for c in range(n):
                if gr[r][c] == color and not visited[r][c]:
                    q = deque([(r,c)])
                    visited[r][c] = True
                    comp = [(r,c)]
                    while q:
                        cr, cc = q.popleft()
                        for nr, nc in neighbors(cr, cc):
                            if gr[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr,nc))
                                comp.append((nr,nc))
                    comps.append(comp)
        return comps

    # Check connectivity constraint: all of a color must be connected
    def check_connectivity(gr):
        black_cells = [(r,c) for r in range(n) for c in range(n) if gr[r][c]==1]
        white_cells = [(r,c) for r in range(n) for c in range(n) if gr[r][c]==2]

        if len(black_cells) > 0:
            comps = get_components(gr, 1)
            if len(comps) > 1:
                return False
        if len(white_cells) > 0:
            comps = get_components(gr, 2)
            if len(comps) > 1:
                return False
        return True

    # Check if current state can possibly satisfy connectivity (no isolated forced cells)
    def check_possible_connectivity(gr):
        # For each color, check that all known cells can potentially connect
        # through unknown cells
        for color in [1, 2]:
            # BFS from first known cell of this color
            start = None
            for r in range(n):
                for c in range(n):
                    if gr[r][c] == color:
                        start = (r,c)
                        break
                if start:
                    break

            if not start:
                continue

            # Can all cells of this color reach each other through cells that are
            # either this color or unknown?
            visited = [[False]*n for _ in range(n)]
            q = deque([start])
            visited[start[0]][start[1]] = True

            while q:
                r, c = q.popleft()
                for nr, nc in neighbors(r, c):
                    if not visited[nr][nc] and gr[nr][nc] in (0, color):
                        visited[nr][nc] = True
                        q.append((nr,nc))

            # Check all cells of this color are visited
            for r in range(n):
                for c in range(n):
                    if gr[r][c] == color and not visited[r][c]:
                        return False
        return True

    # Constraint propagation: deduce forced cells
    def propagate(gr):
        changed = True
        while changed:
            changed = False

            # Rule 1: 2x2 with 3 same color forces 4th
            for r in range(n-1):
                for c in range(n-1):
                    cells = [(r,c), (r+1,c), (r,c+1), (r+1,c+1)]
                    vals = [gr[x][y] for x,y in cells]
                    if vals.count(1) == 3 and vals.count(0) == 1:
                        idx = vals.index(0)
                        rr, cc = cells[idx]
                        gr[rr][cc] = 2
                        changed = True
                    elif vals.count(2) == 3 and vals.count(0) == 1:
                        idx = vals.index(0)
                        rr, cc = cells[idx]
                        gr[rr][cc] = 1
                        changed = True

            # Rule 2: check for cells that would isolate a color
            for r in range(n):
                for c in range(n):
                    if gr[r][c] != 0:
                        continue
                    # Try both colors, see which violates constraints
                    can_black = can_place(gr, r, c, 1)
                    can_white = can_place(gr, r, c, 2)

                    if can_black and not can_white:
                        gr[r][c] = 1
                        changed = True
                    elif can_white and not can_black:
                        gr[r][c] = 2
                        changed = True
                    elif not can_black and not can_white:
                        return False  # contradiction

            # Rule 3: connectivity check - if placing a color disconnects, forbid it
            if not changed:
                for r in range(n):
                    for c in range(n):
                        if gr[r][c] != 0:
                            continue

                        # Test black
                        valid_black = True
                        if can_place(gr, r, c, 1):
                            gr[r][c] = 1
                            if not check_possible_connectivity(gr):
                                valid_black = False
                            gr[r][c] = 0
                        else:
                            valid_black = False

                        # Test white
                        valid_white = True
                        if can_place(gr, r, c, 2):
                            gr[r][c] = 2
                            if not check_possible_connectivity(gr):
                                valid_white = False
                            gr[r][c] = 0
                        else:
                            valid_white = False

                        if valid_black and not valid_white:
                            gr[r][c] = 1
                            changed = True
                        elif valid_white and not valid_black:
                            gr[r][c] = 2
                            changed = True
                        elif not valid_black and not valid_white:
                            return False

        return True

    # Main solver with backtracking
    def solve_recursive(gr):
        # Propagate constraints
        gr_copy = [row[:] for row in gr]
        if not propagate(gr_copy):
            return None

        # Check if solved
        complete = True
        for r in range(n):
            for c in range(n):
                if gr_copy[r][c] == 0:
                    complete = False
                    break
            if not complete:
                break

        if complete:
            if check_connectivity(gr_copy) and check_2x2(gr_copy):
                return gr_copy
            return None

        # Find best cell to branch (minimum remaining values)
        best_r, best_c = -1, -1
        best_score = float('inf')

        for r in range(n):
            for c in range(n):
                if gr_copy[r][c] != 0:
                    continue

                # Count valid options
                options = 0
                for color in [1, 2]:
                    if can_place(gr_copy, r, c, color):
                        gr_copy[r][c] = color
                        if check_possible_connectivity(gr_copy):
                            options += 1
                        gr_copy[r][c] = 0

                if options < best_score:
                    best_score = options
                    best_r, best_c = r, c
                    if options == 0:
                        return None

        if best_score == 0:
            return None

        # Try colors
        for color in [1, 2]:
            if not can_place(gr_copy, best_r, best_c, color):
                continue

            gr_copy[best_r][best_c] = color
            if not check_possible_connectivity(gr_copy):
                gr_copy[best_r][best_c] = 0
                continue

            gr_copy[best_r][best_c] = 0  # reset for recursive call

            new_gr = [row[:] for row in gr_copy]
            new_gr[best_r][best_c] = color

            result = solve_recursive(new_gr)
            if result is not None:
                return result

        return None

    result = solve_recursive(grid)

    if result is None:
        return "No Solution"

    # Convert to output format
    output = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if result[r][c] == 1 else 'W')
        output.append(row)

    return output

