    # stars[r] = column where star is placed in row r, or -1 if not placed
    stars = [-1] * n

    def get_blocked_cells(r, c):
        """Get all cells blocked by placing a star at (r,c) - includes diagonals"""
        blocked = set()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    blocked.add((nr, nc))
        return blocked

    def propagate():
        """Constraint propagation: apply logical deductions"""
        changed = True
        while changed:
            changed = False

            # Rule 1: If a row has only 1 possible column, place it
            for r in range(n):
                if stars[r] == -1 and len(row_possible[r]) == 1:
                    c = next(iter(row_possible[r]))
                    if not place_star(r, c):
                        return False
                    changed = True

            # Rule 2: If a column has only 1 possible row, place it
            for c in range(n):
                if len(col_possible[c]) == 1:
                    r = next(iter(col_possible[c]))
                    if stars[r] == -1:
                        if not place_star(r, c):
                            return False
                        changed = True

            # Rule 3: If a row has no possible columns, fail
            for r in range(n):
                if stars[r] == -1 and len(row_possible[r]) == 0:
                    return False

            # Rule 4: If a column has no possible rows, fail
            for c in range(n):
                if len(col_possible[c]) == 0:
                    return False

        return True

    def place_star(r, c):
        """Place a star at (r,c) and update constraints"""
        if stars[r] != -1:
            return stars[r] == c

        # Check if position is still valid
        if c not in row_possible[r] or r not in col_possible[c]:
            return False

        stars[r] = c

        # Remove this column from all other rows
        for other_r in range(n):
            if other_r != r and c in row_possible[other_r]:
                row_possible[other_r].discard(c)

        # Remove this row from all other columns
        for other_c in range(n):
            if other_c != c and r in col_possible[other_c]:
                col_possible[other_c].discard(r)

        # Clear this row and column's possibilities (except the placed star)
        row_possible[r] = {c}
        col_possible[c] = {r}

        # Block adjacent cells (including diagonals)
        blocked = get_blocked_cells(r, c)
        for br, bc in blocked:
            if br != r or bc != c:  # Don't block the star itself
                if bc in row_possible[br]:
                    row_possible[br].discard(bc)
                if br in col_possible[bc]:
                    col_possible[bc].discard(br)

