                    best_r = r
        return best_r, min_options

    def search():
        """Backtracking search with constraint propagation"""
        # Check if complete
        if all(s != -1 for s in stars):
            return True

        # Select most constrained row
        r, num_options = select_most_constrained_row()
        if r == -1:
            return True
        if num_options == 0:
            return False

        # Try each possible column for this row
        # Sort by constraint (fewest options in column)
        cols = sorted(row_possible[r], key=lambda c: len(col_possible[c]))

        for c in cols:
            saved = save_state()

            if place_star(r, c):
                if propagate():
                    if search():
                        return True

            restore_state(saved)

        return False

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Search for solution
    if not search():
        return "No Solution"

    # Build result grid
    result = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        if stars[r] != -1:
            result[r][stars[r]] = 'S'

    return result

