            return -count  # More constraints first

        unknown_constraint.sort(key=constraint_score)

        if not solve_constraint(unknown_constraint, 0, numbered_cells):
            return "No Solution"

    # Build result
    for r in range(rows):
        for c in range(cols):
            if status[r][c] == 1:
                result[r][c] = 'F'

    return result

