from collections import deque

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # State: 0 = white, 1 = black, None = unknown
    state = [[None] * m for _ in range(n)]

    # Precompute which cells are in each numbered cell's neighborhood
    # For each numbered cell, store list of (r,c) in its 3x3 neighborhood
    numbered_cells = []
    neighborhoods = {}  # (r,c) -> list of cells in neighborhood

    for r in range(n):
        for c in range(m):
            if grid[r][c] is not None:
                numbered_cells.append((r, c))
                neigh = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            neigh.append((nr, nc))
                neighborhoods[(r, c)] = neigh

    # For each cell, which numbered cells' neighborhoods contain it
    cell_to_numbers = {}
    for r in range(n):
        for c in range(m):
            cell_to_numbers[(r, c)] = []
    for (nr, nc), neigh in neighborhoods.items():
        for (r, c) in neigh:
            cell_to_numbers[(r, c)].append((nr, nc))

    # Constraint propagation queue
    queue = deque()

    def add_to_queue(cells):
        for cell in cells:
            if cell not in queue:
                queue.append(cell)

    # Initialize queue with all numbered cells
    add_to_queue(numbered_cells)

    def get_neigh_state(nr, nc):
        """Get current state of neighborhood: (black_count, white_count, unknown_count, unknown_cells)"""
        neigh = neighborhoods[(nr, nc)]
        black = 0
        white = 0
        unknown = 0
        unknown_cells = []
        for (r, c) in neigh:
            if state[r][c] == 1:
                black += 1
            elif state[r][c] == 0:
                white += 1
            else:
                unknown += 1
                unknown_cells.append((r, c))
        return black, white, unknown, unknown_cells

    def propagate():
        """Propagate constraints, return False if contradiction found"""
        while queue:
            num_cell = queue.popleft()
            nr, nc = num_cell
            target = grid[nr][nc]
            black, white, unknown, unknown_cells = get_neigh_state(nr, nc)

            # Check if already satisfied or impossible
            if black > target:
                return False  # Too many black
            if black + unknown < target:
                return False  # Can't reach target

            # If exactly need more black, all unknown must be black
            if black + unknown == target:
                for (r, c) in unknown_cells:
                    state[r][c] = 1
                    # Add all numbered cells that see this cell
                    add_to_queue(cell_to_numbers[(r, c)])

            # If already have enough black, rest must be white
            if black == target:
                for (r, c) in unknown_cells:
                    state[r][c] = 0
                    add_to_queue(cell_to_numbers[(r, c)])

        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        for r in range(n):
            for c in range(m):
                if state[r][c] is None:
                    return False
        # Verify all constraints
        for (nr, nc) in numbered_cells:
            black, _, _, _ = get_neigh_state(nr, nc)
            if black != grid[nr][nc]:
                return False
        return True

    if is_solved():
        return format_result(state)

    # Need to guess - find cell with most constraint propagation potential
    def solve_recursive(depth=0):
        if depth > n * m:
            return None

        # Find best cell to branch on (involved in most constraints)
        best_cell = None
        best_score = -1
        for r in range(n):
            for c in range(m):
                if state[r][c] is None:
                    score = len(cell_to_numbers[(r, c)])
                    if score > best_score:
                        best_score = score
                        best_cell = (r, c)

        if best_cell is None:
            # All assigned, check solution
            if is_solved():
                return [row[:] for row in state]
            return None

        r, c = best_cell

        # Try black first (usually more constrained)
        for val in [1, 0]:
            # Save state
            old_state = [row[:] for row in state]

            state[r][c] = val
            add_to_queue(cell_to_numbers[(r, c)])

            if propagate():
                result = solve_recursive(depth + 1)
                if result is not None:
                    return result

            # Restore state
            for i in range(n):
                for j in range(m):
                    state[i][j] = old_state[i][j]
            queue.clear()

        return None

    result = solve_recursive()
    if result is None:
        return "No Solution"

    return format_result(result)

def format_result(state):
    """Convert state to required output format"""
    result = []
    for row in state:
        new_row = []
        for cell in row:
            if cell == 1:
                new_row.append('B')
            else:
                new_row.append(None)
        result.append(new_row)
    return result

