            # Deduction: if row needs more water, and only one region can provide it
            for r in range(rows):
                needed = row_clues[r] - row_counts[r]
                if needed == 0:
                    # All unknown must be dry
                    for c in range(cols):
                        if new_grid[r][c] == 0:
                            new_grid[r][c] = -1
                            changed = True
                elif needed == row_possible[r]:
                    # All unknown must be water
                    for c in range(cols):
                        if new_grid[r][c] == 0:
                            new_grid[r][c] = 1
                            changed = True

            for c in range(cols):
                needed = col_clues[c] - col_counts[c]
                if needed == 0:
                    for r in range(rows):
                        if new_grid[r][c] == 0:
                            new_grid[r][c] = -1
                            changed = True
                elif needed == col_possible[c]:
                    for r in range(rows):
                        if new_grid[r][c] == 0:
                            new_grid[r][c] = 1
                            changed = True

        return True, new_grid, new_levels

    def solve_recursive(grid, region_levels, depth=0):
        """Recursive solver with constraint propagation"""
        success, new_grid, new_levels = propagate(grid, region_levels)
        if not success:
            return None

        # Check if solved
        solved = True
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] == 0:
                    solved = False
                    break
            if not solved:
                break

        if solved:
            return new_grid

        # Find region with fewest remaining possibilities to branch on
        best_rid = None
        best_options = None

        for rid in regions:
            if rid in new_levels:
                continue

            possible = []
            for lvl in get_region_possible_levels(rid):
                # Quick check
                water_cells = get_region_water_cells(rid, lvl)
                valid = True
                for (r, c) in water_cells:
                    if new_grid[r][c] == -1:
                        valid = False
                        break
                if not valid:
                    continue

                # Check non-water constraint
                for r in range(lvl + 1, regions[rid]['max_row'] + 1):
                    if r in regions[rid]['by_row']:
                        for c in regions[rid]['by_row'][r]:
                            if new_grid[r][c] == 1:
                                valid = False
                                break
                    if not valid:
                        break

                if valid:
                    possible.append(lvl)

            if len(possible) == 0:
                return None

            if best_options is None or len(possible) < len(best_options):
                best_rid = rid
                best_options = possible
                if len(possible) == 1:
                    break

        if best_rid is None:
            # All regions assigned, should be solved
            return new_grid if solved else None

        # Try each option
        for lvl in best_options:
            new_region_levels = dict(new_levels)
            new_region_levels[best_rid] = lvl
            result = solve_recursive(new_grid, new_region_levels, depth + 1)
            if result is not None:
                return result

        return None

    result = solve_recursive(grid, {})

    if result is None:
        return "No Solution"

    # Format output
    output = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if result[r][c] == 1:
                row.append('W')
            else:
                row.append(None)
        output.append(row)

    return output

