def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Target counts: half black, half white
    target_b_row = m // 2
    target_w_row = m - target_b_row
    target_b_col = n // 2
    target_w_col = n - target_b_col

    # Initialize working grid
    board = [row[:] for row in grid]

    # Precompute fixed cells
    fixed = [[cell is not None for cell in row] for row in board]

    def get_counts(board):
        row_b = [sum(1 for c in row if c == 'B') for row in board]
        row_w = [sum(1 for c in row if c == 'W') for row in board]
        col_b = [sum(1 for r in range(n) if board[r][c] == 'B') for c in range(m)]
        col_w = [sum(1 for r in range(n) if board[r][c] == 'W') for c in range(m)]
        return row_b, row_w, col_b, col_w

    def has_three_consecutive(seq):
        for i in range(len(seq) - 2):
            if seq[i] is not None and seq[i] == seq[i+1] == seq[i+2]:
                return True
        return False

    def check_no_three(board):
        for r in range(n):
            row = board[r]
            if has_three_consecutive(row):
                return False
        for c in range(m):
            col = [board[r][c] for r in range(n)]
            if has_three_consecutive(col):
                return False
        return True

    def is_valid_partial(board):
        # Check counts don't exceed
        row_b, row_w, col_b, col_w = get_counts(board)
        for r in range(n):
            if row_b[r] > target_b_row or row_w[r] > target_w_row:
                return False
        for c in range(m):
            if col_b[c] > target_b_col or col_w[c] > target_w_col:
                return False

        # Check no three consecutive in completed portions
        for r in range(n):
            row = board[r]
            # Check for forced three
            for i in range(m - 2):
                vals = [row[i], row[i+1], row[i+2]]
                non_none = [v for v in vals if v is not None]
                if len(non_none) == 2 and len(set(non_none)) == 1:
                    # Two same, one None - check if placing same would make three
                    if vals.count(non_none[0]) == 2:
                        return False

        for c in range(m):
            col = [board[r][c] for r in range(n)]
            for i in range(n - 2):
                vals = [col[i], col[i+1], col[i+2]]
                non_none = [v for v in vals if v is not None]
                if len(non_none) == 2 and len(set(non_none)) == 1:
                    if vals.count(non_none[0]) == 2:
                        return False

        return True

    def is_complete_valid(board):
        row_b, row_w, col_b, col_w = get_counts(board)
        for r in range(n):
            if row_b[r] != target_b_row or row_w[r] != target_w_row:
                return False
        for c in range(m):
            if col_b[c] != target_b_col or col_w[c] != target_w_col:
                return False

        # Check all rows different
        rows = [''.join(row) for row in board]
        if len(set(rows)) != n:
            return False

        # Check all columns different
        cols = [''.join(board[r][c] for r in range(n)) for c in range(m)]
        if len(set(cols)) != m:
            return False

        return check_no_three(board)

    def deduce(board):
        """Apply constraint propagation"""
        changed = True
        while changed:
            changed = False
            row_b, row_w, col_b, col_w = get_counts(board)

            # Row deductions
            for r in range(n):
                for c in range(m):
                    if board[r][c] is not None:
                        continue

                    # Try B
                    can_b = True
                    board[r][c] = 'B'
                    if not is_valid_partial(board):
                        can_b = False
                    board[r][c] = None

                    # Try W
                    can_w = True
                    board[r][c] = 'W'
                    if not is_valid_partial(board):
                        can_w = False
                    board[r][c] = None

                    if can_b and not can_w:
                        board[r][c] = 'B'
                        changed = True
                    elif can_w and not can_b:
                        board[r][c] = 'W'
                        changed = True

            # Forced by count
            for r in range(n):
                if row_b[r] == target_b_row:
                    for c in range(m):
                        if board[r][c] is None:
                            board[r][c] = 'W'
                            changed = True
                if row_w[r] == target_w_row:
                    for c in range(m):
                        if board[r][c] is None:
                            board[r][c] = 'B'
                            changed = True

            for c in range(m):
                if col_b[c] == target_b_col:
                    for r in range(n):
                        if board[r][c] is None:
                            board[r][c] = 'W'
                            changed = True
                if col_w[c] == target_w_col:
                    for r in range(n):
                        if board[r][c] is None:
                            board[r][c] = 'B'
                            changed = True

            # Avoid three consecutive
            for r in range(n):
                row = board[r]
                for i in range(m - 2):
                    vals = row[i:i+3]
                    if vals[0] == vals[1] and vals[0] is not None and vals[2] is None:
                        board[r][i+2] = 'W' if vals[0] == 'B' else 'B'
                        changed = True
                    elif vals[0] == vals[2] and vals[0] is not None and vals[1] is None:
                        board[r][i+1] = 'W' if vals[0] == 'B' else 'B'
                        changed = True
                    elif vals[1] == vals[2] and vals[1] is not None and vals[0] is None:
                        board[r][i] = 'W' if vals[1] == 'B' else 'B'
                        changed = True

            for c in range(m):
                col = [board[r][c] for r in range(n)]
                for i in range(n - 2):
                    vals = col[i:i+3]
                    if vals[0] == vals[1] and vals[0] is not None and vals[2] is None:
                        board[i+2][c] = 'W' if vals[0] == 'B' else 'B'
                        changed = True
                    elif vals[0] == vals[2] and vals[0] is not None and vals[1] is None:
                        board[i+1][c] = 'W' if vals[0] == 'B' else 'B'
                        changed = True
                    elif vals[1] == vals[2] and vals[1] is not None and vals[0] is None:
                        board[i][c] = 'W' if vals[1] == 'B' else 'B'
                        changed = True

            row_b, row_w, col_b, col_w = get_counts(board)

        return board

    def find_empty(board):
        for r in range(n):
            for c in range(m):
                if board[r][c] is None:
                    return (r, c)
        return None

    def copy_board(board):
        return [row[:] for row in board]

    def solve_recursive(board):
        board = deduce(copy_board(board))

        if not is_valid_partial(board):
            return None

        empty = find_empty(board)
        if empty is None:
            if is_complete_valid(board):
                return board
            return None

        r, c = empty

        # Try B first
        test = copy_board(board)
        test[r][c] = 'B'
        result = solve_recursive(test)
        if result is not None:
            return result

        # Try W
        test = copy_board(board)
        test[r][c] = 'W'
        result = solve_recursive(test)
        if result is not None:
            return result

        return None

    result = solve_recursive(board)
    return result if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
