def solve(observation):
    grid = observation['data']
    n = len(grid)
    if n == 0:
        return "No Solution"

    # Build region map: region_id -> list of (r, c) cells
    regions = {}
    for r in range(n):
        for c in range(n):
            rid = grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    num_regions = len(regions)
    region_ids = list(regions.keys())

    # Precompute: for each cell, which cells are adjacent (including diagonal)
    # These cannot both have stars
    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    neighbors.append((nr, nc))
        return neighbors

    # State tracking
    # stars[r][c] = 0 (unknown), 1 (star), -1 (no star)
    stars = [[0] * n for _ in range(n)]
    row_count = [0] * n  # stars placed in each row
    col_count = [0] * n  # stars placed in each column
    region_count = {rid: 0 for rid in region_ids}  # stars placed in each region

    # For each cell, track if it's blocked (cannot be star)
    blocked = [[False] * n for _ in range(n)]

    # Helper to check if placing star at (r,c) is valid
    def can_place(r, c):
        if stars[r][c] != 0 or blocked[r][c]:
            return False
        if row_count[r] >= 2 or col_count[c] >= 2:
            return False
        rid = grid[r][c]
        if region_count[rid] >= 2:
            return False
        # Check no adjacent star
        for nr, nc in get_neighbors(r, c):
            if stars[nr][nc] == 1:
                return False
        return True

    # Helper to place a star
    def place_star(r, c):
        stars[r][c] = 1
        row_count[r] += 1
        col_count[c] += 1
        rid = grid[r][c]
        region_count[rid] += 1
        # Block neighbors
        for nr, nc in get_neighbors(r, c):
            if stars[nr][nc] == 0:
                stars[nr][nc] = -1

    # Helper to remove a star (for backtracking)
    def remove_star(r, c):
        stars[r][c] = 0
        row_count[r] -= 1
        col_count[c] -= 1
        rid = grid[r][c]
        region_count[rid] -= 1
        # Unblock neighbors - need to check if they should still be blocked
        # This is tricky, so we'll use a different approach: recompute blocked states

    # Constraint propagation: apply deductions until fixed point
    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule 1: If row has 2 stars, mark rest as no-star
            for r in range(n):
                if row_count[r] == 2:
                    for c in range(n):
                        if stars[r][c] == 0:
                            stars[r][c] = -1
                            changed = True
                elif row_count[r] == 1:
                    # If only one cell can have the second star, place it
                    candidates = []
                    for c in range(n):
                        if can_place(r, c):
                            candidates.append(c)
                    if len(candidates) == 1:
                        place_star(r, candidates[0])
                        changed = True
                    elif len(candidates) == 0 and row_count[r] < 2:
                        return False  # Dead end

            # Rule 2: If column has 2 stars, mark rest as no-star
            for c in range(n):
                if col_count[c] == 2:
                    for r in range(n):
                        if stars[r][c] == 0:
                            stars[r][c] = -1
                            changed = True
                elif col_count[c] == 1:
                    candidates = []
                    for r in range(n):
                        if can_place(r, c):
                            candidates.append(r)
                    if len(candidates) == 1:
                        place_star(candidates[0], c)
                        changed = True
                    elif len(candidates) == 0 and col_count[c] < 2:
                        return False

            # Rule 3: If region has 2 stars, mark rest as no-star
            for rid, cells in regions.items():
                if region_count[rid] == 2:
                    for r, c in cells:
                        if stars[r][c] == 0:
                            stars[r][c] = -1
                            changed = True
                elif region_count[rid] == 1:
                    candidates = []
                    for r, c in cells:
                        if can_place(r, c):
                            candidates.append((r, c))
                    if len(candidates) == 1:
                        place_star(candidates[0][0], candidates[0][1])
                        changed = True
                    elif len(candidates) == 0 and region_count[rid] < 2:
                        return False

            # Rule 4: If row needs 2 stars and has exactly 2 candidates, place both
            for r in range(n):
                need = 2 - row_count[r]
                if need > 0:
                    candidates = [c for c in range(n) if can_place(r, c)]
                    if len(candidates) == need:
                        for c in candidates:
                            place_star(r, c)
                            changed = True
                    elif len(candidates) < need:
                        return False

            # Rule 5: If column needs 2 stars and has exactly 2 candidates
            for c in range(n):
                need = 2 - col_count[c]
                if need > 0:
                    candidates = [r for r in range(n) if can_place(r, c)]
                    if len(candidates) == need:
                        for r in candidates:
                            place_star(r, c)
                            changed = True
                    elif len(candidates) < need:
                        return False

            # Rule 6: If region needs 2 stars and has exactly 2 candidates
            for rid, cells in regions.items():
                need = 2 - region_count[rid]
                if need > 0:
                    candidates = [(r, c) for r, c in cells if can_place(r, c)]
                    if len(candidates) == need:
                        for r, c in candidates:
                            place_star(r, c)
                            changed = True
                    elif len(candidates) < need:
                        return False

        return True

    # Deep copy state for backtracking
    def save_state():
        return (
            [row[:] for row in stars],
            row_count[:],
            col_count[:],
            dict(region_count)
        )

    def restore_state(state):
        nonlocal stars, row_count, col_count, region_count
        stars, row_count, col_count, region_count = state

    # Recursive solver with constraint propagation
    def solve_recursive():
        # Check if solved
        if all(row_count[r] == 2 for r in range(n)) and \
           all(col_count[c] == 2 for c in range(n)) and \
           all(region_count[rid] == 2 for rid in region_ids):
            return True

        # Find most constrained variable (region with fewest candidates)
        best_rid = None
        best_candidates = None
        best_score = float('inf')

        for rid in region_ids:
            if region_count[rid] >= 2:
                continue
            need = 2 - region_count[rid]
            candidates = [(r, c) for r, c in regions[rid] if can_place(r, c)]
            if len(candidates) < need:
                return False
            # Score: fewer candidates is better, also consider row/col constraints
            score = len(candidates)
            if score < best_score:
                best_score = score
                best_rid = rid
                best_candidates = candidates

        if best_rid is None:
            return False

        # Try placing stars in this region
        need = 2 - region_count[best_rid]

        # Generate combinations of 'need' cells from candidates
        from itertools import combinations

        for combo in combinations(best_candidates, need):
            state = save_state()

            # Try placing all stars in this combination
            valid = True
            for r, c in combo:
                if not can_place(r, c):
                    valid = False
                    break
                place_star(r, c)

            if valid:
                if propagate():
                    if solve_recursive():
                        return True

            restore_state(state)

        return False

    # Initial propagation
    if not propagate():
        return "No Solution"

    if solve_recursive():
        # Format result
        result = []
        for r in range(n):
            row = []
            for c in range(n):
                if stars[r][c] == 1:
                    row.append('S')
                else:
                    row.append(None)
            result.append(row)
        return result

    return "No Solution"

