    # Helper functions
    def get_cross(r, c):
        """Get all cells in same row/col until blocked, excluding (r,c) itself"""
        cells = []
        # Up
        for nr in range(r-1, -1, -1):
            if (nr, c) in black:
                break
            cells.append((nr, c))
        # Down
        for nr in range(r+1, n):
            if (nr, c) in black:
                break
            cells.append((nr, c))
        # Left
        for nc in range(c-1, -1, -1):
            if (r, nc) in black:
                break
            cells.append((r, nc))
        # Right
        for nc in range(c+1, n):
            if (r, nc) in black:
                break
            cells.append((r, nc))
        return cells

    def get_adjacent(r, c):
        """Get orthogonally adjacent cells"""
        adj = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < n:
                adj.append((nr, nc))
        return adj

    # Precompute illumination lines for each white cell
    white_cells = [(r, c) for r in range(n) for c in range(n) if (r, c) not in black]

    # For each white cell, find which cells can illuminate it (same row/col, no black between)
    # Actually, we need: for each white cell, where can a bulb be placed to illuminate it?
    def find_illuminators(r, c):
        """Find all white cells where a bulb would illuminate (r,c)"""
        illums = []
        # Check same row left
        for nc in range(c-1, -1, -1):
            if (r, nc) in black:
                break
            illums.append((r, nc))
        # Check same row right
        for nc in range(c+1, n):
            if (r, nc) in black:
                break
            illums.append((r, nc))
        # Check same col up
        for nr in range(r-1, -1, -1):
            if (nr, c) in black:
                break
            illums.append((nr, c))
        # Check same col down
        for nr in range(r+1, n):
            if (nr, c) in black:
                break
            illums.append((nr, c))
        return illums

    # Precompute: for each cell, which cells it can illuminate (if bulb placed there)
    illuminates = {}
    for r, c in white_cells:
        illuminates[(r, c)] = get_cross(r, c) + [(r, c)]  # includes itself

    # Precompute: for each white cell, where can bulbs be placed to illuminate it
    illuminated_by = {}
    for r, c in white_cells:
        illuminated_by[(r, c)] = find_illuminators(r, c) + [(r, c)]

    # State: bulbs placed
    bulbs = set()
    # Track which cells are illuminated
    lit = set()
    # Track remaining requirements for numbered cells
    remaining = {k: v for k, v in numbers.items()}

    def is_valid_placement(r, c):
        """Check if placing bulb at (r,c) is valid"""
        # Must be white
        if (r, c) in black:
            return False
        # Check no other bulb in illumination line
        for cell in illuminates[(r, c)]:
            if cell in bulbs:
                return False
        return True

    def place_bulb(r, c):
        """Place bulb and update state"""
        bulbs.add((r, c))
        for cell in illuminates[(r, c)]:
