        # Update number constraints
        for nr, nc in get_adjacent(r, c):
            if (nr, nc) in remaining:
                remaining[(nr, nc)] -= 1

    def remove_bulb(r, c):
        """Remove bulb and update state"""
        bulbs.remove((r, c))
        # Recalculate lit
        lit.clear()
        for b in bulbs:
            for cell in illuminates[b]:
                lit.add(cell)
        # Recalculate remaining
        for k in remaining:
            remaining[k] = numbers[k]
        for b in bulbs:
            for nr, nc in get_adjacent(*b):
                if (nr, nc) in remaining:
                    remaining[(nr, nc)] -= 1

    def check_numbers():
        """Check if all number constraints are still satisfiable"""
        for (r, c), req in remaining.items():
            if req < 0:
                return False
            # Count possible adjacent bulb positions
            adj = get_adjacent(r, c)
            possible = 0
            for ar, ac in adj:
                if (ar, ac) not in black and (ar, ac) not in bulbs:
                    # Check if we could place here (no conflict with existing bulbs)
                    can_place = True
                    for cell in illuminates[(ar, ac)]:
                        if cell in bulbs and cell != (ar, ac):
                            can_place = False
                            break
                    if can_place:
                        possible += 1
            # Already placed bulbs adjacent
            placed_adj = sum(1 for ar, ac in adj if (ar, ac) in bulbs)
            if placed_adj > numbers[(r, c)]:
                return False
            if placed_adj + possible < numbers[(r, c)]:
                return False
        return True

    def get_unlit_white():
        """Get white cells not yet illuminated"""
        return [(r, c) for r, c in white_cells if (r, c) not in lit]

    # Constraint propagation: forced moves
    def propagate():
        """Apply constraint propagation, return False if contradiction"""
        changed = True
        while changed:
            changed = False

            # Rule 1: Numbered cells with exact required bulbs
            for (r, c), req in list(remaining.items()):
                if req == 0:
                    continue
                adj = get_adjacent(r, c)
                empty_adj = [(ar, ac) for ar, ac in adj if (ar, ac) not in black and (ar, ac) not in bulbs]
                placed_adj = [(ar, ac) for ar, ac in adj if (ar, ac) in bulbs]

                # If exactly need to place req more, place in all empty that can hold bulbs
                if len(placed_adj) + len(empty_adj) == req:
                    for ar, ac in empty_adj:
                        if not is_valid_placement(ar, ac):
                            return False
                        place_bulb(ar, ac)
                        changed = True

            # Rule 2: Cells that can only be lit from one position
            for r, c in white_cells:
                if (r, c) in lit:
                    continue
                possible = [p for p in illuminated_by[(r, c)] if p not in black and p not in bulbs]
                # Filter by validity
                valid_possible = []
                for p in possible:
                    if is_valid_placement(p[0], p[1]):
                        valid_possible.append(p)
                if len(valid_possible) == 0:
                    return False
                if len(valid_possible) == 1:
                    pr, pc = valid_possible[0]
                    place_bulb(pr, pc)
                    changed = True

            # Rule 3: Numbered cells with 0 - mark adjacent as non-bulb (implicit)
            # Actually handled by remaining check

            if not check_numbers():
                return False

        return True

    # Solve using backtracking with propagation
    def solve_recursive():
        # Propagate constraints
        if not propagate():
            return False

        # Check if solved
        unlit = get_unlit_white()
        if not unlit:
            # Verify all numbers satisfied
            for (r, c), req in numbers.items():
                adj = get_adjacent(r, c)
                count = sum(1 for ar, ac in adj if (ar, ac) in bulbs)
                if count != req:
                    return False
            return True

        # Find most constrained unlit cell
        best_cell = None
        best_options = None

        # Prioritize: cells with fewest valid illuminators, or cells adjacent to numbered cells
        for r, c in unlit:
            options = []
            for p in illuminated_by[(r, c)]:
                if p not in black and p not in bulbs and is_valid_placement(p[0], p[1]):
                    options.append(p)
            if len(options) == 0:
                return False
            if best_options is None or len(options) < len(best_options):
                best_options = options
                best_cell = (r, c)
                if len(options) == 1:
                    break

        if best_cell is None:
            return False

        # Try each option
        for pr, pc in best_options:
            # Save state
            old_bulbs = set(bulbs)
            old_lit = set(lit)
            old_remaining = {k: v for k, v in remaining.items()}

            place_bulb(pr, pc)

            if solve_recursive():
                return True

            # Restore state
            bulbs.clear()
            bulbs.update(old_bulbs)
            lit.clear()
            lit.update(old_lit)
            for k in remaining:
                remaining[k] = old_remaining[k]

        return False

    if not solve_recursive():
        return "No Solution"

    # Build result
    result = [[None for _ in range(n)] for _ in range(n)]
    for r, c in bulbs:
        result[r][c] = 'B'

    return result

