from collections import defaultdict

def solve(observation):
    region = observation['region']
    row_counts = observation['row_stitch_counts']
    col_counts = observation['col_stitch_counts']
    n = len(region)

    # Build region cells mapping
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
