    # Find all potential stitches (between adjacent cells of different regions)
    # A stitch connects two holes. Holes are at cell centers.
    # Stitch between region A and B exists where cells are orthogonally adjacent
    # Holes are indexed by (r, c) for cell at (r,c)
    # Stitch between hole (r1,c1) and (r2,c2) where cells are adjacent

    # Actually, re-reading: holes are at cell centers, so hole grid is N x N
    # Stitch connects two orthogonally adjacent holes
    # But constraint: stitch only between DIFFERENT regions

    # Find all edges between different regions
    edges = []  # list of ((r1,c1), (r2,c2)) where adjacent cells different regions

    for r in range(n):
        for c in range(n):
            # Check right neighbor
            if c + 1 < n and region[r][c] != region[r][c+1]:
                edges.append(((r, c), (r, c+1)))
            # Check down neighbor
            if r + 1 < n and region[r][c] != region[r+1][c]:
                edges.append(((r, c), (r+1, c)))

    # For each hole, find which edges use it
    hole_to_edges = defaultdict(list)
    for i, (h1, h2) in enumerate(edges):
        hole_to_edges[h1].append(i)
        hole_to_edges[h2].append(i)

    # Row/col of each hole
    def hole_row(h): return h[0]
    def hole_col(h): return h[1]

    # Constraint: each hole can be used by at most 1 stitch
    # Constraint: row_counts[r] = number of holes in row r used by stitches
    # Constraint: col_counts[c] = number of holes in col c used by stitches

    # Use constraint propagation + backtracking

    n_edges = len(edges)

    # State: which edges are selected (0=unknown, 1=selected, -1=rejected)
    # Also track hole usage and row/col counts

    def solve_bt(state, hole_used, row_used, col_used, edge_idx):
        # Check if solved
        if edge_idx == n_edges:
            # Verify all constraints satisfied
            for r in range(n):
                if row_used[r] != row_counts[r]:
                    return None
            for c in range(n):
                if col_used[c] != col_counts[c]:
                    return None
            # Build result
            result = []
            for i in range(n_edges):
                if state[i] == 1:
                    h1, h2 = edges[i]
                    result.append([list(h1), list(h2)])
            return result

        # If this edge is already decided by propagation, skip
        if state[edge_idx] != 0:
            return solve_bt(state, hole_used, row_used, col_used, edge_idx + 1)

        # Try not selecting this edge
        state[edge_idx] = -1
        result = solve_bt(state, hole_used, row_used, col_used, edge_idx + 1)
        if result is not None:
            return result
        state[edge_idx] = 0

        # Try selecting this edge
        h1, h2 = edges[edge_idx]

        # Check if holes already used
        if hole_used[h1] or hole_used[h2]:
            return None

        r1, c1 = h1
        r2, c2 = h2

        # Check row/col constraints won't be exceeded
        if row_used[r1] >= row_counts[r1] or row_used[r2] >= row_counts[r2]:
            return None
        if col_used[c1] >= col_counts[c1] or col_used[c2] >= col_counts[c2]:
            return None

        # Apply
        state[edge_idx] = 1
        hole_used[h1] = True
        hole_used[h2] = True
        row_used[r1] += 1
        row_used[r2] += 1
        col_used[c1] += 1
        col_used[c2] += 1

        # Propagation: if a hole now has all required stitches incident, disable others
        # Actually each hole can have at most 1 stitch, so if used, disable all other edges

        # Propagate: for each hole of selected edge, mark other edges as rejected
        propagated = []
        for h in [h1, h2]:
            for other_edge in hole_to_edges[h]:
                if other_edge != edge_idx and state[other_edge] == 0:
                    state[other_edge] = -1
                    propagated.append(other_edge)

        # Additional propagation: check row/col completion
        # If row r is full, no more edges with holes in row r can be selected
        def propagate_rows_cols():
            changed = True
            while changed:
                changed = False
                for r in range(n):
                    if row_used[r] == row_counts[r]:
                        # Reject all unused edges with holes in this row
                        for c in range(n):
                            h = (r, c)
                            if h in hole_to_edges:
                                for ei in hole_to_edges[h]:
                                    if state[ei] == 0:
                                        state[ei] = -1
                                        propagated.append(ei)
                                        changed = True
                    elif row_used[r] > row_counts[r]:
                        return False

                for c in range(n):
                    if col_used[c] == col_counts[c]:
                        for r in range(n):
                            h = (r, c)
                            if h in hole_to_edges:
                                for ei in hole_to_edges[h]:
                                    if state[ei] == 0:
                                        state[ei] = -1
                                        propagated.append(ei)
                                        changed = True
                    elif col_used[c] > col_counts[c]:
                        return False
            return True

        if propagate_rows_cols():
            result = solve_bt(state, hole_used, row_used, col_used, edge_idx + 1)
            if result is not None:
                return result

        # Undo
        for ei in propagated:
            state[ei] = 0

        state[edge_idx] = 0
        hole_used[h1] = False
        hole_used[h2] = False
        row_used[r1] -= 1
        row_used[r2] -= 1
        col_used[c1] -= 1
        col_used[c2] -= 1

        return None

    # Initial propagation: holes that can't possibly be used
    state = [0] * n_edges
    hole_used = defaultdict(bool)
    row_used = [0] * n
    col_used = [0] * n

    # Pre-propagate: if a hole has no edges, it can't be used
    # If row needs 0, no holes in that row can be used
    for r in range(n):
        if row_counts[r] == 0:
            for c in range(n):
                h = (r, c)
                if h in hole_to_edges:
                    for ei in hole_to_edges[h]:
                        state[ei] = -1

    for c in range(n):
        if col_counts[c] == 0:
            for r in range(n):
                h = (r, c)
                if h in hole_to_edges:
                    for ei in hole_to_edges[h]:
                        state[ei] = -1

    result = solve_bt(state, hole_used, row_used, col_used, 0)
    return result if result is not None else "No Solution"

