                fixed[r][c] = True

    # Build adjacency constraints
    # has_dot[r][c][dir] = True if dot exists (dir: 0=right, 1=down)
    has_dot = [[[False, False] for _ in range(n)] for _ in range(n)]
    for ar, ac in adjacent:
        r, c = int(ar), int(ac)
        if ar == r and ac == c + 0.5:  # horizontal gap
            has_dot[r][c][0] = True
        elif ar == r + 0.5 and ac == c:  # vertical gap
            has_dot[r][c][1] = True

    # Precompute all cells and their constraints
    cells = [(r, c) for r in range(n) for c in range(n) if not fixed[r][c]]

    def get_neighbors(r, c):
        res = []
        if c + 1 < n: res.append((r, c+1, 0))  # right
        if r + 1 < n: res.append((r+1, c, 1))  # down
        if c - 1 >= 0: res.append((r, c-1, 0))  # left (check their right)
        if r - 1 >= 0: res.append((r-1, c, 1))  # up (check their down)
        return res

    def consecutive(a, b):
        return abs(a - b) == 1

    def valid_placement(grid, r, c, val):
        # Check row and column uniqueness
        for i in range(n):
            if i != c and grid[r][i] == val:
                return False
            if i != r and grid[i][c] == val:
                return False

        # Check adjacency constraints with already placed neighbors
        # Right neighbor
        if c + 1 < n and grid[r][c+1] != 0:
            expected_dot = consecutive(val, grid[r][c+1])
            actual_dot = has_dot[r][c][0]
            if expected_dot != actual_dot:
                return False

        # Down neighbor
        if r + 1 < n and grid[r+1][c] != 0:
            expected_dot = consecutive(val, grid[r+1][c])
            actual_dot = has_dot[r][c][1]
            if expected_dot != actual_dot:
                return False

        # Left neighbor (check from their side)
        if c - 1 >= 0 and grid[r][c-1] != 0:
            expected_dot = consecutive(val, grid[r][c-1])
            actual_dot = has_dot[r][c-1][0]
            if expected_dot != actual_dot:
                return False

        # Up neighbor (check from their side)
        if r - 1 >= 0 and grid[r-1][c] != 0:
            expected_dot = consecutive(val, grid[r-1][c])
            actual_dot = has_dot[r-1][c][1]
            if expected_dot != actual_dot:
