    # Make copies for solving
    solve_grid = [row[:] for row in grid]
    solve_domains = [[domains[r][c][:] for c in range(n)] for r in range(n)]

    if backtrack(solve_grid, solve_domains):
        # Format result
        result = [[solve_grid[r][c] for c in range(n)] for r in range(n)]
        return result

    return "No Solution"

