# Akari/Light Up Puzzle Solver
# Uses constraint propagation and human-like deduction techniques

from collections import deque

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Cell types: None=white, -1=black no number, 0-4=black with number
    # We'll track: bulb placement, illumination, and constraints

    # Directions: up, down, left, right
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < m

    def is_black(r, c):
        return grid[r][c] is not None and grid[r][c] != -1 or grid[r][c] == -1

    def is_numbered(r, c):
        return grid[r][c] is not None and isinstance(grid[r][c], int) and 0 <= grid[r][c] <= 4

    def get_number(r, c):
        return grid[r][c] if is_numbered(r, c) else None

    def get_adjacent_white(r, c):
        """Get orthogonally adjacent white cells"""
        res = []
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc) and not is_black(nr, nc):
                res.append((nr, nc))
        return res

    def cells_in_line(r, c, dr, dc):
        """Get all cells visible from (r,c) in direction (dr,dc) until blocked"""
        res = []
        nr, nc = r + dr, c + dc
        while in_bounds(nr, nc) and not is_black(nr, nc):
            res.append((nr, nc))
            nr += dr
            nc += dc
        return res

    def all_visible_from(r, c):
        """Get all cells that a bulb at (r,c) would illuminate (excluding itself)"""
        res = []
        for dr, dc in DIRS:
            res.extend(cells_in_line(r, c, dr, dc))
        return res

    # State tracking
    # bulbs[r][c] = True/False/None (None=unknown)
    # illuminated[r][c] = count of bulbs that can illuminate it (0, 1, 2+)
    # forced[r][c] = True if must be bulb, False if cannot be bulb

    bulbs = [[None for _ in range(m)] for _ in range(n)]
    illuminated = [[0 for _ in range(m)] for _ in range(n)]
    forced = [[None for _ in range(m)] for _ in range(n)]  # None=unknown, True=must bulb, False=must empty

    # Pre-compute white cells and their properties
    white_cells = []
    numbered_cells = []
    for r in range(n):
        for c in range(m):
            if not is_black(r, c):
                white_cells.append((r, c))
            elif is_numbered(r, c):
                numbered_cells.append((r, c))

    # Helper to check if cell can have bulb
    def can_place_bulb(r, c):
        if is_black(r, c):
            return False
        if forced[r][c] is False:
            return False
        if bulbs[r][c] is False:
            return False
        # Check if any adjacent bulb
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc) and bulbs[nr][nc] is True:
                return False
        # Check if any bulb in line of sight
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            while in_bounds(nr, nc) and not is_black(nr, nc):
                if bulbs[nr][nc] is True:
                    return False
                nr += dr
                nc += dc
        return True

    def must_place_bulb(r, c):
        """Check if cell must have bulb due to constraints"""
        if is_black(r, c):
            return False
        if forced[r][c] is True:
            return True
        return False

    def place_bulb(r, c):
        """Place a bulb and update illumination"""
        if bulbs[r][c] is True:
            return True  # already placed
        if not can_place_bulb(r, c):
            return False

        bulbs[r][c] = True

        # Illuminate cells
        illuminated[r][c] += 1  # self-illumination (not really used but for consistency)
        for nr, nc in all_visible_from(r, c):
            illuminated[nr][nc] += 1

        return True

    def remove_bulb(r, c):
        """Remove a bulb (for backtracking)"""
        if bulbs[r][c] is not True:
            return

        bulbs[r][c] = None

        for nr, nc in all_visible_from(r, c):
            illuminated[nr][nc] -= 1

    def mark_no_bulb(r, c):
        """Mark cell as definitely not having a bulb"""
        if bulbs[r][c] is True:
            return False  # contradiction
        forced[r][c] = False
        bulbs[r][c] = False
        return True

    # Constraint propagation queue
    queue = deque()

    def add_constraint(r, c, is_bulb):
        """Add a constraint to the queue"""
        if forced[r][c] is not None:
            if forced[r][c] != is_bulb:
                return False  # contradiction
            return True
        queue.append((r, c, is_bulb))
        return True

    # Initialize with numbered cell constraints
    def process_numbered_cells():
        """Apply constraints from numbered black cells"""
        changed = True
        while changed:
            changed = False
            for r, c in numbered_cells:
                num = get_number(r, c)
                adj = get_adjacent_white(r, c)

                # Count known bulbs and forbidden cells
                known_bulbs = sum(1 for ar, ac in adj if bulbs[ar][ac] is True)
                known_empty = sum(1 for ar, ac in adj if bulbs[ar][ac] is False or forced[ar][ac] is False)
                unknown = [p for p in adj if bulbs[p[0]][p[1]] is None and forced[p[0]][p[1]] is None]

                if known_bulbs > num:
                    return False  # too many bulbs

                if known_bulbs + len(unknown) < num:
                    return False  # not enough possible positions

                if known_bulbs == num:
                    # All remaining must be empty
                    for ar, ac in unknown:
                        if not mark_no_bulb(ar, ac):
                            return False
                        changed = True

                elif known_bulbs + len(unknown) == num:
                    # All unknown must be bulbs
                    for ar, ac in unknown:
                        if not place_bulb(ar, ac):
                            return False
                        changed = True
        return True

    # Initialize: process numbered cells
    if not process_numbered_cells():
