                    while in_bounds(nr, nc) and not is_black(nr, nc):
                        if can_place_bulb(nr, nc):
                            possible_sources.append((nr, nc))
                        nr += dr
                        nc += dc

                # If no source possible, contradiction
                if len(possible_sources) == 0:
                    # Check if already illuminated
                    if illuminated[r][c] == 0:
                        return False

                # If only one source and not yet illuminated, must use it
                elif illuminated[r][c] == 0 and len(possible_sources) == 1:
                    sr, sc = possible_sources[0]
                    if not place_bulb(sr, sc):
                        return False
                    changed = True
                    if not process_numbered_cells():
