    def propagate_illumination():
        """Ensure all white cells can be illuminated"""
        for r, c in white_cells:
            if illuminated[r][c] > 0:
                continue

            # Find possible illuminating positions
            sources = []
            # Self
            if bulbs[r][c] is None and can_place_bulb(r, c):
                sources.append((r, c))
            # Others in line
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                while in_bounds(nr, nc) and not is_black(nr, nc):
                    if bulbs[nr][nc] is None and can_place_bulb(nr, nc):
                        sources.append((nr, nc))
                    nr += dr
                    nc += dc

            if len(sources) == 0:
                return False  # cannot be illuminated

        return True

    if not propagate_illumination():
        return "No Solution"

    # Main solving with backtracking
    # Find cell with minimum remaining values

    def select_cell():
        """Select unassigned white cell with most constraints"""
        best = None
        best_score = -1

        for r, c in white_cells:
            if bulbs[r][c] is not None:
                continue

            # Score by constraint tightness
            score = 0

            # Check numbered cell adjacency
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if in_bounds(nr, nc) and is_numbered(nr, nc):
