        """Check if puzzle is solved"""
        # All white cells illuminated
        for r, c in white_cells:
            if illuminated[r][c] == 0 and bulbs[r][c] is not True:
                # Check if self would be illuminated
                has_illumination = False
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    while in_bounds(nr, nc) and not is_black(nr, nc):
                        if bulbs[nr][nc] is True:
                            has_illumination = True
                            break
                        nr += dr
                        nc += dc
                    if has_illumination:
                        break
                if not has_illumination and bulbs[r][c] is not True:
                    return False

        # All numbered cells satisfied
        for r, c in numbered_cells:
            num = get_number(r, c)
            adj = get_adjacent_white(r, c)
            count = sum(1 for ar, ac in adj if bulbs[ar][ac] is True)
