            adj = get_adjacent_white(r, c)
            count = sum(1 for ar, ac in adj if bulbs[ar][ac] is True)
            if count > num:
                return False
            # Check if still possible
            unknown = sum(1 for ar, ac in adj if bulbs[ar][ac] is None)
            if count + unknown < num:
                return False

