        for r, c in white_cells:
            if bulbs[r][c] is not True:
                continue
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                while in_bounds(nr, nc) and not is_black(nr, nc):
                    if bulbs[nr][nc] is True:
