            if grid[r][c] not in ('B', 'W'):
                return False

    # Check row constraints
    for r in range(n):
        b_count = sum(1 for c in range(m) if grid[r][c] == 'B')
        w_count = sum(1 for c in range(m) if grid[r][c] == 'W')
        if b_count != target_row or w_count != target_row:
            return False

        # No three consecutive
        for c in range(m - 2):
            if grid[r][c] == grid[r][c+1] == grid[r][c+2]:
                return False

    # Check column constraints
    for c in range(m):
        b_count = sum(1 for r in range(n) if grid[r][c] == 'B')
        w_count = sum(1 for r in range(n) if grid[r][c] == 'W')
        if b_count != target_col or w_count != target_col:
            return False

        # No three consecutive
        for r in range(n - 2):
            if grid[r][c] == grid[r+1][c] == grid[r+2][c]:
                return False

    # Check all rows different
    rows = [tuple(grid[r]) for r in range(n)]
    if len(set(rows)) != n:
        return False

    # Check all columns different
    cols = [tuple(grid[r][c] for r in range(n)) for c in range(m)]
    if len(set(cols)) != m:
        return False

    return True

