    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Initialize state: 0=unknown, 1=black, 2=white
    # Use integers for efficiency
    state = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                state[i][j] = 1
            elif grid[i][j] == 'W':
