    def get_neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m:
                yield nr, nc

    def check_2x2(state):
        for i in range(n-1):
            for j in range(m-1):
                cells = [state[i][j], state[i+1][j], state[i][j+1], state[i+1][j+1]]
                if 0 not in cells:
                    if all(c == 1 for c in cells) or all(c == 2 for c in cells):
                        return False
        return True

    def find_component(state, color, start_r, start_c, visited):
        # BFS to find connected component
        comp = []
        q = deque()
        q.append((start_r, start_c))
        visited[start_r][start_c] = True
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for nr, nc in get_neighbors(r, c):
                if not visited[nr][nc] and state[nr][nc] == color:
                    visited[nr][nc] = True
                    q.append((nr, nc))
        return comp

    def check_connectivity(state):
        # Check if both colors form single connected components
        # Return (black_ok, white_ok, black_cells, white_cells)
        black_cells = []
        white_cells = []
        for i in range(n):
            for j in range(m):
                if state[i][j] == 1:
                    black_cells.append((i,j))
                elif state[i][j] == 2:
                    white_cells.append((i,j))

        # If no cells of a color, connectivity fails (unless grid is empty)
        if len(black_cells) == 0 or len(white_cells) == 0:
            if len(black_cells) + len(white_cells) == n * m:
                return (len(black_cells) <= 1, len(white_cells) <= 1, black_cells, white_cells)
            return (False, False, black_cells, white_cells)

        # Check black connectivity
        visited = [[False]*m for _ in range(n)]
        comp = find_component(state, 1, black_cells[0][0], black_cells[0][1], visited)
        black_ok = len(comp) == len(black_cells)

        # Check white connectivity
        visited = [[False]*m for _ in range(n)]
        comp = find_component(state, 2, white_cells[0][0], white_cells[0][1], visited)
        white_ok = len(comp) == len(white_cells)

        return (black_ok, white_ok, black_cells, white_cells)

    def is_valid_partial(state):
        # Check 2x2 constraint for filled cells only
        for i in range(n-1):
            for j in range(m-1):
                cells = [state[i][j], state[i+1][j], state[i][j+1], state[i+1][j+1]]
                if 0 not in cells:
                    if all(c == 1 for c in cells) or all(c == 2 for c in cells):
                        return False
        return True

    def propagate_constraints(state):
