        changed = True
        while changed:
            changed = False

            # Rule 1: If placing a color would create 2x2, place opposite
            for i in range(n-1):
                for j in range(m-1):
                    cells = [(i,j), (i+1,j), (i,j+1), (i+1,j+1)]
                    values = [state[r][c] for r,c in cells]
                    unknown = [(r,c) for (r,c),v in zip(cells,values) if v==0]
                    known = [(r,c) for (r,c),v in zip(cells,values) if v!=0]

                    if len(unknown) == 1 and len(known) == 3:
                        ur, uc = unknown[0]
                        # Check if all known are same color
                        if all(state[r][c] == 1 for r,c in known):
                            # Would create 2x2 black, so must be white
                            state[ur][uc] = 2
                            changed = True
                        elif all(state[r][c] == 2 for r,c in known):
                            # Would create 2x2 white, so must be black
                            state[ur][uc] = 1
                            changed = True

            # Rule 2: Check for forced moves to prevent disconnection
            # (simplified: check if a cell is surrounded by one color)
            for i in range(n):
                for j in range(m):
                    if state[i][j] != 0:
                        continue
                    # Check neighbors
                    black_n = 0
                    white_n = 0
                    unknown_n = 0
                    for ni, nj in get_neighbors(i,j):
                        if state[ni][nj] == 1:
                            black_n += 1
                        elif state[ni][nj] == 2:
