        return True

    def solve_recursive(state, depth=0):
        # Check if complete
        complete = True
        for i in range(n):
            for j in range(m):
                if state[i][j] == 0:
                    complete = False
                    break
            if not complete:
                break

        if complete:
            # Final validation
            if not check_2x2(state):
                return None
            black_ok, white_ok, _, _ = check_connectivity(state)
            if black_ok and white_ok:
                return state
            return None

        # Find next unknown cell with most constraints (MRV)
        best_i, best_j = -1, -1
        best_score = -1

        for i in range(n):
            for j in range(m):
                if state[i][j] != 0:
                    continue

                # Count constraints
                score = 0
                # 2x2 constraints
                for di in [-1, 0]:
                    for dj in [-1, 0]:
                        if i+di >= 0 and i+di+1 < n and j+dj >= 0 and j+dj+1 < m:
                            cells = [(i+di, j+dj), (i+di+1, j+dj), (i+di, j+dj+1), (i+di+1, j+dj+1)]
                            filled = sum(1 for r,c in cells if state[r][c] != 0)
                            score += filled * 10

                # Neighbor constraints
                for ni, nj in get_neighbors(i,j):
                    if state[ni][nj] != 0:
                        score += 1

                if score > best_score:
                    best_score = score
                    best_i, best_j = i, j

        if best_i == -1:
            return None

        # Try black first, then white
        for color in [1, 2]:
            new_state = [row[:] for row in state]
            new_state[best_i][best_j] = color

            if not is_valid_partial(new_state):
                continue

            # Propagate constraints
            propagated = propagate_constraints(new_state)
            if not propagated:
                continue

            result = solve_recursive(new_state, depth+1)
            if result is not None:
                return result

        return None

    # Initial propagation
    if not propagate_constraints(state):
        return "No Solution"

    result = solve_recursive(state)

    if result is None:
        return "No Solution"

    # Convert to output format
    output = []
    for i in range(n):
        row = []
        for j in range(m):
            if result[i][j] == 1:
                row.append('B')
            else:
                row.append('W')
        output.append(row)

    return output

