def solve(observation):
    grid = observation['data']
    n = len(grid)

    # Parse grid: -1 is black wall, 0-4 is numbered wall, None is white cell
    is_wall = [[False] * n for _ in range(n)]
    is_numbered = [[False] * n for _ in range(n)]
    number = [[-1] * n for _ in range(n)]
    white_cells = set()

    for r in range(n):
        for c in range(n):
            if grid[r][c] == -1:
                is_wall[r][c] = True
            elif grid[r][c] is not None:  # 0-4
                is_wall[r][c] = True
                is_numbered[r][c] = True
                number[r][c] = grid[r][c]
            else:
                white_cells.add((r, c))

    # Precompute visibility: for each white cell, which cells does it illuminate
    def get_illuminated_from(r, c):
        """Return set of cells illuminated by a bulb at (r,c)"""
        illuminated = {(r, c)}
        # Up
        for nr in range(r-1, -1, -1):
            if is_wall[nr][c]:
                break
            illuminated.add((nr, c))
        # Down
        for nr in range(r+1, n):
            if is_wall[nr][c]:
                break
            illuminated.add((nr, c))
        # Left
        for nc in range(c-1, -1, -1):
            if is_wall[r][nc]:
                break
            illuminated.add((r, nc))
        # Right
        for nc in range(c+1, n):
            if is_wall[r][nc]:
                break
            illuminated.add((r, nc))
        return illuminated

    # Precompute for all white cells
    bulb_illumination = {}
    for r, c in white_cells:
        bulb_illumination[(r, c)] = get_illuminated_from(r, c)

    # For each white cell, find which bulbs can illuminate it
    can_illuminate = {cell: set() for cell in white_cells}
    for bulb_pos, illuminated in bulb_illumination.items():
        for cell in illuminated:
            if cell in white_cells:
                can_illuminate[cell].add(bulb_pos)

    # Check if two bulbs see each other
    def bulbs_see_each_other(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        if r1 == r2:
            min_c, max_c = min(c1, c2), max(c1, c2)
            for c in range(min_c + 1, max_c):
                if is_wall[r1][c]:
                    return False
            return True
        if c1 == c2:
            min_r, max_r = min(r1, r2), max(r1, r2)
            for r in range(min_r + 1, max_r):
                if is_wall[r][c1]:
                    return False
            return True
        return False

    # Adjacent cells
    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield (nr, nc)

    # For numbered cells, get adjacent white cells
    numbered_adjacent_whites = {}
    for r in range(n):
        for c in range(n):
            if is_numbered[r][c]:
                adj = []
                for nr, nc in neighbors(r, c):
                    if not is_wall[nr][nc]:
                        adj.append((nr, nc))
                numbered_adjacent_whites[(r, c)] = adj

    # State tracking
    bulbs = set()
    illuminated = set()

    # Constraint propagation
    def propagate():
        """Apply constraint propagation, return False if contradiction"""
        changed = True
        while changed:
            changed = False

            # Rule 1: Numbered cells must have exact count
            for (r, c), target in [(pos, number[pos[0]][pos[1]]) for pos in numbered_adjacent_whites]:
                adj = numbered_adjacent_whites[(r, c)]
                current = sum(1 for pos in adj if pos in bulbs)
                forced = [pos for pos in adj if pos not in bulbs and len(can_illuminate[pos]) == 1]
                forbidden = [pos for pos in adj if any(bulbs_see_each_other(pos, b) for b in bulbs)]

                # If already satisfied, no more bulbs adjacent
                if current == target:
                    for pos in adj:
                        if pos not in bulbs and pos in white_cells:
                            # Remove from consideration by marking as illuminated-only
                            pass  # handled by other constraints

                # If need more, check if forced
                remaining = target - current
                available = [pos for pos in adj if pos not in bulbs and pos not in forbidden and 
                           not any(bulbs_see_each_other(pos, b) for b in bulbs)]

                if remaining < 0:
                    return False
                if remaining > len(available):
                    return False

                # If exactly enough available, place them all
                if remaining > 0 and remaining == len(available):
                    for pos in available:
                        if pos not in bulbs:
                            if not place_bulb(pos):
                                return False
                            changed = True

            # Rule 2: Cells that can only be illuminated one way
            for cell in white_cells:
                if cell not in illuminated:
                    possible = [b for b in can_illuminate[cell] if b not in bulbs 
                               and not any(bulbs_see_each_other(b, existing) for existing in bulbs)]
                    if len(possible) == 0:
                        return False
                    if len(possible) == 1:
                        b = possible[0]
                        if b not in bulbs:
                            if not place_bulb(b):
                                return False
                            changed = True

            # Rule 3: Bulbs cannot see each other
            for b in list(bulbs):
                for other in list(bulbs):
                    if b < other and bulbs_see_each_other(b, other):
                        return False

        return True

    def place_bulb(pos):
        """Place a bulb and update state, return False if invalid"""
        if pos in bulbs:
            return True

        # Check if it sees any existing bulb
        for b in bulbs:
            if bulbs_see_each_other(pos, b):
                return False

        bulbs.add(pos)
        illuminated.update(bulb_illumination[pos])
        return True

    def unplace_bulb(pos):
        """Remove a bulb (rarely used in backtracking)"""
        bulbs.discard(pos)
        # Recompute illuminated
        illuminated.clear()
        for b in bulbs:
            illuminated.update(bulb_illumination[b])

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Find unilluminated cells and try to cover them
    def solve_recursive():
        # Check if solved
        unilluminated = white_cells - illuminated
        if not unilluminated:
            # Verify all numbered constraints
            for (r, c), adj in numbered_adjacent_whites.items():
                target = number[r][c]
                if sum(1 for pos in adj if pos in bulbs) != target:
                    return False
            return True

        # Pick cell with fewest options (MRV)
