    # State: bridges[i][j] = number of bridges (0, 1, or 2) for i<j
    # We'll use a dict for sparse representation

    def get_bridge_key(i, j):
        return (min(i, j), max(i, j))

    def bridges_between(bridges, i, j):
        key = get_bridge_key(i, j)
        return bridges.get(key, 0)

    def count_bridges_at(bridges, i):
        total = 0
        for j in range(num_islands):
            if i != j:
                total += bridges_between(bridges, i, j)
