        candidates.sort(key=lambda x: rem[x[0]] - count_bridges_at(bridges, x[0]))

        for j, max_add in candidates:
            for add in range(max_add, 0, -1):  # Try more bridges first
                key = get_bridge_key(best_i, j)
                new_bridges = dict(bridges)
                new_bridges[key] = new_bridges.get(key, 0) + add

                # Quick check
                if count_bridges_at(new_bridges, best_i) > islands[best_i][2]:
                    continue
                if count_bridges_at(new_bridges, j) > islands[j][2]:
                    continue

                result = search(new_bridges, depth + 1)
                if result is not None:
                    return result

        return None

    # Start with empty bridges
    result = search({})

    if result is None:
        return "No Solution"

    # Format output
    answer = {}
    for (i, j), cnt in result.items():
        if cnt > 0:
            r1, c1, _ = islands[i]
            r2, c2, _ = islands[j]
            answer[((r1, c1), (r2, c2))] = cnt

    return str(answer).replace("'", '"')

