# Akari/Light Up Puzzle Solver with Human-like Deductive Reasoning

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Cell types: -1 = black no number, 0-4 = black with number, None = white
    # We'll track: bulb placement and illumination

