    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_black(r, c):
        return grid[r][c] is not None and grid[r][c] != None

    def is_numbered(r, c):
        return is_black(r, c) and grid[r][c] >= 0

    def get_number(r, c):
        return grid[r][c] if is_numbered(r, c) else None

    def in_bounds(r, c):
