    def get_illuminated_from(r, c, bulbs_set):
        """Get all cells illuminated by a bulb at (r,c), blocked by other bulbs or black cells"""
        illuminated = set()
        illuminated.add((r, c))
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            while in_bounds(nr, nc):
                if is_black(nr, nc):
                    break
                if (nr, nc) in bulbs_set and (nr, nc) != (r, c):
                    break  # Another bulb blocks
                illuminated.add((nr, nc))
                nr += dr
                nc += dc
        return illuminated

    def get_cells_seen_by_bulb(r, c):
        """Get all cells visible from (r,c) in 4 directions (excluding black cells)"""
        seen = set()
        seen.add((r, c))
