    cell_visibility = {}
    for r, c in white_cells:
        cell_visibility[(r, c)] = get_cells_seen_by_bulb(r, c)

    # For numbered cells, get adjacent white cells
    numbered_cells = [(r, c) for r in range(n) for c in range(m) if is_numbered(r, c)]

    def get_adjacent_whites(r, c):
        adj = []
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc) and not is_black(nr, nc):
                adj.append((nr, nc))
        return adj

    # Constraint propagation state
    # bulbs: set of (r,c) where bulbs are placed
    # no_bulb: set of (r,c) where bulbs cannot be placed
    # illuminated: set of cells that are illuminated

    def solve_with_constraints():
        bulbs = set()
        no_bulb = set()

