                # If not enough possible spots
                if len(adj_bulbs) + len(adj_unknown) < num:
                    return None  # Invalid state

            # Check: if a white cell has no possible bulb positions that can illuminate it
            # This is complex, do simpler checks first

            # Check bulb visibility constraint
            for b in list(bulbs):
                for other in bulbs:
                    if other != b and other in cell_visibility[b]:
                        # Two bulbs see each other - invalid
                        # But only if they're in line of sight (not blocked by black)
                        # cell_visibility already accounts for black cells
                        return None

            # Cells that must be illuminated: check if any white cell can only be lit by one position
            for r, c in white_cells:
                if (r, c) in bulbs:
                    continue  # Already has a bulb

                # Find all possible bulb positions that could illuminate this cell
                possible_sources = []
                for src in cell_visibility[(r, c)]:
                    if src in white_set and src not in no_bulb:
                        # Check if placing bulb at src would be valid
                        possible_sources.append(src)

                # If no possible source, invalid
                if not possible_sources:
                    return None

                # If only one possible source and we need to illuminate this cell
                # Actually we need to check if this cell is already illuminated
                illuminated_by_current = False
                for b in bulbs:
                    if (r, c) in cell_visibility[b]:
                        illuminated_by_current = True
                        break

                if not illuminated_by_current and len(possible_sources) == 1:
                    # Must place bulb here
                    src = possible_sources[0]
                    if src not in bulbs:
                        bulbs.add(src)
                        changed = True

        # Check if solved
        # All numbered constraints satisfied
        for r, c in numbered_cells:
            num = get_number(r, c)
            adj = get_adjacent_whites(r, c)
            adj_bulbs = [p for p in adj if p in bulbs]
            if len(adj_bulbs) != num:
                break  # Not solved yet
        else:
            # All numbered satisfied, check illumination
            illuminated = set()
            for b in bulbs:
                illuminated.update(cell_visibility[b])

            if len(illuminated) == len(white_cells):
                # Solved!
                return bulbs

        # Need to guess - find cell with fewest options
        # Prioritize: cells adjacent to numbered cells with remaining needs

        best_cell = None
        best_score = float('inf')

        # First try cells adjacent to numbered cells that need more bulbs
        for r, c in numbered_cells:
            num = get_number(r, c)
            adj = get_adjacent_whites(r, c)
            adj_bulbs = [p for p in adj if p in bulbs]
