                for p in adj_unknown:
                    # Score: prefer cells with more constraint propagation potential
                    score = len(adj_unknown)  # fewer unknowns = more constrained
                    if score < best_score:
                        best_score = score
                        best_cell = p

        # If no priority cell, find any unknown white cell
        if best_cell is None:
            for r, c in white_cells:
                if (r, c) not in bulbs and (r, c) not in no_bulb:
                    # Score by how many cells it illuminates (more = better for coverage)
                    score = -len(cell_visibility[(r, c)])  # negative because we want max
                    # Prefer cells near numbered cells
                    for nr, nc in numbered_cells:
                        if abs(r - nr) + abs(c - nc) == 1:
                            score += 10  # bonus for being adjacent to numbered
                    if score < best_score:
                        best_score = score
                        best_cell = (r, c)

        if best_cell is None:
            return None  # No cell to branch on, but not solved - invalid

        # Try placing bulb
        br, bc = best_cell

        # Try: place bulb
        new_bulbs = set(bulbs)
        new_bulbs.add((br, bc))
        new_no_bulb = set(no_bulb)
        # Cells that would be seen by this bulb cannot have bulbs
        for seen in cell_visibility[(br, bc)]:
            if seen != (br, bc) and seen not in new_bulbs:
                new_no_bulb.add(seen)

        # Recursively solve with this choice
        result = solve_recursive(new_bulbs, new_no_bulb, 0)
        if result is not None:
            return result

        # Try: no bulb
        new_no_bulb2 = set(no_bulb)
        new_no_bulb2.add((br, bc))
        result = solve_recursive(bulbs, new_no_bulb2, 0)
        return result

    def solve_recursive(bulbs, no_bulb, depth):
        # Local constraint propagation
        changed = True
        while changed:
            changed = False

            for r, c in numbered_cells:
                num = get_number(r, c)
                adj = get_adjacent_whites(r, c)
                adj_bulbs = [p for p in adj if p in bulbs]
                adj_no_bulb = [p for p in adj if p in no_bulb]
                adj_unknown = [p for p in adj if p not in bulbs and p not in no_bulb]

                if len(adj_bulbs) == num:
                    for p in adj_unknown:
                        if p not in no_bulb:
                            no_bulb.add(p)
                            changed = True

                remaining = num - len(adj_bulbs)
                if remaining == len(adj_unknown) and remaining > 0:
                    for p in adj_unknown:
                        if p not in bulbs:
                            bulbs.add(p)
                            # Add visibility constraints
                            for seen in cell_visibility[p]:
                                if seen != p and seen not in bulbs:
                                    no_bulb.add(seen)
                            changed = True

                if len(adj_bulbs) > num:
                    return None

                if len(adj_bulbs) + len(adj_unknown) < num:
                    return None

            # Check bulb conflicts
            for b in bulbs:
                for other in bulbs:
                    if other != b and other in cell_visibility[b]:
                        return None

            # Check forced illumination
            for r, c in white_cells:
                if (r, c) in bulbs:
                    continue

                possible_sources = []
                for src in cell_visibility[(r, c)]:
                    if src in white_set and src not in no_bulb:
                        possible_sources.append(src)

                if not possible_sources:
                    return None

                illuminated_by_current = False
                for b in bulbs:
                    if (r, c) in cell_visibility[b]:
                        illuminated_by_current = True
                        break

                if not illuminated_by_current and len(possible_sources) == 1:
                    src = possible_sources[0]
                    if src not in bulbs:
                        bulbs.add(src)
                        for seen in cell_visibility[src]:
                            if seen != src and seen not in bulbs:
                                no_bulb.add(seen)
                        changed = True

        # Check solved
        for r, c in numbered_cells:
            num = get_number(r, c)
            adj = get_adjacent_whites(r, c)
            adj_bulbs = [p for p in adj if p in bulbs]
            if len(adj_bulbs) != num:
                break
        else:
            illuminated = set()
            for b in bulbs:
                illuminated.update(cell_visibility[b])
            if len(illuminated) == len(white_cells):
                return bulbs

        # Find next cell to branch
        best_cell = None
        best_priority = (float('inf'), float('inf'))

        for r, c in numbered_cells:
            num = get_number(r, c)
            adj = get_adjacent_whites(r, c)
            adj_bulbs = [p for p in adj if p in bulbs]
            adj_unknown = [p for p in adj if p not in bulbs and p not in no_bulb]
            remaining = num - len(adj_bulbs)
            if remaining > 0 and len(adj_unknown) > 0:
                priority = (len(adj_unknown), remaining)
                if priority < best_priority:
                    best_priority = priority
                    best_cell = adj_unknown[0]

        if best_cell is None:
            for r, c in white_cells:
                if (r, c) not in bulbs and (r, c) not in no_bulb:
                    best_cell = (r, c)
                    break

        if best_cell is None:
            return None

        br, bc = best_cell

        # Try bulb
        new_bulbs = set(bulbs)
        new_bulbs.add((br, bc))
        new_no_bulb = set(no_bulb)
        for seen in cell_visibility[(br, bc)]:
            if seen != (br, bc) and seen not in new_bulbs:
                new_no_bulb.add(seen)

        result = solve_recursive(new_bulbs, new_no_bulb, depth + 1)
        if result is not None:
            return result

        # Try no bulb
        new_no_bulb2 = set(no_bulb)
        new_no_bulb2.add((br, bc))
        return solve_recursive(bulbs, new_no_bulb2, depth + 1)

    result = solve_with_constraints()

    if result is None:
        return "No Solution"

    # Format output
    output = [[None for _ in range(m)] for _ in range(n)]
    for r, c in result:
        output[r][c] = 'B'

    return output

