    n = len(data)

    # Parse dots into sets for quick lookup
    h_dots = set()  # horizontal dots: (r, c) means dot between (r,c) and (r,c+1)
    v_dots = set()  # vertical dots: (r, c) means dot between (r,c) and (r+1,c)

    for coord in adjacent:
        r, c = coord
        if r == int(r):  # horizontal gap
            h_dots.add((int(r), int(c - 0.5)))
        else:  # vertical gap
            v_dots.add((int(r - 0.5), int(c)))

    # Initialize grid and domains
    grid = [[0] * n for _ in range(n)]
    domains = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    # Apply given clues
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                val = data[r][c]
                grid[r][c] = val
                domains[r][c] = {val}

    def get_neighbors(r, c):
        """Get orthogonal neighbors with their relative position"""
        neighbors = []
        if r > 0: neighbors.append((r-1, c, 'up'))
        if r < n-1: neighbors.append((r+1, c, 'down'))
        if c > 0: neighbors.append((r, c-1, 'left'))
        if c < n-1: neighbors.append((r, c+1, 'right'))
        return neighbors

    def has_dot(r1, c1, r2, c2):
        """Check if there's a dot between two adjacent cells"""
        if r1 == r2:  # horizontal
            c = min(c1, c2)
            return (r1, c) in h_dots
        else:  # vertical
            r = min(r1, r2)
            return (r, c1) in v_dots

    def consecutive(a, b):
        return abs(a - b) == 1

    def propagate():
        """Constraint propagation using AC-3 style algorithm"""
        changed = True
        while changed:
            changed = False

            for r in range(n):
                for c in range(n):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Row constraint
                        for cc in range(n):
                            if cc != c and val in domains[r][cc]:
                                domains[r][cc].discard(val)
                                if len(domains[r][cc]) == 0:
                                    return False
                                changed = True
                        # Col constraint
                        for rr in range(n):
                            if rr != r and val in domains[rr][c]:
                                domains[rr][c].discard(val)
                                if len(domains[rr][c]) == 0:
                                    return False
                                changed = True

            # Adjacency constraints
            for r in range(n):
                for c in range(n):
                    for nr, nc, _ in get_neighbors(r, c):
                        dot = has_dot(r, c, nr, nc)
                        to_remove = set()
                        for v1 in domains[r][c]:
                            valid = False
                            for v2 in domains[nr][nc]:
                                if consecutive(v1, v2) == dot:
                                    valid = True
                                    break
                            if not valid:
                                to_remove.add(v1)
                        if to_remove:
                            domains[r][c] -= to_remove
                            if len(domains[r][c]) == 0:
                                return False
                            changed = True

            # Hidden singles in rows/cols
            for r in range(n):
                for val in range(1, n+1):
                    positions = [c for c in range(n) if val in domains[r][c]]
                    if len(positions) == 1:
                        c = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            for c in range(n):
                for val in range(1, n+1):
                    positions = [r for r in range(n) if val in domains[r][c]]
                    if len(positions) == 1:
                        r = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

        return True

    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        for r in range(n):
            for c in range(n):
                if len(domains[r][c]) != 1:
                    return False
        return True

    if is_solved():
        return [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]

    # Backtracking with MRV heuristic
    def select_unassigned():
        min_size = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                size = len(domains[r][c])
                if size > 1 and size < min_size:
                    min_size = size
                    best = (r, c)
        return best

    def copy_domains():
        return [[set(d) for d in row] for row in domains]

    def restore_domains(saved):
        nonlocal domains
        domains = saved

    def backtrack():
        if is_solved():
            return True

        cell = select_unassigned()
        if cell is None:
            return False

        r, c = cell
        values = sorted(domains[r][c], key=lambda v: -sum(
            1 for nr, nc, _ in get_neighbors(r, c) 
            if v in domains[nr][nc] and consecutive(v, next(iter(domains[nr][nc])) if len(domains[nr][nc])==1 else 0)
