            if not propagate():
                domains = copy_domains()
                for i in range(n):
                    for j in range(n):
                        domains[i][j] = saved[i][j].copy()
                continue

            if backtrack():
                return True

            domains = copy_domains()
            for i in range(n):
                for j in range(n):
                    domains[i][j] = saved[i][j].copy()

        return False

    if backtrack():
        return [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]
    else:
        return "No Solution"

