                if not (illuminated >> i) & 1:
                    unlit += 1
        score += unlit
        return -score  # higher score first

    undecided.sort(key=priority)

    # Precompute for each undecided cell: which numbers it affects
    cell_to_numbers = {}
    for cell in undecided:
        r, c = cell
        affected = []
        for (nr, nc), (req, neighs) in num_neighbors.items():
