                        break

                if valid_place:
                    res = search(idx + 1, new_bulbs, forbidden_set, new_illum)
                    if res is not None:
                        return res

        return None

    final_bulbs = search(0, bulbs, forbidden, illuminated)

    if final_bulbs is None:
        return "No Solution"

    # Build result
    result = [[None for _ in range(m)] for _ in range(n)]
    for r, c in final_bulbs:
        result[r][c] = 'B'
    return result

