    # Bitmask helpers
    def bit(x):
        return 1 << (x - 1)

    def get_candidates(r, c):
        if grid[r][c] != 0:
            return 0
        used = 0
        # Row
        for j in range(N):
            if grid[r][j] != 0:
                used |= bit(grid[r][j])
        # Col
        for i in range(N):
            if grid[i][c] != 0:
                used |= bit(grid[i][c])
        # Box
        br, bc = (r // R) * R, (c // C) * C
        for i in range(br, br + R):
            for j in range(bc, bc + C):
                if grid[i][j] != 0:
                    used |= bit(grid[i][j])
        return ((1 << N) - 1) & ~used

    # Find cell with minimum candidates (MRV heuristic)
    def find_mrv():
        min_count = N + 1
        best = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    cand = get_candidates(r, c)
                    count = bin(cand).count('1')
                    if count < min_count:
                        min_count = count
                        best = (r, c, cand)
                        if count == 1:
                            return best
        return best

    # Constraint propagation: naked singles, hidden singles
    def propagate():
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0:
                        cand = get_candidates(r, c)
                        if cand == 0:
                            return False  # Contradiction
                        # Naked single
                        if cand & (cand - 1) == 0:  # Power of 2
                            val = (cand.bit_length())
                            grid[r][c] = val
                            changed = True

            # Hidden singles in rows
            for r in range(N):
                for num in range(1, N + 1):
                    b = bit(num)
                    positions = []
                    for c in range(N):
                        if grid[r][c] == 0 and (get_candidates(r, c) & b):
                            positions.append(c)
                    if len(positions) == 1:
