                                        break
                                if found:
                                    break
                            if not found:
                                return False
        return True

    # Save state for backtracking
    def save_state():
        return [row[:] for row in grid]

    def load_state(state):
        for i in range(N):
            for j in range(N):
                grid[i][j] = state[i][j]

    # Recursive solver with constraint propagation
    def solve_recursive():
        if not propagate():
            return False

        mrv = find_mrv()
        if mrv is None:
            return True  # Solved

        r, c, cand = mrv
        if cand == 0:
            return False

        # Try each candidate
        nums = []
        temp = cand
        while temp:
            lsb = temp & -temp
            num = lsb.bit_length()
            nums.append(num)
            temp ^= lsb

        # Sort by constraint propagation effect (least constraining value)
        # Simple heuristic: try values that appear least in peers
        def score(num):
            count = 0
            # Row peers
            for j in range(N):
                if j != c and grid[r][j] == 0:
                    if get_candidates(r, j) & bit(num):
                        count += 1
            # Col peers
            for i in range(N):
                if i != r and grid[i][c] == 0:
                    if get_candidates(i, c) & bit(num):
                        count += 1
            # Box peers
            br, bc = (r // R) * R, (c // C) * C
            for i in range(br, br + R):
                for j in range(bc, bc + C):
                    if (i != r or j != c) and grid[i][j] == 0:
                        if get_candidates(i, j) & bit(num):
                            count += 1
            return count

        nums.sort(key=score)

        for num in nums:
            state = save_state()
            grid[r][c] = num
            if solve_recursive():
                return True
            load_state(state)

        return False

    if solve_recursive():
