                row_b = sum(1 for cc in range(m) if board[r][cc] == 'B')
                row_w = sum(1 for cc in range(m) if board[r][cc] == 'W')
                if row_b == req_row or row_w == req_row:
                    score += 10
                score += row_b + row_w

                # Col completion pressure
                col_b = sum(1 for rr in range(n) if board[rr][c] == 'B')
                col_w = sum(1 for rr in range(n) if board[rr][c] == 'W')
                if col_b == req_col or col_w == req_col:
                    score += 10
                score += col_b + col_w

                # Check for forced moves due to consecutive
                # Horizontal
                for dc in [-2, -1, 1, 2]:
                    nc = c + dc
                    if 0 <= nc < m and board[r][nc]:
                        score += 2

                # Vertical
                for dr in [-2, -1, 1, 2]:
                    nr = r + dr
                    if 0 <= nr < n and board[nr][c]:
                        score += 2

                if score > best_score:
                    best_score = score
                    best = (r, c)

        return best

