                    continue
                if w_count == req_row:
                    for c in blanks:
                        board[r][c] = 'B'
                        changed = True
                    continue

                # Check for forced by consecutive in row
                for c in blanks:
                    # Try B
                    board[r][c] = 'B'
                    valid_b = True
                    # Check consecutive
                    for cc in range(max(0, c-2), min(m-2, c)+1):
                        if board[r][cc] and board[r][cc+1] and board[r][cc+2]:
                            if board[r][cc] == board[r][cc+1] == board[r][cc+2]:
                                valid_b = False
                                break
                    # Check count
                    if sum(1 for cc in range(m) if board[r][cc] == 'B') > req_row:
                        valid_b = False

                    board[r][c] = 'W'
                    valid_w = True
                    for cc in range(max(0, c-2), min(m-2, c)+1):
                        if board[r][cc] and board[r][cc+1] and board[r][cc+2]:
                            if board[r][cc] == board[r][cc+1] == board[r][cc+2]:
                                valid_w = False
                                break
                    if sum(1 for cc in range(m) if board[r][cc] == 'W') > req_row:
                        valid_w = False

                    board[r][c] = None

                    if valid_b and not valid_w:
                        board[r][c] = 'B'
                        changed = True
                    elif valid_w and not valid_b:
                        board[r][c] = 'W'
                        changed = True

            if changed:
                if not is_valid_partial():
                    return False
                continue

            # Column propagation
            for c in range(m):
                blanks = [r for r in range(n) if board[r][c] is None]
                if not blanks:
                    continue

                b_count = sum(1 for r in range(n) if board[r][c] == 'B')
                w_count = sum(1 for r in range(n) if board[r][c] == 'W')

                if b_count == req_col:
                    for r in blanks:
                        board[r][c] = 'W'
                        changed = True
                    continue
                if w_count == req_col:
                    for r in blanks:
                        board[r][c] = 'B'
                        changed = True
                    continue

                for r in blanks:
                    board[r][c] = 'B'
                    valid_b = True
                    for rr in range(max(0, r-2), min(n-2, r)+1):
                        if board[rr][c] and board[rr+1][c] and board[rr+2][c]:
                            if board[rr][c] == board[rr+1][c] == board[rr+2][c]:
                                valid_b = False
                                break
                    if sum(1 for rr in range(n) if board[rr][c] == 'B') > req_col:
                        valid_b = False

                    board[r][c] = 'W'
                    valid_w = True
                    for rr in range(max(0, r-2), min(n-2, r)+1):
                        if board[rr][c] and board[rr+1][c] and board[rr+2][c]:
                            if board[rr][c] == board[rr+1][c] == board[rr+2][c]:
                                valid_w = False
                                break
                    if sum(1 for rr in range(n) if board[rr][c] == 'W') > req_col:
                        valid_w = False

                    board[r][c] = None

                    if valid_b and not valid_w:
                        board[r][c] = 'B'
                        changed = True
                    elif valid_w and not valid_b:
                        board[r][c] = 'W'
                        changed = True

            if changed and not is_valid_partial():
                return False

        return True

    def solve_recursive():
        # Check if complete
        if all(board[r][c] is not None for r in range(n) for c in range(m)):
            return is_complete_valid()

        # Propagate constraints
        if not propagate():
            return False

        if not is_valid_partial():
            return False

        # Check if complete after propagation
        if all(board[r][c] is not None for r in range(n) for c in range(m)):
            return is_complete_valid()

        # Get next cell
        cell = get_next_cell()
        if cell is None:
            return is_complete_valid()

        r, c = cell

        # Try values - prefer forced by constraints
        for val in ['B', 'W']:
            board[r][c] = val

            if is_valid_partial():
                # Save state
                saved = [[board[rr][cc] for cc in range(m)] for rr in range(n)]

                if solve_recursive():
                    return True

                # Restore
                for rr in range(n):
                    for cc in range(m):
                        board[rr][cc] = saved[rr][cc]

            board[r][c] = None

        return False

    if solve_recursive():
        return [[board[r][c] for c in range(m)] for r in range(n)]
    else:
        return "No Solution"

