OBSERVATION = {'row_black_runs': [[1], [3], [3], [4], [2]], 'col_black_runs': [[2, 1], [1, 2], [4], [2], [1]]}

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    rows = len(row_clues)
    cols = len(col_clues)

    # Grid: 0 = unknown, 1 = black, -1 = white
    grid = [[0] * cols for _ in range(rows)]

    def get_line_clue_fits(clue, line_len):
        """Generate all possible placements of clue in a line of given length."""
        if not clue:
            return [tuple([-1] * line_len)]

        num_runs = len(clue)
        min_len = sum(clue) + (num_runs - 1)  # minimum cells needed

        if min_len > line_len:
            return []

        slack = line_len - min_len
        results = []

        def place(pos, run_idx, current, prev_end):
            if run_idx == num_runs:
                # Fill rest with white
                remaining = [-1] * (line_len - len(current))
                results.append(tuple(current + remaining))
                return

            run_len = clue[run_idx]
            # Minimum start position (after previous run + gap)
            min_start = prev_end + 1 if prev_end >= 0 else 0

            # Maximum start position considering remaining slack
            remaining_runs = clue[run_idx + 1:]
            remaining_min = sum(remaining_runs) + len(remaining_runs) if remaining_runs else 0

            for start in range(min_start, line_len - run_len - remaining_min + 1):
                # Add gap if not first run
                new_current = current[:]
                if run_idx > 0:
                    gap_start = prev_end + 1
                    new_current.extend([-1] * (start - gap_start))

                # Place the run
                new_current.extend([1] * run_len)

                place(pos + 1, run_idx + 1, new_current, start + run_len - 1)

        place(0, 0, [], -2)
        return results

    def line_compatible(clue, line):
        """Check if a line is compatible with given clue."""
        # line: list of 0/1/-1 values
        # Check if we can still satisfy the clue
        n = len(line)

        # Simple check: count constraints
        black_count = sum(1 for x in line if x == 1)
        white_count = sum(1 for x in line if x == -1)
        total_black_needed = sum(clue)

        if black_count > total_black_needed:
            return False

        # Check run structure compatibility
        i = 0
        run_idx = 0
        while i < n:
            if line[i] == 1:
                # Start of a run
                run_len = 0
                while i < n and line[i] == 1:
                    run_len += 1
                    i += 1

                if run_idx >= len(clue):
                    return False  # Too many runs

                # If this run is complete (bounded by white or edge)
                right_bound = i >= n or line[i] == -1
                left_bound = i - run_len - 1 < 0 or line[i - run_len - 1] == -1

                if right_bound and left_bound:
                    # Complete run, must match clue exactly
                    if run_len != clue[run_idx]:
                        return False
                    run_idx += 1
                else:
                    # Incomplete run, check if it can still match
                    if run_len > clue[run_idx]:
                        return False
                    # Don't advance run_idx for incomplete runs
            else:
                i += 1

        # Check remaining black cells can form valid runs
        # This is a simplified check
        return True

    def propagate():
        """Propagate constraints until fixed point."""
        changed = True
        while changed:
            changed = False

            # Process rows
            for r in range(rows):
                line = grid[r]
                clue = row_clues[r]

                # Get all valid completions
                valid = []
                for placement in get_line_clue_fits(clue, cols):
                    compatible = True
                    for c in range(cols):
                        if line[c] == 1 and placement[c] != 1:
                            compatible = False
                            break
                        if line[c] == -1 and placement[c] != -1:
                            compatible = False
                            break
                    if compatible:
                        valid.append(placement)

                if not valid:
                    return False  # Contradiction

                # Find cells that are same in all valid placements
                for c in range(cols):
                    if line[c] == 0:
                        all_black = all(v[c] == 1 for v in valid)
                        all_white = all(v[c] == -1 for v in valid)
                        if all_black:
                            grid[r][c] = 1
                            changed = True
                        elif all_white:
                            grid[r][c] = -1
                            changed = True

            # Process columns
            for c in range(cols):
                line = [grid[r][c] for r in range(rows)]
                clue = col_clues[c]

                valid = []
                for placement in get_line_clue_fits(clue, rows):
                    compatible = True
                    for r in range(rows):
                        if line[r] == 1 and placement[r] != 1:
                            compatible = False
                            break
                        if line[r] == -1 and placement[r] != -1:
                            compatible = False
                            break
                    if compatible:
                        valid.append(placement)

                if not valid:
                    return False

                for r in range(rows):
                    if grid[r][c] == 0:
                        all_black = all(v[r] == 1 for v in valid)
                        all_white = all(v[r] == -1 for v in valid)
                        if all_black:
                            grid[r][c] = 1
                            changed = True
                        elif all_white:
                            grid[r][c] = -1
                            changed = True

        return True

    def is_complete():
        return all(grid[r][c] != 0 for r in range(rows) for c in range(cols))

    def solve_recursive(depth=0):
        if not propagate():
            return False

        if is_complete():
            return True

        # Find unknown cell with most constraints (minimum remaining values)
        best_r, best_c = -1, -1
        best_score = float('inf')

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    # Try both values and see which has more constraints
                    score = 0
                    # Prefer cells in dense regions
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != 0:
                                score += 1
                    if score < best_score:
                        best_score = score
                        best_r, best_c = r, c

        if best_r == -1:
            return False

        # Try black first (usually more constrained)
        for val in [1, -1]:
            saved = [row[:] for row in grid]
            grid[best_r][best_c] = val

            if solve_recursive(depth + 1):
                return True

            # Restore
            for r in range(rows):
                for c in range(cols):
                    grid[r][c] = saved[r][c]

        return False

    if solve_recursive():
        result = []
        for r in range(rows):
            row = []
            for c in range(cols):
                if grid[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    else:
        return "No Solution"

