TETROMINO_SHAPES = {
    'L': [(0,0), (1,0), (2,0), (2,1)],  # base shape, will generate rotations/reflections
    'I': [(0,0), (1,0), (2,0), (3,0)],
    'T': [(0,1), (1,0), (1,1), (1,2)],
    'S': [(0,1), (0,2), (1,0), (1,1)],
}

def generate_all_placements(shape, grid_rows, grid_cols):
    """Generate all unique rotations/reflections of a tetromino shape."""
    placements = set()
    # Generate all transformations
    transforms = []
    for flip in [False, True]:
        for rot in range(4):
            transforms.append((flip, rot))

    for flip, rot in transforms:
        transformed = list(shape)
        if flip:
            transformed = [(-r, c) for r, c in transformed]
        for _ in range(rot):
            transformed = [(-c, r) for r, c in transformed]
        # Normalize to origin
        min_r = min(r for r, c in transformed)
        min_c = min(c for r, c in transformed)
        normalized = tuple(sorted((r - min_r, c - min_c) for r, c in transformed))
        placements.add(normalized)

    return list(placements)

def get_all_tetromino_cells():
    """Precompute all tetromino placements for each type."""
    all_placements = {}
    for t_type, shape in TETROMINO_SHAPES.items():
        all_placements[t_type] = generate_all_placements(shape, 6, 6)
    return all_placements

ALL_PLACEMENTS = get_all_tetromino_cells()

def get_region_cells(grid):
    """Extract cells belonging to each region."""
    regions = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            regions[grid[r][c]].append((r, c))
    return dict(regions)

def get_valid_placements_for_region(region_cells, grid_rows, grid_cols):
    """Get all valid tetromino placements that fit entirely within a region."""
    region_set = set(region_cells)
    valid = defaultdict(list)  # type -> list of placements (set of cells)

    for t_type, placements in ALL_PLACEMENTS.items():
        for placement in placements:
            # Try placing at all possible offsets
            for dr in range(grid_rows):
                for dc in range(grid_cols):
                    cells = set((r + dr, c + dc) for r, c in placement)
                    if cells <= region_set and len(cells) == 4:
                        valid[t_type].append(frozenset(cells))
    return valid

def get_adjacent_regions(grid):
    """Find which regions are orthogonally adjacent."""
    rows, cols = len(grid), len(grid[0])
    adj = defaultdict(set)
    for r in range(rows):
        for c in range(cols):
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[r][c] != grid[nr][nc]:
                        adj[grid[r][c]].add(grid[nr][nc])
                        adj[grid[nr][nc]].add(grid[r][c])
    return adj

def check_no_2x2(shaded_grid):
    """Check that no 2x2 block is fully shaded."""
    rows, cols = len(shaded_grid), len(shaded_grid[0])
    for r in range(rows - 1):
        for c in range(cols - 1):
            if (shaded_grid[r][c] and shaded_grid[r][c+1] and 
                shaded_grid[r+1][c] and shaded_grid[r+1][c+1]):
                return False
    return True

def check_connected(shaded_cells, grid_rows, grid_cols):
    """Check if all shaded cells are orthogonally connected."""
    if len(shaded_cells) <= 1:
        return True
    start = next(iter(shaded_cells))
    visited = set([start])
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) in shaded_cells and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))
    return len(visited) == len(shaded_cells)

def solve(observation):
    grid = observation['data']
    rows, cols = len(grid), len(grid[0])

    # Get region information
    regions = get_region_cells(grid)
    region_ids = sorted(regions.keys())
    adj_regions = get_adjacent_regions(grid)

    # Precompute valid placements for each region
    region_placements = {}
    for rid in region_ids:
        region_placements[rid] = get_valid_placements_for_region(regions[rid], rows, cols)
        # If any region has no valid placements, no solution
        if not any(region_placements[rid].values()):
            return "No Solution"

    # Sort regions by fewest valid placements (most constrained first)
    def region_constraint_count(rid):
        count = 0
        for t_type, placements in region_placements[rid].items():
            count += len(placements)
        return count

    sorted_regions = sorted(region_ids, key=region_constraint_count)

    # Backtracking with constraint propagation
    solution = {}  # region_id -> (type, placement)
    used_types = {}  # region_id -> type
    shaded = set()  # all shaded cells

    def is_valid_partial():
