        for r1, t1 in used_types.items():
            for r2 in adj_regions.get(r1, set()):
                if r2 in used_types and used_types[r2] == t1:
                    return False
        # Check no 2x2 (only check newly added cells)
        return True

    def propagate_constraints():
        """Simple constraint propagation: remove placements that violate adjacency."""
        changed = True
        while changed:
            changed = False
            for rid in region_ids:
                if rid in solution:
                    continue
                # Remove placements that conflict with used adjacent types
                forbidden = set()
                for adj in adj_regions.get(rid, set()):
                    if adj in used_types:
                        forbidden.add(used_types[adj])

                new_placements = {}
                for t_type, placements in region_placements[rid].items():
                    if t_type in forbidden:
                        continue
                    new_placements[t_type] = placements

                if not any(new_placements.values()):
                    return False  # No valid placement

                # Check if any type is forced
                valid_types = [t for t, p in new_placements.items() if p]
                if len(valid_types) == 1 and len(new_placements[valid_types[0]]) == 1:
                    # Forced placement - could assign, but let's just check consistency
                    pass

                if len(valid_types) < len([t for t, p in region_placements[rid].items() if p]):
                    changed = True
                    region_placements[rid] = new_placements

        return True

    def backtrack(idx):
        if idx == len(sorted_regions):
            # Check global constraints
            if not check_connected(shaded, rows, cols):
                return False
            return True

        rid = sorted_regions[idx]
        if rid in solution:
            return backtrack(idx + 1)

        # Get valid types (not used by adjacent regions)
        forbidden = set()
        for adj in adj_regions.get(rid, set()):
            if adj in used_types:
                forbidden.add(used_types[adj])

        # Try each valid type and placement
        valid_types = [(t, p) for t, p in region_placements[rid].items() if t not in forbidden and p]
        # Sort by fewest placements
        valid_types.sort(key=lambda x: len(x[1]))

        for t_type, placements in valid_types:
            for placement in placements:
                # Check 2x2 constraint incrementally
                cells = set(placement)
                # Check if adding these cells creates any 2x2
                temp_shaded = shaded | cells
                valid_2x2 = True
                for (r, c) in cells:
                    for dr in [0, -1]:
                        for dc in [0, -1]:
                            nr, nc = r + dr, c + dc
                            if nr >= 0 and nc >= 0:
                                if all((nr + i, nc + j) in temp_shaded for i in [0,1] for j in [0,1]):
                                    valid_2x2 = False
                                    break
                        if not valid_2x2:
                            break
                    if not valid_2x2:
                        break

                if not valid_2x2:
                    continue

                # Apply
                solution[rid] = (t_type, placement)
                used_types[rid] = t_type
                shaded.update(cells)

                if backtrack(idx + 1):
                    return True

                # Backtrack
                del solution[rid]
                del used_types[rid]
                shaded.difference_update(cells)

        return False

    if not backtrack(0):
        return "No Solution"

    # Build result grid
    result = [[None for _ in range(cols)] for _ in range(rows)]
    for rid, (t_type, placement) in solution.items():
        for r, c in placement:
            result[r][c] = t_type

    return result

