def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Target counts (half black, half white)
    target_b_row = m // 2
    target_w_row = m - target_b_row
    target_b_col = n // 2
    target_w_col = n - target_b_col

    # Convert to mutable grid with 0=W, 1=B, -1=unknown
    # Also track fixed cells
    fixed = [[False] * m for _ in range(n)]
    state = [[-1] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                state[i][j] = 1
                fixed[i][j] = True
            elif grid[i][j] == 'W':
                state[i][j] = 0
                fixed[i][j] = True

    # Precompute all valid patterns for a row/column of given length
    def generate_valid_patterns(length, target_ones):
        patterns = []
        def gen(pos, ones, zeros, pat):
            if pos == length:
                if ones == target_ones and zeros == length - target_ones:
                    # Check no three consecutive
                    valid = True
                    for i in range(length - 2):
                        if pat[i] == pat[i+1] == pat[i+2]:
                            valid = False
                            break
                    if valid:
                        patterns.append(tuple(pat))
                return
            # Prune: check if we can still reach target
            remaining = length - pos
            if ones + remaining < target_ones or zeros + remaining < length - target_ones:
                return
            # Try 0
            if not (pos >= 2 and pat[-2] == pat[-1] == 0):
                pat.append(0)
                gen(pos + 1, ones, zeros + 1, pat)
                pat.pop()
            # Try 1
            if not (pos >= 2 and pat[-2] == pat[-1] == 1):
                pat.append(1)
                gen(pos + 1, ones + 1, zeros, pat)
                pat.pop()
        gen(0, 0, 0, [])
        return patterns

    row_patterns = generate_valid_patterns(m, target_b_row)
    col_patterns = generate_valid_patterns(n, target_b_col)

    # Filter patterns based on fixed cells
    def filter_patterns(patterns, fixed_vals):
        # fixed_vals: list of (pos, val) or just a list where -1 means unknown
        result = []
        for pat in patterns:
            match = True
            for i, fv in enumerate(fixed_vals):
                if fv != -1 and pat[i] != fv:
                    match = False
                    break
            if match:
                result.append(pat)
        return result

    # Get possible patterns for each row and column
    row_candidates = []
    for i in range(n):
        fixed_vals = [state[i][j] for j in range(m)]
        candidates = filter_patterns(row_patterns, fixed_vals)
        if len(candidates) == 0:
            return "No Solution"
        row_candidates.append(candidates)

