        # For each cell, find intersection of row and column possibilities
        for i in range(n):
            for j in range(m):
                if state[i][j] != -1:
                    continue

                # What values are possible from row patterns?
                row_vals = set()
                for pat in row_candidates[i]:
                    row_vals.add(pat[j])

                # What values are possible from col patterns?
                col_vals = set()
                for pat in col_candidates[j]:
                    col_vals.add(pat[i])

                # Intersection
                possible = row_vals & col_vals
                if len(possible) == 0:
                    return "No Solution"
                if len(possible) == 1:
                    val = possible.pop()
                    state[i][j] = val
                    fixed[i][j] = True
                    changed = True

                    # Filter row and column candidates
                    new_row_cand = [p for p in row_candidates[i] if p[j] == val]
                    if len(new_row_cand) == 0:
                        return "No Solution"
                    if len(new_row_cand) < len(row_candidates[i]):
                        row_candidates[i] = new_row_cand
                        changed = True

                    new_col_cand = [p for p in col_candidates[j] if p[i] == val]
                    if len(new_col_cand) == 0:
                        return "No Solution"
                    if len(new_col_cand) < len(col_candidates[j]):
                        col_candidates[j] = new_col_cand
                        changed = True

        # Check for rows/columns with only one candidate
        for i in range(n):
