                        changed = True
                        # Update row candidates
                        new_row_cand = [p for p in row_candidates[i] if p[j] == pat[i]]
                        if len(new_row_cand) > 0 and len(new_row_cand) < len(row_candidates[i]):
                            row_candidates[i] = new_row_cand
                            changed = True

    # Check if solved
    if all(state[i][j] != -1 for i in range(n) for j in range(m)):
        # Verify all constraints
