            cols_used.add(col_tup)

        # Convert to output format
        result = []
        for i in range(n):
            row = []
            for j in range(m):
                row.append('B' if state[i][j] == 1 else 'W')
            result.append(row)
        return result

    # Need backtracking - use most constrained variable
    def backtrack(state, row_cand, col_cand, fixed):
        # Find first unassigned cell
        best_i, best_j = -1, -1
        min_options = float('inf')

        for i in range(n):
            for j in range(m):
                if state[i][j] == -1:
