                rows_used.add(row_tup)
            for j in range(m):
                col_tup = tuple(state[i][j] for i in range(n))
                if col_tup in cols_used:
                    return None
                cols_used.add(col_tup)
            return [row[:] for row in state]

        i, j = best_i, best_j

        # Try each possible value
        for pat in row_cand[i]:
            val = pat[j]
            # Check column compatibility
            compatible = False
            for cpat in col_cand[j]:
                if cpat[i] == val:
                    compatible = True
                    break
            if not compatible:
