            old_col_cand = col_cand[j]
            new_row_cand = [p for p in row_cand[i] if p[j] == val]
            new_col_cand = [p for p in col_cand[j] if p[i] == val]

            if len(new_row_cand) == 0 or len(new_col_cand) == 0:
                state[i][j] = old_state
                continue

            row_cand[i] = new_row_cand
            col_cand[j] = new_col_cand

            # Propagate constraints
            # Simple propagation
            prop_changed = True
            valid = True
            while prop_changed and valid:
                prop_changed = False
