                        break

            if valid:
                result = backtrack(state, row_cand, col_cand, fixed)
                if result is not None:
                    return result

            # Restore
            state[i][j] = old_state
            row_cand[i] = old_row_cand
            col_cand[j] = old_col_cand

            # Restore propagated cells
            for ii in range(n):
                for jj in range(m):
                    if not fixed[ii][jj] and (ii != i or jj != j):
                        # Need to restore - but we don't track what was set
