    # Deep copy for backtracking
    import copy
    state_copy = copy.deepcopy(state)
    row_cand_copy = [list(c) for c in row_candidates]
    col_cand_copy = [list(c) for c in col_candidates]

    result = backtrack(state_copy, row_cand_copy, col_cand_copy, fixed)

    if result is None:
