                    if adjtype == rtype:
                        return False
        return True

    def check_no_2x2(assignment, n, m):
        # Check no 2x2 block is fully shaded
        shaded = set()
        for rid, (rtype, rplace) in assignment.items():
            for cell in rplace:
                shaded.add(cell)

        for r in range(n-1):
            for c in range(m-1):
                if ((r,c) in shaded and (r+1,c) in shaded and 
                    (r,c+1) in shaded and (r+1,c+1) in shaded):
                    return False
        return True

    def check_global_connected(assignment, n, m):
        # Check all shaded cells are connected
        shaded = set()
        for rid, (rtype, rplace) in assignment.items():
            for cell in rplace:
                shaded.add(cell)

        if not shaded:
            return True

        # BFS from one cell
        start = next(iter(shaded))
        visited = {start}
        queue = deque([start])

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in shaded and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(shaded)

    # Order regions by constraint tightness (fewest placements first)
    def region_score(rid):
        total = sum(len(region_placements[rid][t]) for t in ['L', 'I', 'T', 'S'])
        return total

    ordered_regions = sorted(regions, key=region_score)
    region_index = {r: i for i, r in enumerate(ordered_regions)}

    # Precompute for each region and type, which placements
    # Forward checking: for unassigned adjacent regions, track available types

    def solve_recursive(assignment, remaining_regions):
        if len(assignment) == num_regions:
            # Check global constraints
            if check_no_2x2(assignment, n, m) and check_global_connected(assignment, n, m):
                return assignment
            return None

        # Pick region with fewest options (MRV)
        best_rid = None
        best_options = None
        best_count = float('inf')

        for rid in remaining_regions:
            if rid in assignment:
                continue
            # Count valid options given current assignment
            options = []
            for ttype in ['L', 'I', 'T', 'S']:
                # Check adjacency with assigned neighbors
                conflict = False
                for adj in region_adj[rid]:
                    if adj in assignment:
                        adjtype, _ = assignment[adj]
                        if adjtype == ttype:
                            conflict = True
                            break
                if conflict:
                    continue
                for place in region_placements[rid][ttype]:
                    options.append((rid, ttype, place))

            if len(options) < best_count:
                best_count = len(options)
                best_rid = rid
                best_options = options

        if best_rid is None or best_count == 0:
            return None

        new_remaining = remaining_regions - {best_rid}

        for rid, ttype, place in best_options:
            assignment[rid] = (ttype, place)

            # Early pruning: check no 2x2 with current assignment
            if not check_no_2x2(assignment, n, m):
                del assignment[rid]
                continue

            # Early pruning: check connectivity can still be satisfied (weak check)
            # Only check full connectivity at end

            result = solve_recursive(assignment, new_remaining)
            if result is not None:
                return result

            del assignment[rid]

        return None

    # Try solving
    result = solve_recursive(set(), set(regions))

    if result is None:
        # Try with different strategy - maybe need to check connectivity more carefully
        # Fall back to more thorough search
        result = solve_recursive({}, set(regions))

    if result is None:
        return "No Solution"

    # Build answer grid
    answer = [[None for _ in range(m)] for _ in range(n)]
    for rid, (ttype, place) in result.items():
        for r, c in place:
            answer[r][c] = ttype

    return answer

