# Human-like Nurikabe/Tents-like solver with constraint propagation
# Key insight: Each numbered cell constrains its 3x3 neighborhood's black count

from collections import deque

def solve(observation):
    grid = observation['data']
    n_rows = len(grid)
    n_cols = len(grid[0]) if n_rows > 0 else 0

    # State: 0 = unknown, 1 = black, 2 = white
    state = [[0] * n_cols for _ in range(n_rows)]

    # Precompute which cells have number constraints
    numbered = {}
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] is not None:
                numbered[(r, c)] = grid[r][c]

    def get_neighbors(r, c):
        """Get all cells in 3x3 neighborhood centered at (r,c)"""
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n_rows and 0 <= nc < n_cols:
                    neighbors.append((nr, nc))
        return neighbors

    def count_in_neighborhood(r, c, target_state):
        """Count cells with target_state in 3x3 neighborhood of (r,c)"""
        count = 0
        for nr, nc in get_neighbors(r, c):
            if state[nr][nc] == target_state:
                count += 1
        return count

    def get_unknown_in_neighborhood(r, c):
        """Get list of unknown cells in 3x3 neighborhood"""
        return [(nr, nc) for nr, nc in get_neighbors(r, c) if state[nr][nc] == 0]

    # Constraint propagation queue
    queue = deque()

    # Initialize queue with all numbered cells
    for (r, c) in numbered:
        queue.append(('num', r, c))

    # Also add cells that might be affected by propagation
    def add_affected(r, c):
        """Add all numbered cells whose neighborhood contains (r,c)"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in numbered:
                    queue.append(('num', nr, nc))

    changed = True
    iterations = 0
    max_iter = 10000

    while changed and iterations < max_iter:
        changed = False
        iterations += 1

        # Process all current constraints
        while queue and iterations < max_iter:
            qtype, r, c = queue.popleft()

            if qtype == 'num':
                if (r, c) not in numbered:
                    continue
                target = numbered[(r, c)]
                black_count = count_in_neighborhood(r, c, 1)
                white_count = count_in_neighborhood(r, c, 2)
                unknown = get_unknown_in_neighborhood(r, c)
                total_cells = len(get_neighbors(r, c))

                # If already satisfied, all unknown must be white
                if black_count == target:
                    for nr, nc in unknown:
                        if state[nr][nc] == 0:
                            state[nr][nc] = 2
                            changed = True
                            add_affected(nr, nc)
                    continue

                # If impossible to satisfy
                if black_count > target:
                    return "No Solution"

                remaining = target - black_count
                # If we need exactly as many blacks as unknowns, all unknown become black
                if remaining == len(unknown):
                    for nr, nc in unknown:
                        if state[nr][nc] == 0:
                            state[nr][nc] = 1
                            changed = True
                            add_affected(nr, nc)
                    continue

                # If impossible to reach target
                if remaining > len(unknown):
                    return "No Solution"

                # If all remaining cells must be black to have enough room for whites
                # Actually, check if we need to force some whites
                # If black_count + len(unknown) == target, we already handled above
                # If we need to check: can we still satisfy?

            # Additional: check if a cell being black/white would violate any constraint
            # This is handled by propagation from numbered cells

        # Additional deduction: for each unknown cell, try both possibilities
        # and see if one leads to immediate contradiction
        if not changed:
            # Find cells to test
            for r in range(n_rows):
                for c in range(n_cols):
                    if state[r][c] != 0:
                        continue

                    # Try black
                    test_black = True
                    # Check all numbered neighborhoods containing (r,c)
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            nr, nc = r + dr, c + dc
                            if (nr, nc) in numbered:
                                target = numbered[(nr, nc)]
                                curr_black = count_in_neighborhood(nr, nc, 1)
                                if curr_black + 1 > target:  # Would exceed
                                    test_black = False
                                    break
                        if not test_black:
                            break

                    # Try white  
                    test_white = True
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            nr, nc = r + dr, c + dc
                            if (nr, nc) in numbered:
                                target = numbered[(nr, nc)]
                                curr_black = count_in_neighborhood(nr, nc, 1)
                                curr_unknown = len(get_unknown_in_neighborhood(nr, nc))
                                # If this is the last unknown and we still need more blacks
                                if curr_unknown == 1 and curr_black < target:
                                    test_white = False
                                    break
                        if not test_white:
                            break

                    if test_black and not test_white:
