def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    n = len(data)

    # Parse adjacency constraints
    # horizontal_adj[r][c] = True if dot between (r,c) and (r,c+1)
    # vertical_adj[r][c] = True if dot between (r,c) and (r+1,c)
    horizontal_adj = [[False] * (n-1) for _ in range(n)]
    vertical_adj = [[False] * n for _ in range(n-1)]

    for coord in adjacent:
        r, c = coord
        if r == int(r):  # horizontal gap
            horizontal_adj[int(r)][int(c-0.5)] = True
        else:  # vertical gap
            vertical_adj[int(r-0.5)][int(c)] = True

    # Initialize domains: possible values for each cell
    domains = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    # Apply given clues
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def get_neighbors(r, c):
        """Get all orthogonal neighbors with their adjacency status"""
        neighbors = []
        # Up
        if r > 0:
            is_adj = vertical_adj[r-1][c]
            neighbors.append((r-1, c, is_adj))
        # Down
        if r < n-1:
            is_adj = vertical_adj[r][c]
            neighbors.append((r+1, c, is_adj))
        # Left
        if c > 0:
            is_adj = horizontal_adj[r][c-1]
            neighbors.append((r, c-1, is_adj))
        # Right
        if c < n-1:
            is_adj = horizontal_adj[r][c]
            neighbors.append((r, c+1, is_adj))
        return neighbors

    def consecutive(a, b):
        return abs(a - b) == 1

    def propagate(domains):
        """Constraint propagation using AC-3 like algorithm"""
        changed = True
        while changed:
            changed = False
            for r in range(n):
                for c in range(n):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Row constraint: remove val from other cells in row
                        for cc in range(n):
                            if cc != c and val in domains[r][cc]:
                                if len(domains[r][cc]) == 1:
                                    return False  # Contradiction
                                domains[r][cc].remove(val)
                                changed = True
                        # Column constraint: remove val from other cells in col
                        for rr in range(n):
                            if rr != r and val in domains[rr][c]:
                                if len(domains[rr][cc]) == 1:
                                    return False
                                domains[rr][c].remove(val)
                                changed = True

                    # Adjacency constraints
                    for nr, nc, is_adj in get_neighbors(r, c):
                        new_domain = set()
                        for v in domains[r][c]:
                            has_valid = False
                            for nv in domains[nr][nc]:
                                if is_adj == consecutive(v, nv):
                                    has_valid = True
                                    break
                            if has_valid:
                                new_domain.add(v)
                        if len(new_domain) < len(domains[r][c]):
                            if len(new_domain) == 0:
                                return False
                            domains[r][c] = new_domain
                            changed = True
        return True

    def is_valid_partial(domains):
        """Check if current state is valid (no empty domains)"""
        for r in range(n):
            for c in range(n):
                if len(domains[r][c]) == 0:
                    return False
        return True

    def is_solved(domains):
        """Check if puzzle is solved (all cells have single value)"""
        for r in range(n):
            for c in range(n):
                if len(domains[r][c]) != 1:
                    return False
        return True

    def copy_domains(domains):
        return [[set(domains[r][c]) for c in range(n)] for r in range(n)]

    def select_unassigned(domains):
        """Select cell with minimum remaining values (MRV heuristic)"""
        min_size = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best = (r, c)
        return best

    def check_adjacency_satisfied(domains):
        """Verify all adjacency constraints are satisfied"""
        for r in range(n):
            for c in range(n):
                val = next(iter(domains[r][c]))
                for nr, nc, is_adj in get_neighbors(r, c):
                    nval = next(iter(domains[nr][nc]))
                    if is_adj != consecutive(val, nval):
                        return False
        return True

    def backtrack(domains):
        """Backtracking search with constraint propagation"""
        if not is_valid_partial(domains):
            return None

        # Deep copy and propagate
        dom = copy_domains(domains)
        if not propagate(dom):
            return None

        if is_solved(dom):
            if check_adjacency_satisfied(dom):
                return dom
            return None

        var = select_unassigned(dom)
        if var is None:
            return None

        r, c = var

        # Try values in order (could use degree heuristic for ordering)
        for val in sorted(domains[r][c]):
            dom_copy = copy_domains(dom)
            dom_copy[r][c] = {val}
            result = backtrack(dom_copy)
            if result is not None:
                return result

        return None

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    # Solve
    solution = backtrack(domains)

    if solution is None:
        return "No Solution"

    # Format output
    result = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(next(iter(solution[r][c])))
        result.append(row)

    return result

