def solve(observation):
    data = observation['data']
    unit_str = observation['unit']

    # Parse unit
    if 'x' in unit_str:
        parts = unit_str.split('x')
        r_unit, c_unit = int(parts[0]), int(parts[1])
    else:
        r_unit = c_unit = int(unit_str)

    n = r_unit * c_unit
    grid = [row[:] for row in data]

    # Helper functions
    def get_subgrid_start(row, col):
        return (row // r_unit) * r_unit, (col // c_unit) * c_unit

    def get_possible(row, col):
        if grid[row][col] is not None:
            return set()

        used = set()
        # Row
        for c in range(n):
            if grid[row][c] is not None:
                used.add(grid[row][c])
        # Col
        for r in range(n):
            if grid[r][col] is not None:
                used.add(grid[r][col])
        # Subgrid
        sr, sc = get_subgrid_start(row, col)
        for r in range(sr, sr + r_unit):
            for c in range(sc, sc + c_unit):
                if grid[r][c] is not None:
                    used.add(grid[r][c])

        return set(range(1, n + 1)) - used

    # Constraint propagation: naked singles, hidden singles
    def propagate():
        changed = True
        while changed:
            changed = False

            # Naked singles
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is None:
                        poss = get_possible(r, c)
                        if len(poss) == 0:
                            return False  # Contradiction
                        if len(poss) == 1:
                            grid[r][c] = poss.pop()
                            changed = True

            # Hidden singles in rows
            for r in range(n):
                for num in range(1, n + 1):
                    positions = []
                    for c in range(n):
                        if grid[r][c] is None and num in get_possible(r, c):
                            positions.append(c)
                    if len(positions) == 1:
                        grid[r][positions[0]] = num
                        changed = True
                    elif len(positions) == 0:
                        # Check if already placed
                        found = False
                        for c in range(n):
                            if grid[r][c] == num:
                                found = True
                                break
                        if not found:
                            return False

            # Hidden singles in columns
            for c in range(n):
                for num in range(1, n + 1):
                    positions = []
                    for r in range(n):
                        if grid[r][c] is None and num in get_possible(r, c):
                            positions.append(r)
                    if len(positions) == 1:
                        grid[positions[0]][c] = num
                        changed = True
                    elif len(positions) == 0:
                        found = False
                        for r in range(n):
                            if grid[r][c] == num:
                                found = True
                                break
                        if not found:
                            return False

            # Hidden singles in subgrids
            for sr in range(0, n, r_unit):
                for sc in range(0, n, c_unit):
                    for num in range(1, n + 1):
                        positions = []
                        for r in range(sr, sr + r_unit):
                            for c in range(sc, sc + c_unit):
                                if grid[r][c] is None and num in get_possible(r, c):
                                    positions.append((r, c))
                        if len(positions) == 1:
                            grid[positions[0][0]][positions[0][1]] = num
                            changed = True
                        elif len(positions) == 0:
                            found = False
                            for r in range(sr, sr + r_unit):
                                for c in range(sc, sc + c_unit):
                                    if grid[r][c] == num:
                                        found = True
                                        break
                                if found:
                                    break
                            if not found:
                                return False

        return True

    # Find cell with minimum candidates (MRV heuristic)
    def find_mrv():
        min_poss = None
        best_cell = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    poss = get_possible(r, c)
                    if len(poss) == 0:
                        return None, None  # Dead end
                    if min_poss is None or len(poss) < len(min_poss):
                        min_poss = poss
                        best_cell = (r, c)
                        if len(min_poss) == 1:
                            return best_cell, min_poss
        return best_cell, min_poss

    # Recursive solver with backtracking
    def solve_recursive():
        # First propagate constraints
        if not propagate():
            return False

        # Check if solved
        cell, poss = find_mrv()
        if cell is None:
            return True  # All filled

        r, c = cell

        # Try each candidate
        for num in sorted(poss):  # Sort for determinism
            # Save state
            old_grid = [row[:] for row in grid]

            grid[r][c] = num

            if solve_recursive():
                return True

            # Backtrack
            for i in range(n):
                grid[i] = old_grid[i][:]

        return False

    if solve_recursive():
        return grid
    else:
        return "No Solution"

