                            opp = 'W' if row[i] == 'B' else 'B'
                            if not would_cause_three_consecutive(r, i-1, opp):
                                board[r][i-1] = opp
                                changed = True
                        # Right neighbor
                        if i + 2 < m and row[i+2] is None:
                            opp = 'W' if row[i] == 'B' else 'B'
                            if not would_cause_three_consecutive(r, i+2, opp):
                                board[r][i+2] = opp
                                changed = True

            for c in range(m):
                col = get_col(c)
                for i in range(n - 1):
                    if col[i] is not None and col[i] == col[i+1]:
                        # Top neighbor
                        if i > 0 and col[i-1] is None:
                            opp = 'W' if col[i] == 'B' else 'B'
                            if not would_cause_three_consecutive(i-1, c, opp):
                                board[i-1][c] = opp
                                changed = True
                        # Bottom neighbor
                        if i + 2 < n and col[i+2] is None:
                            opp = 'W' if col[i] == 'B' else 'B'
                            if not would_cause_three_consecutive(i+2, c, opp):
                                board[i+2][c] = opp
                                changed = True

            # Check row/column completion - if all but one filled, determine last
            for r in range(n):
                b_count = count_in_row(r, 'B')
                w_count = count_in_row(r, 'W')
                empty = m - b_count - w_count
                if empty == 1:
                    for c in range(m):
                        if board[r][c] is None:
                            if b_count < target_black_row:
                                board[r][c] = 'B'
                            else:
                                board[r][c] = 'W'
                            changed = True
                            break

            for c in range(m):
                b_count = count_in_col(c, 'B')
                w_count = count_in_col(c, 'W')
                empty = n - b_count - w_count
                if empty == 1:
                    for r in range(n):
                        if board[r][c] is None:
                            if b_count < target_black_col:
                                board[r][c] = 'B'
                            else:
                                board[r][c] = 'W'
                            changed = True
                            break

            if not is_valid_partial():
                return False

        return True

    # Backtracking with constraint propagation
    def backtrack():
        if is_complete():
            return is_valid_complete()

        # Propagate constraints
        if not propagate():
            return False

        if is_complete():
            return is_valid_complete()

        # Find most constrained cell (fewest valid options)
        best_r, best_c = -1, -1
        best_options = []

        for r in range(n):
            for c in range(m):
                if board[r][c] is not None:
                    continue

                options = []
                for val in ['B', 'W']:
                    if would_cause_three_consecutive(r, c, val):
                        continue
                    if val == 'B':
                        if count_in_row(r, 'B') >= target_black_row or count_in_col(c, 'B') >= target_black_col:
                            continue
                    else:
                        if count_in_row(r, 'W') >= target_white_row or count_in_col(c, 'W') >= target_white_col:
                            continue
                    options.append(val)

                if len(options) == 0:
                    return False

                if best_r == -1 or len(options) < len(best_options):
                    best_r, best_c = r, c
                    best_options = options
                    if len(options) == 1:
                        break
            if best_options and len(best_options) == 1:
                break

        if best_r == -1:
            return is_valid_complete()

        # Try each option
        for val in best_options:
            old_board = [row[:] for row in board]
            board[best_r][best_c] = val

            if is_valid_partial():
                if backtrack():
                    return True

            # Restore
            for r in range(n):
                for c in range(m):
                    board[r][c] = old_board[r][c]

        return False

    if backtrack():
        return board
    else:
        return "No Solution"

