from collections import defaultdict, deque

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Find all islands
    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(m):
            if grid[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, grid[r][c]))

    num_islands = len(islands)
    if num_islands == 0:
        return "{}"

    # Precompute possible connections (horizontal and vertical neighbors)
    # For each island, find islands in same row to left/right and same col up/down
    connections = []  # list of (i1, i2, direction) where direction is 0=horiz, 1=vert

    # Group by row and column
    row_islands = defaultdict(list)  # row -> list of (col, idx)
    col_islands = defaultdict(list)  # col -> list of (row, idx)

    for idx, (r, c, val) in enumerate(islands):
        row_islands[r].append((c, idx))
        col_islands[c].append((r, idx))

    # Sort and find adjacent pairs
    adjacency = [[] for _ in range(num_islands)]  # adjacency[i] = list of (j, direction, cells_between)

    for r in row_islands:
        row_islands[r].sort()
        for i in range(len(row_islands[r]) - 1):
            c1, idx1 = row_islands[r][i]
            c2, idx2 = row_islands[r][i + 1]
            # Check if path is clear (no islands between)
            blocked = False
            for cc in range(c1 + 1, c2):
                if grid[r][cc] is not None:
                    blocked = True
                    break
            if not blocked:
                adjacency[idx1].append((idx2, 0, c2 - c1 - 1))  # 0 = horizontal
                adjacency[idx2].append((idx1, 0, c2 - c1 - 1))

    for c in col_islands:
        col_islands[c].sort()
        for i in range(len(col_islands[c]) - 1):
            r1, idx1 = col_islands[c][i]
            r2, idx2 = col_islands[c][i + 1]
            blocked = False
            for rr in range(r1 + 1, r2):
                if grid[rr][c] is not None:
                    blocked = True
                    break
            if not blocked:
                adjacency[idx1].append((idx2, 1, r2 - r1 - 1))  # 1 = vertical
                adjacency[idx2].append((idx1, 1, r2 - r1 - 1))

    # Normalize edge representation
    def edge_key(i, j):
        return (min(i, j), max(i, j))

    # Build edge list
    edges_set = set()
    for i in range(num_islands):
        for j, _, _ in adjacency[i]:
            edges_set.add(edge_key(i, j))
    edges = sorted(edges_set)
    edge_idx = {e: i for i, e in enumerate(edges)}
    num_edges = len(edges)

    # For each island, which edges connect to it
    island_edges = [[] for _ in range(num_islands)]
    for ei, (i, j) in enumerate(edges):
        island_edges[i].append(ei)
        island_edges[j].append(ei)

    # Target degrees
    target = [islands[i][2] for i in range(num_islands)]

    # State: bridges[ei] = 0, 1, or 2
    # We use constraint propagation + backtracking

    # Precompute which edges cross (for constraint checking)
    def get_edge_cells(e):
        i, j = e
        r1, c1, _ = islands[i]
        r2, c2, _ = islands[j]
        cells = []
        if r1 == r2:  # horizontal
            for c in range(min(c1, c2) + 1, max(c1, c2)):
                cells.append((r1, c))
        else:  # vertical
            for r in range(min(r1, r2) + 1, max(r1, r2)):
                cells.append((r, c1))
        return frozenset(cells)

    edge_cells = [get_edge_cells(e) for e in edges]

    # Check if two edges cross
    def edges_cross(ei, ej):
        if ei == ej:
            return False
        # Edges share an island -> don't cross
        i1, j1 = edges[ei]
        i2, j2 = edges[ej]
        if len({i1, j1, i2, j2}) < 4:
            return False
        # Check if cells intersect
        return len(edge_cells[ei] & edge_cells[ej]) > 0

    # Build crossing graph
    crosses = [[] for _ in range(num_edges)]
    for ei in range(num_edges):
        for ej in range(ei + 1, num_edges):
            if edges_cross(ei, ej):
                crosses[ei].append(ej)
                crosses[ej].append(ei)

    # Constraint propagation
    def propagate(bridges, remaining):
        # remaining[i] = remaining degree needed for island i
        changed = True
        while changed:
            changed = False
            for i in range(num_islands):
                if remaining[i] < 0:
                    return False  # invalid
                # Get edges that can still be increased
                possible = []
                fixed_sum = 0
                for ei in island_edges[i]:
                    if bridges[ei] == 0:
                        # Check if this edge can be used (doesn't cross used edges)
                        can_use = True
                        for ej in crosses[ei]:
                            if bridges[ej] > 0:
                                can_use = False
                                break
                        if can_use:
                            possible.append(ei)
                    else:
                        fixed_sum += bridges[ei]

                if fixed_sum > target[i]:
                    return False

                need = remaining[i]
                max_possible = fixed_sum + 2 * len(possible)

                if max_possible < need:
                    return False

                # If need equals fixed_sum, all possible must be 0
                if need == fixed_sum:
                    for ei in possible:
                        if bridges[ei] != 0:
                            return False  # should already be 0
                    continue

                # If need - fixed_sum == 2 * len(possible), all must be 2
                if need - fixed_sum == 2 * len(possible):
                    for ei in possible:
                        if bridges[ei] != 0:
                            return False
                        bridges[ei] = 2
                        # Check crossings
                        for ej in crosses[ei]:
                            if bridges[ej] > 0:
                                return False
                        changed = True
                    remaining[i] = 0
                    # Update neighbors
                    for ei in possible:
                        j = edges[ei][0] if edges[ei][1] == i else edges[ei][1]
                        remaining[j] -= 2
                    continue

                # If len(possible) == 1 and need - fixed_sum > 0
                if len(possible) == 1:
                    ei = possible[0]
                    val = need - fixed_sum
                    if val > 2:
                        return False
                    if bridges[ei] != 0 and bridges[ei] != val:
                        return False
                    if bridges[ei] == 0:
                        bridges[ei] = val
                        # Check crossings
                        for ej in crosses[ei]:
                            if bridges[ej] > 0:
                                return False
                        changed = True
                        j = edges[ei][0] if edges[ei][1] == i else edges[ei][1]
                        remaining[i] -= val
                        remaining[j] -= val
        return True

    def is_connected(bridges):
        # Check if all islands with bridges form connected component
        # Build adjacency
        adj = [[] for _ in range(num_islands)]
        for ei, b in enumerate(bridges):
            if b > 0:
                i, j = edges[ei]
                adj[i].append(j)
                adj[j].append(i)

        # Find first island with any bridge
        start = -1
        for i in range(num_islands):
            if len(adj[i]) > 0:
                start = i
                break

        if start == -1:
            return num_islands <= 1  # no bridges, only valid if single island

        visited = [False] * num_islands
        stack = [start]
        visited[start] = True
        count = 1
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    count += 1
                    stack.append(v)

        # Check all islands with degree > 0 are visited
        for i in range(num_islands):
            if len(adj[i]) > 0 and not visited[i]:
                return False
        return True

    def solve_recursive(bridges, remaining, idx):
        if idx == num_edges:
            # Check if all remaining are 0 and connected
            if any(r != 0 for r in remaining):
                return None
            if not is_connected(bridges):
                return None
            return list(bridges)

        # Skip if already set
        if bridges[idx] != 0:
            return solve_recursive(bridges, remaining, idx + 1)

        # Check if this edge can be used (crossing constraint)
        can_use = True
        for ej in crosses[idx]:
            if bridges[ej] > 0:
                can_use = False
                break

        # Try 0, 1, 2
        for val in ([0] if not can_use else [0, 2, 1]):
            # Optimization: try 2 before 1 if it helps satisfy constraints
            new_bridges = list(bridges)
            new_remaining = list(remaining)

            new_bridges[idx] = val
            if val > 0:
                i, j = edges[idx]
                new_remaining[i] -= val
                new_remaining[j] -= val

            # Propagate
            if not propagate(new_bridges, new_remaining):
                continue

            # Additional pruning: check if any island is impossible
            valid = True
            for ii in range(num_islands):
                # Max possible bridges for island ii
                max_pos = 0
                fixed = 0
                for ei in island_edges[ii]:
                    if new_bridges[ei] > 0:
                        fixed += new_bridges[ei]
                    elif new_bridges[ei] == 0:
                        # Check if can use
                        can = True
                        for ej in crosses[ei]:
                            if new_bridges[ej] > 0:
                                can = False
                                break
                        if can:
                            max_pos += 2

                if fixed > target[ii] or fixed + max_pos < new_remaining[ii]:
                    valid = False
                    break

            if not valid:
                continue

            result = solve_recursive(new_bridges, new_remaining, idx + 1)
            if result is not None:
                return result

        return None

    # Initial propagation
    initial_bridges = [0] * num_edges
    initial_remaining = list(target)

    if not propagate(initial_bridges, initial_remaining):
        return "{}"

    # Order edges by constraint (most constrained first)
    edge_priority = []
    for ei in range(num_edges):
        i, j = edges[ei]
        # Priority based on how constrained the endpoints are
        pri = -len(crosses[ei]) * 10 - abs(target[i] - target[j])
        edge_priority.append((pri, ei))
    edge_priority.sort()

    # Reorder edges
    new_order = [ei for _, ei in edge_priority]
    new_edges = [edges[ei] for ei in new_order]
    # Remap
    old_to_new = {old: new for new, old in enumerate(new_order)}

    # Rebuild structures
    edges = new_edges
    edge_idx = {e: i for i, e in enumerate(edges)}

    # Rebuild island_edges
    island_edges = [[] for _ in range(num_islands)]
    for ei, (i, j) in enumerate(edges):
        island_edges[i].append(ei)
        island_edges[j].append(ei)

    # Rebuild crosses
    new_crosses = [[] for _ in range(num_edges)]
    for old_ei in range(len(crosses)):
        new_ei = old_to_new[old_ei]
        for old_ej in crosses[old_ei]:
            new_ej = old_to_new[old_ej]
            new_crosses[new_ei].append(new_ej)
    crosses = new_crosses

    # Rebuild edge_cells
    edge_cells = [get_edge_cells(e) for e in edges]

    # Re-initialize
    initial_bridges = [0] * num_edges
    initial_remaining = list(target)

    if not propagate(initial_bridges, initial_remaining):
        return "{}"

    result = solve_recursive(initial_bridges, initial_remaining, 0)

    if result is None:
        return "{}"

    # Build answer
    ans = {}
    for ei, b in enumerate(result):
        if b > 0:
            i, j = edges[ei]
            p1 = islands[i][:2]
            p2 = islands[j][:2]
            ans[(p1, p2)] = b

    # Format as string
    items = []
    for (p1, p2), b in sorted(ans.items()):
        items.append(f"(({p1[0]}, {p1[1]}), ({p2[0]}, {p2[1]})): {b}")
    return "{" + ", ".join(items) + "}"

