from collections import defaultdict, deque

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Identify regions
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))

    regions = list(region_cells.keys())
    num_regions = len(regions)

    # Precompute adjacency between regions
    region_adj = defaultdict(set)
    for r in range(n):
        for c in range(m):
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[r][c] != grid[nr][nc]:
                        region_adj[grid[r][c]].add(grid[nr][nc])

    # Tetromino shapes (relative coordinates)
    # L: 3 in a line + 1 perpendicular at end
    L_shapes = [
        [(0, 0), (1, 0), (2, 0), (2, 1)],  # |_ shape
        [(0, 0), (0, 1), (0, 2), (1, 0)],  # L shape
        [(0, 0), (0, 1), (1, 1), (2, 1)],  # _| shape
        [(0, 2), (1, 0), (1, 1), (1, 2)],  # -| shape
        [(0, 0), (1, 0), (2, 0), (0, 1)],  # mirror |_ 
        [(0, 0), (1, 0), (1, 1), (1, 2)],  # mirror L
        [(0, 1), (1, 1), (2, 1), (2, 0)],  # mirror _|
        [(0, 0), (0, 1), (0, 2), (1, 2)],  # mirror -|
    ]

    # I: straight line of 4
    I_shapes = [
        [(0, 0), (0, 1), (0, 2), (0, 3)],
        [(0, 0), (1, 0), (2, 0), (3, 0)],
    ]

    # T: 3 in a line + 1 in middle perpendicular
    T_shapes = [
        [(0, 0), (0, 1), (0, 2), (1, 1)],
        [(0, 1), (1, 0), (1, 1), (1, 2)],
        [(0, 0), (1, 0), (2, 0), (1, 1)],
        [(0, 1), (1, 0), (1, 1), (2, 1)],
    ]

    # S: zigzag
    S_shapes = [
        [(0, 1), (0, 2), (1, 0), (1, 1)],
        [(0, 0), (1, 0), (1, 1), (2, 1)],
        [(0, 0), (0, 1), (1, 1), (1, 2)],
        [(0, 1), (1, 0), (1, 1), (2, 0)],
    ]

    tetromino_types = {
        'L': L_shapes,
        'I': I_shapes,
        'T': T_shapes,
        'S': S_shapes,
    }

    def get_all_placements(cells, shapes):
        """Get all valid placements of shapes within given cells."""
        cell_set = set(cells)
        placements = []
        for shape in shapes:
            # Try all offsets
            min_r = min(p[0] for p in shape)
            max_r = max(p[0] for p in shape)
            min_c = min(p[1] for p in shape)
            max_c = max(p[1] for p in shape)

            for dr in range(-min_r, n - max_r + 1):
                for dc in range(-min_c, m - max_c + 1):
                    placed = [(p[0] + dr, p[1] + dc) for p in shape]
                    if all(p in cell_set for p in placed):
                        placements.append(tuple(sorted(placed)))
        return list(set(placements))

    # Precompute placements for each region and type
    region_type_placements = {}
    for rid in regions:
        cells = region_cells[rid]
        for ttype in tetromino_types:
            placements = get_all_placements(cells, tetromino_types[ttype])
            region_type_placements[(rid, ttype)] = placements

    # Check if placement creates 2x2 shaded block
    def creates_2x2(shaded_set, new_cells):
        for r, c in new_cells:
            # Check all 2x2 squares containing this cell
            for sr in [r-1, r]:
                for sc in [c-1, c]:
                    if sr >= 0 and sc >= 0:
                        square = [(sr, sc), (sr+1, sc), (sr, sc+1), (sr+1, sc+1)]
                        if all((s in shaded_set or s in new_cells) for s in square):
                            return True
        return False

    # Check connectivity of shaded cells
    def is_connected(shaded_set):
        if len(shaded_set) <= 1:
            return True
        start = next(iter(shaded_set))
        visited = set([start])
        queue = deque([start])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in shaded_set and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == len(shaded_set)

    # Order regions by constraint tightness (fewest placements first)
    def region_priority(rid):
        total = 0
        for ttype in tetromino_types:
            total += len(region_type_placements.get((rid, ttype), []))
        return total

    sorted_regions = sorted(regions, key=region_priority)

    # Backtracking with constraint propagation
    solution = {}
    shaded_cells = set()

    def can_complete_connectivity(remaining_regions, current_shaded):
        """Quick check if remaining regions can connect the shaded component."""
        if not remaining_regions:
            return is_connected(current_shaded)

        # Find connected components of current shaded
        if len(current_shaded) == 0:
            return True  # Will be checked later

        # BFS from any shaded cell
        start = next(iter(current_shaded))
        visited = set([start])
        queue = deque([start])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in current_shaded and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        # Check if unvisited shaded exists (disconnected)
        if len(visited) != len(current_shaded):
            return False

        # Check if remaining regions can connect to current component
        # or if they form a connected structure themselves
        return True

    def backtrack(idx, used_types_per_region):
        if idx == num_regions:
            # Check final connectivity
            return is_connected(shaded_cells)

        rid = sorted_regions[idx]
        adj_regions = region_adj[rid]
        forbidden_types = set()
        for adj in adj_regions:
            if adj in used_types_per_region:
                forbidden_types.add(used_types_per_region[adj])

        # Try each valid type
        for ttype in ['I', 'L', 'T', 'S']:  # Order by simplicity
            if ttype in forbidden_types:
                continue

            placements = region_type_placements.get((rid, ttype), [])
            for placement in placements:
                new_cells = set(placement)

                # Check 2x2 constraint
                if creates_2x2(shaded_cells, new_cells):
                    continue

                # Apply placement
                solution[rid] = (ttype, placement)
                for cell in new_cells:
                    shaded_cells.add(cell)
                used_types_per_region[rid] = ttype

                # Early connectivity check - only if many regions placed
                if idx >= num_regions // 2:
                    if not can_complete_connectivity(sorted_regions[idx+1:], shaded_cells):
                        # Undo
                        for cell in new_cells:
                            shaded_cells.remove(cell)
                        del solution[rid]
                        del used_types_per_region[rid]
                        continue

                if backtrack(idx + 1, used_types_per_region):
                    return True

                # Undo
                for cell in new_cells:
                    shaded_cells.remove(cell)
                del solution[rid]
                del used_types_per_region[rid]

        return False

    if not backtrack(0, {}):
        return "No Solution"

    # Build result grid
    result = [[None for _ in range(m)] for _ in range(n)]
    for rid, (ttype, cells) in solution.items():
