from itertools import combinations

def solve(observation):
    row_sums = observation['row_sum']
    col_sums = observation['col_sum']
    n_rows = len(row_sums)
    n_cols = len(col_sums)

    # Weights: row i has weight i+1, col j has weight j+1
    row_weights = list(range(1, n_rows + 1))
    col_weights = list(range(1, n_cols + 1))

    # For each row, find all valid subsets of columns that sum to row_sums[i]
    # Each subset represents which columns have black cells in that row
    row_options = []
    for r in range(n_rows):
        target = row_sums[r]
        valid = []
        # Try all possible subsets of columns
        for size in range(n_cols + 1):
            for cols in combinations(range(n_cols), size):
                if sum(col_weights[c] for c in cols) == target:
                    valid.append(frozenset(cols))
        if not valid:
            return "No Solution"
        row_options.append(valid)

    # For each column, find all valid subsets of rows that sum to col_sums[j]
    col_options = []
    for c in range(n_cols):
        target = col_sums[c]
        valid = []
        for size in range(n_rows + 1):
            for rows in combinations(range(n_rows), size):
                if sum(row_weights[r] for r in rows) == target:
                    valid.append(frozenset(rows))
        if not valid:
            return "No Solution"
        col_options.append(valid)

    # Constraint propagation: iteratively filter options
    # A cell (r,c) is black iff c is in row r's chosen set AND r is in col c's chosen set

    def propagate():
        changed = True
        while changed:
            changed = False

            # For each row, filter options based on column constraints
            for r in range(n_rows):
                # Find which columns MUST be black in row r (present in all options)
                # and which CANNOT be black (present in no options)
                if len(row_options[r]) <= 1:
                    continue

                must_black = set(range(n_cols))
                cannot_black = set()

                for opt in row_options[r]:
                    must_black &= opt

                # Check column constraints to further limit
                new_options = []
                for opt in row_options[r]:
                    valid = True
                    for c in opt:
                        # Check if any col option for c contains r
                        if not any(r in co for co in col_options[c]):
                            valid = False
                            break
                    for c in range(n_cols):
                        if c not in opt:
                            # Check if all col options for c contain r (then r must be black)
                            if all(r in co for co in col_options[c]):
                                valid = False
                                break
                    if valid:
                        new_options.append(opt)

                if len(new_options) < len(row_options[r]):
                    row_options[r] = new_options
                    changed = True
                    if not row_options[r]:
                        return False

            # For each column, filter options based on row constraints
            for c in range(n_cols):
                if len(col_options[c]) <= 1:
                    continue

                new_options = []
                for opt in col_options[c]:
                    valid = True
                    for r in opt:
                        if not any(c in ro for ro in row_options[r]):
                            valid = False
                            break
                    for r in range(n_rows):
                        if r not in opt:
                            if all(c in ro for ro in row_options[r]):
                                valid = False
                                break
                    if valid:
                        new_options.append(opt)

                if len(new_options) < len(col_options[c]):
                    col_options[c] = new_options
                    changed = True
                    if not col_options[c]:
                        return False

        return True

    if not propagate():
        return "No Solution"

    # Backtracking search with constraint propagation
    solution = {}  # (r,c) -> bool (black or not)

    def is_consistent(r, c, is_black):
        # Check row constraint
        row_black_cols = {cc for cc in range(n_cols) if solution.get((r, cc), False) or (cc == c and is_black)}
        if not any(row_black_cols <= opt for opt in row_options[r]):
            return False

        # Check column constraint
        col_black_rows = {rr for rr in range(n_rows) if solution.get((rr, c), False) or (rr == r and is_black)}
        if not any(col_black_rows <= opt for opt in col_options[c]):
            return False

        return True

    def select_unassigned():
        # MRV heuristic: select cell with fewest valid options
        min_options = float('inf')
        best = None
        for r in range(n_rows):
            for c in range(n_cols):
                if (r, c) in solution:
                    continue
                # Count valid assignments
                valid = 0
                for val in [True, False]:
                    if is_consistent(r, c, val):
                        valid += 1
                if valid < min_options:
                    min_options = valid
                    best = (r, c)
                if valid == 0:
                    return None
        return best

    def backtrack():
        cell = select_unassigned()
        if cell is None:
            # All assigned, verify solution
            return verify_solution()
        if cell is None:
            return False

        r, c = cell

        # Try black first (usually more constrained)
        for is_black in [True, False]:
            if is_consistent(r, c, is_black):
                solution[(r, c)] = is_black
                if backtrack():
                    return True
                del solution[(r, c)]

        return False

    def verify_solution():
        # Verify all rows
        for r in range(n_rows):
            black_cols = {c for c in range(n_cols) if solution.get((r, c), False)}
            if black_cols not in row_options[r]:
                return False

        # Verify all columns
        for c in range(n_cols):
            black_rows = {r for r in range(n_rows) if solution.get((r, c), False)}
            if black_rows not in col_options[c]:
                return False

        return True

    if not backtrack():
        return "No Solution"

    # Format output
    grid = []
    for r in range(n_rows):
        row = []
        for c in range(n_cols):
            row.append('B' if solution.get((r, c), False) else None)
        grid.append(row)

    return grid

