# Tetromino puzzle solver with human-like deduction

from collections import defaultdict, deque

TETROMINOES = {
    'L': [(0,0), (1,0), (2,0), (2,1)],  # and rotations/reflections
    'I': [(0,0), (1,0), (2,0), (3,0)],  # and rotations
    'T': [(0,0), (0,1), (0,2), (1,1)],  # and rotations
    'S': [(0,1), (0,2), (1,0), (1,1)],  # and rotations/reflections (Z included)
}

def get_all_shapes(base_shape):
    """Generate all rotations and reflections of a base shape."""
    shapes = set()
    shape = tuple(sorted(base_shape))
    shapes.add(shape)

    # Generate rotations and reflections
    for _ in range(4):  # 4 rotations
        new_shapes = set()
        for s in shapes:
            # Rotate 90: (r, c) -> (c, -r)
            rotated = tuple(sorted((c, -r) for r, c in s))
            new_shapes.add(rotated)
            # Reflect: (r, c) -> (r, -c)
            reflected = tuple(sorted((r, -c) for r, c in s))
            new_shapes.add(reflected)
        shapes.update(new_shapes)

    # Normalize: translate to origin (min row=0, min col=0)
    result = []
    for s in shapes:
        min_r = min(r for r, c in s)
        min_c = min(c for r, c in s)
        normalized = tuple(sorted((r - min_r, c - min_c) for r, c in s))
        result.append(normalized)

    return list(set(result))

# Precompute all shape variations
SHAPE_VARIATIONS = {}
for name, base in TETROMINOES.items():
    SHAPE_VARIATIONS[name] = get_all_shapes(base)

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Build region map
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))

    regions = sorted(region_cells.keys())
    num_regions = len(regions)

    # Precompute valid placements for each region and tetromino type
    region_placements = {}  # region_id -> {tet_type: [list of (cells, bounding_box)]}

    for rid in regions:
        cells = set(region_cells[rid])
        region_placements[rid] = {}

        for tname in ['L', 'I', 'T', 'S']:
            placements = []
            for shape in SHAPE_VARIATIONS[tname]:
                # Try placing shape at all positions
                max_r = max(r for r, c in shape)
                max_c = max(c for r, c in shape)
                for dr in range(n - max_r + 1):
                    for dc in range(m - max_c + 1):
                        placed = tuple(sorted((r + dr, c + dc) for r, c in shape))
                        # Check if all cells are in this region
                        if all(cell in cells for cell in placed):
                            placements.append((placed, tname))
            region_placements[rid][tname] = placements

    # Build adjacency graph of regions
    region_adj = defaultdict(set)
    for r in range(n):
        for c in range(m):
            for dr, dc in [(0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    r1, r2 = grid[r][c], grid[nr][nc]
                    if r1 != r2:
                        region_adj[r1].add(r2)
                        region_adj[r2].add(r1)

    # Check if a placement creates 2x2 shaded block
    def has_2x2_conflict(placed_cells, existing_shaded):
        cells_set = set(placed_cells)
        for r, c in placed_cells:
            # Check all 2x2 squares containing this cell
            for sr in [r-1, r]:
                for sc in [c-1, c]:
                    if sr < 0 or sc < 0:
                        continue
                    square = [(sr, sc), (sr+1, sc), (sr, sc+1), (sr+1, sc+1)]
                    if all(cell in cells_set or cell in existing_shaded for cell in square):
                        # All 4 would be shaded
                        return True
        return False

    # Check connectivity of shaded cells (must be connected at end)
    def check_connectivity(shaded_cells):
        if len(shaded_cells) <= 1:
            return True
        cells = set(shaded_cells)
        start = next(iter(cells))
        visited = set([start])
        queue = deque([start])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == len(cells)

    # For early pruning: check if remaining regions can connect
    def can_connect_to_existing(region_id, ttype, placed_cells, assigned, shaded_so_far):
        # Simple check: placed cells should be adjacent to existing shaded or future possible
        if not shaded_so_far:
            return True

        cells_set = set(placed_cells)
        # Check if any cell is adjacent to existing shaded
        for r, c in placed_cells:
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in shaded_so_far:
                    return True
        # Also check if any unassigned region is adjacent and could connect
        for adj_rid in region_adj[region_id]:
            if adj_rid not in assigned:
                return True  # Hope for future connection

        return False

    # Main solver with constraint propagation
    assigned = {}  # region_id -> tet_type
    region_placement = {}  # region_id -> placed_cells
    shaded_cells = set()

    # Order regions by constraint tightness (fewest valid placements)
    def get_region_order():
        remaining = [r for r in regions if r not in assigned]
        scores = []
        for rid in remaining:
            # Count total valid placements considering adjacency constraints
            total = 0
            for tname in ['L', 'I', 'T', 'S']:
                # Check adjacency constraint
                valid = True
                for adj in region_adj[rid]:
                    if adj in assigned and assigned[adj] == tname:
                        valid = False
                        break
                if valid:
                    total += len(region_placements[rid].get(tname, []))
            scores.append((total, rid))
        scores.sort()
        return [rid for _, rid in scores]

    # Precompute all 2x2 squares for fast checking
    all_2x2 = []
    for r in range(n-1):
        for c in range(m-1):
            all_2x2.append(((r, c), (r+1, c), (r, c+1), (r+1, c+1)))

    def solve_recursive(idx):
        if len(assigned) == num_regions:
            # Check final connectivity
            return check_connectivity(shaded_cells)

        # Get next region to assign
        order = get_region_order()
        rid = order[0]

        # Try each tetromino type
        for tname in ['L', 'I', 'T', 'S']:
            # Check adjacency constraint
            valid_type = True
            for adj in region_adj[rid]:
                if adj in assigned and assigned[adj] == tname:
                    valid_type = False
                    break
            if not valid_type:
                continue

            placements = region_placements[rid].get(tname, [])
            for placed, _ in placements:
                # Check 2x2 constraint
                if has_2x2_conflict(placed, shaded_cells):
                    continue

                # Check connectivity feasibility
                if not can_connect_to_existing(rid, tname, placed, assigned, shaded_cells):
                    if shaded_cells:  # Only enforce if we have existing cells
                        continue

                # Make assignment
                assigned[rid] = tname
                region_placement[rid] = placed
                new_shaded = set(placed)
                shaded_cells.update(new_shaded)

                # Recurse
                if solve_recursive(idx + 1):
                    return True

                # Backtrack
                del assigned[rid]
                del region_placement[rid]
                shaded_cells.difference_update(new_shaded)

        return False

    # Try to solve
    if solve_recursive(0):
        # Build result grid
        result = [[None for _ in range(m)] for _ in range(n)]
        for rid, tname in assigned.items():
            for r, c in region_placement[rid]:
                result[r][c] = tname
        return result

    return "No Solution"

