from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n > 0 else 0

    # Grid has (n+1) x (m+1) dots
    rows = n + 1
    cols = m + 1

    # Edge variables: horizontal edges (r, c) to (r, c+1), vertical edges (r, c) to (r+1, c)
    # h_edges[r][c] = 0/1/None (unknown) for edge from (r,c) to (r,c+1), valid c in 0..m-1
    # v_edges[r][c] = 0/1/None for edge from (r,c) to (r+1,c), valid r in 0..n-1

    h_edges = [[None] * m for _ in range(rows)]
    v_edges = [[None] * cols for _ in range(n)]

    # For each clue cell, track which edges are around it
    # Cell (i,j) in data corresponds to center at (i+0.5, j+0.5)
    # Edges around it: h_edges[i][j], h_edges[i+1][j], v_edges[i][j], v_edges[i][j+1]

    def get_cell_edges(i, j):
        """Return list of (type, r, c) for edges around cell (i,j)"""
        return [('h', i, j), ('h', i+1, j), ('v', i, j), ('v', i, j+1)]

    def count_unknown_around(i, j):
        edges = get_cell_edges(i, j)
        unknown = []
        known_sum = 0
        for typ, r, c in edges:
            if typ == 'h':
                val = h_edges[r][c]
            else:
                val = v_edges[r][c]
            if val is None:
                unknown.append((typ, r, c))
            else:
                known_sum += val
        return unknown, known_sum

    def set_edge(typ, r, c, val):
        """Set edge value, return True if changed, False if consistent, raise if conflict"""
        if typ == 'h':
            if h_edges[r][c] is not None:
                if h_edges[r][c] != val:
                    raise ValueError("Conflict")
                return False
            h_edges[r][c] = val
        else:
            if v_edges[r][c] is not None:
                if v_edges[r][c] != val:
                    raise ValueError("Conflict")
                return False
            v_edges[r][c] = val
        return True

    def propagate():
        """Propagate constraints using queue"""
        queue = deque()

        # Initialize with all clue cells
        for i in range(n):
            for j in range(m):
                if data[i][j] is not None:
                    queue.append(('cell', i, j))

        # Also add all dots for degree constraints
        for r in range(rows):
            for c in range(cols):
                queue.append(('dot', r, c))

        while queue:
            item = queue.popleft()

            if item[0] == 'cell':
                i, j = item[1], item[2]
                clue = data[i][j]
                if clue is None:
                    continue

                unknown, known_sum = count_unknown_around(i, j)
                need = clue - known_sum

                if need < 0 or need > len(unknown):
                    raise ValueError("Impossible")

                if len(unknown) == 0:
                    if known_sum != clue:
                        raise ValueError("Impossible")
                    continue

                if need == 0:
                    # All unknown must be 0
                    for typ, r, c in unknown:
                        if set_edge(typ, r, c, 0):
                            queue.append(('edge', typ, r, c))
                elif need == len(unknown):
                    # All unknown must be 1
                    for typ, r, c in unknown:
                        if set_edge(typ, r, c, 1):
                            queue.append(('edge', typ, r, c))

            elif item[0] == 'dot':
                r, c = item[1], item[2]
                # Get all edges incident to this dot
                incident = []
                # Left: h_edges[r][c-1] if c > 0
                if c > 0:
                    incident.append(('h', r, c-1))
                # Right: h_edges[r][c] if c < m
                if c < m:
                    incident.append(('h', r, c))
                # Up: v_edges[r-1][c] if r > 0
                if r > 0:
                    incident.append(('v', r-1, c))
                # Down: v_edges[r][c] if r < n
                if r < n:
                    incident.append(('v', r, c))

                unknown = []
                known_sum = 0
                for typ, rr, cc in incident:
                    if typ == 'h':
                        val = h_edges[rr][cc]
                    else:
                        val = v_edges[rr][cc]
                    if val is None:
                        unknown.append((typ, rr, cc))
                    else:
                        known_sum += val

                # Dot must have degree 0 or 2 in final loop
                if len(unknown) == 0:
                    if known_sum not in (0, 2):
                        raise ValueError("Dot degree not 0 or 2")
                    continue

                # If we have some known edges
                if known_sum == 2:
                    # All unknown must be 0
                    for typ, rr, cc in unknown:
                        if set_edge(typ, rr, cc, 0):
                            queue.append(('edge', typ, rr, cc))
                elif known_sum == 1:
                    # Need exactly 1 more, so if only 1 unknown, it's 1
                    if len(unknown) == 1:
                        typ, rr, cc = unknown[0]
                        if set_edge(typ, rr, cc, 1):
                            queue.append(('edge', typ, rr, cc))
                elif known_sum == 0:
                    # Need 0 or 2. If only 2 unknowns, they must be equal (both 0 or both 1)
                    # But we can't deduce directly unless we know more
                    pass
                # known_sum > 2 is impossible

            elif item[0] == 'edge':
                typ, r, c = item[1], item[2], item[3]
                # Propagate to adjacent cells and dots
                if typ == 'h':
                    # Affects cells above and below, and dots left and right
                    if r > 0:
                        queue.append(('cell', r-1, c))
                    if r < n:
                        queue.append(('cell', r, c))
                    queue.append(('dot', r, c))
                    queue.append(('dot', r, c+1))
                else:
                    # Affects cells left and right, and dots above and below
                    if c > 0:
                        queue.append(('cell', r, c-1))
                    if c < m:
                        queue.append(('cell', r, c))
                    queue.append(('dot', r, c))
                    queue.append(('dot', r+1, c))

    def check_connectivity():
        """Check that all 1-edges form a single loop"""
        # Build adjacency
        adj = {}
        for r in range(rows):
            for c in range(m):
                if h_edges[r][c] == 1:
                    n1, n2 = (r, c), (r, c+1)
                    adj.setdefault(n1, []).append(n2)
                    adj.setdefault(n2, []).append(n1)

        for r in range(n):
            for c in range(cols):
                if v_edges[r][c] == 1:
                    n1, n2 = (r, c), (r+1, c)
                    adj.setdefault(n1, []).append(n2)
                    adj.setdefault(n2, []).append(n1)

        # Check all degrees are 0 or 2
        nodes_with_edges = []
        for node, neigh in adj.items():
            if len(neigh) not in (0, 2):
                return False
            if len(neigh) == 2:
                nodes_with_edges.append(node)

        if len(nodes_with_edges) == 0:
            return False  # Empty loop

        # Check single component
        visited = set()
        stack = [nodes_with_edges[0]]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for nxt in adj.get(node, []):
                if nxt not in visited:
                    stack.append(nxt)

        return len(visited) == len(nodes_with_edges)

    def extract_loop():
        """Extract the loop as ordered list of coordinates"""
        # Build adjacency
        adj = {}
        for r in range(rows):
            for c in range(m):
                if h_edges[r][c] == 1:
                    n1, n2 = (r, c), (r, c+1)
                    adj.setdefault(n1, []).append(n2)
                    adj.setdefault(n2, []).append(n1)

        for r in range(n):
            for c in range(cols):
                if v_edges[r][c] == 1:
                    n1, n2 = (r, c), (r+1, c)
                    adj.setdefault(n1, []).append(n2)
                    adj.setdefault(n2, []).append(n1)

        # Find start
        start = None
        for node, neigh in adj.items():
            if len(neigh) == 2:
                start = node
                break

        if start is None:
            return None

        # Traverse
        result = [start]
        prev = None
        curr = start

        while True:
            neigh = adj[curr]
            nxt = neigh[0] if neigh[0] != prev else neigh[1] if len(neigh) > 1 else None
            if nxt is None or nxt == start:
                break
            result.append(nxt)
            prev, curr = curr, nxt

        result.append(start)
        return result

    def solve_recursive():
        """Recursive solving with constraint propagation"""
        try:
            propagate()
        except ValueError:
            return False

        # Check if solved
        all_set = True
        for r in range(rows):
            for c in range(m):
                if h_edges[r][c] is None:
                    all_set = False
                    break
            if not all_set:
                break

        if all_set:
            for r in range(n):
                for c in range(cols):
                    if v_edges[r][c] is None:
                        all_set = False
                        break
                if not all_set:
                    break

        if all_set:
            return check_connectivity()

        # Find unknown edge with most constraints (fewest possibilities)
        # Actually just find first unknown
        best_typ, best_r, best_c = None, None, None

        # Prioritize edges that are more constrained
        for r in range(rows):
            for c in range(m):
                if h_edges[r][c] is None:
                    best_typ, best_r, best_c = 'h', r, c
                    break
            if best_typ:
                break

        if not best_typ:
            for r in range(n):
                for c in range(cols):
                    if v_edges[r][c] is None:
                        best_typ, best_r, best_c = 'v', r, c
                        break
                if best_typ:
                    break

        if not best_typ:
            return check_connectivity()

        # Try 0
        saved_h = [row[:] for row in h_edges]
        saved_v = [row[:] for row in v_edges]

        try:
            set_edge(best_typ, best_r, best_c, 0)
            if solve_recursive():
                return True
        except ValueError:
            pass

        # Restore and try 1
        for i in range(len(h_edges)):
            h_edges[i] = saved_h[i][:]
        for i in range(len(v_edges)):
            v_edges[i] = saved_v[i][:]

        try:
            set_edge(best_typ, best_r, best_c, 1)
            if solve_recursive():
                return True
        except ValueError:
            pass

        # Restore
        for i in range(len(h_edges)):
            h_edges[i] = saved_h[i][:]
        for i in range(len(v_edges)):
            v_edges[i] = saved_v[i][:]

        return False

    # Additional constraint: border edges
    # For cells on border, some edges are outside (implicitly 0)
    # Actually all edges are within the grid, no need for special handling

    # Preprocessing: cells with clue 0
    for i in range(n):
        for j in range(m):
            if data[i][j] == 0:
                for typ, r, c in get_cell_edges(i, j):
                    set_edge(typ, r, c, 0)

    if solve_recursive():
        loop = extract_loop()
        if loop:
            return str(loop)

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
