def solve(observation):
    data = observation['data']
    unit_str = observation['unit']

    # Parse unit string
    if 'x' in unit_str:
        parts = unit_str.split('x')
        r_unit = int(parts[0])
        c_unit = int(parts[1])
    else:
        r_unit = c_unit = int(unit_str)

    n = r_unit * c_unit
    grid = [row[:] for row in data]

    # Bitmask helpers
    def bit(x):
        return 1 << (x - 1)

    def bit_count(x):
        return x.bit_count()

    def get_values(mask):
        res = []
        v = 1
        while mask:
            if mask & 1:
                res.append(v)
            mask >>= 1
            v += 1
        return res

    # Initialize candidates
    rows = [0] * n
    cols = [0] * n
    boxes = [0] * n

    for i in range(n):
        for j in range(n):
            if grid[i][j] is not None:
                v = grid[i][j]
                b = (i // r_unit) * c_unit + (j // c_unit)
                rows[i] |= bit(v)
                cols[j] |= bit(v)
                boxes[b] |= bit(v)

    # Get candidates for a cell
    def get_candidates(r, c):
        if grid[r][c] is not None:
            return []
        b = (r // r_unit) * c_unit + (c // c_unit)
        used = rows[r] | cols[c] | boxes[b]
        return get_values(((1 << n) - 1) ^ used)

    # Set a value
    def set_val(r, c, v):
        b = (r // r_unit) * c_unit + (c // c_unit)
        grid[r][c] = v
        bv = bit(v)
        rows[r] |= bv
        cols[c] |= bv
        boxes[b] |= bv

    # Unset a value (for backtracking)
    def unset_val(r, c, v):
        b = (r // r_unit) * c_unit + (c // c_unit)
        grid[r][c] = None
        bv = bit(v)
        rows[r] ^= bv
        cols[c] ^= bv
        boxes[b] ^= bv

    # Constraint propagation: naked singles, hidden singles
    def propagate():
        changed = True
        while changed:
            changed = False

            # Naked singles
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is None:
                        cand = get_candidates(r, c)
                        if len(cand) == 0:
                            return False  # Contradiction
                        if len(cand) == 1:
                            set_val(r, c, cand[0])
                            changed = True
                        elif len(cand) == 1:
                            pass

            # Hidden singles in rows
            for r in range(n):
                pos = [[] for _ in range(n+1)]
                for c in range(n):
                    if grid[r][c] is None:
                        for v in get_candidates(r, c):
                            pos[v].append(c)
                for v in range(1, n+1):
                    if len(pos[v]) == 1:
                        c = pos[v][0]
                        if grid[r][c] is None:
                            set_val(r, c, v)
                            changed = True

            # Hidden singles in columns
            for c in range(n):
                pos = [[] for _ in range(n+1)]
                for r in range(n):
