    # Save state for backtracking
    def save_state():
        return ([r[:] for r in grid], rows[:], cols[:], boxes[:])

    def load_state(state):
        nonlocal grid, rows, cols, boxes
        g, rs, cs, bs = state
        grid = [r[:] for r in g]
        rows = rs[:]
        cols = cs[:]
        boxes = bs[:]

    # Recursive solver with constraint propagation
    def solve_recursive():
        if not propagate():
            return False

        cell = find_min_cell()
        if cell is None:
            return True  # Solved

        r, c, cands = cell
        if len(cands) == 0:
            return False

        state = save_state()

        # Try candidates in order (could optimize with heuristic)
        for v in cands:
            load_state(state)
            set_val(r, c, v)
            if solve_recursive():
                return True

        load_state(state)
        return False

    # Initial propagation
    if not propagate():
        return "No Solution"

    if solve_recursive():
        return grid
    else:
        return "No Solution"

