            while old_state != str(state):
                old_state = str(state)
                propagate()
                # Check validity
                valid = True
                for cr, cc in clue_cells:
                    clue_val = grid[cr][cc]
                    m = count_mines_around(cr, cc)
                    u = len(get_unknown_neighbors(cr, cc))
                    if m > clue_val or m + u < clue_val:
                        valid = False
                        break
                if not valid:
                    break

            if valid and all_clues_satisfied(state):
                # Recurse
                if backtrack():
                    return True

            # Restore
            for i in range(rows):
                for j in range(cols):
                    state[i][j] = saved_state[i][j]

        return False

    # Run backtracking if needed
    if not is_solved():
        backtrack()

    # Build result
    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if state[r][c] == 1:
                row.append('F')
            else:
                row.append(None)
        result.append(row)

    return result

