    def bit(x):
        return 1 << (x - 1)

    def get_val(mask):
        if mask & (mask - 1) == 0 and mask != 0:  # power of 2
            return (mask.bit_length() - 1) + 1
        return None

    def count_bits(mask):
        return bin(mask).count('1')

    # Initialize candidates: full mask for empty cells
    full_mask = (1 << n) - 1

    # row_mask[i] = bits of values used in row i
    # col_mask[j] = bits of values used in col j  
    # box_mask[i][j] = bits of values used in subgrid containing (i,j)
    row_mask = [0] * n
    col_mask = [0] * n
    box_mask = [[0] * (n // c_unit) for _ in range(n // r_unit)]

    # Initialize from given values
    for i in range(n):
        for j in range(n):
            if grid[i][j] is not None:
                v = grid[i][j]
                b = bit(v)
                row_mask[i] |= b
                col_mask[j] |= b
                bi, bj = i // r_unit, j // c_unit
                box_mask[bi][bj] |= b

    # candidates[i][j] = bitmask of possible values
    candidates = [[None] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] is None:
                bi, bj = i // r_unit, j // c_unit
                used = row_mask[i] | col_mask[j] | box_mask[bi][bj]
                candidates[i][j] = full_mask & ~used
            else:
                candidates[i][j] = 0  # filled

    # Constraint propagation: naked singles, hidden singles, pointing pairs, etc.
    def propagate():
        changed = True
        while changed:
            changed = False

            # Naked singles
            for i in range(n):
                for j in range(n):
                    if grid[i][j] is None and candidates[i][j] != 0:
                        if count_bits(candidates[i][j]) == 1:
                            v = get_val(candidates[i][j])
                            if not assign(i, j, v):
                                return False
