                        if len(cells) >= 2:
                            # Check if all in same row
                            rows = set(c[0] for c in cells)
                            if len(rows) == 1:
                                row = cells[0][0]
                                for j in range(n):
                                    if j // c_unit != bj and grid[row][j] is None:
                                        if candidates[row][j] & b:
                                            candidates[row][j] &= ~b
                                            if candidates[row][j] == 0:
                                                return False
                                            changed = True
                            # Check if all in same col
                            cols = set(c[1] for c in cells)
                            if len(cols) == 1:
                                col = cells[0][1]
                                for i in range(n):
                                    if i // r_unit != bi and grid[i][col] is None:
                                        if candidates[i][col] & b:
                                            candidates[i][col] &= ~b
                                            if candidates[i][col] == 0:
                                                return False
                                            changed = True

        return True

    def assign(i, j, v):
        """Assign value v to cell (i,j), update structures"""
        nonlocal row_mask, col_mask, box_mask

        b = bit(v)
        grid[i][j] = v
        candidates[i][j] = 0

        # Update masks
        row_mask[i] |= b
        col_mask[j] |= b
        bi, bj = i // r_unit, j // c_unit
        box_mask[bi][bj] |= b

        # Remove from other cells in row, col, box
        # Row
