        # Col
        for r in range(n):
            if grid[r][j] is None and (candidates[r][j] & b):
                candidates[r][j] &= ~b
                if candidates[r][j] == 0:
                    return False

        # Box
        for di in range(r_unit):
            for dj in range(c_unit):
                r = bi * r_unit + di
                c = bj * c_unit + dj
                if grid[r][c] is None and (candidates[r][c] & b):
                    candidates[r][c] &= ~b
                    if candidates[r][c] == 0:
