    # Backtracking with MRV heuristic
    def select_var():
        min_options = n + 1
        best = None
        for i in range(n):
            for j in range(n):
                if grid[i][j] is None:
                    opts = count_bits(candidates[i][j])
                    if opts < min_options:
                        min_options = opts
                        best = (i, j)
                        if opts == 1:
