        return best

    # Save state for backtracking
    def save_state():
        return ([row[:] for row in grid], 
                row_mask[:], col_mask[:], 
                [[box_mask[i][j] for j in range(len(box_mask[0]))] for i in range(len(box_mask))],
                [[candidates[i][j] for j in range(n)] for i in range(n)])

    def restore_state(state):
        nonlocal grid, row_mask, col_mask, box_mask, candidates
        grid, row_mask, col_mask, box_mask, candidates = state

    def backtrack():
        if is_solved():
            return True

        var = select_var()
        if var is None:
            return False

        i, j = var
        mask = candidates[i][j]

        # Try each possible value
        vals = []
        temp = mask
        while temp:
            lsb = temp & -temp
            v = (lsb.bit_length() - 1) + 1
            vals.append(v)
            temp &= temp - 1

        # Sort by constraint propagation success likelihood
        for v in vals:
            state = save_state()

            if assign(i, j, v):
                if propagate():
                    if backtrack():
                        return True

            restore_state(state)

        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

