    # h_edges[r][c] = 0/1/None (unknown) for edge from (r,c) to (r,c+1), c in 0..cols-1
    # v_edges[r][c] = 0/1/None for edge from (r,c) to (r+1,c), r in 0..rows-1

    h_edges = [[None] * cols for _ in range(rows + 1)]  # (rows+1) x cols
    v_edges = [[None] * (cols + 1) for _ in range(rows)]  # rows x (cols+1)

    # Helper to get edges around a cell (r+0.5, c+0.5)
    def get_cell_edges(cr, cc):
        # cr, cc are cell coordinates (0-indexed in data)
        # returns [top, right, bottom, left] edges
        r, c = cr, cc
        top = h_edges[r][c]      # (r,c)-(r,c+1)
        right = v_edges[r][c+1]  # (r,c+1)-(r+1,c+1)
        bottom = h_edges[r+1][c] # (r+1,c)-(r+1,c+1)
        left = v_edges[r][c]     # (r,c)-(r+1,c)
        return [top, right, bottom, left]

    def set_edge(edge_type, r, c, val):
        if edge_type == 'h':
            if h_edges[r][c] is not None and h_edges[r][c] != val:
                return False
            h_edges[r][c] = val
        else:
            if v_edges[r][c] is not None and v_edges[r][c] != val:
                return False
            v_edges[r][c] = val
        return True

    # Constraint propagation queue
    queue = deque()

    # Initialize with clues
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                queue.append(('cell', r, c))

    # Add all edges to queue initially
    for r in range(rows + 1):
        for c in range(cols):
            if h_edges[r][c] is None:
                queue.append(('h_edge', r, c))
    for r in range(rows):
        for c in range(cols + 1):
            if v_edges[r][c] is None:
                queue.append(('v_edge', r, c))

    def propagate():
        nonlocal queue
        while queue:
            item = queue.popleft()
            if item[0] == 'cell':
                cr, cc = item[1], item[2]
                clue = data[cr][cc]
                edges = get_cell_edges(cr, cc)
                known = [e for e in edges if e is not None]
                unknown_count = sum(1 for e in edges if e is None)
                known_sum = sum(known)

                if known_sum > clue:
                    return False
                if unknown_count == 0:
                    if known_sum != clue:
                        return False
                    continue

                # If must fill remaining
                if known_sum + unknown_count == clue:
                    # set all unknown to 1
                    for i, e in enumerate(edges):
                        if e is None:
                            if i == 0:  # top
                                if not set_edge('h', cr, cc, 1): return False
                                queue.append(('h_edge', cr, cc))
                            elif i == 1:  # right
                                if not set_edge('v', cr, cc+1, 1): return False
                                queue.append(('v_edge', cr, cc+1))
                            elif i == 2:  # bottom
                                if not set_edge('h', cr+1, cc, 1): return False
                                queue.append(('h_edge', cr+1, cc))
                            else:  # left
                                if not set_edge('v', cr, cc, 1): return False
                                queue.append(('v_edge', cr, cc))

                # If must exclude remaining
                if known_sum == clue:
                    # set all unknown to 0
                    for i, e in enumerate(edges):
                        if e is None:
                            if i == 0:  # top
                                if not set_edge('h', cr, cc, 0): return False
                                queue.append(('h_edge', cr, cc))
                            elif i == 1:  # right
                                if not set_edge('v', cr, cc+1, 0): return False
                                queue.append(('v_edge', cr, cc+1))
                            elif i == 2:  # bottom
                                if not set_edge('h', cr+1, cc, 0): return False
                                queue.append(('h_edge', cr+1, cc))
                            else:  # left
                                if not set_edge('v', cr, cc, 0): return False
                                queue.append(('v_edge', cr, cc))

            elif item[0] == 'h_edge':
                r, c = item[1], item[2]
                if h_edges[r][c] is None:
                    continue
                # Affects cells above and below, and dots at ends
                # Cell above: (r-1, c) if r > 0
                if r > 0 and data[r-1][c] is not None:
                    queue.append(('cell', r-1, c))
                # Cell below: (r, c) if r < rows
                if r < rows and data[r][c] is not None:
                    queue.append(('cell', r, c))
                # Dots: (r,c) and (r,c+1)
                queue.append(('dot', r, c))
                queue.append(('dot', r, c+1))

            elif item[0] == 'v_edge':
                r, c = item[1], item[2]
                if v_edges[r][c] is None:
                    continue
                # Affects cells left and right
                if c > 0 and data[r][c-1] is not None:
                    queue.append(('cell', r, c-1))
                if c < cols and data[r][c] is not None:
                    queue.append(('cell', r, c))
                queue.append(('dot', r, c))
                queue.append(('dot', r+1, c))

            elif item[0] == 'dot':
                r, c = item[1], item[2]
                # Count edges at this dot
                edges = []
                # left: h_edges[r][c-1] if c > 0
                if c > 0:
                    edges.append(h_edges[r][c-1])
                # right: h_edges[r][c] if c < cols
                if c < cols:
                    edges.append(h_edges[r][c])
                # up: v_edges[r-1][c] if r > 0
                if r > 0:
                    edges.append(v_edges[r-1][c])
                # down: v_edges[r][c] if r < rows
                if r < rows:
                    edges.append(v_edges[r][c])

                known = [e for e in edges if e is not None]
                unknown = [i for i, e in enumerate(edges) if e is None]
                known_sum = sum(known)

                # Loop constraint: each dot has 0 or 2 edges
                if len(unknown) == 0:
                    if known_sum not in (0, 2):
                        return False
                    continue

                if known_sum > 2:
                    return False

                if known_sum == 2:
                    # all unknown must be 0
                    for idx in unknown:
                        if idx == 0 and c > 0:  # left
                            if not set_edge('h', r, c-1, 0): return False
                            queue.append(('h_edge', r, c-1))
                        elif idx == 1 and c < cols:  # right
                            if not set_edge('h', r, c, 0): return False
                            queue.append(('h_edge', r, c))
                        elif idx == 2 and r > 0:  # up
                            if not set_edge('v', r-1, c, 0): return False
                            queue.append(('v_edge', r-1, c))
                        elif idx == 3 and r < rows:  # down
                            if not set_edge('v', r, c, 0): return False
                            queue.append(('v_edge', r, c))

                elif len(unknown) == 2 and known_sum == 0:
                    # must use both unknown
                    for idx in unknown:
                        if idx == 0 and c > 0:
                            if not set_edge('h', r, c-1, 1): return False
                            queue.append(('h_edge', r, c-1))
                        elif idx == 1 and c < cols:
                            if not set_edge('h', r, c, 1): return False
                            queue.append(('h_edge', r, c))
                        elif idx == 2 and r > 0:
                            if not set_edge('v', r-1, c, 1): return False
                            queue.append(('v_edge', r-1, c))
                        elif idx == 3 and r < rows:
                            if not set_edge('v', r, c, 1): return False
                            queue.append(('v_edge', r, c))

        return True

    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        for r in range(rows + 1):
            for c in range(cols):
                if h_edges[r][c] is None:
                    return False
        for r in range(rows):
            for c in range(cols + 1):
                if v_edges[r][c] is None:
                    return False
        return True

    # Find connected component of loop
    def get_loop_path():
        # Find start of loop (any edge with value 1)
        start = None
        for r in range(rows + 1):
            for c in range(cols):
                if h_edges[r][c] == 1:
                    start = (r, c)
                    break
            if start:
                break

        if not start:
            # Check vertical
            for r in range(rows):
                for c in range(cols + 1):
                    if v_edges[r][c] == 1:
                        start = (r, c)
                        break
                if start:
                    break

        if not start:
            return None

        # BFS to find loop
        path = [start]
        visited = {start}
        current = start

        while True:
            r, c = current
            neighbors = []
            # Check all 4 directions for edges with value 1
            # left: h_edges[r][c-1] if c > 0
            if c > 0 and h_edges[r][c-1] == 1:
                neighbors.append((r, c-1))
            # right: h_edges[r][c] if c < cols
            if c < cols and h_edges[r][c] == 1:
                neighbors.append((r, c+1))
            # up: v_edges[r-1][c] if r > 0
            if r > 0 and v_edges[r-1][c] == 1:
                neighbors.append((r-1, c))
            # down: v_edges[r][c] if r < rows
            if r < rows and v_edges[r][c] == 1:
                neighbors.append((r+1, c))

            # Filter to unvisited, or start if we're closing the loop
            unvisited = [n for n in neighbors if n not in visited]

            if len(unvisited) == 0:
                # Check if we can return to start
                if start in neighbors and len(path) > 2:
                    path.append(start)
                    return path
                return None

            if len(unvisited) > 1:
                return None  # Branching, not a simple loop

            current = unvisited[0]
            path.append(current)
            visited.add(current)

            if len(path) > (rows + 1) * (cols + 1):
                return None  # Too long, something wrong

    def check_single_loop():
        path = get_loop_path()
        if path is None:
            return False

        # Count all edges with value 1
        edge_count = 0
        for r in range(rows + 1):
            for c in range(cols):
                if h_edges[r][c] == 1:
                    edge_count += 1
        for r in range(rows):
            for c in range(cols + 1):
                if v_edges[r][c] == 1:
                    edge_count += 1

        # Path length - 1 should equal edge count (each edge used once)
        return len(path) - 1 == edge_count

    # Backtracking for remaining unknowns
    def backtrack():
        if is_solved():
            return check_single_loop()

        # Find first unknown
        for r in range(rows + 1):
            for c in range(cols):
                if h_edges[r][c] is None:
                    for val in [0, 1]:
                        # Save state
                        old_h = [row[:] for row in h_edges]
                        old_v = [row[:] for row in v_edges]

                        if not set_edge('h', r, c, val):
                            continue

                        queue.clear()
                        queue.append(('h_edge', r, c))

                        if propagate():
                            if backtrack():
                                return True

                        # Restore
                        for i in range(len(h_edges)):
                            h_edges[i] = old_h[i][:]
                        for i in range(len(v_edges)):
                            v_edges[i] = old_v[i][:]
                    return False

        for r in range(rows):
            for c in range(cols + 1):
                if v_edges[r][c] is None:
                    for val in [0, 1]:
                        old_h = [row[:] for row in h_edges]
                        old_v = [row[:] for row in v_edges]

                        if not set_edge('v', r, c, val):
                            continue

                        queue.clear()
                        queue.append(('v_edge', r, c))

                        if propagate():
                            if backtrack():
                                return True

                        for i in range(len(h_edges)):
                            h_edges[i] = old_h[i][:]
                        for i in range(len(v_edges)):
                            v_edges[i] = old_v[i][:]
                    return False

        return check_single_loop()

    if not backtrack():
        return "No Solution"

    # Extract path
    path = get_loop_path()
    if path is None:
        return "No Solution"

    # Format as list of tuples
    return str(path)

if __name__ == "__main__":
    print(solve(OBSERVATION))
