# Tetromino shapes represented as (dr, dc) offsets from a base cell
# L: 3 in a line with one perpendicular (size 4)
# I: 4 in a line
# T: 3 in a line with one in center perpendicular
# S: zigzag shape

TETROMINOES = {
    'L': [(0,0), (1,0), (2,0), (2,1)],  # base shape, will rotate
    'I': [(0,0), (1,0), (2,0), (3,0)],
    'T': [(0,0), (0,1), (0,2), (1,1)],
    'S': [(0,1), (0,2), (1,0), (1,1)],
}

def get_rotations(shape):
    """Generate all unique rotations and reflections of a tetromino shape."""
    def rotate(shape):
        # Rotate 90 degrees clockwise
        return [(c, -r) for r, c in shape]

    def reflect(shape):
        # Reflect horizontally
        return [(-r, c) for r, c in shape]

    def normalize(shape):
        # Normalize to start at (0,0)
        min_r = min(r for r, c in shape)
        min_c = min(c for r, c in shape)
        return tuple(sorted((r - min_r, c - min_c) for r, c in shape))

    seen = set()
    result = []
    current = shape

    for _ in range(4):  # 4 rotations
        norm = normalize(current)
        if norm not in seen:
            seen.add(norm)
            result.append(list(norm))

        reflected = reflect(current)
        norm_ref = normalize(reflected)
        if norm_ref not in seen:
            seen.add(norm_ref)
            result.append(list(norm_ref))

        current = rotate(current)

    return result

# Precompute all rotations for each tetromino type
TETRO_ROTATIONS = {t: get_rotations(s) for t, s in TETROMINOES.items()}

def get_region_cells(grid, region_id):
    """Get all cells belonging to a region."""
    cells = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == region_id:
                cells.append((r, c))
    return cells

def can_place(grid, region_cells, shape, start_r, start_c):
    """Check if a tetromino shape can be placed at given position."""
    placed = []
    for dr, dc in shape:
        r, c = start_r + dr, start_c + dc
        if (r, c) not in region_cells:
            return None
        placed.append((r, c))
    return placed

def get_all_placements(grid, region_cells, tetro_type):
    """Get all valid placements of a tetromino type in a region."""
    placements = []
    region_set = set(region_cells)
    for shape in TETRO_ROTATIONS[tetro_type]:
        # Try each cell in region as potential base
        for r, c in region_cells:
            placed = can_place(grid, region_set, shape, r, c)
            if placed:
                placements.append((placed, shape))
    # Remove duplicates
    unique = []
    seen = set()
    for placed, shape in placements:
        key = tuple(sorted(placed))
        if key not in seen:
            seen.add(key)
            unique.append((placed, shape))
    return unique

def get_adjacent_regions(grid, region_id, region_map):
    """Get region IDs of orthogonally adjacent regions."""
    adj = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == region_id:
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        nid = grid[nr][nc]
                        if nid != region_id:
                            adj.add(nid)
    return adj

def check_no_2x2(shaded_grid):
    """Check that no 2x2 block is fully shaded."""
    rows, cols = len(shaded_grid), len(shaded_grid[0])
    for r in range(rows - 1):
        for c in range(cols - 1):
            if (shaded_grid[r][c] and shaded_grid[r][c+1] and 
                shaded_grid[r+1][c] and shaded_grid[r+1][c+1]):
                return False
    return True

def check_connected(shaded_grid):
    """Check if all shaded cells are orthogonally connected."""
    rows, cols = len(shaded_grid), len(shaded_grid[0])
    shaded = []
    for r in range(rows):
        for c in range(cols):
            if shaded_grid[r][c]:
                shaded.append((r, c))

    if len(shaded) <= 1:
        return True

    # BFS from first shaded cell
    start = shaded[0]
    visited = {start}
    queue = [start]
    shaded_set = set(shaded)

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) in shaded_set and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

    return len(visited) == len(shaded)

def solve(observation):
    grid = observation['data']
    rows, cols = len(grid), len(grid[0])

    # Find all regions
    region_ids = set()
    for r in range(rows):
        for c in range(cols):
            region_ids.add(grid[r][c])

    # Get cells for each region
    regions = {rid: get_region_cells(grid, rid) for rid in region_ids}

    # Check each region has exactly 4 cells
    for rid, cells in regions.items():
        if len(cells) != 4:
            return "No Solution"  # Each region must have exactly 4 cells for a tetromino

    # Get adjacent regions
    adjacencies = {rid: get_adjacent_regions(grid, rid, regions) for rid in region_ids}

    # Precompute all possible placements for each region and tetromino type
    placements = {}
    for rid in region_ids:
        placements[rid] = {}
        for t in ['L', 'I', 'T', 'S']:
            placements[rid][t] = get_all_placements(grid, regions[rid], t)

    # Sort regions by fewest valid placements (most constrained first)
    def region_options_count(rid):
        count = 0
        for t in ['L', 'I', 'T', 'S']:
            count += len(placements[rid][t])
        return count

    sorted_regions = sorted(region_ids, key=region_options_count)

    # State: region_id -> tetromino type, and which cells are shaded
    solution = {}  # rid -> (type, placed_cells)
    shaded = [[False] * cols for _ in range(rows)]

    def is_valid_partial():
        # Check no 2x2 shaded block
        for r in range(rows - 1):
            for c in range(cols - 1):
                if (shaded[r][c] and shaded[r][c+1] and 
                    shaded[r+1][c] and shaded[r+1][c+1]):
                    return False
        return True

    def solve_recursive(idx):
        if idx == len(sorted_regions):
            # All regions assigned, check global connectivity
            return check_connected(shaded)

        rid = sorted_regions[idx]
        adj_types = set(solution.get(adj_rid, (None, None))[0] for adj_rid in adjacencies[rid] if adj_rid in solution)

        for t in ['L', 'I', 'T', 'S']:
            if t in adj_types:
                continue  # Adjacent region already uses this type

            for placed_cells, _ in placements[rid][t]:
                # Check if any cell already shaded
                conflict = False
                for r, c in placed_cells:
                    if shaded[r][c]:
                        conflict = True
                        break
                if conflict:
                    continue

                # Place this tetromino
                for r, c in placed_cells:
                    shaded[r][c] = True

                if is_valid_partial():
                    solution[rid] = (t, placed_cells)

                    if solve_recursive(idx + 1):
                        return True

                    del solution[rid]

                # Unplace
                for r, c in placed_cells:
                    shaded[r][c] = False

        return False

    if not solve_recursive(0):
        return "No Solution"

    # Build result grid
    result = [[None] * cols for _ in range(rows)]
    for rid, (t, cells) in solution.items():
        for r, c in cells:
            result[r][c] = t

    return result

