    rows = len(data)
    cols = len(data[0]) if rows > 0 else 0

    # Grid dimensions: dots are at integer coordinates from (0,0) to (rows, cols)
    dot_rows = rows + 1
    dot_cols = cols + 1

    # Edge representation: horizontal_edges[r][c] is edge from (r,c) to (r,c+1)
    # vertical_edges[r][c] is edge from (r,c) to (r+1,c)
    # States: 0 = unknown, 1 = part of loop, -1 = not part of loop

    from collections import deque

    # Initialize constraint propagation
    def get_cell_edges(r, c, horiz, vert):
        """Get the 4 edges around cell center (r+0.5, c+0.5)"""
        # Top edge: horizontal_edges[r][c]
        # Bottom edge: horizontal_edges[r+1][c]
        # Left edge: vertical_edges[r][c]
        # Right edge: vertical_edges[r][c+1]
        return [horiz[r][c], horiz[r+1][c], vert[r][c], vert[r+1][c]]

    def count_edges(edges):
        """Count known loop edges (1s) and possible edges (0s or 1s)"""
        known = sum(1 for e in edges if e == 1)
        unknown = sum(1 for e in edges if e == 0)
        forbidden = sum(1 for e in edges if e == -1)
        return known, unknown, forbidden

    def propagate(horiz, vert, data):
        """Apply constraint propagation. Returns (changed, contradiction)"""
        changed = True
        iterations = 0
        max_iter = 10000

        while changed and iterations < max_iter:
            changed = False
            iterations += 1

            # Process clue constraints
            for r in range(rows):
                for c in range(cols):
                    clue = data[r][c]
                    if clue is None:
                        continue

                    edges = get_cell_edges(r, c, horiz, vert)
                    known, unknown, forbidden = count_edges(edges)

                    # If we need exactly 'clue' edges and have 'known' so far
                    # with 'unknown' remaining possibilities
                    remaining = clue - known

                    if remaining < 0:
                        return False, True  # Contradiction: too many edges

                    if remaining > unknown:
                        return False, True  # Contradiction: not enough possible edges

                    if remaining == 0:
                        # All unknown edges must be -1
                        for i, e in enumerate(edges):
                            if e == 0:
