                        for i, e in enumerate(edges):
                            if e == 0:
                                if i == 0:  # top
                                    if horiz[r][c] != 0:
                                        return False, True
                                    horiz[r][c] = 1
                                elif i == 1:  # bottom
                                    if horiz[r+1][c] != 0:
                                        return False, True
                                    horiz[r+1][c] = 1
                                elif i == 2:  # left
                                    if vert[r][c] != 0:
                                        return False, True
                                    vert[r][c] = 1
                                else:  # right
                                    if vert[r][c+1] != 0:
                                        return False, True
                                    vert[r][c+1] = 1
                                changed = True

            # Process dot constraints (each dot has degree 0 or 2)
            for r in range(dot_rows):
                for c in range(dot_cols):
                    # Get all edges incident to this dot
                    incident = []
                    # Up: vertical_edges[r-1][c] if r > 0
                    if r > 0:
                        incident.append(('U', vert[r-1][c]))
                    # Down: vertical_edges[r][c] if r < dot_rows - 1
                    if r < dot_rows - 1:
                        incident.append(('D', vert[r][c]))
                    # Left: horizontal_edges[r][c-1] if c > 0
                    if c > 0:
                        incident.append(('L', horiz[r][c-1]))
                    # Right: horizontal_edges[r][c] if c < dot_cols - 1
                    if c < dot_cols - 1:
                        incident.append(('R', horiz[r][c]))

                    known_on = sum(1 for _, e in incident if e == 1)
                    unknown = sum(1 for _, e in incident if e == 0)
                    known_off = sum(1 for _, e in incident if e == -1)

                    # Each dot in loop has exactly 2 edges, outside has 0
                    # But we don't know which dots are in loop yet

                    # If 2 edges are on, rest must be off
                    if known_on == 2:
                        for dir_name, e in incident:
                            if e == 0:
                                if dir_name == 'U':
                                    vert[r-1][c] = -1
                                elif dir_name == 'D':
                                    vert[r][c] = -1
                                elif dir_name == 'L':
                                    horiz[r][c-1] = -1
                                else:
                                    horiz[r][c] = -1
                                changed = True

                    # If only 2 unknown and need 2 more, both must be on
                    elif known_on < 2 and unknown == 2 - known_on:
                        for dir_name, e in incident:
                            if e == 0:
                                if dir_name == 'U':
                                    vert[r-1][c] = 1
                                elif dir_name == 'D':
                                    vert[r][c] = 1
                                elif dir_name == 'L':
                                    horiz[r][c-1] = 1
                                else:
                                    horiz[r][c] = 1
                                changed = True

                    # If 3 edges are off, last must be off (can't have 1 edge)
                    elif known_off == 3 and unknown == 1:
                        for dir_name, e in incident:
                            if e == 0:
                                if dir_name == 'U':
                                    vert[r-1][c] = -1
                                elif dir_name == 'D':
                                    vert[r][c] = -1
                                elif dir_name == 'L':
                                    horiz[r][c-1] = -1
                                else:
                                    horiz[r][c] = -1
                                changed = True

                    # If 2 edges are on and there's another unknown, invalid
                    elif known_on > 2:
                        return False, True

        return True, False

    def check_connectivity(horiz, vert):
        """Check that all 1-edges form a single loop without branches"""
        # Find all edges that are 1
        edges_set = set()

        for r in range(dot_rows):
            for c in range(dot_cols - 1):
                if horiz[r][c] == 1:
                    edges_set.add(((r, c), (r, c+1)))

        for r in range(dot_rows - 1):
            for c in range(dot_cols):
                if vert[r][c] == 1:
                    edges_set.add(((r, c), (r+1, c)))

        if not edges_set:
            return False

        # Build adjacency
        adj = {}
        for (a, b) in edges_set:
            if a not in adj:
                adj[a] = []
            if b not in adj:
                adj[b] = []
            adj[a].append(b)
            adj[b].append(a)

        # Check all vertices in loop have degree 2
        for v, neighbors in adj.items():
            if len(neighbors) != 2:
                return False

        # Check single connected component
        start = next(iter(adj.keys()))
        visited = set()
        stack = [start]
        while stack:
            v = stack.pop()
            if v in visited:
                continue
            visited.add(v)
            for n in adj[v]:
                if n not in visited:
                    stack.append(n)

        return len(visited) == len(adj)

    def extract_loop(horiz, vert):
        """Extract the loop as ordered list of coordinates"""
        # Find all edges that are 1
        edges_set = set()

        for r in range(dot_rows):
            for c in range(dot_cols - 1):
                if horiz[r][c] == 1:
                    edges_set.add(((r, c), (r, c+1)))

        for r in range(dot_rows - 1):
            for c in range(dot_cols):
                if vert[r][c] == 1:
                    edges_set.add(((r, c), (r+1, c)))

        # Build adjacency
        adj = {}
        for (a, b) in edges_set:
            if a not in adj:
                adj[a] = []
            if b not in adj:
                adj[b] = []
            adj[a].append(b)
            adj[b].append(a)

        # Find start (topmost, leftmost)
        start = min(adj.keys())

        # Traverse loop
        result = [start]
        prev = None
        curr = start

        while True:
            neighbors = adj[curr]
            next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
            if next_node == start:
                break
            result.append(next_node)
            prev, curr = curr, next_node

        result.append(start)
        return result

    def copy_state(horiz, vert):
        return [row[:] for row in horiz], [row[:] for row in vert]

    def solve_recursive(horiz, vert, depth=0):
        """Recursive solving with constraint propagation"""
        # Propagate constraints
        ok, contradiction = propagate(horiz, vert, data)
        if not ok or contradiction:
            return None

        # Check if solved
        # All clues satisfied and all edges determined
        all_determined = True
        for r in range(dot_rows):
            for c in range(dot_cols - 1):
                if horiz[r][c] == 0:
                    all_determined = False
                    break
            if not all_determined:
                break

        for r in range(dot_rows - 1):
            for c in range(dot_cols):
                if vert[r][c] == 0:
                    all_determined = False
                    break
            if not all_determined:
                break

        if all_determined:
            if check_connectivity(horiz, vert):
                return extract_loop(horiz, vert)
            return None

        # Find best variable to branch on
        # Prefer cells with clues, then edges near determined edges
        best_score = -1
        best_var = None

        # Check clue cells first
        for r in range(rows):
            for c in range(cols):
                if data[r][c] is None:
                    continue
                edges = get_cell_edges(r, c, horiz, vert)
                unknown_count = sum(1 for e in edges if e == 0)
                if unknown_count > 0 and unknown_count < best_score or best_score == -1:
                    # Find first unknown edge
                    for i, e in enumerate(edges):
                        if e == 0:
                            if i == 0:
                                best_var = ('H', r, c)
                            elif i == 1:
                                best_var = ('H', r+1, c)
                            elif i == 2:
                                best_var = ('V', r, c)
                            else:
                                best_var = ('V', r, c+1)
                            best_score = unknown_count
                            break

        # If no good clue cell, pick any unknown edge
        if best_var is None:
            for r in range(dot_rows):
                for c in range(dot_cols - 1):
                    if horiz[r][c] == 0:
                        best_var = ('H', r, c)
                        break
                if best_var:
                    break

            if best_var is None:
                for r in range(dot_rows - 1):
                    for c in range(dot_cols):
                        if vert[r][c] == 0:
                            best_var = ('V', r, c)
                            break
                    if best_var:
                        break

        if best_var is None:
            return None

        # Try both assignments
        var_type, vr, vc = best_var

        # Try 1 first (part of loop)
        h2, v2 = copy_state(horiz, vert)
        if var_type == 'H':
            h2[vr][vc] = 1
        else:
            v2[vr][vc] = 1

        result = solve_recursive(h2, v2, depth+1)
        if result:
            return result

        # Try -1 (not part of loop)
        h2, v2 = copy_state(horiz, vert)
        if var_type == 'H':
            h2[vr][vc] = -1
        else:
            v2[vr][vc] = -1

        result = solve_recursive(h2, v2, depth+1)
        return result

    # Initialize edge arrays
    horiz = [[0] * cols for _ in range(dot_rows)]
    vert = [[0] * dot_cols for _ in range(rows)]

    # Pre-process: 0 clues mean all edges are off
    for r in range(rows):
        for c in range(cols):
            if data[r][c] == 0:
                horiz[r][c] = -1
                horiz[r+1][c] = -1
                vert[r][c] = -1
                vert[r][c+1] = -1

    result = solve_recursive(horiz, vert)
    return result if result else "No Solution"

