        # Generate all valid configurations
        def gen_configs(idx, pos, current):
            if idx == len(clues):
                # Fill rest with white
                result = current + [-1] * (n - len(current))
                if len(result) == n:
                    yield result
                return

            clue = clues[idx]
            min_start = pos
            max_start = n - clue - sum(clues[idx+1:]) - (len(clues) - idx - 1)

            for start in range(min_start, max_start + 1):
                # Check: can't overlap with existing whites
                valid = True
                for i in range(start, start + clue):
                    if i < n and line[i] == -1:
                        valid = False
                        break
                if not valid:
                    continue

                # Check: previous cell must be white or start
                if start > 0 and current and current[-1] == 1:
                    continue  # need gap

                new_current = current + [-1] * (start - len(current)) + [1] * clue
                if start + clue < n:
                    new_current = new_current + [-1]  # gap
                    next_pos = start + clue + 1
                else:
                    next_pos = start + clue

                yield from gen_configs(idx + 1, next_pos, new_current)

        valid_configs = []
        for config in gen_configs(0, 0, []):
            # Verify against known cells
            valid = True
            for i in range(n):
                if line[i] == 1 and config[i] != 1:
                    valid = False
                    break
                if line[i] == -1 and config[i] != -1:
                    valid = False
                    break
            if valid:
                valid_configs.append(config)

        if not valid_configs:
            return None

        # Find cells that are same in all valid configs
        result = list(line)
        for i in range(n):
            if line[i] == 0:
                vals = set(c[i] for c in valid_configs)
                if len(vals) == 1:
                    result[i] = vals.pop()

        return result

    def propagate():
        """Propagate constraints until fixed point"""
        nonlocal grid
        changed = True
        while changed:
            changed = False

            # Process rows
            for r in range(rows):
                line = grid[r]
                new_line = solve_line(line, row_clues[r])
                if new_line is None:
                    return False
                for c in range(cols):
                    if line[c] == 0 and new_line[c] != 0:
                        grid[r][c] = new_line[c]
                        changed = True

            # Process columns
            for c in range(cols):
                line = [grid[r][c] for r in range(rows)]
                new_line = solve_line(line, col_clues[c])
                if new_line is None:
                    return False
                for r in range(rows):
                    if grid[r][c] == 0 and new_line[r] != 0:
                        grid[r][c] = new_line[r]
                        changed = True

        return True

    def is_complete():
        """Check if puzzle is completely solved"""
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    return False
        return True

    def is_valid_complete():
        """Verify complete solution"""
        for r in range(rows):
            line = grid[r]
            if not line_satisfies(line, row_clues[r]):
                return False
        for c in range(cols):
            line = [grid[r][c] for r in range(rows)]
            if not line_satisfies(line, col_clues[c]):
                return False
        return True

    def solve_recursive():
        """Recursive solving with backtracking"""
        if is_complete():
            return is_valid_complete()

        # Find most constrained cell
        best_r, best_c = -1, -1
        best_score = float('inf')

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    # Simple heuristic: prefer cells in more constrained lines
                    score = 0
                    # Count unknowns in row and column
                    row_unknowns = sum(1 for x in grid[r] if x == 0)
                    col_unknowns = sum(1 for grid[r][c] == 0 for r in range(rows))
                    score = row_unknowns + col_unknowns
                    if score < best_score:
                        best_score = score
                        best_r, best_c = r, c

        if best_r == -1:
            return is_valid_complete()

        # Try black
        grid[best_r][best_c] = 1
        old_grid = [row[:] for row in grid]

        if propagate():
            if solve_recursive():
                return True

        # Restore and try white
        grid = old_grid
        grid[best_r][best_c] = -1

        if propagate():
            if solve_recursive():
                return True

        # Restore
        grid = old_grid
        grid[best_r][best_c] = 0
        return False

    # Initial propagation
    if not propagate():
        return "No Solution"

    if is_complete():
        if is_valid_complete():
            # Format result
            result = []
            for r in range(rows):
                row = []
                for c in range(cols):
                    row.append('B' if grid[r][c] == 1 else None)
                result.append(row)
            return result
        return "No Solution"

