from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n > 0 else 0

    # Grid has (n+1) x (m+1) dots
    rows = n + 1
    cols = m + 1

    # Edge representation: horizontal edges and vertical edges
    # h_edges[r][c] = edge from (r,c) to (r,c+1), valid for r in [0,rows), c in [0,cols-1)
    # v_edges[r][c] = edge from (r,c) to (r+1,c), valid for r in [0,rows-1), c in [0,cols)
    h_edges = [[None] * (cols - 1) for _ in range(rows)]
    v_edges = [[None] * cols for _ in range(rows - 1)]

