    def get_cell_edges(cr, cc):
        """Get the 4 edges surrounding cell (cr, cc) where clue is at (cr+0.5, cc+0.5)"""
        # Cell center is at (cr+0.5, cc+0.5), so cell spans rows cr to cr+1, cols cc to cc+1
        # Top edge: h_edges[cr][cc]
        # Bottom edge: h_edges[cr+1][cc]
        # Left edge: v_edges[cr][cc]
        # Right edge: v_edges[cr][cc+1]
        return [
            ('h', cr, cc),      # top
            ('h', cr + 1, cc),  # bottom
            ('v', cr, cc),      # left
            ('v', cr, cc + 1)   # right
        ]

    def get_edge_val(etype, er, ec):
        if etype == 'h':
            if 0 <= er < rows and 0 <= ec < cols - 1:
                return h_edges[er][ec]
            return None
        else:
            if 0 <= er < rows - 1 and 0 <= ec < cols:
                return v_edges[er][ec]
            return None

    def set_edge_val(etype, er, ec, val):
        if etype == 'h':
            if 0 <= er < rows and 0 <= ec < cols - 1:
                h_edges[er][ec] = val
        else:
            if 0 <= er < rows - 1 and 0 <= ec < cols:
                v_edges[er][ec] = val

    def count_cell_edges(cr, cc):
        """Count how many edges are ON around cell (cr, cc)"""
        edges = get_cell_edges(cr, cc)
        count = 0
        unknown = 0
        for etype, er, ec in edges:
            val = get_edge_val(etype, er, ec)
            if val == 1:
                count += 1
            elif val is None:
                unknown += 1
        return count, unknown

