    def verify_loop():
        """Verify the solution forms a single closed loop without branches"""
        # Find starting point
        start = None
        for r in range(rows):
            for c in range(cols):
                # Count edges at this dot
                count = 0
                if c > 0 and h_edges[r][c-1] == 1:
