        return len(visited) == edge_count and len(visited) > 0

    def get_loop_path():
        """Extract the loop path as list of coordinates"""
        # Find start
        start = None
        for r in range(rows):
            for c in range(cols):
                count = 0
                if c > 0 and h_edges[r][c-1] == 1:
                    count += 1
                if c < cols - 1 and h_edges[r][c] == 1:
                    count += 1
                if r > 0 and v_edges[r-1][c] == 1:
                    count += 1
                if r < rows - 1 and v_edges[r][c] == 1:
                    count += 1
