            if c < cols - 1 and h_edges[r][c] == 1:
                next_dots.append((r, c+1))
            if r > 0 and v_edges[r-1][c] == 1:
                next_dots.append((r-1, c))
            if r < rows - 1 and v_edges[r][c] == 1:
                next_dots.append((r+1, c))

            candidates = [d for d in next_dots if d != prev]
            if not candidates:
                break

            prev, curr = curr, candidates[0]
            path.append(curr)

            if curr == start:
                break

        return path

