    def place_tent(tree_idx, r, c):
        tent_grid[r][c] = 't'
        tree_tent[tree_idx] = (r, c)
        row_counts[r] += 1
        col_counts[c] += 1

    def remove_tent(tree_idx, r, c):
        tent_grid[r][c] = None
        del tree_tent[tree_idx]
        row_counts[r] -= 1
        col_counts[c] -= 1

    # Backtracking solver
    def backtrack():
