            return False

        # Try each position
        for (r, c) in best_options:
            place_tent(best_tree, r, c)

            if forward_check([i for i in unpaired if i != best_tree]):
                if backtrack():
                    return True

            remove_tent(best_tree, r, c)

        return False

    # Initial propagation
    if not propagate():
        # Need to backtrack from start
        if not backtrack():
            return "No Solution"
    else:
        # Check if solved
        if len(tree_tent) < num_trees:
            if not backtrack():
                return "No Solution"

    # Verify solution
    for r in range(rows):
        if row_counts[r] != row_clues[r]:
            return "No Solution"
    for c in range(cols):
        if col_counts[c] != col_clues[c]:
            return "No Solution"

    # Format answer
    answer = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if tent_grid[r][c] == 't':
                row.append('t')
            else:
                row.append(None)
        answer.append(row)

    return answer

