        # stars = list of placed stars [(r,c), ...]
        # blocked = set of cells blocked by existing stars (including diagonals)

        # Use iterative deepening / constraint propagation with backtracking

        # State representation for backtracking
        class State:
            __slots__ = ['row_has', 'col_has', 'reg_has', 'stars', 'blocked']
            def __init__(self):
                self.row_has = [False] * n
                self.col_has = [False] * n
                self.reg_has = {r: False for r in regions}
                self.stars = []
                self.blocked = set()

