            new_state.row_has = state.row_has[:]
            new_state.col_has = state.col_has[:]
            new_state.reg_has = state.reg_has.copy()
            new_state.stars = state.stars + [(r, c)]
            new_state.blocked = state.blocked | get_neighbors(r, c) | {(r, c)}

            new_state.row_has[r] = True
            new_state.col_has[c] = True
            new_state.reg_has[cell_region[(r, c)]] = True

