            # Trace loop
            visited = set()
            current = start
            prev = None
            path = [current]

            while True:
                visited.add(current)
                neighbors = adj.get(current, [])
                next_node = None
                for nb in neighbors:
                    if nb != prev:
                        next_node = nb
                        break

                if next_node is None:
                    return None

                if next_node in visited:
                    if next_node == start and len(path) > 2:
                        # Check all degree-2 nodes visited
                        for pos, deg in [(p, len(adj.get(p,[]))) for p in adj]:
                            if deg == 2 and pos not in visited:
                                return None
                        path.append(start)
                        return path
                    return None

                prev, current = current, next_node
                path.append(current)

            return None

        return backtrack(0, [], {})

    result = solve_edges()

    if result is None:
        return "No Solution"

    return result

