                        # Can be used or not
                        pass

            # If no endpoints, check if valid complete
            if len(endpoints) == 0:
                return is_valid_partial() and is_single_loop() and clues_satisfied()

            # If exactly 2 endpoints, try to connect them
            if len(endpoints) == 2:
                r1, c1 = endpoints[0]
                r2, c2 = endpoints[1]

                # Try all ways to connect
                # Direct connection if adjacent
                if abs(r1-r2) + abs(c1-c2) == 1:
                    # Try adding edge
                    if r1 == r2:  # horizontal
                        hc = min(c1, c2)
                        if not h_edges[r1][hc]:
                            h_edges[r1][hc] = True
                            if solve_remaining():
                                return True
                            h_edges[r1][hc] = False
                    else:  # vertical
                        vr = min(r1, r2)
                        if not v_edges[vr][c1]:
                            v_edges[vr][c1] = True
                            if solve_remaining():
