                            v_edges[vr][c1] = False

                # Or extend each endpoint
                # Try extending r1,c1
                for nr, nc, d in get_neighbors(r1, c1):
                    if get_degree(nr, nc) >= 2:
                        continue
                    if (r1, c1) in clues and (nr, nc) in clues:
                        continue  # Don't connect clues directly unless required

                    # Add edge
                    if d == 0:  # up from r1,c1
                        if not v_edges[r1-1][c1]:
                            v_edges[r1-1][c1] = True
                            if solve_remaining():
                                return True
                            v_edges[r1-1][c1] = False
                    elif d == 1:
                        if not h_edges[r1][c1]:
                            h_edges[r1][c1] = True
                            if solve_remaining():
                                return True
                            h_edges[r1][c1] = False
                    elif d == 2:
                        if not v_edges[r1][c1]:
                            v_edges[r1][c1] = True
                            if solve_remaining():
