                            v_edges[r1][c1] = False
                    elif d == 3:
                        if not h_edges[r1][c1-1]:
                            h_edges[r1][c1-1] = True
                            if solve_remaining():
                                return True
                            h_edges[r1][c1-1] = False

                return False

            # More than 2 endpoints - need to extend one
            if len(endpoints) > 2:
                r1, c1 = endpoints[0]
                for nr, nc, d in get_neighbors(r1, c1):
                    if get_degree(nr, nc) >= 2:
                        continue

                    if d == 0:
                        if not v_edges[r1-1][c1]:
                            v_edges[r1-1][c1] = True
                            if solve_remaining():
                                return True
                            v_edges[r1-1][c1] = False
                    elif d == 1:
                        if not h_edges[r1][c1]:
                            h_edges[r1][c1] = True
                            if solve_remaining():
                                return True
                            h_edges[r1][c1] = False
                    elif d == 2:
                        if not v_edges[r1][c1]:
                            v_edges[r1][c1] = True
                            if solve_remaining():
                                return True
                            v_edges[r1][c1] = False
                    elif d == 3:
                        if not h_edges[r1][c1-1]:
                            h_edges[r1][c1-1] = True
                            if solve_remaining():
                                return True
                            h_edges[r1][c1-1] = False

                return False

            return False

        return solve_remaining()

    # Modified backtrack that also completes the loop
    def backtrack_complete(clue_idx):
        if clue_idx == len(clue_order):
            # Try to complete the loop
            if complete_loop():
                path = extract_path()
                if path and check_w_turns(set(path[:-1]), path):
                    return path
            return None

        r, c = clue_order[clue_idx]
        typ = clues[(r, c)]
        valid_pairs = clue_valid_dirs[(r, c)]

        for d1, d2 in valid_pairs:
            edges_to_set = []

            # Compute edges
            def add_edge(d):
                if d == 0 and r > 0:
                    if not v_edges[r-1][c]:
                        edges_to_set.append(('v', r-1, c))
                elif d == 1 and c < m-1:
                    if not h_edges[r][c]:
                        edges_to_set.append(('h', r, c))
                elif d == 2 and r < n-1:
                    if not v_edges[r][c]:
                        edges_to_set.append(('v', r, c))
                elif d == 3 and c > 0:
                    if not h_edges[r][c-1]:
                        edges_to_set.append(('h', r, c-1))

            add_edge(d1)
            add_edge(d2)

            if len(edges_to_set) != 2:
                continue

            # Check for duplicate
            if edges_to_set[0] == edges_to_set[1]:
                continue

            # Apply
            for etype, er, ec in edges_to_set:
                if etype == 'h':
                    h_edges[er][ec] = True
                else:
                    v_edges[er][ec] = True

            # Quick validity check
            valid = True
            for etype, er, ec in edges_to_set:
                if etype == 'h':
                    if get_degree(er, ec) > 2 or get_degree(er, ec+1) > 2:
                        valid = False
                else:
                    if get_degree(er, ec) > 2 or get_degree(er+1, ec) > 2:
                        valid = False

            if valid:
                result = backtrack_complete(clue_idx + 1)
                if result is not None:
                    return result

            # Undo
            for etype, er, ec in edges_to_set:
                if etype == 'h':
                    h_edges[er][ec] = False
                else:
                    v_edges[er][ec] = False

        return None

    # Try solving
    result = backtrack_complete(0)

    if result is None:
        # Try alternative: more exhaustive search with connection
        result = backtrack(0)
        if result:
            # Need to complete the loop
            pass

    return result if result else "No Solution"

