                result.append(tuple(current_indices))
                return
            if current_sum > target:
                return
            for i in range(start, n):
                w = weights[i]
                if current_sum + w <= target:
                    dfs(i + 1, current_sum + w, current_indices + [i])

        dfs(0, 0, [])
