        best_score = float('inf')

        for r in range(n_rows):
            for c in range(n_cols):
                if grid[r][c] != 0:
                    continue

                # Count possibilities if we set to black vs white
                black_count = sum(1 for poss in row_possibilities[r] if c in poss)
                white_count = sum(1 for poss in row_possibilities[r] if c not in poss)

                # Also consider column constraints
                black_count_col = sum(1 for poss in col_possibilities[c] if r in poss)
                white_count_col = sum(1 for poss in col_possibilities[c] if r not in poss)

                # Score: prefer cells where one option is impossible or very constrained
                score = min(black_count + black_count_col, white_count + white_count_col)

                if score < best_score:
                    best_score = score
                    best_r, best_c = r, c

        if best_r == -1:
            return False

        r, c = best_r, best_c

        # Try black first (usually more constrained)
        for val in [1, -1]:
            # Save state
            old_grid = [row[:] for row in grid]
            old_row_poss = [p[:] for p in row_possibilities]
            old_col_poss = [p[:] for p in col_possibilities]

            grid[r][c] = val

            if propagate():
                if backtrack():
