            # Restore state
            for i in range(n_rows):
                grid[i] = old_grid[i][:]
            row_possibilities[:] = [p[:] for p in old_row_poss]
            col_possibilities[:] = [p[:] for p in old_col_poss]

        return False

    if backtrack():
        return format_solution(grid)
    else:
        return "No Solution"

def format_solution(grid):
    n_rows = len(grid)
    n_cols = len(grid[0])
    result = []
    for r in range(n_rows):
        row = []
        for c in range(n_cols):
            if grid[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        result.append(row)
    return result

