# Star Battle Solver with Human-like Deductive Reasoning
# Uses constraint propagation and backtracking with aggressive pruning

def solve(observation):
    grid = observation['data']
    n = len(grid)
    if n == 0:
        return "No Solution"

    # Build region map: region_id -> set of (r, c) cells
    regions = {}
    for r in range(n):
        for c in range(n):
            rid = grid[r][c]
            if rid not in regions:
                regions[rid] = set()
            regions[rid].add((r, c))

    num_regions = len(regions)
    if num_regions != n:
        return "No Solution"  # Must have n regions for n rows/cols

    # Precompute: for each cell, which cells it conflicts with (same row/col/region + adjacent)
    # But we'll use dynamic constraint checking

    # State tracking
    # stars[r] = c if row r has star at column c, else -1
    # cols_used[c] = True if column c has a star
    # regions_used[rid] = True if region rid has a star

    stars = [-1] * n  # stars[r] = column of star in row r
    cols_used = [False] * n
    regions_used = {rid: False for rid in regions}

    # For each row, track possible columns (constraint propagation)
    # possible[r] = set of valid columns for row r

    def get_region(r, c):
        return grid[r][c]

    def is_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1 and (r1, c1) != (r2, c2)

    def would_conflict(r, c, stars_so_far):
        # Check column
        if cols_used[c]:
            return True
        # Check region
        rid = get_region(r, c)
        if regions_used[rid]:
            return True
        # Check adjacency with existing stars
        for r2 in range(r):
            if stars[r2] != -1:
                c2 = stars[r2]
                if is_adjacent(r, c, r2, c2):
                    return True
        return False

    def get_possible_cols(row, stars_so_far):
        """Get all valid columns for this row given current state"""
        possible = []
        for c in range(n):
            if would_conflict(row, c, stars_so_far):
                continue
            possible.append(c)
        return possible

    # Constraint propagation: For remaining rows, check if any region/column is forced
    def propagate(stars, cols_used, regions_used, next_row):
        """Returns (success, updated_possible) or (False, None) if contradiction"""
        # Build possible sets for all remaining rows
        possible = {}
        for r in range(next_row, n):
            poss = []
            for c in range(n):
                if cols_used[c]:
                    continue
                rid = get_region(r, c)
                if regions_used[rid]:
                    continue
                # Check adjacency with placed stars
                conflict = False
                for r2 in range(next_row):
                    if stars[r2] != -1:
                        if is_adjacent(r, c, r2, stars[r2]):
                            conflict = True
                            break
                if not conflict:
                    poss.append(c)
            if not poss:
                return False, None  # No valid placement for this row
            possible[r] = poss

        # Check for forced placements by region constraint
        # If a region only appears in one remaining row, that row must place there
        changed = True
        while changed:
            changed = False

            # For each unplaced region, find which rows can still place it
            region_possible_rows = {}
            for rid, used in regions_used.items():
                if used:
                    continue
                region_possible_rows[rid] = []
                for r in range(next_row, n):
                    for c in possible.get(r, []):
                        if get_region(r, c) == rid:
                            region_possible_rows[rid].append((r, c))
                            break  # Only need to know row can place this region

            # If any region has only one possible row, and that row has multiple options,
            # we can't force column, but if region has only one cell in that row's possibilities...

            # Check for regions with only one possible (row, col) pair
            for rid, placements in region_possible_rows.items():
                if len(placements) == 0:
                    return False, None  # No place for this region
                # If only one placement possible, it's forced
                if len(placements) == 1:
                    r, c = placements[0]
                    # Verify this is still possible
                    if c in possible.get(r, []):
                        # This is a forced placement - but we handle in search
                        pass

        return True, possible

    def solve_recursive(row):
        if row == n:
            # All rows placed, verify solution
            return True

        # Get possible columns with constraint propagation
        success, possible = propagate(stars, cols_used, regions_used, row)
        if not success:
            return False

        # Try each possible column for this row, ordered by constraint tightness
        candidates = possible.get(row, [])

        # Sort by: number of constraints this placement adds (prefer tighter constraints)
        # Actually, prefer cells that are in regions with fewer remaining options
        def score(c):
            rid = get_region(row, c)
            # Count how many other rows could place in this region
            count = 0
            for r2 in range(row + 1, n):
                for c2 in possible.get(r2, []):
                    if get_region(r2, c2) == rid:
                        count += 1
                        break
            return count

        candidates.sort(key=score)

        for c in candidates:
            # Place star at (row, c)
            rid = get_region(row, c)
            stars[row] = c
            cols_used[c] = True
            regions_used[rid] = True

            if solve_recursive(row + 1):
                return True

            # Backtrack
            stars[row] = -1
            cols_used[c] = False
            regions_used[rid] = False

        return False

    if solve_recursive(0):
        # Build result grid
        result = [[None for _ in range(n)] for _ in range(n)]
        for r in range(n):
            result[r][stars[r]] = 'S'
        return result

    return "No Solution"

