# Slitherlink Solver with Human-like Deductive Reasoning
# Uses constraint propagation and pattern-based deduction before search

from collections import deque

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows > 0 else 0

    # Grid dimensions: dots are at integer coordinates (0..rows, 0..cols)
    # Cells are between dots, clues are at cell centers

    # Edge state: 0=unknown, 1=line, -1=no line
    # Horizontal edges: h_edges[r][c] connects (r,c) to (r,c+1), size rows+1 x cols
    # Vertical edges: v_edges[r][c] connects (r,c) to (r+1,c), size rows x cols+1

    h_edges = [[0] * cols for _ in range(rows + 1)]
    v_edges = [[0] * (cols + 1) for _ in range(rows)]

    # Helper to get edges around a cell
    def cell_edges(r, c):
        # Returns (top, right, bottom, left) edge states
        return (h_edges[r][c], v_edges[r][c+1], h_edges[r+1][c], v_edges[r][c])

    def set_h_edge(r, c, val):
        if h_edges[r][c] != 0 and h_edges[r][c] != val:
            return False  # Conflict
        if h_edges[r][c] == 0:
            h_edges[r][c] = val
            return True  # Changed
        return False  # No change

    def set_v_edge(r, c, val):
        if v_edges[r][c] != 0 and v_edges[r][c] != val:
            return False  # Conflict
        if v_edges[r][c] == 0:
            v_edges[r][c] = val
            return True  # Changed
        return False  # No change

    # Constraint propagation queue
    queue = deque()

    # Initialize with clue constraints
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                queue.append(('cell', r, c))

    # Add all edges for degree checking
    for r in range(rows + 1):
        for c in range(cols):
            queue.append(('h_dot', r, c))
    for r in range(rows):
        for c in range(cols + 1):
            queue.append(('v_dot', r, c))

    def propagate():
        while queue:
            item = queue.popleft()
            typ = item[0]

            if typ == 'cell':
                r, c = item[1], item[2]
                clue = data[r][c]
                if clue is None:
                    continue

                top, right, bot, left = cell_edges(r, c)
                edges = [top, right, bot, left]
                unknown = [i for i, e in enumerate(edges) if e == 0]
                known_line = sum(1 for e in edges if e == 1)
                known_noline = sum(1 for e in edges if e == -1)

                # If clue satisfied, remaining edges must be no-line
                if known_line == clue:
                    for i in unknown:
                        if i == 0: 
                            if set_h_edge(r, c, -1): queue.append(('h_edge', r, c, -1))
                        elif i == 1: 
                            if set_v_edge(r, c+1, -1): queue.append(('v_edge', r, c+1, -1))
                        elif i == 2: 
                            if set_h_edge(r+1, c, -1): queue.append(('h_edge', r+1, c, -1))
                        elif i == 3: 
                            if set_v_edge(r, c, -1): queue.append(('v_edge', r, c, -1))

                # If remaining unknowns must all be lines to satisfy clue
                if known_line + len(unknown) == clue:
                    for i in unknown:
                        if i == 0: 
                            if set_h_edge(r, c, 1): queue.append(('h_edge', r, c, 1))
                        elif i == 1: 
                            if set_v_edge(r, c+1, 1): queue.append(('v_edge', r, c+1, 1))
                        elif i == 2: 
                            if set_h_edge(r+1, c, 1): queue.append(('h_edge', r+1, c, 1))
                        elif i == 3: 
                            if set_v_edge(r, c, 1): queue.append(('v_edge', r, c, 1))

                # If too many lines or impossible to satisfy
                if known_line > clue or known_line + len(unknown) < clue:
                    return False

            elif typ == 'h_edge':
                r, c, val = item[1], item[2], item[3]
                # Affect adjacent cells and dots
                # Affects cell above (r-1, c) if r > 0
                if r > 0 and data[r-1][c] is not None:
                    queue.append(('cell', r-1, c))
                # Affects cell below (r, c) if r < rows
                if r < rows and data[r][c] is not None:
                    queue.append(('cell', r, c))
                # Affect dots
                queue.append(('h_dot', r, c))
                if c > 0:
                    queue.append(('h_dot', r, c-1))

            elif typ == 'v_edge':
                r, c, val = item[1], item[2], item[3]
                # Affect adjacent cells
                if c > 0 and data[r][c-1] is not None:
                    queue.append(('cell', r, c-1))
                if c < cols and data[r][c] is not None:
                    queue.append(('cell', r, c))
                # Affect dots
                queue.append(('v_dot', r, c))
                if r > 0:
                    queue.append(('v_dot', r-1, c))

            elif typ == 'h_dot':
                r, c = item[1], item[2]
                # Dot at (r,c): connected to h_edges[r][c-1], h_edges[r][c], v_edges[r-1][c], v_edges[r][c]
                # (with bounds checking)
                connections = []
                if c > 0:
                    connections.append(('h', r, c-1, h_edges[r][c-1]))
                if c < cols:
                    connections.append(('h', r, c, h_edges[r][c]))
                if r > 0:
