                if r < rows:
                    connections.append(('v', r, c, v_edges[r][c]))

                lines = sum(1 for t in connections if t[3] == 1)
                nolines = sum(1 for t in connections if t[3] == -1)
                unknown = [t for t in connections if t[3] == 0]

                # In loop, each dot has exactly 0 or 2 lines
                if lines == 2:
                    # Remaining must be no-line
                    for t in unknown:
                        if t[0] == 'h':
                            if set_h_edge(t[1], t[2], -1): queue.append(('h_edge', t[1], t[2], -1))
                        else:
                            if set_v_edge(t[1], t[2], -1): queue.append(('v_edge', t[1], t[2], -1))
                elif lines == 1 and len(unknown) == 1:
                    # Need one more line
                    t = unknown[0]
                    if t[0] == 'h':
                        if set_h_edge(t[1], t[2], 1): queue.append(('h_edge', t[1], t[2], 1))
                    else:
                        if set_v_edge(t[1], t[2], 1): queue.append(('v_edge', t[1], t[2], 1))
                elif lines == 0 and len(unknown) == 0:
                    return False  # Isolated dot with no lines, but we need single loop
                elif lines > 2:
                    return False

            elif typ == 'v_dot':
                r, c = item[1], item[2]
                # Same logic as h_dot
                connections = []
                if c > 0:
                    connections.append(('h', r, c-1, h_edges[r][c-1]))
                if c < cols:
                    connections.append(('h', r, c, h_edges[r][c]))
                if r > 0:
                    connections.append(('v', r-1, c, v_edges[r-1][c]))
                if r < rows:
                    connections.append(('v', r, c, v_edges[r][c]))

                lines = sum(1 for t in connections if t[3] == 1)
                nolines = sum(1 for t in connections if t[3] == -1)
                unknown = [t for t in connections if t[3] == 0]

                if lines == 2:
                    for t in unknown:
                        if t[0] == 'h':
                            if set_h_edge(t[1], t[2], -1): queue.append(('h_edge', t[1], t[2], -1))
                        else:
                            if set_v_edge(t[1], t[2], -1): queue.append(('v_edge', t[1], t[2], -1))
                elif lines == 1 and len(unknown) == 1:
                    t = unknown[0]
                    if t[0] == 'h':
                        if set_h_edge(t[1], t[2], 1): queue.append(('h_edge', t[1], t[2], 1))
                    else:
                        if set_v_edge(t[1], t[2], 1): queue.append(('v_edge', t[1], t[2], 1))
                elif lines > 2:
                    return False

        return True

    # Run initial propagation
    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        for r in range(rows):
            for c in range(cols):
                if data[r][c] is not None:
                    top, right, bot, left = cell_edges(r, c)
                    if sum(e == 1 for e in [top, right, bot, left]) != data[r][c]:
                        return False
        # Check all dots have 0 or 2 lines
        for r in range(rows + 1):
            for c in range(cols + 1):
                connections = []
                if c > 0 and h_edges[r][c-1] == 1:
                    connections.append(1)
                if c < cols and h_edges[r][c] == 1:
                    connections.append(1)
                if r > 0 and v_edges[r-1][c] == 1:
                    connections.append(1)
                if r < rows and v_edges[r][c] == 1:
                    connections.append(1)
                if len(connections) not in [0, 2]:
                    return False
        # Check single loop (connected component)
        return has_single_loop()

    def has_single_loop():
        # Find one line edge, follow loop
        start = None
        for r in range(rows + 1):
            for c in range(cols):
                if h_edges[r][c] == 1:
                    start = (r, c)
                    break
            if start:
                break
        if not start:
            for r in range(rows):
                for c in range(cols + 1):
                    if v_edges[r][c] == 1:
                        start = (r, c)
                        break
                if start:
                    break

        if not start:
            return False  # No lines at all

        # BFS to find all connected line edges
        visited_dots = set()
        queue = [(start[0], start[1])]
        # Actually we need to traverse through dots
        # Start from a dot
        dot = (start[0], start[1])
        if h_edges[start[0]][start[1]] == 1:
            dot = (start[0], start[1])  # left end of horizontal edge

        # Find all dots in the loop
        visited = set([dot])
        stack = [dot]
        while stack:
            r, c = stack.pop()
            # Find neighbors connected by lines
            neighbors = []
            if c > 0 and h_edges[r][c-1] == 1:
                neighbors.append((r, c-1))
            if c < cols and h_edges[r][c] == 1:
                neighbors.append((r, c+1))
            if r > 0 and v_edges[r-1][c] == 1:
                neighbors.append((r-1, c))
            if r < rows and v_edges[r][c] == 1:
                neighbors.append((r+1, c))

            for nr, nc in neighbors:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        # Count total line edges
        total_lines = sum(sum(1 for e in row if e == 1) for row in h_edges) + \
                      sum(sum(1 for e in row if e == 1) for row in v_edges)

        # In a single loop, edges = dots in loop
        if len(visited) != total_lines:
            return False

        # Check all dots with lines are in this component
        for r in range(rows + 1):
            for c in range(cols + 1):
                has_line = False
                if c > 0 and h_edges[r][c-1] == 1:
                    has_line = True
                if c < cols and h_edges[r][c] == 1:
                    has_line = True
                if r > 0 and v_edges[r-1][c] == 1:
                    has_line = True
                if r < rows and v_edges[r][c] == 1:
                    has_line = True
                if has_line and (r, c) not in visited:
                    return False

        return True

    def get_loop_path():
        # Extract the loop path from solved grid
        # Find starting point
        start = None
        for r in range(rows + 1):
            for c in range(cols + 1):
                lines = 0
                if c > 0 and h_edges[r][c-1] == 1:
                    lines += 1
                if c < cols and h_edges[r][c] == 1:
                    lines += 1
                if r > 0 and v_edges[r-1][c] == 1:
                    lines += 1
                if r < rows and v_edges[r][c] == 1:
                    lines += 1
                if lines == 2:
                    start = (r, c)
                    break
            if start:
                break

        if not start:
            return []

        path = [start]
        prev = None
        curr = start

        while True:
            r, c = curr
            # Find next dot connected by line
            next_dots = []
            if c > 0 and h_edges[r][c-1] == 1 and (r, c-1) != prev:
                next_dots.append((r, c-1))
            if c < cols and h_edges[r][c] == 1 and (r, c+1) != prev:
                next_dots.append((r, c+1))
            if r > 0 and v_edges[r-1][c] == 1 and (r-1, c) != prev:
                next_dots.append((r-1, c))
            if r < rows and v_edges[r][c] == 1 and (r+1, c) != prev:
                next_dots.append((r+1, c))

            if not next_dots:
                break

            prev = curr
            curr = next_dots[0]
            path.append(curr)

            if curr == start:
                break

        return path

    # Recursive search with backtracking
    def search():
        nonlocal h_edges, v_edges

        if is_solved():
            return get_loop_path()

        # Find unknown edge with most constraints (MRV)
        best_score = -1
        best_edge = None
        best_type = None

        for r in range(rows + 1):
            for c in range(cols):
                if h_edges[r][c] == 0:
                    # Score by adjacent clues and dot constraints
                    score = 0
                    if r > 0 and data[r-1][c] is not None:
                        score += 1
                    if r < rows and data[r][c] is not None:
                        score += 1
                    # Dot constraints
                    score += 2
                    if score > best_score:
                        best_score = score
                        best_edge = (r, c)
                        best_type = 'h'

        for r in range(rows):
            for c in range(cols + 1):
                if v_edges[r][c] == 0:
                    score = 0
                    if c > 0 and data[r][c-1] is not None:
                        score += 1
                    if c < cols and data[r][c] is not None:
                        score += 1
                    score += 2
                    if score > best_score:
                        best_score = score
                        best_edge = (r, c)
                        best_type = 'v'

        if best_edge is None:
            return None

        # Try both values
        for val in [1, -1]:
            # Save state
            old_h = [row[:] for row in h_edges]
            old_v = [row[:] for row in v_edges]
            old_queue = list(queue)

            # Set edge
            success = True
            if best_type == 'h':
                if not set_h_edge(best_edge[0], best_edge[1], val):
                    success = False
                else:
                    queue.append(('h_edge', best_edge[0], best_edge[1], val))
            else:
                if not set_v_edge(best_edge[0], best_edge[1], val):
                    success = False
                else:
                    queue.append(('v_edge', best_edge[0], best_edge[1], val))

            if success:
                if propagate():
                    result = search()
                    if result is not None:
                        return result

            # Restore state
            h_edges = old_h
            v_edges = old_v
            queue.clear()
            queue.extend(old_queue)

        return None

    result = search()
    if result is None:
        return "No Solution"

    # Format as list of tuples
    return str(result)

