def solve(observation):
    grid = observation['data']
    n = len(grid)
    if n == 0:
        return "No Solution"

    # Build region to cells mapping
    region_cells = {}
    for r in range(n):
        for c in range(n):
            rid = grid[r][c]
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((r, c))

    num_regions = len(region_cells)
    if num_regions != n:
        return "No Solution"

    # Precompute which cells are adjacent (including diagonally)
    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    neighbors.append((nr, nc))
        return neighbors

    # For each region, track possible cells
    # State: row_used[r], col_used[c], region_placed[rid]
    # We'll use constraint propagation and backtracking

    region_ids = sorted(region_cells.keys())

    # For each cell, precompute which rows/cols/regions it affects
    cell_to_region = {}
    for r in range(n):
        for c in range(n):
            cell_to_region[(r, c)] = grid[r][c]

    # Constraint propagation: if a row/col/region has only one possible cell, use it
    # Track available cells per region, row, col

    def solve_recursive(assignment, row_used, col_used, region_done, region_remaining):
        if len(assignment) == n:
            # Verify solution
            return assignment

        # Find region with fewest options (MRV heuristic)
        best_region = None
        best_options = None
        min_options = float('inf')

        for rid in region_remaining:
            cells = region_cells[rid]
            valid = []
            for (r, c) in cells:
                if row_used[r] or col_used[c]:
                    continue
                # Check no adjacent stars
                conflict = False
                for (ar, ac) in assignment:
                    if abs(ar - r) <= 1 and abs(ac - c) <= 1:
                        conflict = True
                        break
                if not conflict:
                    valid.append((r, c))

            if len(valid) == 0:
                return None  # Dead end

            if len(valid) < min_options:
                min_options = len(valid)
                best_region = rid
                best_options = valid
                if min_options == 1:
                    break

        if best_region is None:
            return None

        # Try each option
        for (r, c) in best_options:
            # Place star
            new_assignment = assignment + [(r, c)]
            new_row_used = row_used.copy()
            new_col_used = col_used.copy()
            new_row_used[r] = True
            new_col_used[c] = True
            new_region_done = region_done.copy()
            new_region_done[best_region] = True
            new_region_remaining = [rid for rid in region_remaining if rid != best_region]

            result = solve_recursive(new_assignment, new_row_used, new_col_used, 
                                   new_region_done, new_region_remaining)
            if result is not None:
                return result

        return None

    row_used = [False] * n
    col_used = [False] * n
    region_done = {rid: False for rid in region_ids}

    solution = solve_recursive([], row_used, col_used, region_done, region_ids)

    if solution is None:
        return "No Solution"

    # Build result grid
    result = [[None for _ in range(n)] for _ in range(n)]
    for (r, c) in solution:
        result[r][c] = 'S'

    return result

