    # We'll use union-find like approach or just track regions

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m:
                yield (nr, nc)

    def get_component(start_r, start_c, state_grid):
        """Get connected component of white cells"""
        if state_grid[start_r][start_c] != 1:
            return set()
        comp = set()
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r,c) in comp:
                continue
            comp.add((r,c))
            for nr, nc in neighbors(r,c):
                if state_grid[nr][nc] == 1 and (nr,nc) not in comp:
                    stack.append((nr,nc))
        return comp

    def check_2x2_black(state_grid):
        """Check if any 2x2 is all black"""
        for r in range(n-1):
            for c in range(m-1):
                if state_grid[r][c] == 2 and state_grid[r][c+1] == 2 and \
                   state_grid[r+1][c] == 2 and state_grid[r+1][c+1] == 2:
                    return False
        return True

    def check_black_connected(state_grid):
        """Check if black cells form one connected component"""
        black_cells = [(r,c) for r in range(n) for c in range(m) if state_grid[r][c] == 2]
        if len(black_cells) <= 1:
            return True
        visited = set()
        stack = [black_cells[0]]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for nr, nc in neighbors(r,c):
                if state_grid[nr][nc] == 2 and (nr,nc) not in visited:
                    stack.append((nr,nc))
        return len(visited) == len(black_cells)

    def check_islands_valid(state_grid):
        """Check if all white islands are valid (each has exactly one number, size matches)"""
        visited = [[False]*m for _ in range(n)]

        for r in range(n):
            for c in range(m):
                if state_grid[r][c] == 1 and not visited[r][c]:
                    # Found new white island
                    comp = get_component(r, c, state_grid)
                    for (cr, cc) in comp:
                        visited[cr][cc] = True

                    # Check if contains exactly one number
                    nums_in_comp = [(pos, numbers[pos]) for pos in comp if pos in numbers]
                    if len(nums_in_comp) != 1:
