    # Constraint propagation
    def propagate(state_grid):
        """Apply constraint propagation rules"""
        changed = True
        while changed:
            changed = False

            # Rule 1: If a white island has reached its size, surround with black
            visited = [[False]*m for _ in range(n)]
            for r in range(n):
                for c in range(m):
                    if state_grid[r][c] == 1 and not visited[r][c]:
                        comp = get_component(r, c, state_grid)
                        for (cr, cc) in comp:
                            visited[cr][cc] = True

                        nums_in_comp = [pos for pos in comp if pos in numbers]
                        if len(nums_in_comp) == 1:
                            pos = nums_in_comp[0]
                            target = numbers[pos]
                            if len(comp) == target:
                                # Island complete, mark neighbors as black
                                for (cr, cc) in comp:
                                    for nr, nc in neighbors(cr, cc):
                                        if state_grid[nr][nc] == 0:
                                            state_grid[nr][nc] = 2
                                            changed = True

            # Rule 2: If a cell being white would create 2x2 white with 3 whites, 
            # and that would connect two numbers or exceed size, mark black
            # (simplified: avoid creating invalid white regions)

            # Rule 3: Black cells cannot disconnect the black region
            # (complex, skip for efficiency)

            # Rule 4: If a number needs more cells, and only one path exists...
            # (BFS for required cells)
            for pos, val in numbers.items():
                # Find current island
                comp = get_component(pos[0], pos[1], state_grid)
                if len(comp) < val:
                    # Need to expand
                    needed = val - len(comp)
                    # Find reachable unknown cells
                    frontier = set()
                    for (cr, cc) in comp:
                        for nr, nc in neighbors(cr, cc):
                            if state_grid[nr][nc] == 0:
                                frontier.add((nr, nc))

                    # If frontier is smaller than needed, invalid
                    if len(frontier) < needed:
                        return None  # Invalid state

                    # If frontier equals needed, all must be white
                    if len(frontier) == needed:
                        for (fr, fc) in frontier:
                            if state_grid[fr][fc] == 0:
                                state_grid[fr][fc] = 1
                                changed = True

        return state_grid

    # Solve using backtracking with constraint propagation
    def solve_recursive(state_grid):
        # Propagate constraints
        propagated = propagate([row[:] for row in state_grid])
        if propagated is None:
            return None

        state_grid = propagated

        # Check if complete
        unknown = [(r,c) for r in range(n) for c in range(m) if state_grid[r][c] == 0]
        if not unknown:
            if is_complete_valid(state_grid):
                return state_grid
            return None

        # Find best cell to branch on (most constrained)
        # Prefer cells adjacent to numbered islands or black cells
        def score_cell(r, c):
            s = 0
            for nr, nc in neighbors(r, c):
                if state_grid[nr][nc] == 1:
                    s += 10
                elif state_grid[nr][nc] == 2:
                    s += 5
            return s

        unknown.sort(key=lambda x: -score_cell(x[0], x[1]))
        r, c = unknown[0]

        # Try white first (usually more constrained)
        for color in [1, 2]:
            new_grid = [row[:] for row in state_grid]
            new_grid[r][c] = color

            if not is_valid_partial(new_grid):
                continue

            result = solve_recursive(new_grid)
            if result is not None:
                return result

        return None

    solution = solve_recursive(state)

    if solution is None:
        return "No Solution"

    # Convert to output format
    result = []
    for r in range(n):
        row = []
        for c in range(m):
            if solution[r][c] == 2:
                row.append('B')
            else:
                row.append(None)
        result.append(row)

    return result

