    # For each cell, track possible directions (0-3) the loop can go
    # Each cell can have 0, 1, or 2 directions (0 or 2 for loop)
    # We'll use constraint propagation to narrow down

    # Initialize: for each dot, which directions are possible?
    # A dot is at (r, c), edges connect to neighbors

    # First, let's identify all clue positions
    clues = {}  # (r, c) -> 'W' or 'B'
    for r in range(n):
        for c in range(m):
            if grid[r][c] in ('W', 'B'):
                clues[(r, c)] = grid[r][c]

    # For constraint propagation, we track for each edge whether it's IN or OUT of loop
    # Edge from (r,c) to (r+dr[d], c+dc[d]) for d in 0,1,2,3

    # Use 0=unknown, 1=must be in loop, -1=must not be in loop
    # Actually use: 0=unknown, 1=yes, -1=no

    # edges[r][c][d] = status of edge from (r,c) in direction d
    edges = [[[0]*4 for _ in range(m)] for _ in range(n)]

    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < m

    def get_neighbor(r, c, d):
        nr, nc = r + dr[d], c + dc[d]
        if in_bounds(nr, nc):
            return (nr, nc)
        return None

    def opposite(d):
        return (d + 2) % 4

    def set_edge(r, c, d, val):
        """Set edge (r,c,d) to val (1=in, -1=out), propagate to neighbor"""
        if edges[r][c][d] == val:
            return True  # already set
        if edges[r][c][d] == -val:
            return False  # contradiction

        edges[r][c][d] = val
        nr, nc = r + dr[d], c + dc[d]
        if in_bounds(nr, nc):
            edges[nr][nc][opposite(d)] = val
        return True

    # Apply clue constraints
    def apply_clue_constraints():
        changed = True
        while changed:
            changed = False
            for (r, c), typ in clues.items():
                # Count known edges
                known_in = [d for d in range(4) if edges[r][c][d] == 1]
                known_out = [d for d in range(4) if edges[r][c][d] == -1]
                unknown = [d for d in range(4) if edges[r][c][d] == 0]

                if typ == 'W':  # straight through, turn before or after
                    # W means: goes straight, so opposite edges are both in or both out
                    # And exactly 2 edges in (the straight line)
                    # Actually: straight means entry and exit are opposite

                    # For W: the two edges used must be opposite (straight)
                    # And at least one of (prev cell's turn) or (next cell's turn)
                    # But locally: we need exactly 2 opposite edges

                    pairs = [(0, 2), (1, 3)]  # vertical or horizontal

                    # If we know one edge is in, its opposite must be in, others out
                    for d in range(4):
                        if edges[r][c][d] == 1:
                            opp = opposite(d)
                            if edges[r][c][opp] == -1:
                                return False  # contradiction
                            if edges[r][c][opp] == 0:
                                if not set_edge(r, c, opp, 1):
                                    return False
                                changed = True
                            # Other two must be out
                            for d2 in range(4):
                                if d2 != d and d2 != opp:
                                    if edges[r][c][d2] == 1:
                                        return False
                                    if edges[r][c][d2] == 0:
                                        if not set_edge(r, c, d2, -1):
                                            return False
                                        changed = True

                    # If we know two non-opposite edges are out, the remaining pair is in
                    if len(known_out) >= 2:
                        for p in pairs:
                            if p[0] in known_out and p[1] in known_out:
                                # This pair is out, so other pair must be in
                                other = [(0,2), (1,3)][1-[(0,2), (1,3)].index(p)]
                                for d in other:
                                    if edges[r][c][d] == -1:
                                        return False
                                    if edges[r][c][d] == 0:
                                        if not set_edge(r, c, d, 1):
                                            return False
                                        changed = True

                    # If we know one edge of a pair is out, and one of the other pair is out...
                    # Actually let's check: if 3 edges known out, last is in (but need opposite too)

                else:  # 'B' - turn here, straight before and after
                    # B means: turn, so the two edges used are adjacent (not opposite)
                    # And the path is straight in previous and next cells

                    # For B: exactly 2 edges in, and they are adjacent (not opposite)
                    pairs = [(0, 2), (1, 3)]  # these are forbidden (would be straight)

                    # If we know one edge is in, its opposite must be out
                    for d in range(4):
                        if edges[r][c][d] == 1:
                            opp = opposite(d)
                            if edges[r][c][opp] == 1:
                                return False  # can't be straight
                            if edges[r][c][opp] == 0:
                                if not set_edge(r, c, opp, -1):
                                    return False
                                changed = True

                    # If we know two opposite edges are out, we must use adjacent pair
                    for p in pairs:
                        if edges[r][c][p[0]] == -1 and edges[r][c][p[1]] == -1:
                            # This straight pair is out, so use the other... wait no
                            # Actually if vertical is out, we use horizontal
                            other = [(0,2), (1,3)][1-[(0,2), (1,3)].index(p)]
                            for d in other:
                                if edges[r][c][d] == -1:
                                    return False
                                if edges[r][c][d] == 0:
                                    if not set_edge(r, c, d, 1):
                                        return False
                                    changed = True

            # Degree constraint: each dot has exactly 0 or 2 edges in loop
            for r in range(n):
                for c in range(m):
                    known_in = sum(1 for d in range(4) if edges[r][c][d] == 1)
                    known_out = sum(1 for d in range(4) if edges[r][c][d] == -1)
                    unknown = [d for d in range(4) if edges[r][c][d] == 0]

                    if known_in > 2:
                        return False

                    # If we have 2 in, rest must be out
                    if known_in == 2:
                        for d in unknown:
                            if not set_edge(r, c, d, -1):
                                return False
                            changed = True

                    # If we need 2 in and have enough unknown
                    need = 2 - known_in
                    if need < 0:
                        return False
                    if len(unknown) < need:
                        return False
                    if need == 0:
                        continue
                    if len(unknown) == need:
                        # all unknown must be in
                        for d in unknown:
                            if not set_edge(r, c, d, 1):
                                return False
                            changed = True

        return True

    if not apply_clue_constraints():
        return "No Solution"

    # Now use more advanced deduction and search
    # Let's try to solve by backtracking with constraint propagation

    def copy_edges():
        return [[[edges[r][c][d] for d in range(4)] for c in range(m)] for r in range(n)]

    def restore_edges(saved):
        nonlocal edges
        edges = saved

    def solve_recursive():
        # Check if solved: all clues satisfied and single loop
        # First check all clues
        for (r, c), typ in clues.items():
            known_in = [d for d in range(4) if edges[r][c][d] == 1]
            if len(known_in) != 2:
                return None  # not solved

        # Check if all edges determined where needed
        # Find a starting point
        start = None
        for r in range(n):
            for c in range(m):
                known_in = [d for d in range(4) if edges[r][c][d] == 1]
                if len(known_in) == 2:
                    start = (r, c)
                    break
            if start:
                break

        if not start:
            return None

        # Verify single closed loop
        visited = set()
        r, c = start
        # pick first direction
        d = [d for d in range(4) if edges[r][c][d] == 1][0]
        path = [(r, c)]
        visited.add((r, c))

        while True:
            nr, nc = r + dr[d], c + dc[d]
            if not in_bounds(nr, nc):
                return None
            if edges[r][c][d] != 1:
                return None

            r, c = nr, nc
            if (r, c) == start:
                break

            if (r, c) in visited:
                return None  # multiple loops

            visited.add((r, c))
            path.append((r, c))

            # find exit direction (not the one we came from)
            opp = opposite(d)
            next_dirs = [d2 for d2 in range(4) if edges[r][c][d2] == 1 and d2 != opp]
            if len(next_dirs) != 1:
                return None
            d = next_dirs[0]

        # Check all dots with edges are visited
        for r in range(n):
            for c in range(m):
                if any(edges[r][c][d] == 1 for d in range(4)):
                    if (r, c) not in visited:
                        return None

        # Check all clues are on path
        for (r, c) in clues:
            if (r, c) not in visited:
                return None

        return path + [start]

    def find_best_cell():
        """Find cell with most constraints to branch on"""
        best = None
        best_score = -1
        for r in range(n):
            for c in range(m):
                if (r, c) in clues:
                    continue  # already constrained
                known_in = sum(1 for d in range(4) if edges[r][c][d] == 1)
                known_out = sum(1 for d in range(4) if edges[r][c][d] == -1)
                unknown = 4 - known_in - known_out

                if known_in == 2:
                    continue  # satisfied
                if unknown == 0:
                    if known_in != 0 and known_in != 2:
                        return None  # invalid
                    continue

                # Prefer cells with more known edges (more constrained)
                score = known_in + known_out
                if score > best_score:
                    best_score = score
                    best = (r, c, known_in, unknown)

        return best

    def search():
        # Try to solve with current constraints
        result = solve_recursive()
        if result:
            return result

        # Find cell to branch on
        cell = find_best_cell()
        if cell is None:
            # Check if valid partial - might need to verify more
            return None

        r, c, known_in, unknown = cell

        # Try possibilities: need total 0 or 2 edges
        # known_in + new_edges = 0 or 2
        # so new_edges = 0 or 2 - known_in

        unknown_dirs = [d for d in range(4) if edges[r][c][d] == 0]

        candidates = []
        if known_in == 0:
            # need 0 or 2 more
            candidates.append([])  # 0 edges
            # all pairs
            for i, d1 in enumerate(unknown_dirs):
                for d2 in unknown_dirs[i+1:]:
                    candidates.append([d1, d2])
        elif known_in == 1:
            # need 1 more (impossible, need 0 or 2 total)
            # actually we need 1 more to make 2, but that's odd... wait
            # We need exactly 0 or 2 edges at each dot
            # If we have 1, we need 1 more - but that's impossible (would be 1)
            # So this state is invalid
            return None
        elif known_in == 2:
            # need 0 more
            candidates.append([])

        # Try each candidate
        for new_edges in candidates:
            saved = copy_edges()

            # Set new edges
            valid = True
            for d in unknown_dirs:
                val = 1 if d in new_edges else -1
                if not set_edge(r, c, d, val):
                    valid = False
                    break

            if valid:
                if apply_clue_constraints():
                    result = search()
                    if result:
                        return result

            restore_edges(saved)

        return None

    result = search()
    if result:
        return result
    return "No Solution"

