    grid = [[0] * n_cols for _ in range(n_rows)]

    # Precompute all possible subsets for each row/column
    def get_subsets(n, target, weights):
        """Get all subsets of {0,...,n-1} where sum of weights[i] equals target"""
        result = []
        def dfs(idx, current_sum, chosen):
            if current_sum == target:
                result.append(chosen[:])
                return
            if idx >= n or current_sum > target:
                return
            # Try including idx
            chosen.append(idx)
            dfs(idx + 1, current_sum + weights[idx], chosen)
            chosen.pop()
            # Try excluding idx
            dfs(idx + 1, current_sum, chosen)
        dfs(0, 0, [])
        return result

    # For rows: column weights are 0,1,2,...,n_cols-1
    col_weights = list(range(n_cols))
    row_possibilities = []
    for r in range(n_rows):
        target = row_sums[r]
        poss = get_subsets(n_cols, target, col_weights)
        if not poss:
            return "No Solution"
        row_possibilities.append(poss)

