                must_white = set()

                # A cell must be black if it's in all possibilities
                # A cell must be white if it's in no possibilities
                if not row_possibilities[r]:
                    return False

                all_sets = [set(p) for p in row_possibilities[r]]
                must_black = set.intersection(*all_sets) if len(all_sets) > 1 else all_sets[0]
                union_all = set.union(*all_sets) if len(all_sets) > 1 else all_sets[0]
                must_white = set(range(n_cols)) - union_all

                # Apply to grid and filter column possibilities
