    # Backtracking with constraint propagation
    def backtrack():
        if is_solved():
            return True

        # Find unassigned cell
        best_r, best_c = -1, -1
        min_options = float('inf')

        for r in range(n_rows):
            for c in range(n_cols):
                if grid[r][c] != 0:
                    continue
                # Count valid options for this cell
                options = 0
                # Try black
                if any(c in poss for poss in row_possibilities[r]) and any(r in poss for poss in col_possibilities[c]):
                    options += 1
                # Try white
                if any(c not in poss for poss in row_possibilities[r]) and any(r not in poss for poss in col_possibilities[c]):
                    options += 1
                if options < min_options:
                    min_options = options
                    best_r, best_c = r, c

        if best_r == -1:
            return is_solved()

        r, c = best_r, best_c

        # Try black first
