        # Place tent
        tent_grid[r][c] = 't'
        tree_matched[tree] = True
        row_count[r] += 1
        col_count[c] += 1
        return True

    # Undo tent placement
    def remove_tent(tree, cell):
        r, c = cell
        tent_grid[r][c] = None
        tree_matched[tree] = False
        row_count[r] -= 1
        col_count[c] -= 1

    # Check if solution is complete
    def is_complete():
