                    if edges[nr][nc][back] != 1:
                        break
                    other_dirs = [d for d in range(4) if d != back and edges[nr][nc][d] == 1]
                    if len(other_dirs) != 1:
                        break
                    if other_dirs[0] != d1:
                        break  # turned
                    len1 += 1
                    nr += dr[d1]
                    nc += dc[d1]

                len2 = 1
                d2 = used[1]
