                        break
                if not all_determined:
                    break
            if not all_determined:
                break

        if all_determined:
            if verify_loop(edges) and check_clues(edges):
                return edges
            return None

        # Find best variable to branch on
        # Prefer clues, then high-constraint nodes
        best_score = -1
        best_var = None

        for r in range(n+1):
            for c in range(n+1):
                unknown = [d for d in range(4) if edges[r][c][d] == 2]
                if len(unknown) == 0:
