                # Check neighbors
                for d in unknown:
                    nr, nc = r + dr[d], c + dc[d]
                    if 0 <= nr <= n and 0 <= nc <= n:
                        if edges[nr][nc][opposite[d]] != 2:
                            score += 5

                if score > best_score:
                    best_score = score
                    best_var = (r, c, unknown[0])

        if best_var is None:
            return None

        r, c, d = best_var

        # Try yes
        edges_copy = [[[edges[i][j][k] for k in range(4)] for j in range(n+1)] for i in range(n+1)]
        edges_copy[r][c][d] = 1
        nr, nc = r + dr[d], c + dc[d]
        if 0 <= nr <= n and 0 <= nc <= n:
            edges_copy[nr][nc][opposite[d]] = 1

        result = solve_recursive(edges_copy, depth+1)
        if result is not None:
