        # Try no
        edges_copy = [[[edges[i][j][k] for k in range(4)] for j in range(n+1)] for i in range(n+1)]
        edges_copy[r][c][d] = 0
        nr, nc = r + dr[d], c + dc[d]
        if 0 <= nr <= n and 0 <= nc <= n:
            edges_copy[nr][nc][opposite[d]] = 0

        result = solve_recursive(edges_copy, depth+1)
        return result

    # Initialize and solve
    edges = init_edges()
    result = solve_recursive(edges)

    if result is None:
        return "No Solution"

    # Extract path from result
    # Build adjacency and find cycle
    adj = {}
    for r in range(n+1):
        for c in range(n+1):
            neighbors = []
            for d in range(4):
                if result[r][c][d] == 1:
                    nr, nc = r + dr[d], c + dc[d]
                    neighbors.append((nr, nc))
            if len(neighbors) == 2:
                adj[(r, c)] = neighbors

    # Find cycle
    start = min(adj.keys())
    path = [start]
    prev = None
    curr = start

    while True:
        neighbors = adj[curr]
        nxt = None
        for nb in neighbors:
            if nb != prev:
                nxt = nb
                break

        if nxt is None or nxt == start:
            break

        path.append(nxt)
        prev, curr = curr, nxt

        if len(path) > (n+1) * (n+1):
            return "No Solution"

    path.append(start)
    return path

