    def get_white_component(start_r, start_c, temp_state=None):
        """Get connected white component including unknowns that could be white"""
        s = temp_state if temp_state else state
        if s[start_r][start_c] == 2:
            return set()
        visited = set()
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and s[nr][nc] != 2:
