    """Generate all permutations of 1..n satisfying both visibility clues."""
    valid = []
    for perm in permutations(range(1, n + 1)):
        if count_visible(perm) == left_clue and count_visible(perm[::-1]) == right_clue:
            valid.append(perm)
    return valid

