            return "No Solution"

    # Order rows by fewest candidates (Minimum Remaining Values heuristic)
    row_order = sorted(range(n), key=lambda i: len(row_candidates[i]))

    # Grid to store the solution
    grid = [[0] * n for _ in range(n)]

    def backtrack(pos):
