                for idx, val in enumerate(col_partial):
                    if c_cand[idx] != val:
                        match = False
                        break
                if match:
                    found = True
                    break

            if not found:
                return False
        return True

    def backtrack(pos):
        if pos == N:
            return True

        i = rows_order[pos]
        assigned_rows[i] = True

        for r_cand in row_cands[i]:
            # Place candidate
            for j in range(N):
                grid[i][j] = r_cand[j]

            # Check validity with constraint propagation
            if is_partial_valid():
                if backtrack(pos + 1):
                    return True

            # Backtrack
            for j in range(N):
                grid[i][j] = 0

        assigned_rows[i] = False
        return False

    if backtrack(0):
        return grid

    return "No Solution"

