def solve(observation):
    n = len(observation['U'])
    U, D, L, R = observation['U'], observation['D'], observation['L'], observation['R']

    from itertools import permutations

    def calc_vis(perm):
        count = max_h = 0
        for h in perm:
            if h > max_h:
                count += 1
                max_h = h
        return count

    all_perms = list(permutations(range(1, n+1)))
    vis_cache = {p: (calc_vis(p), calc_vis(p[::-1])) for p in all_perms}

    row_cands = []
    for i in range(n):
        valid = [p for p in all_perms if vis_cache[p][0] == L[i] and vis_cache[p][1] == R[i]]
        if not valid:
            return None
        row_cands.append(set(valid))

    col_cands = []
    for j in range(n):
        valid = [p for p in all_perms if vis_cache[p][0] == U[j] and vis_cache[p][1] == D[j]]
        if not valid:
            return None
        col_cands.append(set(valid))

    domains = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    def update_domains():
        for i in range(n):
            for j in range(n):
                row_vals = set(p[j] for p in row_cands[i])
                col_vals = set(p[i] for p in col_cands[j])
                domains[i][j] = row_vals & col_vals
                if not domains[i][j]:
                    return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            for i in range(n):
                new_cands = set()
                for p in row_cands[i]:
                    valid = True
                    for j in range(n):
                        if p[j] not in domains[i][j]:
                            valid = False
                            break
                    if valid:
                        new_cands.add(p)
                if len(new_cands) < len(row_cands[i]):
                    row_cands[i] = new_cands
                    changed = True
                    if not new_cands:
                        return False

            for j in range(n):
                new_cands = set()
                for p in col_cands[j]:
                    valid = True
                    for i in range(n):
                        if p[i] not in domains[i][j]:
                            valid = False
                            break
                    if valid:
                        new_cands.add(p)
                if len(new_cands) < len(col_cands[j]):
                    col_cands[j] = new_cands
                    changed = True
                    if not new_cands:
                        return False

            if changed:
                if not update_domains():
                    return False

        return True

    if not update_domains() or not propagate():
        return None

    def backtrack():
        if all(len(domains[i][j]) == 1 for i in range(n) for j in range(n)):
            return [[next(iter(domains[i][j])) for j in range(n)] for i in range(n)]

        min_size = n + 1
        target_i = target_j = -1
        for i in range(n):
            for j in range(n):
                sz = len(domains[i][j])
                if sz > 1 and sz < min_size:
                    min_size = sz
                    target_i, target_j = i, j

        if target_i == -1:
            return None

        i, j = target_i, target_j
        values_to_try = list(domains[i][j])

        for val in values_to_try:
            old_domains = [[set(domains[r][c]) for c in range(n)] for r in range(n)]
            old_row_cands = [set(rc) for rc in row_cands]
            old_col_cands = [set(cc) for cc in col_cands]

            domains[i][j] = {val}
            row_cands[i] = {p for p in row_cands[i] if p[j] == val}
            col_cands[j] = {p for p in col_cands[j] if p[i] == val}

            if not row_cands[i] or not col_cands[j]:
                for r in range(n):
                    for c in range(n):
                        domains[r][c] = old_domains[r][c]
                for k in range(n):
                    row_cands[k] = old_row_cands[k]
                    col_cands[k] = old_col_cands[k]
                continue

            if propagate():
                result = backtrack()
                if result is not None:
                    return result

            for r in range(n):
                for c in range(n):
                    domains[r][c] = old_domains[r][c]
            for k in range(n):
                row_cands[k] = old_row_cands[k]
                col_cands[k] = old_col_cands[k]

        return None

    return backtrack()

