            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, n + 1))

    # Parse constraints as (smaller_cell, larger_cell) pairs
    constraints = []

    # Horizontal: at (r, c+0.5), between col c and c+1
    for key, symbol in horizontal.items():
        r, c = ast.literal_eval(key)
        left_col = int(c)
        right_col = left_col + 1
        left_cell = (int(r), left_col)
        right_cell = (int(r), right_col)

        if symbol == '<':
            constraints.append((left_cell, right_cell))
        else:  # '>'
            constraints.append((right_cell, left_cell))

    # Vertical: at (r+0.5, c), between row r and r+1
    for key, symbol in vertical.items():
        r, c = ast.literal_eval(key)
        top_row = int(r)
        bot_row = top_row + 1
        top_cell = (top_row, int(c))
        bot_cell = (bot_row, int(c))

        if symbol == '^':
            constraints.append((top_cell, bot_cell))
        else:  # 'v' or 'V'
            constraints.append((bot_cell, top_cell))

    def propagate(domains):
        """Constraint propagation: arc consistency + hidden singles"""
        changed = True
        while changed:
            changed = False

            # 1. Forward checking: determined cells eliminate values from peers
            for (r, c), dom in list(domains.items()):
                if len(dom) != 1:
                    continue
                val = next(iter(dom))

                # Row peers
                for cc in range(n):
                    if cc == c:
                        continue
                    peer_dom = domains[(r, cc)]
                    if val in peer_dom:
                        if len(peer_dom) == 1:
                            return False
                        peer_dom.remove(val)
                        changed = True
                        if not peer_dom:
                            return False

                # Column peers
                for rr in range(n):
                    if rr == r:
                        continue
                    peer_dom = domains[(rr, c)]
                    if val in peer_dom:
                        if len(peer_dom) == 1:
                            return False
                        peer_dom.remove(val)
                        changed = True
                        if not peer_dom:
                            return False

            # 2. Inequality constraints: bound tightening
            for cell_a, cell_b in constraints:
                # cell_a < cell_b
                dom_a = domains[cell_a]
                dom_b = domains[cell_b]

                # Remove from dom_a any value >= max(dom_b)
                max_b = max(dom_b)
                to_remove = [v for v in dom_a if v >= max_b]
                if to_remove:
                    for v in to_remove:
                        dom_a.remove(v)
                    changed = True
                    if not dom_a:
                        return False

                # Remove from dom_b any value <= min(dom_a)
                min_a = min(dom_a)
                to_remove = [v for v in dom_b if v <= min_a]
                if to_remove:
                    for v in to_remove:
                        dom_b.remove(v)
                    changed = True
                    if not dom_b:
                        return False

            # 3. Hidden singles in rows
            for r in range(n):
                for val in range(1, n + 1):
                    possible = [c for c in range(n) if val in domains[(r, c)]]
                    if len(possible) == 1:
                        c = possible[0]
                        if len(domains[(r, c)]) > 1:
                            domains[(r, c)] = {val}
                            changed = True

            # 4. Hidden singles in columns
            for c in range(n):
                for val in range(1, n + 1):
                    possible = [r for r in range(n) if val in domains[(r, c)]]
                    if len(possible) == 1:
                        r = possible[0]
                        if len(domains[(r, c)]) > 1:
                            domains[(r, c)] = {val}
                            changed = True

        return True

    def is_valid(domains):
        """Check if current state satisfies all hard constraints"""
        # Check rows for duplicates in fixed cells
        for r in range(n):
            seen = set()
            for c in range(n):
                dom = domains[(r, c)]
                if len(dom) == 1:
                    val = next(iter(dom))
                    if val in seen:
                        return False
                    seen.add(val)

        # Check columns for duplicates
        for c in range(n):
            seen = set()
            for r in range(n):
                dom = domains[(r, c)]
                if len(dom) == 1:
                    val = next(iter(dom))
                    if val in seen:
                        return False
                    seen.add(val)

        # Check inequalities for determined cells
        for cell_a, cell_b in constraints:
            dom_a = domains[cell_a]
            dom_b = domains[cell_b]
            if len(dom_a) == 1 and len(dom_b) == 1:
                if not (next(iter(dom_a)) < next(iter(dom_b))):
                    return False

        return True

    def copy_dom(domains):
        return {k: set(v) for k, v in domains.items()}

    def backtrack(domains):
        # Check complete
        if all(len(v) == 1 for v in domains.values()):
            return domains

        if not is_valid(domains):
            return None

        # MRV heuristic: choose cell with smallest domain > 1
        min_cell = None
        min_size = n + 1
        for cell, dom in domains.items():
            size = len(dom)
            if 1 < size < min_size:
                min_size = size
                min_cell = cell
                if size == 2:
                    break

        if min_cell is None:
            return None

        # Least constraining value heuristic
        r, c = min_cell
        values = list(domains[min_cell])

        def count_restrictions(val):
            """Count how many peer cells would lose this value"""
            count = 0
            # Row
            for cc in range(n):
                if cc != c and val in domains[(r, cc)] and len(domains[(r, cc)]) > 1:
                    count += 1
            # Col
            for rr in range(n):
                if rr != r and val in domains[(rr, c)] and len(domains[(rr, c)]) > 1:
                    count += 1
            return count

        values.sort(key=count_restrictions)

        for val in values:
            new_dom = copy_dom(domains)
            new_dom[min_cell] = {val}

            if propagate(new_dom):
                result = backtrack(new_dom)
                if result is not None:
                    return result

        return None

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    result = backtrack(domains)

    if result is None:
        return "No Solution"

    # Extract solution
    grid = [[0] * n for _ in range(n)]
    for (r, c), dom in result.items():
        grid[r][c] = next(iter(dom))

    return grid

