                    constraints.append((r, c1, r, c2, '<'))

    # Vertical inequalities: between (r, c) and (r+1, c) at position (r+0.5, c)
    v_ineqs = observation.get('vertical', {})
    for key, op in v_ineqs.items():
        s = key.strip()
        if s.startswith('(') and s.endswith(')'):
