            parts = [p.strip() for p in s.split(',')]
            r_pos = float(parts[0])
            c = int(float(parts[1]))
            r1 = int(r_pos - 0.5)
            r2 = r1 + 1
            if 0 <= r1 < n and 0 <= r2 < n and 0 <= c < n:
