def _propagate(domains, constraints, n):
    """Apply constraint propagation until fixed point. Return False if contradiction."""
    changed = True
    while changed:
        changed = False

        # 1. Propagate fixed cells (domain size 1) to row and column
        for r in range(n):
            for c in range(n):
                if len(domains[r][c]) == 1:
                    val = next(iter(domains[r][c]))

                    # Remove from row
                    for cc in range(n):
                        if cc != c and val in domains[r][cc]:
                            domains[r][cc].remove(val)
                            if len(domains[r][cc]) == 0:
                                return False
                            changed = True

                    # Remove from column
                    for rr in range(n):
                        if rr != r and val in domains[rr][c]:
                            domains[rr][c].remove(val)
                            if len(domains[rr][c]) == 0:
                                return False
                            changed = True

        # 2. Hidden singles: if a value can only go in one cell in a row/col
        # Check rows
        for r in range(n):
            for val in range(1, n+1):
                possible_cols = [c for c in range(n) if val in domains[r][c]]
                if len(possible_cols) == 0:
                    return False
                if len(possible_cols) == 1:
                    c = possible_cols[0]
                    if len(domains[r][c]) > 1:
                        domains[r][c] = {val}
                        changed = True

        # Check columns
        for c in range(n):
            for val in range(1, n+1):
                possible_rows = [r for r in range(n) if val in domains[r][c]]
                if len(possible_rows) == 0:
                    return False
                if len(possible_rows) == 1:
                    r = possible_rows[0]
                    if len(domains[r][c]) > 1:
                        domains[r][c] = {val}
                        changed = True

        # 3. Inequality constraints
        for r1, c1, r2, c2, op in constraints:
            d1 = domains[r1][c1]
            d2 = domains[r2][c2]

            if op == '>':
                # Constraint: d1 > d2
                # Prune d1: remove values that are <= min(d2)
                if d2:
                    min_d2 = min(d2)
                    to_remove = [x for x in d1 if x <= min_d2]
                    if to_remove:
                        for x in to_remove:
                            d1.remove(x)
                        if not d1:
                            return False
                        changed = True

                # Prune d2: remove values that are >= max(d1)
                if d1:
                    max_d1 = max(d1)
                    to_remove = [y for y in d2 if y >= max_d1]
                    if to_remove:
                        for y in to_remove:
                            d2.remove(y)
                        if not d2:
                            return False
                        changed = True

            elif op == '<':
                # Constraint: d1 < d2
                # Prune d1: remove values that are >= max(d2)
                if d2:
                    max_d2 = max(d2)
                    to_remove = [x for x in d1 if x >= max_d2]
                    if to_remove:
                        for x in to_remove:
                            d1.remove(x)
                        if not d1:
                            return False
                        changed = True

                # Prune d2: remove values that are <= min(d1)
                if d1:
                    min_d1 = min(d1)
                    to_remove = [y for y in d2 if y <= min_d1]
                    if to_remove:
                        for y in to_remove:
                            d2.remove(y)
                        if not d2:
                            return False
                        changed = True

    return True


def _solve_recursive(domains, constraints, n):
    """Recursive solver with constraint propagation."""
    # Make a deep copy to avoid modifying parent's state
    domains = copy.deepcopy(domains)

    # Apply constraint propagation
    if not _propagate(domains, constraints, n):
        return None

    # Check if solved
    if all(len(domains[r][c]) == 1 for r in range(n) for c in range(n)):
        return [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]

    # Find cell with minimum remaining values (MRV heuristic)
    min_size = n + 1
    best_r, best_c = -1, -1
    for r in range(n):
        for c in range(n):
            size = len(domains[r][c])
            if 1 < size < min_size:
                min_size = size
                best_r, best_c = r, c
                if min_size == 2:  # Can't get better than 2
                    break
        if min_size == 2:
            break

    if best_r == -1:
        return None

    # Try each candidate value
    candidates = sorted(domains[best_r][best_c])
    for val in candidates:
        new_domains = copy.deepcopy(domains)
        new_domains[best_r][best_c] = {val}
        result = _solve_recursive(new_domains, constraints, n)
        if result is not None:
            return result

    return None


