        c_left = int(c_float - 0.5)
        c_right = int(c_float + 0.5)
        if sym == '>':
            # left > right
            inequalities[(r, c_left)].append(((r, c_right), True))
            inequalities[(r, c_right)].append(((r, c_left), False))
        else:  # '<'
            # left < right
            inequalities[(r, c_left)].append(((r, c_right), False))
            inequalities[(r, c_right)].append(((r, c_left), True))

