        r_up = int(r_float - 0.5)
        r_down = int(r_float + 0.5)
        if sym == 'v':
            # up > down
            inequalities[(r_up, c)].append(((r_down, c), True))
            inequalities[(r_down, c)].append(((r_up, c), False))
        else:  # '^'
            # up < down
            inequalities[(r_up, c)].append(((r_down, c), False))
            inequalities[(r_down, c)].append(((r_up, c), True))

