            if not doms[r][c]:
                return False

            changed = False

            # 1. Naked single propagation (row/col constraints)
            if len(doms[r][c]) == 1:
                val = next(iter(doms[r][c]))
                # Row elimination
                for cc in range(n):
                    if cc != c and val in doms[r][cc]:
                        doms[r][cc].discard(val)
                        queue.append((r, cc))
                        if not doms[r][cc]:
                            return False
                # Col elimination
                for rr in range(n):
                    if rr != r and val in doms[rr][c]:
                        doms[rr][c].discard(val)
                        queue.append((rr, c))
                        if not doms[rr][c]:
                            return False

            # 2. Inequality constraint propagation
            for (nr, nc), gt in inequalities[(r, c)]:
                if not doms[nr][nc]:
                    return False
                if gt:  # (r,c) > (nr,nc)
                    min_other = min(doms[nr][nc])
                    # Remove values too small from (r,c)
                    to_rem = {v for v in doms[r][c] if v <= min_other}
                    if to_rem:
                        doms[r][c] -= to_rem
                        changed = True
                    # Remove values too large from neighbor
                    max_self = max(doms[r][c])
                    to_rem_n = {v for v in doms[nr][nc] if v >= max_self}
                    if to_rem_n:
                        doms[nr][nc] -= to_rem_n
                        queue.append((nr, nc))
                        if not doms[nr][nc]:
                            return False
                else:  # (r,c) < (nr,nc)
                    max_other = max(doms[nr][nc])
                    to_rem = {v for v in doms[r][c] if v >= max_other}
                    if to_rem:
                        doms[r][c] -= to_rem
                        changed = True
                    min_self = min(doms[r][c])
                    to_rem_n = {v for v in doms[nr][nc] if v <= min_self}
                    if to_rem_n:
                        doms[nr][nc] -= to_rem_n
                        queue.append((nr, nc))
                        if not doms[nr][nc]:
                            return False

            # 3. Hidden singles (row)
            if len(doms[r][c]) > 1:
                for val in list(doms[r][c]):
                    count = sum(1 for cc in range(n) if val in doms[r][cc])
                    if count == 1:
                        doms[r][c] = {val}
                        queue.append((r, c))
                        changed = True
                        break

            # 4. Hidden singles (col)
            if len(doms[r][c]) > 1:
                for val in list(doms[r][c]):
                    count = sum(1 for rr in range(n) if val in doms[rr][c])
                    if count == 1:
                        doms[r][c] = {val}
                        queue.append((r, c))
                        changed = True
                        break

            if changed:
                queue.append((r, c))
                if not doms[r][c]:
                    return False

        return True

    def copy_doms(doms):
        return [[set(cell) for cell in row] for row in doms]

    def is_solved(doms):
        for r in range(n):
            for c in range(n):
                if len(doms[r][c]) != 1:
                    return False
        return True

    def get_solution(doms):
        return [[next(iter(doms[r][c])) for c in range(n)] for r in range(n)]

    def solve_recursive(doms):
        if not propagate(doms):
            return None

        if is_solved(doms):
            return get_solution(doms)

        # MRV heuristic: choose cell with smallest domain > 1
        min_size = n + 2
        best_cell = None
        for r in range(n):
            for c in range(n):
                size = len(doms[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best_cell = (r, c)
                    if size == 2:
                        break
            if best_cell and min_size == 2:
                break

        if best_cell is None:
            return None

        r, c = best_cell
        values = sorted(doms[r][c])

        for val in values:
            new_doms = copy_doms(doms)
            new_doms[r][c] = {val}
            result = solve_recursive(new_doms)
            if result is not None:
                return result

        return None

    result = solve_recursive(domains)
    if result is None:
        return "No Solution"
    return result

