                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(domains[(r, c)]) > 1:
                            domains[(r, c)] = {val}
                            changed = True

            # 3. Hidden singles in columns
            for c in range(n):
                for val in range(1, n + 1):
