        return True

    def is_solved(domains):
        """Check if all cells have exactly one value"""
        for r in range(n):
            for c in range(n):
                if len(domains[(r, c)]) != 1:
                    return False
        return True

    def backtrack(domains):
        """Backtracking search with MRV heuristic"""
        if is_solved(domains):
            return domains

        # Find cell with minimum remaining values (MRV)
        min_size = n + 1
        target = None
        for r in range(n):
            for c in range(n):
                size = len(domains[(r, c)])
                if 1 < size < min_size:
                    min_size = size
                    target = (r, c)

        if target is None:
            return None

        r, c = target
        values = sorted(domains[(r, c)])  # Try in sorted order

        for val in values:
            new_domains = copy.deepcopy(domains)
            new_domains[(r, c)] = {val}
            if propagate(new_domains):
                result = backtrack(new_domains)
                if result is not None:
                    return result
        return None

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    # Solve
    result = backtrack(domains)

    if result is None:
        return "No Solution"

    # Convert to grid
    grid = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            grid[r][c] = next(iter(result[(r, c)]))

    return grid

