        """Check if all cells have exactly one value assigned."""
        for i in range(n):
            for j in range(n):
                if len(domains[i][j]) != 1:
                    return False
        return True

    def copy_domains(domains):
        """Deep copy the domain structure."""
        return [[set(domains[i][j]) for j in range(n)] for i in range(n)]

    def select_variable(domains):
        """
        Select unassigned cell with Minimum Remaining Values (MRV).
        Returns (i, j) or None if all assigned.
        """
        min_size = n + 2
        candidates = []
        for i in range(n):
            for j in range(n):
                size = len(domains[i][j])
                if size == 1:
                    continue
                if size < min_size:
                    min_size = size
                    candidates = [(i, j)]
                elif size == min_size:
                    candidates.append((i, j))

        if not candidates:
            return None
        # Break ties arbitrarily (first found)
        return candidates[0]

    def backtrack(domains):
        """Recursive backtracking search with constraint propagation."""
        if is_complete(domains):
            # Extract solution
            return [[next(iter(domains[i][j])) for j in range(n)] for i in range(n)]

        var = select_variable(domains)
        if var is None:
            return None

        i, j = var
        values = sorted(domains[i][j])  # Try values in ascending order

        for val in values:
            new_domains = copy_domains(domains)
            new_domains[i][j] = {val}

            if propagate(new_domains):
                result = backtrack(new_domains)
                if result is not None:
                    return result

        return None

    result = backtrack(domains)
    if result is None:
        return "No Solution"
    return result

