def solve(observation):
    data = observation['data']
    N = len(data) - 1

    # Grid state: None, '/' or '\'
    grid = [[None for _ in range(N)] for _ in range(N)]

    # Precompute which cells affect each dot
    # dot_to_cells[r][c] = list of (cell_r, cell_c, orientation_required)
    dot_to_cells = [[[] for _ in range(N+1)] for _ in range(N+1)]
    for r in range(N):
        for c in range(N):
            # '\' connects (r,c) to (r+1,c+1)
            dot_to_cells[r][c].append((r, c, '\\'))
            dot_to_cells[r+1][c+1].append((r, c, '\\'))
            # '/' connects (r,c+1) to (r+1,c)
            dot_to_cells[r][c+1].append((r, c, '/'))
            dot_to_cells[r+1][c].append((r, c, '/'))

    # Target constraints: -1 means no constraint
    target = [[data[r][c] if data[r][c] is not None else -1 for c in range(N+1)] for r in range(N+1)]

    # Union-Find utilities
    def uf_create():
        return list(range((N+1) * (N+1)))

    def uf_find(uf, x):
        # Path compression
        while uf[x] != x:
            uf[x] = uf[uf[x]]
            x = uf[x]
        return x

    def uf_union(uf, x, y):
        px, py = uf_find(uf, x), uf_find(uf, y)
        if px == py:
            return False  # Already connected - would form loop
        uf[px] = py
        return True

    def dot_idx(r, c):
        return r * (N+1) + c

    # Constraint propagation: repeatedly apply forced moves
    def propagate(grid, dot_curr, uf):
        # Work on copies
        g = [row[:] for row in grid]
        dc = [row[:] for row in dot_curr]
        u = uf[:]

        changed = True
        while changed:
            changed = False
            for r in range(N+1):
                for c in range(N+1):
                    if target[r][c] < 0:
                        continue

                    curr = dc[r][c]
                    tgt = target[r][c]

                    if curr > tgt:
                        return None, None, None

                    # Count unset cells and set cells matching constraint
                    unset = []
                    set_matching = 0
                    for cr, cc, orient in dot_to_cells[r][c]:
                        if g[cr][cc] is None:
                            unset.append((cr, cc, orient))
                        elif g[cr][cc] == orient:
                            set_matching += 1

                    if set_matching != curr:
                        return None, None, None

                    needed = tgt - curr
                    if needed < 0 or needed > len(unset):
                        return None, None, None

                    if needed == 0:
                        # All unset must be the opposite orientation
                        for cr, cc, orient in unset:
                            other = '/' if orient == '\\' else '\\'
                            if g[cr][cc] is None:
                                g[cr][cc] = other
                                # Update the two dots this cell touches
                                if other == '\\':
                                    d1, d2 = (cr, cc), (cr+1, cc+1)
                                else:
                                    d1, d2 = (cr, cc+1), (cr+1, cc)

                                # Check loop
                                i1, i2 = dot_idx(*d1), dot_idx(*d2)
                                if uf_find(u, i1) == uf_find(u, i2):
                                    return None, None, None
                                uf_union(u, i1, i2)

                                dc[d1[0]][d1[1]] += 1
                                dc[d2[0]][d2[1]] += 1
                                changed = True
                            elif g[cr][cc] == orient:
                                return None, None, None
                    elif needed == len(unset):
                        # All unset must be this orientation
                        for cr, cc, orient in unset:
                            if g[cr][cc] is None:
                                g[cr][cc] = orient
                                if orient == '\\':
                                    d1, d2 = (cr, cc), (cr+1, cc+1)
                                else:
                                    d1, d2 = (cr, cc+1), (cr+1, cc)

                                i1, i2 = dot_idx(*d1), dot_idx(*d2)
                                if uf_find(u, i1) == uf_find(u, i2):
                                    return None, None, None
                                uf_union(u, i1, i2)

                                dc[d1[0]][d1[1]] += 1
                                dc[d2[0]][d2[1]] += 1
                                changed = True
                            elif g[cr][cc] != orient:
                                return None, None, None
        return g, dc, u

    # Initialize
    dot_curr_init = [[0 for _ in range(N+1)] for _ in range(N+1)]
    uf_init = uf_create()

    grid, dot_curr, uf = propagate(grid, dot_curr_init, uf_init)
    if grid is None:
        return "No Solution"

    def is_complete(g):
        return all(g[r][c] is not None for r in range(N) for c in range(N))

    # Recursive solver with heuristics
    def solve_recursive(g, dc, u):
        if is_complete(g):
            # Verify all constraints
            for r in range(N+1):
                for c in range(N+1):
                    if target[r][c] >= 0 and dc[r][c] != target[r][c]:
                        return None
            return g

        # Find cell with minimum remaining values
        best_r, best_c = -1, -1
        best_opts = []

        for r in range(N):
            for c in range(N):
                if g[r][c] is not None:
                    continue

                opts = []
                for val in ['\\', '/']:
                    # Determine affected dots
                    if val == '\\':
                        dots = [(r, c), (r+1, c+1)]
                    else:
                        dots = [(r, c+1), (r+1, c)]

                    # Check if any dot constraint would be violated
                    valid = True
                    for dr, dc_ in dots:
                        if target[dr][dc_] >= 0 and dc[dr][dc_] >= target[dr][dc_]:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check loop
                    if val == '\\':
                        i1, i2 = dot_idx(r, c), dot_idx(r+1, c+1)
                    else:
                        i1, i2 = dot_idx(r, c+1), dot_idx(r+1, c)

                    if uf_find(u, i1) == uf_find(u, i2):
                        continue

                    opts.append(val)

                if len(opts) == 0:
                    return None
                if len(best_opts) == 0 or len(opts) < len(best_opts):
                    best_r, best_c = r, c
                    best_opts = opts
                    if len(opts) == 1:
                        break
            if len(best_opts) == 1:
                break

        if best_r == -1:
            return None

        # Try each option
        for val in best_opts:
            # Save state
            new_g = [row[:] for row in g]
            new_dc = [row[:] for row in dc]
            new_u = u[:]

            # Place value
            new_g[best_r][best_c] = val

            # Update dots and union-find
            if val == '\\':
                dots = [(best_r, best_c), (best_r+1, best_c+1)]
            else:
                dots = [(best_r, best_c+1), (best_r+1, best_c)]

            for dr, dc_ in dots:
                new_dc[dr][dc_] += 1

            if val == '\\':
                i1, i2 = dot_idx(best_r, best_c), dot_idx(best_r+1, best_c+1)
            else:
                i1, i2 = dot_idx(best_r, best_c+1), dot_idx(best_r+1, best_c)

            # This should not happen due to pre-check, but be safe
            if uf_find(new_u, i1) == uf_find(new_u, i2):
                continue
            uf_union(new_u, i1, i2)

            # Propagate constraints
            pg, pdc, pu = propagate(new_g, new_dc, new_u)
            if pg is None:
                continue

            result = solve_recursive(pg, pdc, pu)
            if result is not None:
                return result

        return None

    result = solve_recursive(grid, dot_curr, uf)
    if result is None:
        return "No Solution"
    return result

