def solve(observation):
    data = observation['data']
    h_cons = observation['horizontal']
    v_cons = observation['vertical']
    n = len(data)
    target = n // 2

    grid = [row[:] for row in data]

    # Parse constraints into usable format
    h_constraints = {}
    for k, v in h_cons.items():
        inner = k[1:-1]
        r_str, c_str = inner.split(',')
        r, c = float(r_str), float(c_str)
        h_constraints[(r, c)] = v

    v_constraints = {}
    for k, v in v_cons.items():
        inner = k[1:-1]
        r_str, c_str = inner.split(',')
        r, c = float(r_str), float(c_str)
        v_constraints[(r, c)] = v

    def get(r, c):
        if 0 <= r < n and 0 <= c < n:
            return grid[r][c]
        return None

    def set_cell(r, c, val):
        if grid[r][c] is None:
            grid[r][c] = val
            return True
        return grid[r][c] == val

    def propagate():
        changed = True
        while changed:
            changed = False

            # Apply adjacency constraints
            for (r, c), typ in h_constraints.items():
                r_int = int(r)
                c_left = int(c - 0.5)
                c_right = c_left + 1
                left_val = get(r_int, c_left)
                right_val = get(r_int, c_right)

                if left_val is not None and right_val is None:
                    if typ == '=':
                        if not set_cell(r_int, c_right, left_val): return False
                        changed = True
                    else:
                        opp = 'W' if left_val == 'B' else 'B'
                        if not set_cell(r_int, c_right, opp): return False
                        changed = True
                elif right_val is not None and left_val is None:
                    if typ == '=':
                        if not set_cell(r_int, c_left, right_val): return False
                        changed = True
                    else:
                        opp = 'W' if right_val == 'B' else 'B'
                        if not set_cell(r_int, c_left, opp): return False
                        changed = True
                elif left_val is not None and right_val is not None:
                    if typ == '=' and left_val != right_val: return False
                    if typ == 'x' and left_val == right_val: return False

            for (r, c), typ in v_constraints.items():
                r_top = int(r - 0.5)
                r_bot = r_top + 1
                c_int = int(c)
                top_val = get(r_top, c_int)
                bot_val = get(r_bot, c_int)

                if top_val is not None and bot_val is None:
                    if typ == '=':
                        if not set_cell(r_bot, c_int, top_val): return False
                        changed = True
                    else:
                        opp = 'W' if top_val == 'B' else 'B'
                        if not set_cell(r_bot, c_int, opp): return False
                        changed = True
                elif bot_val is not None and top_val is None:
                    if typ == '=':
                        if not set_cell(r_top, c_int, bot_val): return False
                        changed = True
                    else:
                        opp = 'W' if bot_val == 'B' else 'B'
                        if not set_cell(r_top, c_int, opp): return False
                        changed = True
                elif top_val is not None and bot_val is not None:
                    if typ == '=' and top_val != bot_val: return False
                    if typ == 'x' and top_val == bot_val: return False

            # Row/column counting and no-three-consecutive
            for i in range(n):
                # Row
                row = grid[i]
                b_cnt = row.count('B')
                w_cnt = row.count('W')
                if b_cnt > target or w_cnt > target: return False

                if b_cnt == target:
                    for j in range(n):
                        if grid[i][j] is None:
                            if not set_cell(i, j, 'W'): return False
                            changed = True
                if w_cnt == target:
                    for j in range(n):
                        if grid[i][j] is None:
                            if not set_cell(i, j, 'B'): return False
                            changed = True

                # Row no-three-consecutive
                for j in range(n-2):
                    cells = [grid[i][j], grid[i][j+1], grid[i][j+2]]
                    if cells.count('B') == 2 and cells.count(None) == 1:
                        idx = cells.index(None)
                        if not set_cell(i, j+idx, 'W'): return False
                        changed = True
                    elif cells.count('W') == 2 and cells.count(None) == 1:
                        idx = cells.index(None)
                        if not set_cell(i, j+idx, 'B'): return False
                        changed = True

                # Column
                col = [grid[r][i] for r in range(n)]
                b_cnt = col.count('B')
                w_cnt = col.count('W')
                if b_cnt > target or w_cnt > target: return False

                if b_cnt == target:
                    for r in range(n):
                        if grid[r][i] is None:
                            if not set_cell(r, i, 'W'): return False
                            changed = True
                if w_cnt == target:
                    for r in range(n):
                        if grid[r][i] is None:
                            if not set_cell(r, i, 'B'): return False
                            changed = True

                # Col no-three-consecutive
                for r in range(n-2):
                    cells = [grid[r][i], grid[r+1][i], grid[r+2][i]]
                    if cells.count('B') == 2 and cells.count(None) == 1:
                        idx = cells.index(None)
                        if not set_cell(r+idx, i, 'W'): return False
                        changed = True
                    elif cells.count('W') == 2 and cells.count(None) == 1:
                        idx = cells.index(None)
                        if not set_cell(r+idx, i, 'B'): return False
                        changed = True
        return True

    def is_complete():
        return all(grid[i][j] is not None for i in range(n) for j in range(n))

    def backtrack():
        if not propagate():
            return False
        if is_complete():
            return True

        # Find first empty cell
        for i in range(n):
            for j in range(n):
                if grid[i][j] is None:
                    # Save state
                    saved = [row[:] for row in grid]

                    # Try B
                    grid[i][j] = 'B'
                    if backtrack():
                        return True

                    # Restore and try W
                    for r in range(n):
                        for c in range(n):
                            grid[r][c] = saved[r][c]

                    grid[i][j] = 'W'
                    if backtrack():
                        return True

                    # Restore on failure
                    for r in range(n):
                        for c in range(n):
                            grid[r][c] = saved[r][c]
                    return False
        return True

    if backtrack():
        return grid
    return "No Solution"

