class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        return True

    def copy(self):
        new_uf = UnionFind(0)
        new_uf.parent = self.parent[:]
        new_uf.rank = self.rank[:]
        return new_uf


def solve(observation):
    data = observation['data']
    N = len(data) - 1
    if N <= 0:
        return []

    # Precompute incident relationships
    # dot_to_cells[(r,c)] = list of (cell_r, cell_c, touch_val) where touch_val is '/' or '\'
    dot_to_cells = {}
    for r in range(N + 1):
        for c in range(N + 1):
            cells = []
            # Cell (r-1, c-1): '\' touches dot (r,c) as bottom-right
            if r > 0 and c > 0:
                cells.append((r - 1, c - 1, '\\'))
            # Cell (r-1, c): '/' touches dot (r,c) as bottom-left
            if r > 0 and c < N:
                cells.append((r - 1, c, '/'))
            # Cell (r, c-1): '/' touches dot (r,c) as top-right
            if r < N and c > 0:
                cells.append((r, c - 1, '/'))
            # Cell (r, c): '\' touches dot (r,c) as top-left
            if r < N and c < N:
                cells.append((r, c, '\\'))
            dot_to_cells[(r, c)] = cells

    # cell_to_dots[(r,c)] = list of (dot_r, dot_c, touch_val)
    cell_to_dots = {}
    for r in range(N):
        for c in range(N):
            dots = [
                (r, c, '\\'),      # '\' touches top-left
                (r, c + 1, '/'),   # '/' touches top-right
                (r + 1, c, '/'),   # '/' touches bottom-left
                (r + 1, c + 1, '\\') # '\' touches bottom-right
            ]
            cell_to_dots[(r, c)] = dots

    def dot_id(r, c):
        return r * (N + 1) + c

    class SolverState:
        def __init__(self):
            self.grid = [[None for _ in range(N)] for _ in range(N)]
            self.uf = UnionFind((N + 1) * (N + 1))

        def copy(self):
            new = SolverState()
            new.grid = [row[:] for row in self.grid]
            new.uf = self.uf.copy()
            return new

        def check_dot(self, r, c):
            """Returns (valid, forced_list) where forced_list is list of (cr, cc, val)"""
            clue = data[r][c]
            if clue is None:
                return (True, [])

            incident = dot_to_cells[(r, c)]
            current = 0
            unknown = []

            for cr, cc, touch_val in incident:
                val = self.grid[cr][cc]
                if val is None:
                    unknown.append((cr, cc, touch_val))
                elif val == touch_val:
                    current += 1

            if current > clue or current + len(unknown) < clue:
                return (False, [])

            need = clue - current
            forced = []

            if need == 0:
                # All unknown must be non-touching
                for cr, cc, touch_val in unknown:
                    forced.append((cr, cc, '/' if touch_val == '\\' else '\\'))
            elif need == len(unknown):
                # All unknown must be touching
                for cr, cc, touch_val in unknown:
                    forced.append((cr, cc, touch_val))

            return (True, forced)

        def set_cell(self, r, c, val):
            """Set cell (r,c) to val. Returns False if invalid (conflict or cycle)."""
            if self.grid[r][c] is not None:
                return self.grid[r][c] == val

            self.grid[r][c] = val

            # Check for cycle: find the two dots connected by this diagonal
            dots = cell_to_dots[(r, c)]
            endpoints = []
            for dr, dc, touch_val in dots:
                if touch_val == val:
                    endpoints.append((dr, dc))

            # Should have exactly 2 endpoints
            if len(endpoints) != 2:
                return False

            d1, d2 = endpoints
            id1 = dot_id(d1[0], d1[1])
            id2 = dot_id(d2[0], d2[1])

            # If already connected, adding this edge creates a cycle
            if self.uf.find(id1) == self.uf.find(id2):
                return False

            self.uf.union(id1, id2)
            return True

        def propagate(self):
            """Constraint propagation. Returns False if contradiction found."""
            from collections import deque
            queue = deque()
            # Add all clued dots initially
            for r in range(N + 1):
                for c in range(N + 1):
                    if data[r][c] is not None:
                        queue.append((r, c))

            # Use set to avoid duplicates
            in_queue = set((r, c) for r in range(N + 1) for c in range(N + 1) if data[r][c] is not None)

            while queue:
                r, c = queue.popleft()
                in_queue.discard((r, c))

                valid, forced = self.check_dot(r, c)
                if not valid:
                    return False

                for cr, cc, val in forced:
                    if self.grid[cr][cc] is None:
                        if not self.set_cell(cr, cc, val):
                            return False
                        # Add affected dots to queue
                        for dr, dc, _ in cell_to_dots[(cr, cc)]:
                            if data[dr][dc] is not None and (dr, dc) not in in_queue:
                                queue.append((dr, dc))
                                in_queue.add((dr, dc))
                    elif self.grid[cr][cc] != val:
                        return False

            return True

        def is_complete(self):
            return all(self.grid[r][c] is not None for r in range(N) for c in range(N))

        def get_solution(self):
            return [row[:] for row in self.grid]

        def find_empty_cell(self):
            """Find first empty cell. Could be improved with MRV."""
            for r in range(N):
                for c in range(N):
                    if self.grid[r][c] is None:
                        return (r, c)
            return None

        def solve(self):
            if not self.propagate():
                return None

            if self.is_complete():
                return self.get_solution()

            # Find empty cell
            cell = self.find_empty_cell()
            if cell is None:
                return None

            r, c = cell

            # Try both values
            for val in ['/', '\\']:
                new_state = self.copy()
                if new_state.set_cell(r, c, val):
                    result = new_state.solve()
                    if result is not None:
                        return result

            return None

    solver = SolverState()
    solution = solver.solve()

    if solution is None:
        return "No Solution"
    return solution


