    print(solve(OBSERVATION))

OBSERVATION = {'data': [[1, 5, 3, 4, 1], [5, 3, 5, 3, 1], [3, 5, 4, 1, 5], [5, 1, 2, 3, 4], [2, 1, 1, 1, 3]]}

def solve(observation):
    grid = observation['data']
    n = len(grid)

    # Precompute value positions for each row and column
    row_vals = [{} for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v not in row_vals[r]:
                row_vals[r][v] = []
            row_vals[r][v].append(c)

    col_vals = [{} for _ in range(n)]
    for c in range(n):
        for r in range(n):
            v = grid[r][c]
            if v not in col_vals[c]:
                col_vals[c][v] = []
            col_vals[c][v].append(r)

    # Directions: up, down, left, right
    DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # State encoding: 0 = unknown, 1 = white, 2 = black
    def copy_state(s):
        return [row[:] for row in s]

    def is_valid_placement(s, r, c, val):
        """Check if placing val at (r,c) is valid with current state."""
        if val == 2:  # black
            # No adjacent black cells
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and s[nr][nc] == 2:
                    return False
            return True
        else:  # white
            v = grid[r][c]
            # No same value white in row
            for cc in range(n):
                if cc != c and s[r][cc] == 1 and grid[r][cc] == v:
                    return False
            # No same value white in column
            for rr in range(n):
                if rr != r and s[rr][c] == 1 and grid[rr][c] == v:
                    return False
            return True

    def propagate(s):
        """Constraint propagation. Returns False if contradiction found."""
        changed = True
        while changed:
            changed = False

            for r in range(n):
                for c in range(n):
                    if s[r][c] != 0:
                        continue

                    # Determine possible values
                    can_black = True
                    for dr, dc in DIRS:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and s[nr][nc] == 2:
                            can_black = False
                            break

                    can_white = is_valid_placement(s, r, c, 1)

                    if not can_black and not can_white:
                        return False
                    if not can_black:
                        s[r][c] = 1
                        changed = True
                    elif not can_white:
                        s[r][c] = 2
                        changed = True

            # If a cell is white, all other cells with same value in row/col must be black
            for r in range(n):
                for v, cols in row_vals[r].items():
                    white_cols = [c for c in cols if s[r][c] == 1]
                    if len(white_cols) > 1:
                        return False
                    if len(white_cols) == 1:
                        wc = white_cols[0]
                        for c in cols:
                            if c != wc and s[r][c] == 0:
                                # Force to black, check validity
                                for dr, dc in DIRS:
                                    nr, nc = r + dr, c + dc
                                    if 0 <= nr < n and 0 <= nc < n and s[nr][nc] == 2:
                                        return False
                                s[r][c] = 2
                                changed = True

            for c in range(n):
                for v, rows in col_vals[c].items():
                    white_rows = [r for r in rows if s[r][c] == 1]
                    if len(white_rows) > 1:
                        return False
                    if len(white_rows) == 1:
                        wr = white_rows[0]
                        for r in rows:
                            if r != wr and s[r][c] == 0:
                                for dr, dc in DIRS:
                                    nr, nc = r + dr, c + dc
                                    if 0 <= nr < n and 0 <= nc < n and s[nr][nc] == 2:
                                        return False
                                s[r][c] = 2
                                changed = True

        return True

    def check_connectivity(s):
        """Check if all white cells form one orthogonally connected group."""
        white_cells = [(r, c) for r in range(n) for c in range(n) if s[r][c] == 1]
        if not white_cells:
            return False

        start = white_cells[0]
        visited = set([start])
        stack = [start]
        count = 0

        while stack:
            r, c = stack.pop()
            count += 1
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and s[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        return count == len(white_cells)

    def is_complete(s):
        """Check if all cells are determined."""
        for r in range(n):
            for c in range(n):
                if s[r][c] == 0:
                    return False
        return True

    def solve_recursive(s):
        s = copy_state(s)
        if not propagate(s):
            return None

        if is_complete(s):
            return s if check_connectivity(s) else None

        # Select most constrained unknown cell
        best_r, best_c = -1, -1
        best_score = -1

        for r in range(n):
            for c in range(n):
                if s[r][c] != 0:
                    continue

                score = 0
                v = grid[r][c]

                # Forced by adjacent black -> must be white
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and s[nr][nc] == 2:
                        score += 1000

                # Forced by duplicate white in row/col -> must be black
                for cc in range(n):
                    if cc != c and s[r][cc] == 1 and grid[r][cc] == v:
                        score += 1000
                for rr in range(n):
                    if rr != r and s[rr][c] == 1 and grid[rr][c] == v:
                        score += 1000

                # Prefer cells with many determined neighbors
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and s[nr][nc] != 0:
                        score += 1

                if score > best_score:
                    best_score = score
                    best_r, best_c = r, c

        if best_r == -1:
            return None

        r, c = best_r, best_c

        # Try white first if forced by adjacent black, else try black first
        try_white = any(0 <= r+dr < n and 0 <= c+dc < n and s[r+dr][c+dc] == 2 for dr, dc in DIRS)

        if try_white:
            # Try white
            s2 = copy_state(s)
            s2[r][c] = 1
            res = solve_recursive(s2)
            if res:
                return res
            # Try black
            s2 = copy_state(s)
            s2[r][c] = 2
            return solve_recursive(s2)
        else:
            # Try black
            s2 = copy_state(s)
            s2[r][c] = 2
            res = solve_recursive(s2)
            if res:
                return res
            # Try white
            s2 = copy_state(s)
            s2[r][c] = 1
            return solve_recursive(s2)

    initial = [[0 for _ in range(n)] for _ in range(n)]
    solution = solve_recursive(initial)

    if solution is None:
        return "No Solution"

    # Convert to output format: 'B' for black, None for white
    result = []
    for r in range(n):
        row = []
        for c in range(n):
