def solve(observation):
    data = observation['data']
    n = len(data) - 1  # grid size

    # Precompute incident cells for each dot
    # incident[r][c] = list of (cell_r, cell_c, diag) where diag is the diagonal touching dot (r,c)
    incident = [[[] for _ in range(n+1)] for _ in range(n+1)]
    for r in range(n):
        for c in range(n):
            # '\' touches (r,c) and (r+1,c+1)
            incident[r][c].append((r, c, '\\'))
            incident[r+1][c+1].append((r, c, '\\'))
            # '/' touches (r,c+1) and (r+1,c)
            incident[r][c+1].append((r, c, '/'))
            incident[r+1][c].append((r, c, '/'))

    # DSU utilities
    def dsu_find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def dsu_union(parent, x, y):
        px, py = dsu_find(parent, x), dsu_find(parent, y)
        if px == py:
            return False
        parent[px] = py
        return True

    # Get the two dots connected by a diagonal in cell (r,c)
    def get_connection(r, c, diag):
        if diag == '\\':
            return (r * (n+1) + c, (r+1) * (n+1) + (c+1))
        else:
            return (r * (n+1) + (c+1), (r+1) * (n+1) + c)

    # Attempt to assign a cell, returns (success, new_grid, new_degree, new_parent)
    # or modifies in place and returns success boolean
    def assign_cell(grid, degree, parent, r, c, val):
        if grid[r][c] is not None:
            return grid[r][c] == val
        grid[r][c] = val

        # Get connected dots
        u, v = get_connection(r, c, val)

        # Check for loop
        if dsu_find(parent, u) == dsu_find(parent, v):
            return False

        # Union the two dots
        dsu_union(parent, u, v)

        # Update degrees
        ur, uc = u // (n+1), u % (n+1)
        vr, vc = v // (n+1), v % (n+1)
        degree[ur][uc] += 1
        degree[vr][vc] += 1

        # Check constraints
        if data[ur][uc] is not None and degree[ur][uc] > data[ur][uc]:
            return False
        if data[vr][vc] is not None and degree[vr][vc] > data[vr][vc]:
            return False
        return True

    # Constraint propagation
    def propagate(grid, degree, parent):
        changed = True
        while changed:
            changed = False
            for r in range(n+1):
                for c in range(n+1):
                    if data[r][c] is None:
                        continue
                    target = data[r][c]
                    curr = degree[r][c]

                    # Collect unknown incident cells
                    unknown = []
                    for (cr, cc, touch_diag) in incident[r][c]:
                        val = grid[cr][cc]
                        if val is None:
                            unknown.append((cr, cc, touch_diag))
                        # Note: already set cells are already counted in degree

                    # Check bounds
                    max_possible = curr + len(unknown)
                    if curr > target or max_possible < target:
                        return False

                    if curr == target:
                        # Force all unknown to avoid
                        for (cr, cc, touch_diag) in unknown:
                            other = '/' if touch_diag == '\\' else '\\'
                            if not assign_cell(grid, degree, parent, cr, cc, other):
                                return False
                            changed = True
                    elif max_possible == target:
                        # Force all unknown to touch
                        for (cr, cc, touch_diag) in unknown:
                            if not assign_cell(grid, degree, parent, cr, cc, touch_diag):
                                return False
                            changed = True
        return True

    # Recursive search with propagation
    def search(grid, degree, parent):
        # Deep copy state
        grid = [row[:] for row in grid]
        degree = [row[:] for row in degree]
        parent = parent[:]

        # Propagate constraints
        if not propagate(grid, degree, parent):
            return None

        # Check if complete
        complete = True
        start_r, start_c = -1, -1
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    complete = False
                    start_r, start_c = r, c
                    break
            if not complete:
                break

        if complete:
            return grid

        # Branch on first unknown cell
        # Try '/'
        grid_copy = [row[:] for row in grid]
        deg_copy = [row[:] for row in degree]
        par_copy = parent[:]
        if assign_cell(grid_copy, deg_copy, par_copy, start_r, start_c, '/'):
            res = search(grid_copy, deg_copy, par_copy)
            if res is not None:
                return res

        # Try '\'
        grid_copy = [row[:] for row in grid]
        deg_copy = [row[:] for row in degree]
        par_copy = parent[:]
        if assign_cell(grid_copy, deg_copy, par_copy, start_r, start_c, '\\'):
            res = search(grid_copy, deg_copy, par_copy)
            if res is not None:
                return res

        return None

    # Initialize
    init_grid = [[None for _ in range(n)] for _ in range(n)]
    init_degree = [[0 for _ in range(n+1)] for _ in range(n+1)]
    init_parent = list(range((n+1)*(n+1)))

    result = search(init_grid, init_degree, init_parent)
    return result

