    state = [[0]*n for _ in range(n)]

    def set_cell(r, c, val, queue):
        """Set cell (r,c) to val (1 or 2), add to queue. Return False if contradiction."""
        if state[r][c] == val:
            return True
        if state[r][c] != 0:
            return False
        state[r][c] = val
        queue.append((r, c, val))
        return True

    def propagate(initial_queue):
        """Propagate constraints from initial queue. Return False if contradiction."""
        queue = initial_queue[:]
        while queue:
            r, c, val = queue.pop(0)
            v = grid[r][c]

            if val == 2:  # Black cell
                # Orthogonal neighbors must be white
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if state[nr][nc] == 2:
                            return False
                        if not set_cell(nr, nc, 1, queue):
                            return False
            else:  # White cell
                # All other cells with same value in row must be black
                for cc in row_pos[r][v]:
                    if cc != c:
                        if state[r][cc] == 1:
                            return False
                        if not set_cell(r, cc, 2, queue):
                            return False
                # All other cells with same value in column must be black
                for rr in col_pos[c][v]:
                    if rr != r:
                        if state[rr][c] == 1:
                            return False
                        if not set_cell(rr, c, 2, queue):
                            return False
        return True

    def apply_static_deductions():
        """Apply triplet rule and other static patterns."""
        changed = True
        while changed:
            changed = False
            # Horizontal triplets: three consecutive same values
            for r in range(n):
                for c in range(n - 2):
                    v = grid[r][c]
                    if v == grid[r][c+1] == grid[r][c+2]:
                        if state[r][c+1] == 0:
                            # Middle cannot be black (would force ends white, causing duplicate)
                            if not propagate([(r, c+1, 1)]):
