        start = whites[0]
        visited = {start}
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and state[nr][nc] != 2 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return all((r, c) in visited for r, c in whites)

    def select_cell():
        """Select undecided cell with highest constraint (most same-value neighbors)."""
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if state[r][c] == 0:
                    v = grid[r][c]
                    # Count non-black cells with same value in row and column
                    score = 0
                    for cc in row_pos[r][v]:
                        if state[r][cc] != 2:
                            score += 1
                    for rr in col_pos[c][v]:
                        if state[rr][c] != 2:
