    # Use iterative deepening or simple recursion with backtracking
    def search():
        cell = select_cell()
        if cell is None:
            return check_connectivity()

        r, c = cell
        saved_state = [row[:] for row in state]

        # Try White first (often more constrained)
        if propagate([(r, c, 1)]):
            if check_connectivity():
                if search():
                    return True

        # Restore
        for i in range(n):
            for j in range(n):
