    def check_connectivity(state):
        white_cells = []
        for r in range(n):
            for c in range(n):
                if state[r][c] == 1:  # WHITE
                    white_cells.append((r, c))

        if not white_cells:
            return True

        # BFS from first white cell through non-black cells
        from collections import deque
        start = white_cells[0]
        visited = {start}
        q = deque([start])

        while q:
            r, c = q.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and state[nr][nc] != 2 and (nr, nc) not in visited:
