    # state: 0=unknown, 1=white, 2=black
    def propagate(state, start_r, start_c, start_color):
        from collections import deque
        q = deque()
        q.append((start_r, start_c, start_color))

        while q:
            r, c, color = q.popleft()
            if state[r][c] != 0:
                if state[r][c] != color:
                    return False
                continue

            state[r][c] = color

            if color == 2:  # BLACK
                # Orthogonal neighbors must be WHITE
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        q.append((nr, nc, 1))
