def solve(observation):
    data = observation['data']
    n = len(data)

    UNKNOWN = 0
    WHITE = 1
    BLACK = 2

    # Initialize grid
    grid = [[UNKNOWN for _ in range(n)] for _ in range(n)]
    clues = []
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                grid[r][c] = WHITE
                clues.append((r, c, data[r][c]))

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_line(r, c, dr, dc):
        """Get list of cells in direction until border"""
        cells = []
        nr, nc = r + dr, c + dc
        while 0 <= nr < n and 0 <= nc < n:
            cells.append((nr, nc))
            nr += dr
            nc += dc
        return cells

    def compute_dir_bounds(grid, r, c, dr, dc):
        """Return (min_vis, max_vis, visible_cells_in_max, blocker_pos_or_none)"""
        cells = get_line(r, c, dr, dc)

        # Min: consecutive WHITE from start
        min_vis = 0
        for cell in cells:
            cr, cc = cell
            if grid[cr][cc] == WHITE:
                min_vis += 1
            else:
                break

        # Max: until first BLACK
        max_vis = 0
        blocker = None
        for i, cell in enumerate(cells):
            cr, cc = cell
            if grid[cr][cc] == BLACK:
                blocker = cell
                break
            max_vis += 1

        visible_range = cells[:max_vis]
        # Next cell after visible range is the blocker position (could be out of bounds or the black cell found)
        next_cell = cells[max_vis] if max_vis < len(cells) else None

        return min_vis, max_vis, visible_range, next_cell

    def propagate(grid):
        """Propagate constraints. Returns (new_grid, is_valid, changed)"""
        changed = True
        while changed:
            changed = False

            # Rule 1: Clue constraints
            for r, c, val in clues:
                min_total = 1
                max_total = 1
                dir_info = []

                for dr, dc in dirs:
                    min_v, max_v, vis_cells, blocker = compute_dir_bounds(grid, r, c, dr, dc)
                    min_total += min_v
                    max_total += max_v
                    dir_info.append((min_v, max_v, vis_cells, blocker))

                if min_total > val or max_total < val:
                    return grid, False, False  # Contradiction

                if min_total == val:
                    # Need to block at min_v in each direction
                    for min_v, max_v, vis_cells, blocker in dir_info:
                        if blocker is not None:
                            br, bc = blocker
                            if grid[br][bc] == WHITE:
                                return grid, False, False
                            if grid[br][bc] == UNKNOWN:
                                grid[br][bc] = BLACK
                                changed = True

                if max_total == val:
                    # All cells in visible range must be white, and next must be black
