                                return grid, False, False
                            if grid[vr][vc] == UNKNOWN:
                                grid[vr][vc] = WHITE
                                changed = True
                        if blocker is not None:
                            br, bc = blocker
                            if grid[br][bc] == WHITE:
                                return grid, False, False
                            if grid[br][bc] == UNKNOWN:
                                grid[br][bc] = BLACK
                                changed = True

            # Rule 2: Black cells cannot touch orthogonally
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == BLACK:
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < n:
                                if grid[nr][nc] == BLACK:
                                    return grid, False, False
                                if grid[nr][nc] == UNKNOWN:
                                    grid[nr][nc] = WHITE
                                    changed = True

            # Rule 3: Check white connectivity feasibility
            # All white cells must be connected through non-black cells
            white_cells = []
            non_black = set()
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == WHITE:
                        white_cells.append((r, c))
                    if grid[r][c] != BLACK:
                        non_black.add((r, c))

            if white_cells:
                # BFS from first white cell through non_black cells
                start = white_cells[0]
                visited = set([start])
                queue = [start]
                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if (nr, nc) in non_black and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

                # Check all white cells are visited
                for wc in white_cells:
                    if wc not in visited:
                        return grid, False, False

        return grid, True, False

    def is_solved(grid):
        # Check no unknowns
        for r in range(n):
            for c in range(n):
                if grid[r][c] == UNKNOWN:
                    return False

        # Check all clues satisfied
        for r, c, val in clues:
            count = 1
            for dr, dc in dirs:
                cells = get_line(r, c, dr, dc)
                for cell in cells:
                    cr, cc = cell
                    if grid[cr][cc] == BLACK:
                        break
                    count += 1
            if count != val:
                return False

        # Check white connectivity
        white_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == WHITE]
        if not white_cells:
            return False
        visited = set()
        stack = [white_cells[0]]
        while stack:
            cell = stack.pop()
            if cell in visited:
                continue
            visited.add(cell)
            cr, cc = cell
            for dr, dc in dirs:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == WHITE and (nr, nc) not in visited:
                    stack.append((nr, nc))

        return len(visited) == len(white_cells)

    def copy_grid(grid):
        return [row[:] for row in grid]

    def solve_recursive(grid):
        grid, valid, _ = propagate(grid)
        if not valid:
            return None
        if is_solved(grid):
            return grid

        # Find unknown cell
        # Heuristic: pick cell involved in tightest constraint
        best_cell = None
        best_score = float('inf')
        for r in range(n):
            for c in range(n):
                if grid[r][c] == UNKNOWN:
                    # Simple heuristic: first unknown
                    best_cell = (r, c)
                    break
            if best_cell:
                break

        if not best_cell:
            return None  # Should not happen if not solved

        r, c = best_cell

        # Try WHITE first or BLACK first? 
        # Usually cells are more likely white, but let's try both
        for val in [WHITE, BLACK]:
            new_grid = copy_grid(grid)
            new_grid[r][c] = val
            result = solve_recursive(new_grid)
            if result is not None:
                return result

        return None

    solution_grid = solve_recursive(grid)

    if solution_grid is None:
        return "No Solution"

    # Format output
    result = []
    for r in range(n):
        row = []
        for c in range(n):
            if data[r][c] is not None:
                row.append(data[r][c])
            elif solution_grid[r][c] == BLACK:
                row.append('B')
            else:
                row.append(None)
        result.append(row)

    return result

