OBSERVATION = {'U': [0, 5, 0, 0, 3], 'D': [2, 0, 4, 0, 0], 'L': [0, 4, 0, 0, 0], 'R': [3, 0, 0, 0, 3]}

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    # Initialize domains: each cell can be 1..N
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    from collections import deque

    def force(domains, r, c, val):
        """Force cell (r,c) to be val, returns False if contradiction"""
        if val not in domains[r][c]:
            return False
        domains[r][c] = {val}
        return True

    # Apply forced constraints from clues = 1 or = N
    for c in range(N):
        if U[c] == 1:
            if not force(domains, 0, c, N):
                return "No Solution"
        if U[c] == N:
            for r in range(N):
                if not force(domains, r, c, r+1):
                    return "No Solution"
        if D[c] == 1:
            if not force(domains, N-1, c, N):
                return "No Solution"
        if D[c] == N:
            for r in range(N):
                if not force(domains, r, c, N-r):
                    return "No Solution"

    for r in range(N):
        if L[r] == 1:
            if not force(domains, r, 0, N):
                return "No Solution"
        if L[r] == N:
            for c in range(N):
                if not force(domains, r, c, c+1):
                    return "No Solution"
        if R[r] == 1:
            if not force(domains, r, N-1, N):
                return "No Solution"
        if R[r] == N:
            for c in range(N):
                if not force(domains, r, c, N-c):
                    return "No Solution"

    # Constraint propagation: if cell fixed, remove from row/col; if value only in one cell, fix it
    def propagate(domains, queue):
        while queue:
            r, c = queue.popleft()
            val = list(domains[r][c])[0]
            # Remove from row
            for cc in range(N):
                if cc != c and val in domains[r][cc]:
                    domains[r][cc].remove(val)
                    if len(domains[r][cc]) == 0:
                        return None
                    if len(domains[r][cc]) == 1:
                        queue.append((r, cc))
            # Remove from col
            for rr in range(N):
                if rr != r and val in domains[rr][c]:
                    domains[rr][c].remove(val)
                    if len(domains[rr][c]) == 0:
                        return None
                    if len(domains[rr][c]) == 1:
                        queue.append((rr, c))
        return domains

    # Initialize queue with all fixed cells
    queue = deque()
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) == 1:
                queue.append((r, c))

    domains = propagate(domains, queue)
    if domains is None:
        return "No Solution"

    # Visibility bounds calculation using greedy algorithms
    def get_min_visible(line_domains):
        """Minimum visible from left: hide whenever possible, use largest values"""
        max_h = 0
        seen = 0
        for dom in line_domains:
            hidden = [v for v in dom if v <= max_h]
            if hidden:
                val = max(hidden)  # Largest hidden to save small ones
            else:
                val = max(dom)  # Must show, pick largest to block
                seen += 1
                max_h = val
        return seen

    def get_max_visible(line_domains):
        """Maximum visible from left: show whenever possible, use smallest visible"""
        max_h = 0
        seen = 0
        for dom in line_domains:
            visible = [v for v in dom if v > max_h]
            if visible:
                val = min(visible)  # Smallest visible to allow more
                seen += 1
                max_h = val
            else:
                val = min(dom)  # Hide, pick smallest to save large
        return seen

    def check_constraints(domains):
        """Check if visibility clues are still satisfiable"""
        # U: top to bottom
        for c in range(N):
            if U[c] > 0:
                line = [domains[r][c] for r in range(N)]
                if U[c] < get_min_visible(line) or U[c] > get_max_visible(line):
                    return False
        # D: bottom to top
        for c in range(N):
            if D[c] > 0:
                line = [domains[r][c] for r in range(N-1, -1, -1)]
                if D[c] < get_min_visible(line) or D[c] > get_max_visible(line):
                    return False
        # L: left to right
        for r in range(N):
            if L[r] > 0:
                line = [domains[r][c] for c in range(N)]
                if L[r] < get_min_visible(line) or L[r] > get_max_visible(line):
                    return False
        # R: right to left
        for r in range(N):
            if R[r] > 0:
                line = [domains[r][c] for c in range(N-1, -1, -1)]
                if R[r] < get_min_visible(line) or R[r] > get_max_visible(line):
                    return False
        return True

    if not check_constraints(domains):
        return "No Solution"

    def copy_domains(domains):
        return [[set(d) for d in row] for row in domains]

    def is_complete(domains):
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) != 1:
                    return False
        return True

    def get_solution(domains):
        return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

    def verify(sol):
        """Final verification of solution"""
        # Check Latin square
        for r in range(N):
            if set(sol[r]) != set(range(1, N+1)):
                return False
        for c in range(N):
            if set(sol[r][c] for r in range(N)) != set(range(1, N+1)):
                return False
        # Check visibility
        for c in range(N):
            if U[c] > 0:
                col = [sol[r][c] for r in range(N)]
                if count_visible(col) != U[c]:
                    return False
            if D[c] > 0:
                col = [sol[r][c] for r in range(N-1, -1, -1)]
                if count_visible(col) != D[c]:
                    return False
        for r in range(N):
            if L[r] > 0:
                row = [sol[r][c] for c in range(N)]
                if count_visible(row) != L[r]:
                    return False
            if R[r] > 0:
                row = [sol[r][c] for c in range(N-1, -1, -1)]
                if count_visible(row) != R[r]:
                    return False
        return True

    def count_visible(vals):
        if not vals:
            return 0
        cnt = 1
        max_h = vals[0]
        for v in vals[1:]:
            if v > max_h:
                cnt += 1
                max_h = v
        return cnt

    # Backtracking with MRV heuristic
    def backtrack(domains):
        if is_complete(domains):
            sol = get_solution(domains)
            return sol if verify(sol) else None

        # MRV: find cell with minimum remaining values > 1
        min_size = N + 2
        br, bc = -1, -1
        for r in range(N):
            for c in range(N):
                sz = len(domains[r][c])
                if sz > 1 and sz < min_size:
                    min_size = sz
                    br, bc = r, c

        if br == -1:
            return None

        # Try values in sorted order
        for val in sorted(domains[br][bc]):
            new_dom = copy_domains(domains)
            new_dom[br][bc] = {val}

            q = deque([(br, bc)])
            new_dom = propagate(new_dom, q)
            if new_dom is None:
                continue

            if not check_constraints(new_dom):
                continue

            result = backtrack(new_dom)
            if result is not None:
                return result

        return None

    result = backtrack(domains)
    return result if result is not None else "No Solution"

