def solve(observation):
    class Contradiction(Exception):
        pass

    def parse_obs(obs):
        data = obs['data']
        h_dict = obs['horizontal']
        v_dict = obs['vertical']
        n = len(data)
        grid = [[{'B', 'W'} for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for c in range(n):
                if data[r][c] is not None:
                    grid[r][c] = {data[r][c]}
        h_const = []
        for key, val in h_dict.items():
            key = key.strip('()')
            parts = key.split(',')
            r = int(float(parts[0]))
            col_c = float(parts[1])
            c1 = int(col_c - 0.5)
            c2 = c1 + 1
            h_const.append((r, c1, c2, val))
        v_const = []
        for key, val in v_dict.items():
            key = key.strip('()')
            parts = key.split(',')
            row_c = float(parts[0])
            c = int(float(parts[1]))
            r1 = int(row_c - 0.5)
            r2 = r1 + 1
            v_const.append((r1, c, r2, c, val))
        return grid, h_const, v_const, n

    def check_balance_row(grid, r, n):
        row = grid[r]
        cnt_b = sum(1 for cell in row if cell == {'B'})
        cnt_w = sum(1 for cell in row if cell == {'W'})
        if cnt_b > n//2 or cnt_w > n//2:
            raise Contradiction()
        unknowns = [c for c, cell in enumerate(row) if len(cell) > 1]
        changed = False
        if cnt_b == n//2:
            for c in unknowns:
                if 'W' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'W'}:
                    grid[r][c] = {'W'}
                    changed = True
            return changed
        if cnt_w == n//2:
            for c in unknowns:
                if 'B' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'B'}:
                    grid[r][c] = {'B'}
                    changed = True
            return changed
        if cnt_b + len(unknowns) == n//2:
            for c in unknowns:
                if 'B' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'B'}:
                    grid[r][c] = {'B'}
                    changed = True
            return changed
        if cnt_w + len(unknowns) == n//2:
            for c in unknowns:
                if 'W' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'W'}:
                    grid[r][c] = {'W'}
                    changed = True
            return changed
        return False

    def check_balance_col(grid, c, n):
        col = [grid[r][c] for r in range(n)]
        cnt_b = sum(1 for cell in col if cell == {'B'})
        cnt_w = sum(1 for cell in col if cell == {'W'})
        if cnt_b > n//2 or cnt_w > n//2:
            raise Contradiction()
        unknowns = [r for r, cell in enumerate(col) if len(cell) > 1]
        changed = False
        if cnt_b == n//2:
            for r in unknowns:
                if 'W' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'W'}:
                    grid[r][c] = {'W'}
                    changed = True
            return changed
        if cnt_w == n//2:
