                if 'B' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'B'}:
                    grid[r][c] = {'B'}
                    changed = True
            return changed
        if cnt_w + len(unknowns) == n//2:
            for r in unknowns:
                if 'W' not in grid[r][c]:
                    raise Contradiction()
                if grid[r][c] != {'W'}:
                    grid[r][c] = {'W'}
                    changed = True
