    def check_cons_row(grid, r, n):
        for c in range(n-2):
            a, b, cc = grid[r][c], grid[r][c+1], grid[r][c+2]
            if a == {'B'} and b == {'B'} and len(cc) > 1:
                if 'W' not in cc: raise Contradiction()
                grid[r][c+2] = {'W'}
                return True
            if b == {'B'} and cc == {'B'} and len(a) > 1:
                if 'W' not in a: raise Contradiction()
                grid[r][c] = {'W'}
                return True
            if a == {'B'} and cc == {'B'} and len(b) > 1:
                if 'W' not in b: raise Contradiction()
                grid[r][c+1] = {'W'}
                return True
            if a == {'W'} and b == {'W'} and len(cc) > 1:
                if 'B' not in cc: raise Contradiction()
                grid[r][c+2] = {'B'}
                return True
            if b == {'W'} and cc == {'W'} and len(a) > 1:
                if 'B' not in a: raise Contradiction()
                grid[r][c] = {'B'}
                return True
            if a == {'W'} and cc == {'W'} and len(b) > 1:
                if 'B' not in b: raise Contradiction()
                grid[r][c+1] = {'B'}
                return True
        return False

    def check_cons_col(grid, c, n):
        for r in range(n-2):
            a, b, cc = grid[r][c], grid[r+1][c], grid[r+2][c]
            if a == {'B'} and b == {'B'} and len(cc) > 1:
                if 'W' not in cc: raise Contradiction()
                grid[r+2][c] = {'W'}
                return True
            if b == {'B'} and cc == {'B'} and len(a) > 1:
                if 'W' not in a: raise Contradiction()
                grid[r][c] = {'W'}
                return True
            if a == {'B'} and cc == {'B'} and len(b) > 1:
                if 'W' not in b: raise Contradiction()
                grid[r+1][c] = {'W'}
                return True
            if a == {'W'} and b == {'W'} and len(cc) > 1:
                if 'B' not in cc: raise Contradiction()
                grid[r+2][c] = {'B'}
                return True
            if b == {'W'} and cc == {'W'} and len(a) > 1:
                if 'B' not in a: raise Contradiction()
                grid[r][c] = {'B'}
                return True
            if a == {'W'} and cc == {'W'} and len(b) > 1:
                if 'B' not in b: raise Contradiction()
                grid[r+1][c] = {'B'}
                return True
        return False

    def apply_adj(grid, r1, c1, r2, c2, typ):
        d1, d2 = grid[r1][c1], grid[r2][c2]
        if len(d1) == 1 and len(d2) == 1:
            v1, v2 = next(iter(d1)), next(iter(d2))
            if typ == '=' and v1 != v2:
                raise Contradiction()
            if typ == 'x' and v1 == v2:
                raise Contradiction()
            return False
        if len(d1) == 1:
            v1 = next(iter(d1))
            if typ == '=':
                if v1 not in d2:
                    raise Contradiction()
                if d2 != {v1}:
                    grid[r2][c2] = {v1}
                    return True
            else:
                if v1 in d2:
                    new_d = d2 - {v1}
                    if not new_d:
                        raise Contradiction()
                    grid[r2][c2] = new_d
                    return True
        if len(d2) == 1:
            v2 = next(iter(d2))
            if typ == '=':
                if v2 not in d1:
                    raise Contradiction()
                if d1 != {v2}:
                    grid[r1][c1] = {v2}
                    return True
            else:
                if v2 in d1:
                    new_d = d1 - {v2}
                    if not new_d:
                        raise Contradiction()
                    grid[r1][c1] = new_d
                    return True
        return False

    def propagate(grid, h_const, v_const, n):
        while True:
            changed = False
            for r in range(n):
                if check_balance_row(grid, r, n):
                    changed = True
            for c in range(n):
                if check_balance_col(grid, c, n):
                    changed = True
            for r in range(n):
                if check_cons_row(grid, r, n):
                    changed = True
            for c in range(n):
                if check_cons_col(grid, c, n):
                    changed = True
            for r, c1, c2, typ in h_const:
                if apply_adj(grid, r, c1, r, c2, typ):
                    changed = True
            for r1, c, r2, c2, typ in v_const:
                if apply_adj(grid, r1, c, r2, c, typ):
                    changed = True
            if not changed:
                break
        return grid

    def is_solved(grid, n):
        for r in range(n):
            for c in range(n):
                if len(grid[r][c]) > 1:
                    return False
        return True

    def copy_grid(grid):
        return [row[:] for row in grid]

    grid, h_const, v_const, n = parse_obs(observation)
    try:
        grid = propagate(grid, h_const, v_const, n)
    except Contradiction:
        return "No Solution"

    def dfs(g):
        if is_solved(g, n):
            return g
        min_sz = 3
        target = None
        for r in range(n):
            for c in range(n):
                sz = len(g[r][c])
                if 1 < sz < min_sz:
                    min_sz = sz
                    target = (r, c)
        if target is None:
            return None
        r, c = target
        for val in list(g[r][c]):
            new_g = copy_grid(g)
            new_g[r][c] = {val}
            try:
                new_g = propagate(new_g, h_const, v_const, n)
                res = dfs(new_g)
                if res is not None:
                    return res
            except Contradiction:
                continue
        return None

    result = dfs(grid)
    if result is None:
        return "No Solution"
    return [[next(iter(result[r][c])) for c in range(n)] for r in range(n)]

