def solve(observation):
    import ast
    from collections import deque

    data = observation['data']
    N = len(data)
    all_bits = (1 << N) - 1

    # Initialize domains using bitmasks (bit i represents value i+1)
    domains = []
    for r in range(N):
        row = []
        for c in range(N):
            val = data[r][c]
            if val is None:
                row.append(all_bits)
            else:
                row.append(1 << (val - 1))
        domains.append(row)

    # Parse inequalities: list of (r1, c1, r2, c2, is_gt) where is_gt means cell1 > cell2
    ineqs = []

    # Horizontal: between (r, c) and (r, c+1) at position (r, c+0.5)
    h_ineqs = observation.get('horizontal', {})
    for key, sym in h_ineqs.items():
        coord = ast.literal_eval(key)
        r, c_float = coord
        left_c = int(c_float - 0.5)
        right_c = int(c_float + 0.5)
        if sym == '>':
            ineqs.append((r, left_c, r, right_c, True))
        elif sym == '<':
            ineqs.append((r, right_c, r, left_c, True))

    # Vertical: between (r, c) and (r+1, c) at position (r+0.5, c)
    v_ineqs = observation.get('vertical', {})
    for key, sym in v_ineqs.items():
        coord = ast.literal_eval(key)
        r_float, c = coord
        up_r = int(r_float - 0.5)
        down_r = int(r_float + 0.5)
        if sym == 'v':
            ineqs.append((up_r, c, down_r, c, True))
        elif sym == '^':
            ineqs.append((down_r, c, up_r, c, True))

    def get_bounds(d):
        """Return (min_val, max_val) for domain d."""
        if d == 0:
            return (0, 0)
        min_val = (d & -d).bit_length()
        max_val = d.bit_length()
        return (min_val, max_val)

    def propagate(doms):
        """Apply constraint propagation until fixpoint. Returns False if contradiction."""
        queue = deque()

        # Initialize queue with all constraints
        for r in range(N):
            for c in range(N):
                if doms[r][c] == 0:
                    return False
                queue.append(('cell', r, c))
        for i in range(len(ineqs)):
            queue.append(('ineq', i))

        while True:
            # Process propagation queue
            while queue:
                item = queue.popleft()
                if item[0] == 'cell':
                    r, c = item[1], item[2]
                    d = doms[r][c]
                    if d == 0:
                        return False
                    # If cell is fixed, propagate to row and column (forward checking)
                    if d & (d - 1) == 0:  # single bit
                        bit = d
                        # Row propagation
                        for c2 in range(N):
                            if c2 != c and (doms[r][c2] & bit):
                                doms[r][c2] &= ~bit
                                queue.append(('cell', r, c2))
                                if doms[r][c2] == 0:
                                    return False
                        # Column propagation
                        for r2 in range(N):
                            if r2 != r and (doms[r2][c] & bit):
                                doms[r2][c] &= ~bit
                                queue.append(('cell', r2, c))
                                if doms[r2][c] == 0:
                                    return False
                else:  # inequality constraint
                    idx = item[1]
                    r1, c1, r2, c2, is_gt = ineqs[idx]
                    d1, d2 = doms[r1][c1], doms[r2][c2]
                    if d1 == 0 or d2 == 0:
                        return False

                    min1, max1 = get_bounds(d1)
                    min2, max2 = get_bounds(d2)

                    if is_gt:
                        # cell1 > cell2
                        if max1 <= min2:
                            return False
                        # Remove from d1 values <= min2
                        new_d1 = d1 & ~((1 << min2) - 1)
                        # Remove from d2 values >= max1
                        new_d2 = d2 & ((1 << (max1 - 1)) - 1) if max1 > 1 else 0
                    else:
                        # cell1 < cell2
                        if max2 <= min1:
                            return False
                        # Remove from d1 values >= max2
                        new_d1 = d1 & ((1 << (max2 - 1)) - 1) if max2 > 1 else 0
                        # Remove from d2 values <= min1
                        new_d2 = d2 & ~((1 << min1) - 1)

                    if new_d1 != d1:
                        doms[r1][c1] = new_d1
                        queue.append(('cell', r1, c1))
                        if new_d1 == 0:
                            return False
                    if new_d2 != d2:
                        doms[r2][c2] = new_d2
                        queue.append(('cell', r2, c2))
                        if new_d2 == 0:
                            return False

            # Queue empty - check for hidden singles and naked pairs
            changed = False

            # Hidden singles in rows
            for r in range(N):
                for val in range(1, N + 1):
                    bit = 1 << (val - 1)
                    possible = [c for c in range(N) if doms[r][c] & bit]
                    if len(possible) == 0:
                        return False
                    if len(possible) == 1:
                        c = possible[0]
                        if doms[r][c] != bit:
                            doms[r][c] = bit
                            queue.append(('cell', r, c))
                            changed = True

            if not changed:
                # Hidden singles in columns
                for c in range(N):
                    for val in range(1, N + 1):
                        bit = 1 << (val - 1)
                        possible = [r for r in range(N) if doms[r][c] & bit]
                        if len(possible) == 0:
                            return False
                        if len(possible) == 1:
                            r = possible[0]
                            if doms[r][c] != bit:
                                doms[r][c] = bit
                                queue.append(('cell', r, c))
                                changed = True

            if not changed:
                # Naked pairs in rows
                for r in range(N):
                    # Map domain mask to list of columns with exactly that domain (size 2)
                    dom_to_cols = {}
                    for c in range(N):
                        d = doms[r][c]
                        if d.bit_count() == 2:
                            if d not in dom_to_cols:
                                dom_to_cols[d] = []
                            dom_to_cols[d].append(c)
                    for mask, cols in dom_to_cols.items():
                        if len(cols) >= 2:
                            # Found naked pair/triple - eliminate from other cells
                            for c in range(N):
                                if c not in cols and (doms[r][c] & mask):
                                    doms[r][c] &= ~mask
                                    queue.append(('cell', r, c))
                                    changed = True

            if not changed:
                # Naked pairs in columns
                for c in range(N):
                    dom_to_rows = {}
                    for r in range(N):
                        d = doms[r][c]
                        if d.bit_count() == 2:
                            if d not in dom_to_rows:
                                dom_to_rows[d] = []
                            dom_to_rows[d].append(r)
                    for mask, rows in dom_to_rows.items():
                        if len(rows) >= 2:
                            for r in range(N):
                                if r not in rows and (doms[r][c] & mask):
                                    doms[r][c] &= ~mask
                                    queue.append(('cell', r, c))
                                    changed = True

            if not changed:
                break

        return True

    def is_solved(doms):
        """Check if all cells have exactly one value."""
        for r in range(N):
            for c in range(N):
                d = doms[r][c]
                if d & (d - 1):
                    return False
        return True

    def select_unassigned(doms):
        """Select cell with minimum remaining values (MRV heuristic)."""
        min_count = N + 1
        best = None
        for r in range(N):
            for c in range(N):
                d = doms[r][c]
                if d & (d - 1):  # not fixed
                    cnt = d.bit_count()
                    if cnt < min_count:
                        min_count = cnt
                        best = (r, c)
                        if cnt == 2:
                            return best
        return best

    def search(doms):
        """Backtracking search with constraint propagation."""
        # Make a copy to avoid modifying caller's state during propagation
        current = [row[:] for row in doms]

        if not propagate(current):
            return None

        if is_solved(current):
            return current

        cell = select_unassigned(current)
        if cell is None:
            return None
        r, c = cell
        d = current[r][c]

        # Try each possible value
        bits = []
        temp = d
        while temp:
            lsb = temp & -temp
            bits.append(lsb)
            temp ^= lsb

        for bit in bits:
            new_doms = [row[:] for row in current]
            new_doms[r][c] = bit
            result = search(new_doms)
            if result is not None:
                return result
        return None

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    if is_solved(domains):
        solution = domains
    else:
        solution = search(domains)

    if solution is None:
        return "No Solution"

    # Convert bitmasks back to values
    result = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(solution[r][c].bit_length())
        result.append(row)
    return result

