    # Check if all white cells are connected using BFS
    def check_connectivity():
        white_cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 2]
        if not white_cells:
            return True  # Or False? But usually puzzles have white cells.

        # BFS from first white cell
        visited = set()
        queue = [white_cells[0]]
        visited.add(white_cells[0])
        idx = 0
        while idx < len(queue):
            r, c = queue[idx]
            idx += 1
            for nr, nc in get_neighbors(r, c):
