                            grid[r][c] = 1
                            # Black cells force neighbors white
                            for nr, nc in get_neighbors(r, c):
                                if grid[nr][nc] == 0:
                                    grid[nr][nc] = 2
                                    if not check_white_valid(nr, nc):
                                        return False
                                    changed = True
                            changed = True

            # Rule 2: Black cells have white neighbors (already handled above)
            # Additional: check no two black adjacent (should be maintained by above)

            # Rule 3: Line constraint - checked when setting white
            # Rule 4: Connectivity - expensive, check at end or specific cases

            # Additional deduction for line constraint:
            # If a line has 3 consecutive cells with different regions, middle must be black or bounded
            # But we handle this via check_white_valid when cells are set.

            # Check for cells that are forced black to prevent line constraint violation
            # This is complex, skip for now and let backtracking handle it.

        return True

    # Check if solved and valid
    def is_valid_complete():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False  # Unknown cells

        # Check region counts
        for rid in range(len(region_cells)):
            if not region_cells[rid]:
                continue
            target = region_target[rid]
            if target is not None:
                black, _, _ = region_stats(rid)
                if black != target:
                    return False

        # Check black non-adjacent
        if not check_black_adjacent():
            return False

        # Check line constraints for all white segments
        # Rows
        for r in range(n):
            c = 0
            while c < n:
                if grid[r][c] == 2:
                    # Start of white segment
                    cells = [(r, c)]
                    cc = c + 1
                    while cc < n and grid[r][cc] == 2:
                        cells.append((r, cc))
                        cc += 1
                    if not check_segment_regions(cells):
