        # Cols
        for c in range(n):
            r = 0
            while r < n:
                if grid[r][c] == 2:
                    cells = [(r, c)]
                    rr = r + 1
                    while rr < n and grid[rr][c] == 2:
                        cells.append((rr, c))
                        rr += 1
                    if not check_segment_regions(cells):
