                    r = rr
                else:
                    r += 1

        # Check connectivity
        if not check_connectivity():
            return False

        return True

    # Backtracking with MRV
    def solve_recursive():
        # Propagate constraints
        if not propagate():
            return False

        # Check if complete
        if all(grid[r][c] != 0 for r in range(n) for c in range(n)):
            return is_valid_complete()

        # Find best cell to branch: one with most constrained region
        best_cell = None
        best_score = float('inf')

        # Heuristic: prioritize regions with few unknowns relative to remaining blacks needed
        for rid in range(len(region_cells)):
            if not region_cells[rid]:
                continue
            target = region_target[rid]
            if target is None:
                continue
            black, white, unknown = region_stats(rid)
            if unknown == 0:
                continue
            remaining = target - black
            if remaining < 0 or remaining > unknown:
                continue  # Should have been caught

            # Score: smaller unknown space is better
            score = unknown - remaining  # Number that must be white

            for r, c in region_cells[rid]:
                if grid[r][c] == 0:
                    # Prefer cells in tight regions
                    if unknown < best_score:
                        best_score = unknown
                        best_cell = (r, c)

        if best_cell is None:
            # Pick any unknown
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == 0:
                        best_cell = (r, c)
                        break
                if best_cell:
                    break

        if best_cell is None:
            return is_valid_complete()

        r, c = best_cell

        # Try Black
        grid[r][c] = 1
        # Save state
        saved = [row[:] for row in grid]
        # Check immediate black adjacency
        valid = True
        for nr, nc in get_neighbors(r, c):
            if grid[nr][nc] == 1:
                valid = False
                break
        if valid:
            # Propagate neighbors to white
            changed_any = False
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == 0:
                    grid[nr][nc] = 2
                    changed_any = True
                    if not check_white_valid(nr, nc):
                        valid = False
                        break

            if valid and solve_recursive():
                return True

        # Restore and Try White
        for i in range(n):
            for j in range(n):
                grid[i][j] = saved[i][j]

        grid[r][c] = 2
        if not check_white_valid(r, c):
            return False

        if solve_recursive():
            return True

        return False

    if solve_recursive():
        # Convert to output format
        result = []
        for r in range(n):
            row = []
            for c in range(n):
                if grid[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    else:
        return "No Solution"

