def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n > 0 else 0

    UNKNOWN = 0
    WHITE = 1
    BLACK = 2

    # Initialize grid
    grid = [[UNKNOWN for _ in range(m)] for _ in range(n)]
    clues = []

    for r in range(n):
        for c in range(m):
            if data[r][c] is not None:
                grid[r][c] = WHITE
                clues.append((r, c, data[r][c]))

    def get_direction_cells(r, c, dr, dc):
        """Get list of cells in direction (dr, dc) from (r,c), excluding (r,c)."""
        cells = []
        nr, nc = r + dr, c + dc
        while 0 <= nr < n and 0 <= nc < m:
            cells.append((nr, nc))
            nr += dr
            nc += dc
        return cells

    def get_four_directions(r, c):
        """Return list of 4 direction cell lists."""
        return [
            get_direction_cells(r, c, -1, 0),  # up
            get_direction_cells(r, c, 1, 0),   # down
            get_direction_cells(r, c, 0, -1),  # left
            get_direction_cells(r, c, 0, 1)    # right
        ]

    def compute_min_max(grid, r, c):
        """
        Compute min and max visibility for each direction from (r,c).
        min_v: number of leading WHITE cells (forced visible).
        max_v: number of cells until first BLACK (maximum possible visible).
        """
        directions = get_four_directions(r, c)
        min_vs = []
        max_vs = []

        for cells in directions:
            # min_v: consecutive WHITE cells from start
            min_v = 0
            for (cr, cc) in cells:
                if grid[cr][cc] == WHITE:
                    min_v += 1
                else:
                    break

            # max_v: cells until first BLACK
            max_v = 0
            for (cr, cc) in cells:
                if grid[cr][cc] == BLACK:
                    break
                max_v += 1

            min_vs.append(min_v)
            max_vs.append(max_v)

        return min_vs, max_vs

    def propagate(grid):
        """
        Apply constraint propagation.
        Returns (success, changed_flag).
        Modifies grid in place.
        """
        changed = True
        iterations = 0
        max_iter = 100  # safety limit

        while changed and iterations < max_iter:
            changed = False
            iterations += 1

            # Check black cell adjacency and force constraints
            for r in range(n):
                for c in range(m):
                    if grid[r][c] == BLACK:
                        # Check no adjacent black
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < m:
                                if grid[nr][nc] == BLACK:
                                    return False, False

            # Propagate from clues
            for r, c, val in clues:
                target = val - 1  # cells visible in 4 directions (excluding clue itself)
                min_vs, max_vs = compute_min_max(grid, r, c)
                total_min = sum(min_vs)
                total_max = sum(max_vs)

                # Check bounds
                if total_min > target or total_max < target:
                    return False, False

                directions = get_four_directions(r, c)

                # Case: must use minimum everywhere
                if total_min == target:
                    for i, cells in enumerate(directions):
                        k = min_vs[i]
                        # Cell at position k must be BLACK to block
                        if k < len(cells):
                            br, bc = cells[k]
                            if grid[br][bc] == UNKNOWN:
                                grid[br][bc] = BLACK
                                changed = True
                            elif grid[br][bc] == WHITE:
                                return False, False  # contradiction

                # Case: must use maximum everywhere
                if total_max == target:
                    for i, cells in enumerate(directions):
                        k = max_vs[i]
                        # Cells 0..k-1 must be WHITE
                        for j in range(k):
                            wr, wc = cells[j]
                            if grid[wr][wc] == UNKNOWN:
                                grid[wr][wc] = WHITE
                                changed = True
                            elif grid[wr][wc] == BLACK:
                                return False, False  # contradiction
                        # Cell k must be BLACK (to block further)
                        if k < len(cells):
                            br, bc = cells[k]
                            if grid[br][bc] == UNKNOWN:
                                grid[br][bc] = BLACK
                                changed = True
                            elif grid[br][bc] == WHITE:
                                return False, False  # contradiction

        return True, True

    def is_complete(grid):
        for r in range(n):
            for c in range(m):
                if grid[r][c] == UNKNOWN:
                    return False
        return True

    def check_solution(grid):
        """Validate complete solution."""
        # Check black cells not adjacent
        for r in range(n):
            for c in range(m):
                if grid[r][c] == BLACK:
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == BLACK:
                            return False

        # Check clue values
        for r, c, val in clues:
            count = 1  # clue cell itself
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                while 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == WHITE:
                    count += 1
                    nr += dr
                    nc += dc
            if count != val:
                return False

        # Check white connectivity
        white_cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == WHITE]
        if not white_cells:
            return False

        visited = [[False] * m for _ in range(n)]
        stack = [white_cells[0]]
        visited[white_cells[0][0]][white_cells[0][1]] = True
        count = 0

        while stack:
            cr, cc = stack.pop()
            count += 1
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == WHITE and not visited[nr][nc]:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

        return count == len(white_cells)

    # Initial propagation
    ok, _ = propagate(grid)
    if not ok:
        return "No Solution"

    # Backtracking with MRV heuristic
    def backtrack(grid):
        # Already propagated at entry

        if is_complete(grid):
            return grid if check_solution(grid) else None

        # Find unknown cell with highest constraint (fewest valid options)
        # Simple: find first unknown
        candidates = []
        for r in range(n):
            for c in range(m):
                if grid[r][c] == UNKNOWN:
                    candidates.append((r, c))

        if not candidates:
            return None

        # Pick first candidate (could optimize with heuristic)
        r, c = candidates[0]

        # Try BLACK first (more constrained usually)
        for val in [BLACK, WHITE]:
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val
            ok, _ = propagate(new_grid)
            if ok:
                result = backtrack(new_grid)
                if result is not None:
                    return result

        return None

    solution_grid = backtrack(grid)

    if solution_grid is None:
        return "No Solution"

    # Format result
    result = [[None for _ in range(m)] for _ in range(n)]
    for r in range(n):
        for c in range(m):
            if data[r][c] is not None:
                result[r][c] = data[r][c]
            elif solution_grid[r][c] == BLACK:
                result[r][c] = 'B'
            else:
                result[r][c] = None

    return result

