def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)
    all_nums = set(range(1, N + 1))

    from itertools import permutations

    def visible_left(seq):
        """Count visible buildings from left to right."""
        count = 0
        max_h = 0
        for h in seq:
            if h > max_h:
                count += 1
                max_h = h
        return count

    def visible_start(seq, start_max):
        """Count visible with initial max_height."""
        count = 0
        m = start_max
        for h in seq:
            if h > m:
                count += 1
                m = h
        return count

    # Precompute valid permutations for each row based on L and R clues
    row_candidates = []
    for i in range(N):
        l_clue, r_clue = L[i], R[i]
        valid = []
        for perm in permutations(range(1, N + 1)):
            if visible_left(perm) == l_clue and visible_left(perm[::-1]) == r_clue:
                valid.append(perm)
        if not valid:
            return "No Solution"
        row_candidates.append(valid)

    # Order rows by number of candidates (most constrained first)
    order = sorted(range(N), key=lambda i: len(row_candidates[i]))
    candidates_ordered = [row_candidates[i] for i in order]

    # Inverse mapping to restore original order
    inv_order = [0] * N
    for pos, orig in enumerate(order):
        inv_order[orig] = pos

    solution = [None] * N

    def is_valid_partial(k):
        """Check if first k rows satisfy column constraints (uniqueness and bounds)."""
        for j in range(N):
            # Extract column j from first k rows
            col = [solution[i][j] for i in range(k)]

            # Check uniqueness
            if len(set(col)) != len(col):
                return False

            S = set(col)
            T = all_nums - S

            # Check Upper clue (U[j])
            c = visible_left(col)
            if N in S:
                min_U = c
            else:
                min_U = c + 1
            max_U = visible_left(col + sorted(T))
            if not (min_U <= U[j] <= max_U):
                return False

            # Check Down clue (D[j])
            col_rev = col[::-1]  # Reverse for bottom-up view
            max_T_val = max(T) if T else 0
            base_D = visible_start(col_rev, max_T_val)

            if not T:
                min_D = base_D
                max_D = base_D
            else:
                min_D = 1 + base_D
                max_D = len(T) + base_D

            if not (min_D <= D[j] <= max_D):
                return False

        return True

    def backtrack(pos):
        if pos == N:
            # Final verification of all constraints
            for j in range(N):
                col = [solution[i][j] for i in range(N)]
                if visible_left(col) != U[j]:
                    return False
                if visible_left(col[::-1]) != D[j]:
                    return False
            return True

        for cand in candidates_ordered[pos]:
            solution[pos] = cand
            if is_valid_partial(pos + 1):
                if backtrack(pos + 1):
                    return True
            solution[pos] = None
        return False

    if backtrack(0):
        # Restore original row order
        result = [solution[inv_order[i]] for i in range(N)]
        return [list(row) for row in result]
    else:
        return "No Solution"

