                for c in range(m):
                    if grid[r][c] == 2:
                        for nr, nc in get_neighbors(r, c):
                            if grid[nr][nc] == 2:
                                return False
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 1
                                changed = True

            # Rule 3: Line constraint propagation
            # For each unknown cell, check if making it white creates >2 regions in segment
            for r in range(n):
                for c in range(m):
                    if grid[r][c] != 0:
                        continue
                    # Check row
                    # Find current segment bounds in row r
                    left = c - 1
                    while left >= 0 and grid[r][left] != 2:
                        left -= 1
                    left += 1
                    right = c + 1
                    while right < m and grid[r][right] != 2:
                        right += 1
                    right -= 1
                    # Collect regions in segment assuming (r,c) is white
                    seg_regions = set()
                    seg_regions.add(region_map[r][c])
                    for cc in range(left, right + 1):
                        if cc == c:
                            continue
                        if grid[r][cc] == 0:
                            # Unknown - we don't know yet
                            pass
                        elif grid[r][cc] == 1:
                            seg_regions.add(region_map[r][cc])
                    # If we already have > 2 regions in the definite part, and we're adding this white...
                    # Actually, check: if the definite white cells plus this cell span >2 regions, must be black
                    # But unknown cells in between might be black, breaking the segment.
                    # So we need to check the continuous run of white/unknown that would become white.
                    pass  # Skip for now, handle in search with forward checking

            # Check line constraint for current definite whites
            if not check_partial_line_constraint():
                return False

        return True

    def check_white_connectivity():
        """BFS to check all white cells are connected"""
        start = None
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    start = (r, c)
                    break
            if start:
                break

        if not start:
            return False  # No white cells

        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        # Count all white cells
        white_count = sum(row.count(1) for row in grid)
        return len(visited) == white_count

    def solve_recursive():
        # Propagate constraints
        if not propagate():
            return False

        # Check if solved
        unknown_count = sum(row.count(0) for row in grid)
        if unknown_count == 0:
            return check_white_connectivity()

        # Find most constrained unknown cell
        # Priority: cell in region with least unknowns, or cell where line constraint is tight
        best_cell = None
        best_score = float('inf')

        for r in range(n):
            for c in range(m):
                if grid[r][c] != 0:
                    continue
                rid = region_map[r][c]
                clue = region_clue.get(rid)
                black, white, unkn, total = count_region_state(rid)

                # Score: prefer cells in constrained regions
                score = unkn * 10
                if clue is not None:
                    remaining = clue - black
                    if remaining == 0:
                        score -= 100  # Must be white
                    elif remaining == unkn:
                        score -= 50  # Must be black

                # Prefer cells near black cells (forced white) or in long runs
                if score < best_score:
                    best_score = score
                    best_cell = (r, c)

        if not best_cell:
            return False

        r, c = best_cell

        # Try Black
        if is_valid_black_placement(r, c):
            old_grid = [row[:] for row in grid]
            grid[r][c] = 2
            if solve_recursive():
                return True
            # Restore
            for i in range(n):
                for j in range(m):
                    grid[i][j] = old_grid[i][j]

        # Try White
        grid[r][c] = 1
        # Quick line constraint check
        if check_partial_line_constraint():
            old_grid = [row[:] for row in grid]
            if solve_recursive():
                return True
            for i in range(n):
                for j in range(m):
                    grid[i][j] = old_grid[i][j]
        else:
            grid[r][c] = 0

        return False

    # Initialize: set known cells from single-cell regions or obvious constraints
    for rid in region_cells:
        if rid in region_clue:
            clue = region_clue[rid]
            cells = region_cells[rid]
            if len(cells) == clue:
                # All black
                for (r, c) in cells:
                    grid[r][c] = 2
            elif clue == 0:
                # All white
                for (r, c) in cells:
                    grid[r][c] = 1

    if solve_recursive():
        # Convert to output format
        result = [[None for _ in range(m)] for _ in range(n)]
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 2:
                    result[r][c] = 'B'
                else:
                    result[r][c] = None
        return result
    else:
        return "No Solution"

