def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']

    n = len(data)

    # Parse horizontal constraints: (r, c) op (r, c+1)
    h_cons = {}
    for key, val in horizontal.items():
        s = key.strip()
        if s.startswith('(') and s.endswith(')'):
            s = s[1:-1]
        parts = [p.strip() for p in s.split(',')]
        r = int(float(parts[0]))
        c = float(parts[1])
        col = int(c - 0.5)
        h_cons[(r, col)] = val  # '<' or '>'

    # Parse vertical constraints: (r, c) op (r+1, c)
    v_cons = {}
    for key, val in vertical.items():
        s = key.strip()
        if s.startswith('(') and s.endswith(')'):
            s = s[1:-1]
        parts = [p.strip() for p in s.split(',')]
        r = float(parts[0])
        c = int(float(parts[1]))
        row = int(r - 0.5)
        v_cons[(row, c)] = val  # '^' or 'v'

    # Initialize domains
    domains = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def copy_domains(dom):
        return [[set(d) for d in row] for row in dom]

    def propagate(dom):
        # Returns False if inconsistency detected, True otherwise
        changed = True
        while changed:
            changed = False

            # Row constraints: uniqueness
            for r in range(n):
                fixed_vals = []
                for c in range(n):
                    if len(dom[r][c]) == 1:
                        fixed_vals.append((c, next(iter(dom[r][c]))))
                for c, val in fixed_vals:
                    for cc in range(n):
                        if cc != c and val in dom[r][cc]:
                            dom[r][cc].remove(val)
                            changed = True
                            if not dom[r][cc]:
                                return False

            # Column constraints: uniqueness
            for c in range(n):
                fixed_vals = []
                for r in range(n):
                    if len(dom[r][c]) == 1:
                        fixed_vals.append((r, next(iter(dom[r][c]))))
                for r, val in fixed_vals:
                    for rr in range(n):
                        if rr != r and val in dom[rr][c]:
                            dom[rr][c].remove(val)
                            changed = True
                            if not dom[rr][c]:
                                return False

            # Horizontal inequality constraints
            for (r, c), op in h_cons.items():
                dom1 = dom[r][c]
                dom2 = dom[r][c+1]

                if op == '<':
                    # dom1 values must be < some value in dom2
                    max2 = max(dom2)
                    to_remove = [v for v in dom1 if v >= max2]
                    if to_remove:
                        for v in to_remove:
                            dom1.remove(v)
                        changed = True
                        if not dom1:
                            return False

                    # dom2 values must be > some value in dom1
                    min1 = min(dom1)
                    to_remove = [v for v in dom2 if v <= min1]
                    if to_remove:
                        for v in to_remove:
                            dom2.remove(v)
                        changed = True
                        if not dom2:
                            return False

                elif op == '>':
                    # dom1 values must be > some value in dom2
                    min2 = min(dom2)
                    to_remove = [v for v in dom1 if v <= min2]
                    if to_remove:
                        for v in to_remove:
                            dom1.remove(v)
                        changed = True
                        if not dom1:
                            return False

                    # dom2 values must be < some value in dom1
                    max1 = max(dom1)
                    to_remove = [v for v in dom2 if v >= max1]
                    if to_remove:
                        for v in to_remove:
                            dom2.remove(v)
                        changed = True
                        if not dom2:
                            return False

            # Vertical inequality constraints
            for (r, c), op in v_cons.items():
                dom1 = dom[r][c]
                dom2 = dom[r+1][c]

                if op == '^':
                    # '^' points up, so upper (dom1) is smaller: dom1 < dom2
                    max2 = max(dom2)
                    to_remove = [v for v in dom1 if v >= max2]
                    if to_remove:
                        for v in to_remove:
                            dom1.remove(v)
                        changed = True
                        if not dom1:
                            return False

                    min1 = min(dom1)
                    to_remove = [v for v in dom2 if v <= min1]
                    if to_remove:
                        for v in to_remove:
                            dom2.remove(v)
                        changed = True
                        if not dom2:
                            return False

                elif op == 'v':
                    # 'v' points down, so lower (dom2) is smaller: dom1 > dom2
                    min2 = min(dom2)
                    to_remove = [v for v in dom1 if v <= min2]
                    if to_remove:
                        for v in to_remove:
                            dom1.remove(v)
                        changed = True
                        if not dom1:
                            return False

                    max1 = max(dom1)
                    to_remove = [v for v in dom2 if v >= max1]
                    if to_remove:
                        for v in to_remove:
                            dom2.remove(v)
                        changed = True
                        if not dom2:
                            return False

            # Hidden singles in rows
            for r in range(n):
                for val in range(1, n+1):
                    positions = [c for c in range(n) if val in dom[r][c]]
                    if len(positions) == 1:
                        c = positions[0]
                        if len(dom[r][c]) > 1:
                            dom[r][c] = {val}
                            changed = True

            # Hidden singles in columns
            for c in range(n):
                for val in range(1, n+1):
                    positions = [r for r in range(n) if val in dom[r][c]]
                    if len(positions) == 1:
                        r = positions[0]
                        if len(dom[r][c]) > 1:
                            dom[r][c] = {val}
                            changed = True

        return True

    def is_solved(dom):
        for r in range(n):
            for c in range(n):
                if len(dom[r][c]) != 1:
                    return False
        return True

    def select_unassigned_variable(dom):
        # MRV heuristic: select variable with smallest domain > 1
        min_size = n + 1
        min_r, min_c = -1, -1
        for r in range(n):
            for c in range(n):
                size = len(dom[r][c])
                if size > 1 and size < min_size:
                    min_size = size
                    min_r, min_c = r, c
        return min_r, min_c

    def search(dom):
        if not propagate(dom):
            return None

        if is_solved(dom):
            return [[next(iter(dom[r][c])) for c in range(n)] for r in range(n)]

        r, c = select_unassigned_variable(dom)
        if r == -1:
            return None

        values = sorted(dom[r][c])
        for val in values:
            new_dom = copy_domains(dom)
            new_dom[r][c] = {val}
            result = search(new_dom)
            if result is not None:
                return result

        return None

    result = search(domains)
    return result if result is not None else "No Solution"

