                        grid[r][c] = 'B'
                        changed = True

            # Rule 3: Adjacent constraint propagation
            # Horizontal
            for (r, c), typ in h_cons.items():
                left, right = grid[r][c], grid[r][c+1]
                if left is not None and right is None:
                    grid[r][c+1] = left if typ == '=' else ('W' if left == 'B' else 'B')
                    changed = True
                elif right is not None and left is None:
                    grid[r][c] = right if typ == '=' else ('W' if right == 'B' else 'B')
                    changed = True

            # Vertical
            for (r, c), typ in v_cons.items():
                top, bottom = grid[r][c], grid[r+1][c]
                if top is not None and bottom is None:
                    grid[r+1][c] = top if typ == '=' else ('W' if top == 'B' else 'B')
                    changed = True
                elif bottom is not None and top is None:
                    grid[r][c] = bottom if typ == '=' else ('W' if bottom == 'B' else 'B')
                    changed = True

            if not is_valid():
                return False

        return True

    def solve_recursive():
        if is_complete():
            return True

        # Find empty cell with propagation
        # Use heuristic: try cells that are most constrained
        best_cell = None
        min_options = 3

        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    options = []
                    for val in ['B', 'W']:
                        grid[r][c] = val
                        if is_valid():
                            options.append(val)
                        grid[r][c] = None

                    if len(options) == 0:
                        return False
                    if len(options) < min_options:
                        min_options = len(options)
                        best_cell = (r, c)
                        if min_options == 1:
                            break
            if min_options == 1:
                break

        if best_cell is None:
            return is_complete()

        r, c = best_cell
        for val in ['B', 'W']:
            grid[r][c] = val
            if is_valid():
                saved = [row[:] for row in grid]
                if deduce():
                    if solve_recursive():
                        return True
                # Restore
                for i in range(n):
                    for j in range(n):
                        grid[i][j] = saved[i][j]
            grid[r][c] = None

        return False

    # Initial deduction
    if not deduce():
        return None

    if solve_recursive():
        return grid
    else:
        return None

