                            grid[r][c] = 2
                            changed = True

            # Rule 2: Black cells cannot touch orthogonally
            for r in range(n):
                for c in range(m):
                    if grid[r][c] == 2:
                        for nr, nc in get_neighbors(r, c):
                            if grid[nr][nc] == 2:
                                return False
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 1
                                changed = True

            # Rule 3: Line segment constraint (3 consecutive blocks)
            # Check rows
            for r in range(n):
                blocks = row_blocks[r]
                for i in range(len(blocks) - 2):
                    # Window of 3 consecutive blocks
                    b1, b2, b3 = blocks[i], blocks[i+1], blocks[i+2]
                    # Collect cells in these blocks
                    cells_in_window = []
                    for c in range(b1[1], b1[2]+1):
                        cells_in_window.append((r, c))
                    for c in range(b2[1], b2[2]+1):
                        cells_in_window.append((r, c))
                    for c in range(b3[1], b3[2]+1):
                        cells_in_window.append((r, c))

                    # Check if any is black
                    has_black = False
                    unknown_in_window = []
                    for cr, cc in cells_in_window:
                        if grid[cr][cc] == 2:
                            has_black = True
                            break
                        elif grid[cr][cc] == 0:
                            unknown_in_window.append((cr, cc))

                    if not has_black:
                        if len(unknown_in_window) == 0:
                            # All white, spans 3 regions - violation
                            return False
                        elif len(unknown_in_window) == 1:
                            # Must be black to break the segment
                            cr, cc = unknown_in_window[0]
                            grid[cr][cc] = 2
                            changed = True

            # Check columns
            for c in range(m):
                blocks = col_blocks[c]
                for i in range(len(blocks) - 2):
                    b1, b2, b3 = blocks[i], blocks[i+1], blocks[i+2]
                    cells_in_window = []
                    for r in range(b1[1], b1[2]+1):
                        cells_in_window.append((r, c))
                    for r in range(b2[1], b2[2]+1):
                        cells_in_window.append((r, c))
                    for r in range(b3[1], b3[2]+1):
                        cells_in_window.append((r, c))

                    has_black = False
                    unknown_in_window = []
                    for cr, cc in cells_in_window:
                        if grid[cr][cc] == 2:
                            has_black = True
                            break
                        elif grid[cr][cc] == 0:
                            unknown_in_window.append((cr, cc))

                    if not has_black:
                        if len(unknown_in_window) == 0:
                            return False
                        elif len(unknown_in_window) == 1:
                            cr, cc = unknown_in_window[0]
                            grid[cr][cc] = 2
                            changed = True

        return True

    def check_connectivity():
        """Check if all white cells are connected"""
        # Find first white cell
        start = None
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    start = (r, c)
                    break
            if start:
                break

        if start is None:
            # No white cells yet - acceptable
            return True

        # BFS
        visited = set()
        queue = [start]
        visited.add(start)
        count = 0

        while queue:
            r, c = queue.pop(0)
            count += 1
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        # Count total white cells
        total_white = sum(1 for r in range(n) for c in range(m) if grid[r][c] == 1)
        return count == total_white

    def check_complete():
        """Check if solution is complete and valid"""
        # All cells assigned
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 0:
                    return False

        # Check regions
        for rid, cells in region_cells.items():
            if rid in region_clue:
                black_count = sum(1 for r, c in cells if grid[r][c] == 2)
                if black_count != region_clue[rid]:
                    return False

        # Check black adjacency
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 2:
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] == 2:
                            return False

        # Check connectivity
        if not check_connectivity():
            return False

        return True

    def dfs():
        if not propagate():
            return False

        if all(grid[r][c] != 0 for r in range(n) for c in range(m)):
            return check_complete()

        # Find best cell to branch (most constrained)
        # Priority: cells in small regions, or cells that affect line constraints
        best_cell = None
        best_score = -1

        for r in range(n):
            for c in range(m):
                if grid[r][c] == 0:
                    rid = region_map[r][c]
                    clue = region_clue.get(rid)
                    cells_in_region = len(region_cells[rid])
                    # Score by constraint tightness
                    score = 100 - cells_in_region
                    if best_cell is None or score > best_score:
                        best_cell = (r, c)
                        best_score = score

        if best_cell is None:
            return check_complete()

        r, c = best_cell

        # Try white first (usually more constrained)
        for val in [1, 2]:
            grid[r][c] = val
            old_grid = [row[:] for row in grid]

            if propagate():
                if dfs():
                    return True

            # Restore
            for i in range(n):
                for j in range(m):
                    grid[i][j] = old_grid[i][j]

        grid[r][c] = 0
        return False

    if dfs():
        result = [[None if grid[r][c] == 1 else 'B' for c in range(m)] for r in range(n)]
        return result
    else:
        return "No Solution"

