            # Hidden singles: if a value appears in only one cell in a unit (row/col/region), assign it
            # Check rows
            for r in range(n):
                for val in range(1, n + 1):
                    possible_cells = [(r, c) for c in range(n) if val in domains[(r, c)]]
                    if len(possible_cells) == 0:
