        # Select variable
        cell = select_unassigned_variable(domains)
        if cell is None:
            return None

        (r, c) = cell
        values = list(domains[cell])

        # Try values (least constraining value heuristic)
        # Sort by how many options they eliminate
        def count_removals(val):
            count = 0
            for (pr, pc) in peers[cell]:
                if val in domains[(pr, pc)] and len(domains[(pr, pc)]) == 1:
                    return float('inf')  # Conflict
                if val in domains[(pr, pc)]:
                    count += 1
            return count

        values.sort(key=count_removals)

        for val in values:
            new_domains = copy_domains(domains)
            new_domains[cell] = {val}

            if propagate(new_domains):
                result = search(new_domains)
                if result is not None:
                    return result

        return None

    result = search(domains)

    if result is None:
        return "No Solution"

    # Convert to grid
    grid = [[0 for _ in range(n)] for _ in range(n)]
    for (r, c), vals in result.items():
        grid[r][c] = next(iter(vals))

    return grid

