                        # u_idx separates white cells, must be white
                        r, c = vertices[u_idx]
                        if state[r][c] == BLACK:
                            return False  # Contradiction
                        if state[r][c] == UNKNOWN:
                            state[r][c] = WHITE
                            changed = True

            if not changed:
                break

        return True

    def is_solved(state):
        for r in range(n):
            for c in range(n):
                if state[r][c] == UNKNOWN:
                    return False
        return True

    def solve_recursive(state):
        # Make a copy
        new_state = [row[:] for row in state]

        if not propagate(new_state):
            return None

        if is_solved(new_state):
            return new_state

        # Find first undecided cell
        # Heuristic: prioritize cells in rows/cols with duplicates
        target = None
        for r in range(n):
            for c in range(n):
                if new_state[r][c] == UNKNOWN:
                    target = (r, c)
                    break
            if target:
                break

        if not target:
            return new_state

        r, c = target

        # Try WHITE first
        state_white = [row[:] for row in new_state]
        state_white[r][c] = WHITE
        result = solve_recursive(state_white)
        if result is not None:
            return result

        # Try BLACK
        state_black = [row[:] for row in new_state]
        state_black[r][c] = BLACK
        return solve_recursive(state_black)

    initial_state = [[UNKNOWN] * n for _ in range(n)]
    final_state = solve_recursive(initial_state)

    if final_state is None:
        return "No Solution"

    # Convert to output format
    result = []
    for r in range(n):
        row = []
        for c in range(n):
            if final_state[r][c] == BLACK:
                row.append('B')
            else:
                row.append(None)
        result.append(row)

    return result

