    print(solve(OBSERVATION))

OBSERVATION = {'U': [2, 0, 0, 1, 0, 6], 'D': [0, 0, 2, 2, 3, 0], 'L': [4, 0, 3, 0, 2, 0], 'R': [0, 0, 0, 0, 0, 0]}

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    def bit(v):
        return 1 << (v - 1)

    ALL = (1 << N) - 1

    # domains[r][c] represents possible values as bitmask
    domains = [[ALL for _ in range(N)] for _ in range(N)]

    # Apply clue-based constraints
    # U (top, looking down)
    for c in range(N):
        if U[c] == 1:
            domains[0][c] = bit(N)
        elif U[c] == N:
            for r in range(N):
                domains[r][c] = bit(r + 1)

    # D (bottom, looking up)
    for c in range(N):
        if D[c] == 1:
            domains[N-1][c] = bit(N)
        elif D[c] == N:
            for r in range(N):
                domains[r][c] = bit(N - r)

    # L (left, looking right)
    for r in range(N):
        if L[r] == 1:
            domains[r][0] = bit(N)
        elif L[r] == N:
            for c in range(N):
                domains[r][c] = bit(c + 1)

    # R (right, looking left)
    for r in range(N):
        if R[r] == 1:
            domains[r][N-1] = bit(N)
        elif R[r] == N:
            for c in range(N):
                domains[r][c] = bit(N - c)

    def count_bits(x):
        return x.bit_count()

    def get_values(mask):
        # Return list of values represented by mask
        vals = []
        v = 1
        while mask:
            if mask & 1:
                vals.append(v)
            mask >>= 1
            v += 1
        return vals

    def visible(line):
        """Count visible buildings from left"""
        count = 0
        max_h = 0
        for h in line:
            if h > max_h:
                count += 1
                max_h = h
        return count

    # Constraint propagation (AC-3 style with hidden singles)
    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Propagate fixed cells (naked singles)
            for r in range(N):
                for c in range(N):
                    if count_bits(dom[r][c]) == 1:
                        val_bit = dom[r][c]
                        val = val_bit.bit_length()

                        # Remove from row
                        for c2 in range(N):
                            if c2 != c and dom[r][c2] & val_bit:
                                dom[r][c2] &= ~val_bit
                                if dom[r][c2] == 0:
                                    return False
                                changed = True

                        # Remove from column
                        for r2 in range(N):
                            if r2 != r and dom[r2][c] & val_bit:
                                dom[r2][c] &= ~val_bit
                                if dom[r2][c] == 0:
                                    return False
                                changed = True

            # Hidden singles in rows
            for r in range(N):
                for v in range(1, N+1):
                    b = bit(v)
                    pos = -1
                    found = False
                    for c in range(N):
                        if dom[r][c] & b:
                            if found:
                                found = False
                                break
                            found = True
                            pos = c
                    if found and dom[r][pos] != b:
                        dom[r][pos] = b
                        changed = True
                    elif not found:
                        # Value has no place in this row
                        if any(dom[r][c] == b for c in range(N)):
                            # Already assigned elsewhere, ok
                            pass
                        else:
                            # Value must appear somewhere
                            all_covered = True
                            for c in range(N):
                                if dom[r][c] & b:
                                    all_covered = False
                                    break
                            if all_covered:
                                return False

            # Hidden singles in columns
            for c in range(N):
                for v in range(1, N+1):
                    b = bit(v)
                    pos = -1
                    found = False
                    for r in range(N):
                        if dom[r][c] & b:
                            if found:
                                found = False
                                break
                            found = True
                            pos = r
                    if found and dom[pos][c] != b:
                        dom[pos][c] = b
                        changed = True
                    elif not found:
                        # Check if value is eliminated from column
                        eliminated = True
                        for r in range(N):
                            if dom[r][c] & b:
                                eliminated = False
                                break
                        if eliminated:
                            return False

        return True

    # Check if completed grid satisfies all clues
    def verify_solution(grid):
        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if U[c] != 0 and visible(col) != U[c]:
                return False
            if D[c] != 0 and visible(col[::-1]) != D[c]:
                return False

        for r in range(N):
            row = grid[r]
            if L[r] != 0 and visible(row) != L[r]:
                return False
            if R[r] != 0 and visible(row[::-1]) != R[r]:
                return False

        return True

    # Check partial line against clue (basic bounds)
    def check_partial_line(dom_line, clue, reverse=False):
        """Check if a partially assigned line can still satisfy the clue"""
        if clue == 0:
            return True

        # Extract assigned values and track domains for unassigned
        line_vals = []
        unassigned_domains = []

        indices = range(N)
        if reverse:
            indices = range(N-1, -1, -1)

        for i in indices:
            mask = dom_line[i]
            if count_bits(mask) == 1:
                line_vals.append(mask.bit_length())
            else:
                line_vals.append(0)
                unassigned_domains.append(mask)

        # Simple checks
        assigned = [v for v in line_vals if v != 0]
        if len(assigned) == N:
            return visible(line_vals) == clue

        # If we can compute exact visibility range, do so
        # For efficiency with N=6, we use simple bounds

        # Current visible count and max
        vis = 0
        mx = 0
        for v in line_vals:
            if v > 0:
                if v > mx:
                    vis += 1
                    mx = v
            else:
                break  # Stop at first unknown for conservative estimate

        # Upper bound: assume all remaining are visible and increasing
        if vis + len(unassigned_domains) < clue:
            return False

        # Lower bound: need at least one value > mx for visibility to increase
        # Compute minimum possible final visibility
        all_vals = set(assigned)
        remaining_vals = set(range(1, N+1)) - all_vals

        if not remaining_vals:
            return vis == clue

        # Check if N is placed or can be placed after current position
        # This is complex, skip for now - just check if mx == N and vis != clue
        if mx == N and vis != clue:
            return False

        return True

    if not propagate(domains):
        return "No Solution"

    # Backtracking with MRV
    def backtrack(dom):
        # Find cell with minimum remaining values (MRV)
        min_options = N + 1
        best_r, best_c = -1, -1

        for r in range(N):
            for c in range(N):
                cnt = count_bits(dom[r][c])
                if cnt == 1:
                    continue
                if cnt < min_options:
                    min_options = cnt
                    best_r, best_c = r, c
                    if cnt == 2:  # Can't do better
                        pass

        if best_r == -1:
            # All cells assigned, extract solution
            grid = []
            for r in range(N):
                row = []
                for c in range(N):
                    row.append(dom[r][c].bit_length())
                grid.append(row)

            if verify_solution(grid):
                return grid
            return None

        r, c = best_r, best_c
        vals = get_values(dom[r][c])

        # Sort values: try extremes first (heuristic for skyscrapers)
        # Often 1, N, or values near clues are better
        vals.sort(key=lambda x: -(x == N) - (x == 1) - 0.5*(abs(x - N//2)))

        for v in vals:
            new_dom = [row[:] for row in dom]
            new_dom[r][c] = bit(v)

            if not propagate(new_dom):
                continue

            # Check row constraints if row is complete or nearly complete
            row_dom = new_dom[r]
            if not check_partial_line(row_dom, L[r], False):
                continue
            if not check_partial_line(row_dom, R[r], True):
                continue

            # Check column constraints
            col_dom = [new_dom[i][c] for i in range(N)]
            if not check_partial_line(col_dom, U[c], False):
                continue
            if not check_partial_line(col_dom, D[c], True):
                continue

            res = backtrack(new_dom)
            if res is not None:
                return res

        return None

    result = backtrack(domains)
    if result is None:
        return "No Solution"
    return result

