def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(data)

    # Build region to cells mapping
    regions = {}
    for r in range(n):
        for c in range(n):
            reg_id = region_map[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))

    # Initialize grid (0 = empty)
    grid = [[0] * n for _ in range(n)]

    # Candidates as bitmasks (bit i represents number i+1)
    all_mask = (1 << n) - 1
    candidates = [[all_mask for _ in range(n)] for _ in range(n)]

    # Apply givens
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                if not _set_cell(grid, candidates, regions, region_map, r, c, data[r][c], n):
                    return "No Solution"

    # Constraint propagation
    if not _propagate(grid, candidates, regions, region_map, n):
        return "No Solution"

    # Check if solved
    if _is_solved(grid, n):
        return grid

    # Backtracking with MRV
    result = _backtrack(grid, candidates, regions, region_map, n)
    if result is None:
        return "No Solution"
    return result

def _set_cell(grid, candidates, regions, region_map, r, c, val, n):
    """Set cell (r,c) to val and propagate constraints. Returns False if contradiction."""
    if grid[r][c] != 0:
        return grid[r][c] == val

    mask = 1 << (val - 1)
    if not (candidates[r][c] & mask):
        return False

    grid[r][c] = val
    candidates[r][c] = 0

    # Remove from row peers
    for cc in range(n):
        if cc != c and grid[r][cc] == 0:
            if not _remove_candidate(candidates, r, cc, val):
                return False

    # Remove from column peers
    for rr in range(n):
        if rr != r and grid[rr][c] == 0:
            if not _remove_candidate(candidates, rr, c, val):
                return False

    # Remove from region peers
    for (rr, cc) in regions[region_map[r][c]]:
        if (rr, cc) != (r, c) and grid[rr][cc] == 0:
            if not _remove_candidate(candidates, rr, cc, val):
                return False

    return True

def _remove_candidate(candidates, r, c, val):
    """Remove val from candidates of cell (r,c). Returns False if empty."""
    mask = 1 << (val - 1)
    if candidates[r][c] & mask:
        candidates[r][c] &= ~mask
        if candidates[r][c] == 0:
            return False
    return True

def _propagate(grid, candidates, regions, region_map, n):
    """Apply naked and hidden singles until fixed point. Returns False if contradiction."""
    changed = True
    while changed:
        changed = False

        # Naked singles
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    # Check if single candidate
                    cand = candidates[r][c]
                    if cand == 0:
                        return False
                    if cand & (cand - 1) == 0:  # Power of 2
                        val = cand.bit_length()
                        if not _set_cell(grid, candidates, regions, region_map, r, c, val, n):
                            return False
                        changed = True

        # Hidden singles in rows
        for r in range(n):
            for val in range(1, n + 1):
                mask = 1 << (val - 1)
                count = 0
                pos_c = -1
                for c in range(n):
                    if grid[r][c] == 0 and (candidates[r][c] & mask):
                        count += 1
                        pos_c = c
                        if count > 1:
                            break
                if count == 0:
                    # Check if val exists in row
                    found = False
                    for c in range(n):
                        if grid[r][c] == val:
                            found = True
                            break
                    if not found:
                        return False
                elif count == 1 and grid[r][pos_c] == 0:
                    if not _set_cell(grid, candidates, regions, region_map, r, pos_c, val, n):
                        return False
                    changed = True

        # Hidden singles in columns
        for c in range(n):
            for val in range(1, n + 1):
                mask = 1 << (val - 1)
                count = 0
                pos_r = -1
                for r in range(n):
                    if grid[r][c] == 0 and (candidates[r][c] & mask):
                        count += 1
                        pos_r = r
                        if count > 1:
                            break
                if count == 0:
                    found = False
                    for r in range(n):
                        if grid[r][c] == val:
                            found = True
                            break
                    if not found:
                        return False
                elif count == 1 and grid[pos_r][c] == 0:
                    if not _set_cell(grid, candidates, regions, region_map, pos_r, c, val, n):
                        return False
                    changed = True

        # Hidden singles in regions
        for reg_cells in regions.values():
            for val in range(1, n + 1):
                mask = 1 << (val - 1)
                count = 0
                pos = None
                for (r, c) in reg_cells:
                    if grid[r][c] == 0 and (candidates[r][c] & mask):
                        count += 1
                        pos = (r, c)
                        if count > 1:
                            break
                if count == 0:
                    found = False
                    for (r, c) in reg_cells:
                        if grid[r][c] == val:
                            found = True
                            break
                    if not found:
                        return False
                elif count == 1:
                    r, c = pos
                    if grid[r][c] == 0:
                        if not _set_cell(grid, candidates, regions, region_map, r, c, val, n):
                            return False
                        changed = True

    return True

def _is_solved(grid, n):
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                return False
    return True

def _backtrack(grid, candidates, regions, region_map, n):
    """Recursive backtracking with MRV heuristic."""
    if _is_solved(grid, n):
        return [row[:] for row in grid]

    # Find cell with minimum remaining values
    min_r, min_c = -1, -1
    min_options = n + 1
    min_mask = 0

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                cnt = bin(candidates[r][c]).count('1')
                if cnt < min_options:
                    min_options = cnt
                    min_r, min_c = r, c
                    min_mask = candidates[r][c]
                    if cnt == 1:
                        break
        if min_options == 1:
            break

    if min_options == 0:
        return None

    # Try each candidate value
    for val in range(1, n + 1):
        mask = 1 << (val - 1)
        if min_mask & mask:
            # Save state
            grid_save = [row[:] for row in grid]
            cand_save = [row[:] for row in candidates]

            if _set_cell(grid, candidates, regions, region_map, min_r, min_c, val, n):
                if _propagate(grid, candidates, regions, region_map, n):
                    result = _backtrack(grid, candidates, regions, region_map, n)
                    if result is not None:
                        return result

            # Restore state
            for i in range(n):
                grid[i][:] = grid_save[i]
                candidates[i][:] = cand_save[i]

    return None

