def solve(observation):
    """Solve the binary puzzle using constraint propagation and backtracking."""
    import ast

    data = observation['data']
    n = len(data)
    m = len(data[0]) if n > 0 else 0
    target = m // 2  # Each row/col needs target B's and target W's

    # Initialize grid: None for unknown, 'B' or 'W' for known
    grid = [[None for _ in range(m)] for _ in range(n)]

    # Set fixed cells
    for i in range(n):
        for j in range(m):
            if data[i][j] is not None:
                grid[i][j] = data[i][j]

    # Parse constraints into dictionaries for O(1) lookup
    # horiz[(r,c)] = constraint between (r,c) and (r,c+1)
    horiz = {}
    for key, val in observation.get('horizontal', {}).items():
        # Parse string like '(0, 2.5)' -> (0, 2) means between col 2 and 3
        try:
            r, c = ast.literal_eval(key)
            horiz[(int(r), int(c))] = val
        except:
            continue

    # vert[(r,c)] = constraint between (r,c) and (r+1,c)
    vert = {}
    for key, val in observation.get('vertical', {}).items():
        try:
            r, c = ast.literal_eval(key)
            vert[(int(r), int(c))] = val
        except:
            continue

    def get_other_color(c):
        return 'W' if c == 'B' else 'B'

    def propagate():
        """Apply constraint propagation. Return True if consistent, False if contradiction."""
        changed = True
        while changed:
            changed = False

            # Check each row and column for completion
            for i in range(n):
                b_count = sum(1 for j in range(m) if grid[i][j] == 'B')
                w_count = sum(1 for j in range(m) if grid[i][j] == 'W')

                if b_count > target or w_count > target:
                    return False

                if b_count == target:
                    # Fill rest with W
                    for j in range(m):
                        if grid[i][j] is None:
                            grid[i][j] = 'W'
                            changed = True
                        elif grid[i][j] == 'B':
                            pass
                elif w_count == target:
                    for j in range(m):
                        if grid[i][j] is None:
                            grid[i][j] = 'B'
                            changed = True

            for j in range(m):
                b_count = sum(1 for i in range(n) if grid[i][j] == 'B')
                w_count = sum(1 for i in range(n) if grid[i][j] == 'W')

                if b_count > target or w_count > target:
                    return False

                if b_count == target:
                    for i in range(n):
                        if grid[i][j] is None:
                            grid[i][j] = 'W'
                            changed = True
                elif w_count == target:
                    for i in range(n):
                        if grid[i][j] is None:
                            grid[i][j] = 'B'
                            changed = True

            # Check no-three-consecutive rule
            for i in range(n):
                for j in range(m):
                    if grid[i][j] is not None:
                        c = grid[i][j]
                        oc = get_other_color(c)

                        # Horizontal: check j-2, j-1, j
                        if j >= 2 and grid[i][j-1] == c and grid[i][j-2] == c:
                            return False

                        # Horizontal: if j-1 and j are c, then j+1 must be oc
                        if j >= 1 and j < m-1 and grid[i][j-1] == c:
                            if grid[i][j+1] is None:
                                grid[i][j+1] = oc
                                changed = True
                            elif grid[i][j+1] == c:
                                return False

                        # Horizontal: if j and j+1 are c, then j+2 and j-1 must be oc
                        if j < m-1 and grid[i][j+1] == c:
                            if j+2 < m:
                                if grid[i][j+2] is None:
                                    grid[i][j+2] = oc
                                    changed = True
                                elif grid[i][j+2] == c:
                                    return False
                            if j-1 >= 0:
                                if grid[i][j-1] is None:
                                    grid[i][j-1] = oc
                                    changed = True
                                elif grid[i][j-1] == c:
                                    return False

                        # Horizontal: if j-1 and j+1 are c, then j must be oc
                        if j > 0 and j < m-1 and grid[i][j-1] == c and grid[i][j+1] == c:
                            if grid[i][j] != oc:
                                return False

                        # Vertical: similar logic
                        if i >= 2 and grid[i-1][j] == c and grid[i-2][j] == c:
                            return False

                        if i >= 1 and i < n-1 and grid[i-1][j] == c:
                            if grid[i+1][j] is None:
                                grid[i+1][j] = oc
                                changed = True
                            elif grid[i+1][j] == c:
                                return False

                        if i < n-1 and grid[i+1][j] == c:
                            if i+2 < n:
                                if grid[i+2][j] is None:
                                    grid[i+2][j] = oc
                                    changed = True
                                elif grid[i+2][j] == c:
                                    return False
                            if i-1 >= 0:
                                if grid[i-1][j] is None:
                                    grid[i-1][j] = oc
                                    changed = True
                                elif grid[i-1][j] == c:
                                    return False

                        if i > 0 and i < n-1 and grid[i-1][j] == c and grid[i+1][j] == c:
                            if grid[i][j] != oc:
                                return False

            # Process adjacent constraints
            # Horizontal constraints
            for (i, j), cons in horiz.items():
                if j < 0 or j >= m-1 or i < 0 or i >= n:
                    continue
                left, right = grid[i][j], grid[i][j+1]

                if cons == '=':
                    if left is not None and right is None:
                        grid[i][j+1] = left
                        changed = True
                    elif right is not None and left is None:
                        grid[i][j] = right
                        changed = True
                    elif left is not None and right is not None and left != right:
                        return False
                elif cons == 'x':
                    if left is not None and right is None:
                        grid[i][j+1] = get_other_color(left)
                        changed = True
                    elif right is not None and left is None:
                        grid[i][j] = get_other_color(right)
                        changed = True
                    elif left is not None and right is not None and left == right:
                        return False

            # Vertical constraints
            for (i, j), cons in vert.items():
                if i < 0 or i >= n-1 or j < 0 or j >= m:
                    continue
                up, down = grid[i][j], grid[i+1][j]

                if cons == '=':
                    if up is not None and down is None:
                        grid[i+1][j] = up
                        changed = True
                    elif down is not None and up is None:
                        grid[i][j] = down
                        changed = True
                    elif up is not None and down is not None and up != down:
                        return False
                elif cons == 'x':
                    if up is not None and down is None:
                        grid[i+1][j] = get_other_color(up)
                        changed = True
                    elif down is not None and up is None:
                        grid[i][j] = get_other_color(down)
                        changed = True
                    elif up is not None and down is not None and up == down:
                        return False

        return True

    def is_complete():
        for i in range(n):
            for j in range(m):
                if grid[i][j] is None:
                    return False
        return True

    def copy_grid(g):
        return [row[:] for row in g]

    def solve_recursive():
        if not propagate():
            return False

        if is_complete():
            return True

        # Find the best cell to branch on (minimum remaining values)
        best_i, best_j = -1, -1
        min_options = 3

        for i in range(n):
            for j in range(m):
                if grid[i][j] is None:
                    # Heuristic: check how many constraints affect this cell
                    options = 2
                    # Try to pick a cell that will maximize propagation
                    if best_i == -1:
                        best_i, best_j = i, j
                    # Simple: just pick first empty
                    if best_i != -1 and min_options > 0:
                        pass  # Keep first found for simplicity in this optimized version

        if best_i == -1:
            return True  # Should not happen if is_complete checked

        # Try both colors
        for val in ['B', 'W']:
            old_grid = copy_grid(grid)
            grid[best_i][best_j] = val

            if solve_recursive():
                return True

            # Restore
            for i in range(n):
                for j in range(m):
                    grid[i][j] = old_grid[i][j]

        return False

    if solve_recursive():
        return grid
    else:
        return "No Solution"

