import ast
import copy

def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']
    N = len(data)

    # Initialize domains: list of list of sets
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Parse inequalities into list of ((r1,c1), (r2,c2), op)
    # op: '<' means val1 < val2, '>' means val1 > val2
    ineqs = []

    for key, symbol in horizontal.items():
        # key is like "(0, 1.5)" meaning between col 1 and 2 at row 0
        r, c = ast.literal_eval(key)
        left_c = int(c - 0.5)
        right_c = left_c + 1
        if symbol == '<':
            ineqs.append(((int(r), left_c), (int(r), right_c), '<'))
        else:  # '>'
            ineqs.append(((int(r), left_c), (int(r), right_c), '>'))

    for key, symbol in vertical.items():
        # key is like "(0.5, 1)" meaning between row 0 and 1 at col 1
        r, c = ast.literal_eval(key)
        top_r = int(r - 0.5)
        bot_r = top_r + 1
        if symbol == '^':  # top < bottom
            ineqs.append(((top_r, int(c)), (bot_r, int(c)), '<'))
        else:  # 'v', top > bottom
            ineqs.append(((top_r, int(c)), (bot_r, int(c)), '>'))

    def propagate(domains):
        """Apply constraint propagation until fixpoint. Returns False if contradiction."""
        changed = True
        while changed:
            changed = False

            # Row constraints: unique values
            for r in range(N):
                # Track assigned values and their positions
                assigned = {}  # value -> col
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        if val in assigned:
                            return False  # Duplicate assignment
                        assigned[val] = c

                # Remove assigned values from other cells in row
                for c in range(N):
                    if len(domains[r][c]) > 1:
                        for val in list(domains[r][c]):
                            if val in assigned:
                                domains[r][c].remove(val)
                                changed = True
                                if not domains[r][c]:
                                    return False

            # Column constraints: unique values
            for c in range(N):
                assigned = {}  # value -> row
                for r in range(N):
                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        if val in assigned:
                            return False
                        assigned[val] = r

                for r in range(N):
                    if len(domains[r][c]) > 1:
                        for val in list(domains[r][c]):
                            if val in assigned:
                                domains[r][c].remove(val)
                                changed = True
                                if not domains[r][c]:
                                    return False

            # Hidden singles in rows
            for r in range(N):
                val_positions = {}  # value -> list of cols
                for c in range(N):
                    for val in domains[r][c]:
                        if val not in val_positions:
                            val_positions[val] = []
                        val_positions[val].append(c)
                for val, cols in val_positions.items():
                    if len(cols) == 0:
                        return False
                    if len(cols) == 1:
                        c = cols[0]
                        if len(domains[r][c]) > 1:
                            if val not in domains[r][c]:
                                return False
                            domains[r][c] = {val}
                            changed = True

            # Hidden singles in columns
            for c in range(N):
                val_positions = {}  # value -> list of rows
                for r in range(N):
                    for val in domains[r][c]:
                        if val not in val_positions:
                            val_positions[val] = []
                        val_positions[val].append(r)
                for val, rows in val_positions.items():
                    if len(rows) == 0:
                        return False
                    if len(rows) == 1:
                        r = rows[0]
                        if len(domains[r][c]) > 1:
                            if val not in domains[r][c]:
                                return False
                            domains[r][c] = {val}
                            changed = True

            # Inequality constraints (bounds consistency)
            for (r1, c1), (r2, c2), op in ineqs:
                d1 = domains[r1][c1]
                d2 = domains[r2][c2]

                if op == '<':
                    # val1 < val2
                    if d2:
                        max_d2 = max(d2)
                        # Remove from d1 values >= max_d2
                        to_remove = [x for x in d1 if x >= max_d2]
                        if to_remove:
                            for x in to_remove:
                                d1.remove(x)
                            changed = True
                            if not d1:
                                return False

                    if d1:
                        min_d1 = min(d1)
                        # Remove from d2 values <= min_d1
                        to_remove = [x for x in d2 if x <= min_d1]
                        if to_remove:
                            for x in to_remove:
                                d2.remove(x)
                            changed = True
                            if not d2:
                                return False
                else:  # op == '>'
                    # val1 > val2
                    if d2:
                        min_d2 = min(d2)
                        # Remove from d1 values <= min_d2
                        to_remove = [x for x in d1 if x <= min_d2]
                        if to_remove:
                            for x in to_remove:
                                d1.remove(x)
                            changed = True
                            if not d1:
                                return False

                    if d1:
                        max_d1 = max(d1)
                        # Remove from d2 values >= max_d1
                        to_remove = [x for x in d2 if x >= max_d1]
                        if to_remove:
                            for x in to_remove:
                                d2.remove(x)
                            changed = True
                            if not d2:
                                return False
        return True

    def search(domains):
        """Recursive backtracking search with MRV heuristic."""
        # Check if complete (all domains size 1)
        min_size = N+1
        target_cell = None

        for r in range(N):
            for c in range(N):
                size = len(domains[r][c])
                if size == 0:
                    return None
                if size == 1:
                    continue
                if size < min_size:
                    min_size = size
                    target_cell = (r, c)
                    if size == 2:
                        # Early exit for best case
                        pass

        if target_cell is None:
            # All cells have size 1, solution found
            return [[next(iter(domains[r][c])) for c in range(N)] for r in range(N)]

        r, c = target_cell
        # Try each value in domain
        # Sort values to try more promising ones first (optional heuristic)
        values = sorted(domains[r][c])

        for val in values:
            # Create deep copy
            new_domains = [[set(domains[i][j]) for j in range(N)] for i in range(N)]
            new_domains[r][c] = {val}

            if propagate(new_domains):
                result = search(new_domains)
                if result is not None:
                    return result

        return None

    # Initial propagation
    if not propagate(domains):
        return "No Solution"

    result = search(domains)
    if result is None:
        return "No Solution"
    return result

