def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(data)

    # Precompute cell groupings
    regions = {}
    cell_region = {}
    for r in range(n):
        for c in range(n):
            rid = region_map[r][c]
            cell_region[(r, c)] = rid
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    # All constraint groups: rows, cols, regions
    groups = []
    for r in range(n):
        groups.append([(r, c) for c in range(n)])
    for c in range(n):
        groups.append([(r, c) for r in range(n)])
    for rid in sorted(regions.keys()):
        groups.append(regions[rid])

    # Precompute peers for each cell (cells that share row, col, or region)
    peers = {}
    for r in range(n):
        for c in range(n):
            peer_set = set()
            # Same row
            for cc in range(n):
                if cc != c:
                    peer_set.add((r, cc))
            # Same col
            for rr in range(n):
                if rr != r:
                    peer_set.add((rr, c))
            # Same region
            rid = cell_region[(r, c)]
            for rr, cc in regions[rid]:
                if (rr, cc) != (r, c):
                    peer_set.add((rr, cc))
            peers[(r, c)] = list(peer_set)

    # State
    grid = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]

    # Candidates as bitmasks: bit (v-1) represents value v
    all_mask = (1 << n) - 1
    cand = [[all_mask for _ in range(n)] for _ in range(n)]

    # Initialize: filled cells have no candidates
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 0:
                cand[r][c] = 0

    # Helper to remove candidate
    def remove_candidate(r, c, val, cand_grid):
        bit = 1 << (val - 1)
        if cand_grid[r][c] & bit:
            cand_grid[r][c] &= ~bit
            if cand_grid[r][c] == 0:
                return False  # Contradiction
        return True

    # Constraint propagation
    def propagate(grid_state, cand_state):
        changed = True
        while changed:
            changed = False

            # Naked singles: cell with only one candidate
            for r in range(n):
                for c in range(n):
                    if grid_state[r][c] == 0:
                        mask = cand_state[r][c]
                        if mask == 0:
                            return False
                        # Check if power of 2 (single bit)
                        if mask & (mask - 1) == 0:
                            val = mask.bit_length()
                            grid_state[r][c] = val
                            cand_state[r][c] = 0
                            for pr, pc in peers[(r, c)]:
                                if grid_state[pr][pc] == 0:
                                    if not remove_candidate(pr, pc, val, cand_state):
                                        return False
                                    changed = True

            # Hidden singles: value appears in only one cell in a group
            for group in groups:
                for val in range(1, n+1):
                    val_bit = 1 << (val-1)
                    found_pos = None
                    count = 0
                    already_placed = False
                    for r, c in group:
                        if grid_state[r][c] == val:
                            already_placed = True
                            break
                        if grid_state[r][c] == 0 and (cand_state[r][c] & val_bit):
                            found_pos = (r, c)
                            count += 1
                    if already_placed:
                        continue
                    if count == 0:
                        return False  # Value has no place in group
                    if count == 1:
                        r, c = found_pos
                        grid_state[r][c] = val
                        cand_state[r][c] = 0
                        for pr, pc in peers[(r, c)]:
                            if grid_state[pr][pc] == 0:
                                if not remove_candidate(pr, pc, val, cand_state):
                                    return False
                                changed = True
        return True

    # Initial propagation
    # Apply initial constraints from givens
    init_queue = []
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 0:
                init_queue.append((r, c, grid[r][c]))

    # Simple BFS for initial setup
    while init_queue:
        r, c, val = init_queue.pop(0)
        for pr, pc in peers[(r, c)]:
            if grid[pr][pc] == 0:
                if cand[pr][pc] & (1 << (val-1)):
                    cand[pr][pc] &= ~(1 << (val-1))
                    if cand[pr][pc] == 0:
                        return "No Solution"

    if not propagate(grid, cand):
        return "No Solution"

    def is_solved():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    if is_solved():
        return grid

    # Recursive solver with backtracking
    def search():
        # Find most constrained empty cell
        best_r, best_c = -1, -1
        min_options = n + 1

        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    options = bin(cand[r][c]).count('1')
                    if options < min_options:
                        min_options = options
                        best_r, best_c = r, c
                        if options == 1:
                            break
            if min_options == 1:
                break

        if best_r == -1:
            return True

        if min_options == 0:
            return False

        mask = cand[best_r][best_c]
        vals = []
        v = 1
        m = mask
        while m:
            if m & 1:
                vals.append(v)
            m >>= 1
            v += 1

        for val in vals:
            # Save state
            old_grid = [row[:] for row in grid]
            old_cand = [row[:] for row in cand]

            # Place value
            grid[best_r][best_c] = val
            cand[best_r][best_c] = 0

            # Propagate
            valid = True
            val_bit = 1 << (val-1)
            for pr, pc in peers[(best_r, best_c)]:
                if grid[pr][pc] == 0 and (cand[pr][pc] & val_bit):
                    cand[pr][pc] &= ~val_bit
                    if cand[pr][pc] == 0:
                        valid = False
                        break

            if valid:
                valid = propagate(grid, cand)

            if valid and search():
                return True

            # Restore
            for r in range(n):
                for c in range(n):
                    grid[r][c] = old_grid[r][c]
                    cand[r][c] = old_cand[r][c]

        return False

    if search():
        return grid
    else:
        return "No Solution"

