def solve(observation):
    clues = observation['data']
    n = len(clues) - 1  # Grid is n x n cells

    # Grid values: 0=unknown, 1='/', 2='\'
    grid = [[0 for _ in range(n)] for _ in range(n)]

    # DSU for loop detection on (n+1)*(n+1) dots
    size = (n + 1) * (n + 1)
    parent = list(range(size))
    rank = [0] * size

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        x = find(x)
        y = find(y)
        if x == y:
            return False
        if rank[x] < rank[y]:
            x, y = y, x
        parent[y] = x
        if rank[x] == rank[y]:
            rank[x] += 1
        return True

    # Precompute incident cells for each dotted clue
    # For each dot (dr, dc), store list of (cell_r, cell_c, required_value)
    dot_incidents = {}
    for dr in range(n + 1):
        for dc in range(n + 1):
            if clues[dr][dc] is None:
                continue
            incidents = []
            # NW cell: touches dot if '\'
            if dr > 0 and dc > 0:
                incidents.append((dr - 1, dc - 1, 2))
            # NE cell: touches dot if '/'
            if dr > 0 and dc < n:
                incidents.append((dr - 1, dc, 1))
            # SW cell: touches dot if '/'
            if dr < n and dc > 0:
                incidents.append((dr, dc - 1, 1))
            # SE cell: touches dot if '\'
            if dr < n and dc < n:
                incidents.append((dr, dc, 2))
            dot_incidents[(dr, dc)] = incidents

    from collections import deque

    def get_endpoints(r, c, val):
        """Return the two dot indices connected by cell (r,c) with value val"""
        if val == 2:  # '\': connects (r,c) to (r+1,c+1)
            u = r * (n + 1) + c
            v = (r + 1) * (n + 1) + (c + 1)
        else:  # '/': connects (r,c+1) to (r+1,c)
            u = r * (n + 1) + (c + 1)
            v = (r + 1) * (n + 1) + c
        return u, v

    def set_cell(r, c, val, queue):
        """Set cell (r,c) to val, update DSU, queue affected dots. Returns False if invalid."""
        if grid[r][c] == val:
            return True
        if grid[r][c] != 0:
            return False

        u, v = get_endpoints(r, c, val)
        if find(u) == find(v):
            return False  # Would form a cycle

        grid[r][c] = val
        union(u, v)

        # Queue the 4 corner dots for constraint checking
        corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
        for dr, dc in corners:
            if (dr, dc) in dot_incidents:
                queue.append((dr, dc))
        return True

    def propagate(queue):
        """Propagate constraints until queue is empty. Returns False on contradiction."""
        while queue:
            dr, dc = queue.popleft()
            clue = clues[dr][dc]
            incidents = dot_incidents[(dr, dc)]

            touching = 0
            unknowns = []

            for cr, cc, need_val in incidents:
                cell_val = grid[cr][cc]
                if cell_val == 0:
                    unknowns.append((cr, cc, need_val))
                elif cell_val == need_val:
                    touching += 1
                # else: explicitly not touching

            # Constraint check
            if touching > clue:
                return False
            if touching + len(unknowns) < clue:
                return False

            if touching == clue:
                # All unknowns must NOT touch this dot
                for cr, cc, need_val in unknowns:
                    other = 1 if need_val == 2 else 2
                    if not set_cell(cr, cc, other, queue):
                        return False
            elif touching + len(unknowns) == clue:
                # All unknowns must touch this dot
                for cr, cc, need_val in unknowns:
                    if not set_cell(cr, cc, need_val, queue):
                        return False
        return True

    # Initialize with all clues
    init_queue = deque(dot_incidents.keys())
    if not propagate(init_queue):
        return "No Solution"

    def is_solved():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    def find_best_cell():
        """Find unknown cell involved in most constraints"""
        best_r, best_c = -1, -1
        best_score = -1
        for r in range(n):
            for c in range(n):
                if grid[r][c] != 0:
                    continue
                score = 0
                # Check 4 corners
                if (r, c) in dot_incidents:
                    score += 1
                if (r, c + 1) in dot_incidents:
                    score += 1
                if (r + 1, c) in dot_incidents:
                    score += 1
                if (r + 1, c + 1) in dot_incidents:
                    score += 1
                if score > best_score:
                    best_score = score
                    best_r, best_c = r, c
        return best_r, best_c

    # Recursive search with backtracking
    def search():
        if is_solved():
            return True

        r, c = find_best_cell()

        # Save state
        saved_grid = [row[:] for row in grid]
        saved_parent = parent[:]
        saved_rank = rank[:]

        # Try '/'
        queue = deque()
        if set_cell(r, c, 1, queue):
            if propagate(queue):
                if search():
                    return True

        # Restore state
        for i in range(n):
            grid[i][:] = saved_grid[i]
        parent[:] = saved_parent
        rank[:] = saved_rank

        # Try '\'
        queue = deque()
        if set_cell(r, c, 2, queue):
            if propagate(queue):
                if search():
                    return True

        return False

    if not search():
        return "No Solution"

    # Convert to output format
    result = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('/' if grid[r][c] == 1 else '\\')
        result.append(row)
    return result

