            else:
                domains[(r, c)] = set(range(1, n + 1))

    def get_peers(r, c):
        """Get all cells in same row, column, or region"""
        peers = set()
        # Same row
        for cc in range(n):
            if cc != c:
                peers.add((r, cc))
        # Same column
        for rr in range(n):
            if rr != r:
                peers.add((rr, c))
        # Same region
        reg_id = region_map[r][c]
        for (rr, cc) in region_cells[reg_id]:
            if rr != r or cc != c:
                peers.add((rr, cc))
        return peers

    # Pre-compute peers for all cells
    peers_map = {}
    for r in range(n):
        for c in range(n):
            peers_map[(r, c)] = get_peers(r, c)

    def propagate():
        """Constraint propagation using queue"""
        changed = True
        while changed:
            changed = False
            for (r, c), vals in list(domains.items()):
                if len(vals) == 1:
                    val = next(iter(vals))
                    for (pr, pc) in peers_map[(r, c)]:
                        if val in domains[(pr, pc)]:
                            domains[(pr, pc)].discard(val)
                            if len(domains[(pr, pc)]) == 0:
                                return False
                            changed = True
                elif len(vals) == 0:
                    return False
        return True

    def solve_recursive():
        """Backtracking search with MRV heuristic"""
        # Find unassigned cell with minimum remaining values
        min_options = n + 1
        target = None
        for r in range(n):
            for c in range(n):
                if len(domains[(r, c)]) > 1:
                    if len(domains[(r, c)]) < min_options:
                        min_options = len(domains[(r, c)])
                        target = (r, c)

        if target is None:
            return True  # All cells assigned

        r, c = target
        original_domain = domains[(r, c)].copy()

        for val in sorted(original_domain):
            # Try assignment
            domains[(r, c)] = {val}

            # Save state for restoration
            saved_states = {}
            valid = True

            # Forward checking: remove val from peers
            for (pr, pc) in peers_map[(r, c)]:
                if val in domains[(pr, pc)]:
                    if len(domains[(pr, pc)]) == 1:
                        valid = False
                        break
                    saved_states[(pr, pc)] = domains[(pr, pc)].copy()
                    domains[(pr, pc)].discard(val)

            if valid:
                if propagate():
                    if solve_recursive():
                        return True

            # Restore state
            domains[(r, c)] = original_domain
            for (pr, pc), state in saved_states.items():
                domains[(pr, pc)] = state

        return False

    if not propagate():
        return "No Solution"

    if not solve_recursive():
        return "No Solution"

    # Build result grid
    result = [[0 for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            result[r][c] = next(iter(domains[(r, c)]))

    return result

