        return True

    def propagate_constraints():
        """Apply constraint propagation. Returns False if contradiction found."""
        changed = True
        while changed:
            changed = False

            # Clue = 1 means edge is N
            # Clue = N means sequence is 1,2,...,N
            for i in range(N):
                # Left clue = 1
                if L[i] == 1 and grid[i][0] == 0:
