                    if grid[N-1][i] > max_allowed:
                        return False

            # Single candidate propagation
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0:
                        candidates = []
                        for val in range(1, N+1):
                            if val not in row_used[r] and val not in col_used[c]:
