                            return False
                        if len(candidates) == 1:
                            val = candidates[0]
                            grid[r][c] = val
                            row_used[r].add(val)
                            col_used[c].add(val)
                            changed = True

        return True

    def get_best_cell():
        """Find unassigned cell with minimum remaining values (MRV heuristic)."""
        best_r, best_c = -1, -1
        min_options = N + 1

        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    count = 0
                    for val in range(1, N+1):
                        if val not in row_used[r] and val not in col_used[c]:
                            count += 1
                    if count < min_options:
                        min_options = count
                        best_r, best_c = r, c
                        if count == 1:
                            return best_r, best_c
        return best_r, best_c

    def search():
        """Recursive backtracking search."""
        if not is_valid_state():
            return False

        r, c = get_best_cell()
        if r == -1:  # All assigned
            return is_valid_state()

        for val in range(1, N+1):
            if val in row_used[r] or val in col_used[c]:
                continue

            # Place
            grid[r][c] = val
            row_used[r].add(val)
            col_used[c].add(val)

            # Recurse
            if search():
                return True

            # Backtrack
            grid[r][c] = 0
            row_used[r].remove(val)
            col_used[c].remove(val)

        return False

    # Initial propagation
    if not propagate_constraints():
        return None

    if not search():
        return None

    return grid

