from itertools import permutations

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    def count_visible(seq):
        """Count visible buildings from the first element."""
        count = 0
        max_h = 0
        for h in seq:
            if h > max_h:
                count += 1
                max_h = h
        return count

    # Generate all permutations of 1..N
    all_perms = list(permutations(range(1, N+1)))

    # Precompute valid candidates for each row based on L and R clues
    # Also apply edge constraints from U (row 0) and D (row N-1)
    row_candidates = []
    for r in range(N):
        cands = []
        for perm in all_perms:
            # Check L clue (visibility from left)
            if L[r] != 0 and count_visible(perm) != L[r]:
                continue
            # Check R clue (visibility from right)
            if R[r] != 0 and count_visible(perm[::-1]) != R[r]:
                continue

            # Check U constraints for row 0
            if r == 0:
                valid = True
                for c in range(N):
                    if U[c] == 1 and perm[c] != N:
                        valid = False
                        break
                    if U[c] == N and perm[c] != 1:
                        valid = False
                        break
                if not valid:
                    continue

            # Check D constraints for row N-1
            if r == N - 1:
                valid = True
                for c in range(N):
                    if D[c] == 1 and perm[c] != N:
                        valid = False
                        break
                    if D[c] == N and perm[c] != 1:
                        valid = False
                        break
                if not valid:
                    continue

            cands.append(perm)

        if not cands:
            return None  # No valid permutation for this row
        row_candidates.append(cands)

    # State for backtracking
    grid = [None] * N
    col_sets = [set() for _ in range(N)]  # Values used in each column
    col_max = [0] * N  # Max height seen from top so far in each column
    col_vis_U = [0] * N  # Visible count from top so far

    def dfs(row):
        if row == N:
            # Verify D clues for all columns
            for c in range(N):
                if D[c] != 0:
                    col_vals = [grid[r][c] for r in range(N)]
                    if count_visible(col_vals[::-1]) != D[c]:
                        return False
            return True

        for perm in row_candidates[row]:
            # Try placing this permutation in the current row
            valid = True
            updates = []  # Track changes for backtracking

            for c, val in enumerate(perm):
                # Check column uniqueness
                if val in col_sets[c]:
                    valid = False
                    break

                # Check U clue feasibility
                if U[c] != 0:
                    new_vis = col_vis_U[c] + (1 if val > col_max[c] else 0)
                    new_max = val if val > col_max[c] else col_max[c]
                    remaining = N - row - 1

                    # Prune if already exceeded or impossible to reach target
                    if new_vis > U[c] or new_vis + remaining < U[c]:
                        valid = False
                        break

                    updates.append((c, val, col_max[c], col_vis_U[c]))
                    col_max[c] = new_max
                    col_vis_U[c] = new_vis
                else:
                    # Still need to track max for consistency, though no constraint check
                    updates.append((c, val, col_max[c], col_vis_U[c]))
                    if val > col_max[c]:
                        col_max[c] = val

            if not valid:
                continue

            # Place the row
            grid[row] = perm
            for c, val, _, _ in updates:
                col_sets[c].add(val)

            # Recurse
            if dfs(row + 1):
                return True

            # Backtrack
            grid[row] = None
            for c, val, old_max, old_vis in updates:
                col_sets[c].remove(val)
                col_max[c] = old_max
                col_vis_U[c] = old_vis

        return False

    if dfs(0):
        return [list(row) for row in grid]
    return None

