                domains[r][c] = {data[r][c]}

    def propagate():
        """Constraint propagation using forward checking and arc consistency for inequalities."""
        changed = True
        while changed:
            changed = False

            # 1. Forward checking: singletons propagate to rows and columns
            for r in range(n):
                for c in range(n):
                    if len(domains[r][c]) == 1:
