                                domains[rr][c].remove(val)
                                changed = True
                                if not domains[rr][c]:
                                    return False

            # 2. Hidden singles for rows
            for r in range(n):
                for val in range(1, n+1):
                    positions = [c for c in range(n) if val in domains[r][c]]
                    if len(positions) == 0:
                        return False
                    if len(positions) == 1:
                        c = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # 3. Hidden singles for columns
            for c in range(n):
                for val in range(1, n+1):
                    positions = [r for r in range(n) if val in domains[r][c]]
                    if len(positions) == 0:
                        return False
                    if len(positions) == 1:
                        r = positions[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # 4. Inequality constraints (Arc Consistency)
            # Horizontal
            for r in range(n):
                for c in range(n-1):
                    key = f"({r}, {c+0.5})"
                    if key in h_ineq:
                        sym = h_ineq[key]
                        left = domains[r][c]
                        right = domains[r][c+1]

                        if sym == '<':
                            # left < right
                            max_r = max(right)
                            to_rem = {x for x in left if x >= max_r}
                            if to_rem:
                                left -= to_rem
                                changed = True
                                if not left:
                                    return False

                            min_l = min(left)
                            to_rem = {x for x in right if x <= min_l}
                            if to_rem:
                                right -= to_rem
                                changed = True
                                if not right:
