                    if key in v_ineq:
                        sym = v_ineq[key]
                        up = domains[r][c]
                        down = domains[r+1][c]

                        if sym == 'v':
                            # up < down
                            max_d = max(down)
                            to_rem = {x for x in up if x >= max_d}
                            if to_rem:
                                up -= to_rem
                                changed = True
                                if not up:
