        return True

    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        return all(len(domains[r][c]) == 1 for r in range(n) for c in range(n))

    if is_solved():
        return [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]

    # Backtracking with MRV heuristic
    def select_unassigned():
        min_size = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best = (r, c)
        return best

    def backtrack():
        if is_solved():
            return True

        cell = select_unassigned()
        if cell is None:
            return False

        r, c = cell
        saved = [[set(domains[i][j]) for j in range(n)] for i in range(n)]

        # Try values in sorted order
        for val in sorted(domains[r][c]):
            domains[r][c] = {val}
            if propagate():
                if backtrack():
                    return True
            # Restore domains
            for i in range(n):
                for j in range(n):
                    domains[i][j] = saved[i][j]

        return False

    if backtrack():
        return [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]
    else:
        return "No Solution"

