def solve(observation):
    data = observation['data']
    n = len(data) - 1
    targets = [[None if x is None else int(x) for x in row] for row in data]

    # DSU with undo capability for cycle detection
    class UndoDSU:
        __slots__ = ('parent', 'rank', 'hist')
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.hist = []
        def find(self, x):
            while self.parent[x] != x:
                x = self.parent[x]
            return x
        def union(self, a, b):
            a, b = self.find(a), self.find(b)
            if a == b:
                return False
            if self.rank[a] < self.rank[b]:
                a, b = b, a
            self.hist.append((b, self.parent[b], a, self.rank[a]))
            self.parent[b] = a
            if self.rank[a] == self.rank[b]:
                self.rank[a] += 1
            return True
        def snapshot(self):
            return len(self.hist)
        def undo(self, snap):
            while len(self.hist) > snap:
                b, pb, a, ra = self.hist.pop()
                self.parent[b] = pb
                self.rank[a] = ra

    dot_id = lambda r, c: r * (n + 1) + c
    dsu = UndoDSU((n + 1) * (n + 1))

    grid = [[0] * n for _ in range(n)]  # 0=empty, 1=/, 2=\
    dcnt = [[0] * (n + 1) for _ in range(n + 1)]  # Contribution counts per dot

    # Precompute adjacency for numbered dots
    dot_adj = {}
    for r in range(n + 1):
        for c in range(n + 1):
            if targets[r][c] is None:
                continue
            cells = []
            if r < n and c < n: cells.append((r, c, '\\'))      # cell (r,c) as TL
            if r < n and c > 0: cells.append((r, c - 1, '/'))   # cell (r,c-1) as TR
            if r > 0 and c < n: cells.append((r - 1, c, '/'))   # cell (r-1,c) as BL
            if r > 0 and c > 0: cells.append((r - 1, c - 1, '\\'))  # cell (r-1,c-1) as BR
            dot_adj[(r, c)] = cells

    from collections import deque

    def set_cell(gr, dc, ds, r, c, val, q):
        """Assign val to cell (r,c). Returns False if contradiction or cycle."""
        if gr[r][c] != 0:
            cur_val = '/' if gr[r][c] == 1 else '\\'
            return cur_val == val

        # Check for cycle before adding edge
        if val == '/':
            u, v = dot_id(r, c + 1), dot_id(r + 1, c)
        else:
            u, v = dot_id(r, c), dot_id(r + 1, c + 1)

        if ds.find(u) == ds.find(v):
            return False

        gr[r][c] = 1 if val == '/' else 2
        ds.union(u, v)

        # Update contribution counts for the two dots this diagonal touches
        if val == '/':
            touches = [(r, c + 1), (r + 1, c)]
            nontouches = [(r, c), (r + 1, c + 1)]
        else:
            touches = [(r, c), (r + 1, c + 1)]
            nontouches = [(r, c + 1), (r + 1, c)]

        for dr, dcc in touches:
            dc[dr][dcc] += 1
            if targets[dr][dcc] is not None:
                if dc[dr][dcc] > targets[dr][dcc]:
                    return False
                q.append((dr, dcc))

        # Queue the other dots for constraint recheck (they lost a potential contributor)
        for dr, dcc in nontouches:
            if targets[dr][dcc] is not None:
                q.append((dr, dcc))
        return True

    def propagate(gr, dc, ds):
        """Constraint propagation using queue. Modifies state. Returns False if contradiction."""
        q = deque(dot_adj.keys())
        while q:
            r, c = q.popleft()
            if (r, c) not in dot_adj:
                continue
            target = targets[r][c]
            cells = dot_adj[(r, c)]

            curr = 0
            free = []
            for cr, cc, need in cells:
                v = gr[cr][cc]
                if v == 0:
                    free.append((cr, cc, need))
                elif (v == 1 and need == '/') or (v == 2 and need == '\\'):
                    curr += 1

            if curr > target or curr + len(free) < target:
                return False

            if curr == target:
                # All free cells must NOT contribute (set to opposite)
                for cr, cc, need in free:
                    opp = '/' if need == '\\' else '\\'
                    if not set_cell(gr, dc, ds, cr, cc, opp, q):
                        return False
            elif len(free) > 0 and curr + len(free) == target:
                # All free cells MUST contribute
                for cr, cc, need in free:
                    if not set_cell(gr, dc, ds, cr, cc, need, q):
                        return False
        return True

    def copy_state():
        return ([row[:] for row in grid], [row[:] for row in dcnt])

    def restore_state(gr, dc, snap):
        dsu.undo(snap)
        for i in range(n):
            grid[i][:] = gr[i]
            dcnt[i][:] = dc[i]
        dcnt[n][:] = dc[n]

    def search():
        # Find next undetermined cell
        for r in range(n):
            for c in range(n):
                if grid[r][c] != 0:
                    continue
                # Try '/'
                snap = dsu.snapshot()
                old_gr, old_dc = copy_state()
                q = deque()
                if set_cell(grid, dcnt, dsu, r, c, '/', q) and propagate(grid, dcnt, dsu):
                    if search():
                        return True
                restore_state(old_gr, old_dc, snap)

                # Try '\'
                snap = dsu.snapshot()
                old_gr, old_dc = copy_state()
                q = deque()
                if set_cell(grid, dcnt, dsu, r, c, '\\', q) and propagate(grid, dcnt, dsu):
                    if search():
                        return True
                restore_state(old_gr, old_dc, snap)
                return False
        return True

    # Initial propagation
    if not propagate(grid, dcnt, dsu):
        return "No Solution"

    if search():
        return [['/' if grid[r][c] == 1 else '\\' for c in range(n)] for r in range(n)]
    return "No Solution"

