def solve(observation):
    data = observation['data']
    H = len(data) - 1  # number of cell rows
    W = len(data[0]) - 1  # number of cell columns

    # Grid values: -1 = unknown, 0 = '/', 1 = '\'
    # '/' connects top-right to bottom-left: dot (r, c+1) to (r+1, c)
    # '\' connects top-left to bottom-right: dot (r, c) to (r+1, c+1)

    # Precompute constraint info for each dot
    dot_targets = {}  # (r, c) -> target count
    dot_constraints = {}  # (r, c) -> list of (cell_r, cell_c, required_val)
    # required_val: 0 for '/', 1 for '\'

    for r in range(H + 1):
        for c in range(W + 1):
            if data[r][c] is not None:
                target = data[r][c]
                dot_targets[(r, c)] = target
                constraints = []
                # NW cell (r-1, c-1): '\' touches dot (r,c)
                if r > 0 and c > 0:
                    constraints.append((r-1, c-1, 1))
                # NE cell (r-1, c): '/' touches dot (r,c)
                if r > 0 and c < W:
                    constraints.append((r-1, c, 0))
                # SW cell (r, c-1): '/' touches dot (r,c)
                if r < H and c > 0:
                    constraints.append((r, c-1, 0))
                # SE cell (r, c): '\' touches dot (r,c)
                if r < H and c < W:
                    constraints.append((r, c, 1))
                dot_constraints[(r, c)] = constraints

    # Precompute which dots are affected by each cell (for queue updates)
    cell_to_dots = {}
    for r in range(H):
        for c in range(W):
            dots = []
            # Four corners of this cell
            for dr in [r, r+1]:
                for dc in [c, c+1]:
                    if (dr, dc) in dot_targets:
                        dots.append((dr, dc))
            cell_to_dots[(r, c)] = dots

    # Union-Find for cycle detection
    # Dots indexed as r * (W+1) + c
    num_dots = (H + 1) * (W + 1)

    def find(parent, x):
        # Path compression
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(parent, rank, x, y):
        px, py = find(parent, x), find(parent, y)
        if px == py:
            return False, parent, rank  # Already connected (cycle)
        # Union by rank
        new_parent = parent[:]
        new_rank = rank[:]
        if new_rank[px] < new_rank[py]:
            new_parent[px] = py
        elif new_rank[px] > new_rank[py]:
            new_parent[py] = px
        else:
            new_parent[py] = px
            new_rank[px] += 1
        return True, new_parent, new_rank

    # Get the two dots connected by a cell with specific orientation
    def get_connection(r, c, val):
        if val == 0:  # '/'
            d1 = r * (W + 1) + (c + 1)      # top-right
            d2 = (r + 1) * (W + 1) + c      # bottom-left
        else:  # '\'
            d1 = r * (W + 1) + c            # top-left
            d2 = (r + 1) * (W + 1) + (c + 1)  # bottom-right
        return d1, d2

    from collections import deque

    # Propagate constraints
    def propagate(grid, parent, rank):
        # Returns (success, new_grid, new_parent, new_rank)
        g = [row[:] for row in grid]
        p = parent[:]
        r = rank[:]

        q = deque()
        # Initialize with all constrained dots
        for dot in dot_targets:
            q.append(dot)

        # Track what's in queue to avoid duplicates? For correctness, we can have duplicates.

        while q:
            dot = q.popleft()
            if dot not in dot_targets:
                continue

            target = dot_targets[dot]
            constraints = dot_constraints[dot]

            on_count = 0
            off_count = 0
            unknowns = []

            for (cr, cc, need) in constraints:
                val = g[cr][cc]
                if val == -1:
                    unknowns.append((cr, cc, need))
                elif val == need:
                    on_count += 1
                else:
                    off_count += 1

            # Check feasibility
            if on_count > target:
                return False, None, None, None
            if on_count + len(unknowns) < target:
                return False, None, None, None

            must_be_on = target - on_count
            must_be_off = len(unknowns) - must_be_on

            # If all unknowns must be ON
            if must_be_off == 0:
                for (cr, cc, need) in unknowns:
                    if g[cr][cc] == -1:
                        # Set to need
                        d1, d2 = get_connection(cr, cc, need)
                        # Check cycle
                        if find(p, d1) == find(p, d2):
                            return False, None, None, None
                        ok, new_p, new_r = union(p, r, d1, d2)
                        if not ok:
                            return False, None, None, None
                        p, r = new_p, new_r
                        g[cr][cc] = need
                        # Add affected dots to queue
                        for d in cell_to_dots[(cr, cc)]:
                            q.append(d)
                    elif g[cr][cc] != need:
                        return False, None, None, None

            # If all unknowns must be OFF
            elif must_be_on == 0:
                for (cr, cc, need) in unknowns:
                    opp = 1 - need
                    if g[cr][cc] == -1:
                        d1, d2 = get_connection(cr, cc, opp)
                        if find(p, d1) == find(p, d2):
                            return False, None, None, None
                        ok, new_p, new_r = union(p, r, d1, d2)
                        if not ok:
                            return False, None, None, None
                        p, r = new_p, new_r
                        g[cr][cc] = opp
                        for d in cell_to_dots[(cr, cc)]:
                            q.append(d)
                    elif g[cr][cc] == need:
                        return False, None, None, None

        return True, g, p, r

    # Recursive search
    def search(grid, parent, rank):
        # Find next unknown cell
        # Optimization: find cell involved in most constraints, or just first
        for r in range(H):
            for c in range(W):
                if grid[r][c] == -1:
                    # Try '/'
                    for val in [0, 1]:
                        d1, d2 = get_connection(r, c, val)
                        if find(parent, d1) == find(parent, d2):
                            continue  # Would form cycle
                        ok, new_p, new_r = union(parent, rank, d1, d2)
                        if not ok:
                            continue
                        new_grid = [row[:] for row in grid]
                        new_grid[r][c] = val
                        # Propagate
                        prop_ok, g_after, p_after, r_after = propagate(new_grid, new_p, new_r)
                        if prop_ok:
                            result = search(g_after, p_after, r_after)
                            if result is not None:
                                return result
                    return None
        # All filled - verify solution
        for dot, target in dot_targets.items():
            cnt = 0
            for (cr, cc, need) in dot_constraints[dot]:
                if grid[cr][cc] == need:
                    cnt += 1
            if cnt != target:
                return None
        return grid

    # Initialize
    init_parent = list(range(num_dots))
    init_rank = [0] * num_dots
    init_grid = [[-1 for _ in range(W)] for _ in range(H)]

    ok, g, p, r = propagate(init_grid, init_parent, init_rank)
    if not ok:
        return "No Solution"

    result = search(g, p, r)
    if result is None:
        return "No Solution"

    # Format output
    ans = []
    for row in result:
        ans.append(['/' if val == 0 else '\\' for val in row])
    return ans

