OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, 6, None], [None, None, None, None, 5], [None, 7, None, None, None]]}

def solve(observation):
    data = observation['data']
    n = len(data)

    # State: 0 = unknown, 1 = white, 2 = black
    # Initialize grid
    grid = [[0 for _ in range(n)] for _ in range(n)]
    clues = []  # (r, c, value)

    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                grid[r][c] = 1  # Clue cells are white
                clues.append((r, c, data[r][c]))

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_min_visible(r, c, state):
        """Minimum visible cells treating unknowns as blocking."""
        if state[r][c] == 2:
            return -1
        count = 1  # self
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n:
                if state[nr][nc] == 2:
                    break
                if state[nr][nc] == 0:
                    break  # Unknown blocks for min
                # White
                count += 1
                nr += dr
                nc += dc
        return count

    def get_max_visible(r, c, state):
        """Maximum visible cells treating unknowns as white."""
        if state[r][c] == 2:
            return -1
        count = 1  # self
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n:
                if state[nr][nc] == 2:
                    break
                # Unknown or white: assume white
                count += 1
                nr += dr
                nc += dc
        return count

    def get_actual_visible(r, c, state):
        """Actual visible count for completed grid."""
        if state[r][c] != 1:
            return 0
        count = 1
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n:
                if state[nr][nc] == 2:
                    break
                if state[nr][nc] == 1:
                    count += 1
                nr += dr
                nc += dc
        return count

    def propagate(state):
        """Constraint propagation with aggressive deduction."""
        current = [row[:] for row in state]
        changed = True

        while changed:
            changed = False

            # Rule 1: Black cells force orthogonal neighbors to be white
            for r in range(n):
                for c in range(n):
                    if current[r][c] == 2:
                        for dr, dc in dirs:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < n:
                                if current[nr][nc] == 2:
                                    return None, False  # Adjacent black
                                if current[nr][nc] == 0:
                                    current[nr][nc] = 1
                                    changed = True

            # Rule 2: Clue constraints propagation
            for r, c, val in clues:
                if current[r][c] == 2:
                    return None, False

                min_v = get_min_visible(r, c, current)
                max_v = get_max_visible(r, c, current)

                if min_v > val or max_v < val:
                    return None, False

                # If min equals clue: first unknown in each direction must be black
                if min_v == val:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        # Skip confirmed whites
                        while 0 <= nr < n and 0 <= nc < n and current[nr][nc] == 1:
                            nr += dr
                            nc += dc
                        # If unknown, must be black
                        if 0 <= nr < n and 0 <= nc < n and current[nr][nc] == 0:
                            current[nr][nc] = 2
                            changed = True

                # If max equals clue: all unknowns in rays must be white
                if max_v == val:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        while 0 <= nr < n and 0 <= nc < n and current[nr][nc] != 2:
                            if current[nr][nc] == 0:
                                current[nr][nc] = 1
                                changed = True
                            nr += dr
                            nc += dc

        return current, True

    def is_valid_partial(state):
        """Check if partial state can potentially satisfy constraints."""
        # Check clue bounds
        for r, c, val in clues:
            min_v = get_min_visible(r, c, state)
            max_v = get_max_visible(r, c, state)
            if min_v > val or max_v < val:
                return False

        # Check black adjacency
        for r in range(n):
            for c in range(n):
                if state[r][c] == 2:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and state[nr][nc] == 2:
                            return False

        # Check white connectivity potential (treat unknown as traversable)
        whites = []
        for r in range(n):
            for c in range(n):
                if state[r][c] == 1:
                    whites.append((r, c))

        if not whites:
            return True

        start = whites[0]
        visited = set([start])
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited:
                    if state[nr][nc] in (0, 1):  # Unknown or white
                        visited.add((nr, nc))
                        stack.append((nr, nc))

        for r, c in whites:
            if (r, c) not in visited:
                return False

        return True

    def is_complete(state):
        for r in range(n):
            for c in range(n):
                if state[r][c] == 0:
                    return False
        return True

    def check_all_constraints(state):
        # Check clues
        for r, c, val in clues:
            if get_actual_visible(r, c, state) != val:
                return False

        # Check black adjacency
        for r in range(n):
            for c in range(n):
                if state[r][c] == 2:
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and state[nr][nc] == 2:
                            return False

        # Check white connectivity
        whites = [(r, c) for r in range(n) for c in range(n) if state[r][c] == 1]
        if not whites:
            return False

        start = whites[0]
        visited = set([start])
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited and state[nr][nc] == 1:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        return len(visited) == len(whites)

    def select_cell(state):
        """Select unknown cell with highest constraint (near clues)."""
        best_r, best_c = -1, -1
        best_score = -1
        for r in range(n):
            for c in range(n):
                if state[r][c] == 0:
                    # Score by proximity to clues
                    score = 0
                    for cr, cc, _ in clues:
                        dist = abs(r - cr) + abs(c - cc)
                        if dist == 0:
                            continue
                        score += 10.0 / dist
                    # Prefer cells with many determined neighbors
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and state[nr][nc] != 0:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_r, best_c = r, c
        return best_r, best_c

    def backtrack(state):
        # Propagate constraints
        prop_state, valid = propagate(state)
        if not valid or not is_valid_partial(prop_state):
            return None

        if is_complete(prop_state):
            if check_all_constraints(prop_state):
                return prop_state
            return None

        r, c = select_cell(prop_state)
        if r == -1:
            return None

        # Try White
        new_state = [row[:] for row in prop_state]
        new_state[r][c] = 1
        result = backtrack(new_state)
        if result is not None:
            return result

        # Try Black
        new_state = [row[:] for row in prop_state]
        new_state[r][c] = 2
        result = backtrack(new_state)
        if result is not None:
            return result

        return None

    solution = backtrack(grid)

    if solution is None:
        return "No Solution"

    # Format result
    result = []
    for r in range(n):
        row = []
        for c in range(n):
            if data[r][c] is not None:
                row.append(data[r][c])
            elif solution[r][c] == 2:
                row.append('B')
            else:
                row.append(None)
        result.append(row)

    return result

