    ]
}

def solve(observation):
    regions = observation['region']
    data = observation['data']
    n = len(regions)

    # Build region data structures
    region_cells = {}  # region_id -> list of (r, c)
    cell_region = [[0]*n for _ in range(n)]
    region_clue = {}   # region_id -> clue value or None

    for r in range(n):
        for c in range(n):
            rid = regions[r][c]
            cell_region[r][c] = rid
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((r, c))

    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                rid = cell_region[r][c]
                if rid in region_clue and region_clue[rid] != data[r][c]:
                    return "No Solution"  # Contradiction
                region_clue[rid] = data[r][c]

    num_regions = max(max(row) for row in regions) + 1

    # State: 0=unknown, 1=white, 2=black
    grid = [[0]*n for _ in range(n)]

    # Tracking for regions: count of black, white, unknown
    region_black_count = [0] * num_regions
    region_unknown = [set() for _ in range(num_regions)]

    for rid in range(num_regions):
        region_unknown[rid] = set(region_cells[rid])

    # Helper to set a cell
    def set_cell(r, c, val, reason=""):
        # val: 1=white, 2=black
        if grid[r][c] != 0:
            if grid[r][c] != val:
                return False  # Contradiction
            return True
        grid[r][c] = val
        rid = cell_region[r][c]
        if val == 2:  # black
            region_black_count[rid] += 1
        region_unknown[rid].discard((r, c))
        return True

    # Initialize queue with forced values
    queue = []

    # Process initial clues
    for rid in range(num_regions):
        cells = region_cells[rid]
        clue = region_clue.get(rid)
        if clue is not None:
            if clue == 0:
                # All white
                for (r, c) in cells:
                    if not set_cell(r, c, 1):
                        return "No Solution"
                    queue.append((r, c))
            elif clue == len(cells):
                # All black
                for (r, c) in cells:
                    if not set_cell(r, c, 2):
                        return "No Solution"
                    queue.append((r, c))
            elif clue < 0 or clue > len(cells):
                return "No Solution"

    # Propagation function
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def propagate():
        nonlocal queue
        while queue:
            r, c = queue.pop(0)
            val = grid[r][c]
            rid = cell_region[r][c]

            if val == 2:  # If black, neighbors must be white
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] == 2:
                            return False  # Adjacent blacks
                        if grid[nr][nc] == 0:
                            if not set_cell(nr, nc, 1):
                                return False
                            queue.append((nr, nc))

            # Check region constraints
            clue = region_clue.get(rid)
            cells_in_region = region_cells[rid]
            unk = region_unknown[rid]
            blk = region_black_count[rid]

            if clue is not None:
                if blk > clue:
                    return False
                if blk == clue:
                    # All remaining must be white
                    for (cr, cc) in list(unk):
                        if not set_cell(cr, cc, 1):
                            return False
                        queue.append((cr, cc))
                elif len(unk) + blk == clue:
                    # All unknown must be black
                    for (cr, cc) in list(unk):
                        if not set_cell(cr, cc, 2):
                            return False
                        queue.append((cr, cc))

            # Line segment constraints (row and column)
            # Check row r
            if not check_line(r, c, is_row=True):
                return False
            # Check column c  
            if not check_line(r, c, is_row=False):
                return False

        return True

    def check_line(r, c, is_row):
        # Check the line (row r or col c) for segment violations
        # and propagate forced blacks
        if is_row:
            coords = [(r, i) for i in range(n)]
        else:
            coords = [(i, c) for i in range(n)]

        # Find gaps (sequences of non-black cells)
        i = 0
        while i < n:
            # Skip blacks
            while i < n and grid[coords[i][0]][coords[i][1]] == 2:
                i += 1
            if i >= n:
                break

            # Start of gap
            gap_start = i
            gap_cells = []
            gap_regions_white = set()

            while i < n and grid[coords[i][0]][coords[i][1]] != 2:
                cr, cc = coords[i]
                gap_cells.append((cr, cc))
                if grid[cr][cc] == 1:  # white
                    gap_regions_white.add(cell_region[cr][cc])
                i += 1

            # Analyze gap
            if len(gap_regions_white) > 2:
                return False

            if len(gap_regions_white) == 2:
                # Any unknown in this gap from a third region must be black
                for (cr, cc) in gap_cells:
                    if grid[cr][cc] == 0:  # unknown
                        rrid = cell_region[cr][cc]
                        if rrid not in gap_regions_white:
                            # Must be black to avoid 3rd region in segment
                            if not set_cell(cr, cc, 2):
                                return False
                            queue.append((cr, cc))

        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        # Check all clues
        for rid, clue in region_clue.items():
            if region_black_count[rid] != clue:
                return False
        # Check white connectivity
        if not check_white_connected():
            return False
        # Check line segments thoroughly
        if not check_all_line_segments():
            return False
        return True

    def check_white_connected():
        # BFS from first white cell
        start = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1 or grid[r][c] == 0:  # Count unknown as white for partial? No, for final check grid is full
                    if grid[r][c] == 1:
                        start = (r, c)
                        break
            if start:
                break

        if not start:
            return False  # No white cells

        visited = [[False]*n for _ in range(n)]
        q = [start]
        visited[start[0]][start[1]] = True
        count = 0

        while q:
            r, c = q.pop(0)
            count += 1
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                    if grid[nr][nc] == 1:  # white
                        visited[nr][nc] = True
                        q.append((nr, nc))

        # Count total white cells
        total_white = sum(1 for r in range(n) for c in range(n) if grid[r][c] == 1)
        return count == total_white

    def check_all_line_segments():
        # Check all rows and columns for the 2-region rule
        for r in range(n):
            c = 0
            while c < n:
                while c < n and grid[r][c] == 2:
                    c += 1
                if c >= n:
                    break
                seg_regions = set()
                while c < n and grid[r][c] != 2:
                    if grid[r][c] == 1:
                        seg_regions.add(cell_region[r][c])
                    c += 1
                if len(seg_regions) > 2:
                    return False

        for c in range(n):
            r = 0
            while r < n:
                while r < n and grid[r][c] == 2:
                    r += 1
                if r >= n:
                    break
                seg_regions = set()
                while r < n and grid[r][c] != 2:
                    if grid[r][c] == 1:
                        seg_regions.add(cell_region[r][c])
                    r += 1
                if len(seg_regions) > 2:
                    return False

        return True

    # Backtracking
    def select_cell():
        # Heuristic: cell in most constrained region
        best_cell = None
        min_options = 100

        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    rid = cell_region[r][c]
                    clue = region_clue.get(rid)
                    unk = len(region_unknown[rid])
                    blk = region_black_count[rid]

                    # Calculate remaining needed
                    if clue is not None:
                        remaining = clue - blk
                        if remaining == 0:
                            # Must be white
                            return (r, c, [1])
                        elif remaining == unk:
                            # Must be black
                            return (r, c, [2])
                        else:
                            # Both possible
                            opts = 2
                    else:
                        opts = 2

                    # Prefer regions with clues
                    if clue is not None:
                        opts = 1  # Prioritize

                    if opts < min_options:
                        min_options = opts
                        best_cell = (r, c)

        if best_cell is None:
            return None
        r, c = best_cell
        # Try black first if region needs blacks, else white
        rid = cell_region[r][c]
        clue = region_clue.get(rid)
        if clue is not None and region_black_count[rid] < clue:
            return (r, c, [2, 1])
        return (r, c, [1, 2])

    def backtrack():
        if is_solved():
            return True

        # Check early termination: line segments
        if not check_all_line_segments_valid_partial():
            return False

        cell_info = select_cell()
        if cell_info is None:
            # All assigned but not solved? Check constraints
            return is_solved()

        r, c, values = cell_info

        for val in values:
            # Save state
            old_grid = [row[:] for row in grid]
            old_black = region_black_count[:]
            old_unknown = [s.copy() for s in region_unknown]
            old_queue = queue[:]

            # Set and propagate
            if not set_cell(r, c, val):
                continue
            queue.append((r, c))

            if propagate():
                if backtrack():
                    return True

            # Restore
            for i in range(n):
                grid[i] = old_grid[i]
            for i in range(num_regions):
                region_black_count[i] = old_black[i]
                region_unknown[i] = old_unknown[i]
            queue = old_queue

        return False

    def check_all_line_segments_valid_partial():
        # Quick check: no confirmed white segment already spans >2 regions
        for r in range(n):
            c = 0
            while c < n:
                while c < n and grid[r][c] == 2:
                    c += 1
                if c >= n:
                    break
                seg_regions = set()
                has_unknown = False
                while c < n and grid[r][c] != 2:
                    if grid[r][c] == 1:
                        seg_regions.add(cell_region[r][c])
                    else:
                        has_unknown = True
                    c += 1
                if len(seg_regions) > 2:
                    return False
        return True

    if backtrack():
        # Convert to answer format
        result = [[None]*n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 2:
                    result[r][c] = 'B'
                else:
                    result[r][c] = None
        return result
    else:
        return "No Solution"

