def solve(observation):
    import ast
    n = len(observation['data'])
    target = n // 2

    # Initialize domains
    domains = [[{'B', 'W'} for _ in range(n)] for _ in range(n)]
    data = observation['data']
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Parse constraints
    h_cons = []  # (r, c1, c2, type)
    for key, val in observation['horizontal'].items():
        coord = ast.literal_eval(key)
        r, c = coord
        c1 = int(c)
        c2 = c1 + 1
        h_cons.append((int(r), c1, c2, val))

    v_cons = []  # (r1, r2, c, type)
    for key, val in observation['vertical'].items():
        coord = ast.literal_eval(key)
        r, c = coord
        r1 = int(r)
        r2 = r1 + 1
        v_cons.append((r1, r2, int(c), val))

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # Process horizontal constraints
            for r, c1, c2, typ in h_cons:
                d1 = domains[r][c1]
                d2 = domains[r][c2]
                if typ == '=':
                    inter = d1 & d2
                    if not inter:
                        return False
                    if len(inter) < len(d1):
                        domains[r][c1] = inter
                        changed = True
                    if len(inter) < len(d2):
                        domains[r][c2] = inter
                        changed = True
                else:  # 'x'
                    if len(d1) == 1:
                        val = next(iter(d1))
                        other = 'W' if val == 'B' else 'B'
                        if other not in d2:
                            return False
                        if d2 != {other}:
                            domains[r][c2] = {other}
                            changed = True
                    if len(d2) == 1:
                        val = next(iter(d2))
                        other = 'W' if val == 'B' else 'B'
                        if other not in d1:
                            return False
                        if d1 != {other}:
                            domains[r][c1] = {other}
                            changed = True

            # Process vertical constraints
            for r1, r2, c, typ in v_cons:
                d1 = domains[r1][c]
                d2 = domains[r2][c]
                if typ == '=':
                    inter = d1 & d2
                    if not inter:
                        return False
                    if len(inter) < len(d1):
                        domains[r1][c] = inter
                        changed = True
                    if len(inter) < len(d2):
                        domains[r2][c] = inter
                        changed = True
                else:
                    if len(d1) == 1:
                        val = next(iter(d1))
                        other = 'W' if val == 'B' else 'B'
                        if other not in d2:
                            return False
                        if d2 != {other}:
                            domains[r2][c] = {other}
                            changed = True
                    if len(d2) == 1:
                        val = next(iter(d2))
                        other = 'W' if val == 'B' else 'B'
                        if other not in d1:
                            return False
                        if d1 != {other}:
                            domains[r1][c] = {other}
                            changed = True

            # Row counting constraints
            for r in range(n):
                row = domains[r]
                fixed_B = sum(1 for d in row if d == {'B'})
                fixed_W = sum(1 for d in row if d == {'W'})

                if fixed_B > target or fixed_W > target:
                    return False

                unknowns = [c for c, d in enumerate(row) if len(d) > 1]
                remaining = len(unknowns)
                need_B = target - fixed_B
                need_W = target - fixed_W

                if need_B == 0:
                    for c in unknowns:
                        if 'W' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'W'}:
                            domains[r][c] = {'W'}
                            changed = True
                elif need_W == 0:
                    for c in unknowns:
                        if 'B' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'B'}:
                            domains[r][c] = {'B'}
                            changed = True
                elif need_B == remaining:
                    for c in unknowns:
                        if 'B' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'B'}:
                            domains[r][c] = {'B'}
                            changed = True
                elif need_W == remaining:
                    for c in unknowns:
                        if 'W' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'W'}:
                            domains[r][c] = {'W'}
                            changed = True

            # Column counting constraints
            for c in range(n):
                col = [domains[r][c] for r in range(n)]
                fixed_B = sum(1 for d in col if d == {'B'})
                fixed_W = sum(1 for d in col if d == {'W'})

                if fixed_B > target or fixed_W > target:
                    return False

                unknowns = [r for r, d in enumerate(col) if len(d) > 1]
                remaining = len(unknowns)
                need_B = target - fixed_B
                need_W = target - fixed_W

                if need_B == 0:
                    for r in unknowns:
                        if 'W' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'W'}:
                            domains[r][c] = {'W'}
                            changed = True
                elif need_W == 0:
                    for r in unknowns:
                        if 'B' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'B'}:
                            domains[r][c] = {'B'}
                            changed = True
                elif need_B == remaining:
                    for r in unknowns:
                        if 'B' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'B'}:
                            domains[r][c] = {'B'}
                            changed = True
                elif need_W == remaining:
                    for r in unknowns:
                        if 'W' not in domains[r][c]:
                            return False
                        if domains[r][c] != {'W'}:
                            domains[r][c] = {'W'}
                            changed = True

            # No three consecutive - horizontal
            for r in range(n):
                for c in range(n - 2):
                    d0, d1, d2 = domains[r][c], domains[r][c+1], domains[r][c+2]
                    # Pattern X _ X
                    if len(d0) == 1 and len(d2) == 1:
                        v0 = next(iter(d0))
                        v2 = next(iter(d2))
                        if v0 == v2:
                            if len(d1) == 1:
                                if next(iter(d1)) == v0:
                                    return False
                            else:
                                if v0 in d1:
                                    domains[r][c+1] = d1 - {v0}
                                    changed = True
                    # Pattern X X _
                    if len(d0) == 1 and len(d1) == 1:
                        v0 = next(iter(d0))
                        v1 = next(iter(d1))
                        if v0 == v1:
                            other = 'W' if v0 == 'B' else 'B'
                            if other not in d2:
                                return False
                            if d2 != {other}:
                                domains[r][c+2] = {other}
                                changed = True
                    # Pattern _ X X
                    if len(d1) == 1 and len(d2) == 1:
                        v1 = next(iter(d1))
                        v2 = next(iter(d2))
                        if v1 == v2:
                            other = 'W' if v1 == 'B' else 'B'
                            if other not in d0:
                                return False
                            if d0 != {other}:
                                domains[r][c] = {other}
                                changed = True

            # No three consecutive - vertical
            for c in range(n):
                for r in range(n - 2):
                    d0, d1, d2 = domains[r][c], domains[r+1][c], domains[r+2][c]
                    if len(d0) == 1 and len(d2) == 1:
                        v0 = next(iter(d0))
                        v2 = next(iter(d2))
                        if v0 == v2:
                            if len(d1) == 1:
                                if next(iter(d1)) == v0:
                                    return False
                            else:
                                if v0 in d1:
                                    domains[r+1][c] = d1 - {v0}
                                    changed = True
                    if len(d0) == 1 and len(d1) == 1:
                        v0 = next(iter(d0))
                        v1 = next(iter(d1))
                        if v0 == v1:
                            other = 'W' if v0 == 'B' else 'B'
                            if other not in d2:
                                return False
                            if d2 != {other}:
                                domains[r+2][c] = {other}
                                changed = True
                    if len(d1) == 1 and len(d2) == 1:
                        v1 = next(iter(d1))
                        v2 = next(iter(d2))
                        if v1 == v2:
                            other = 'W' if v1 == 'B' else 'B'
                            if other not in d0:
                                return False
                            if d0 != {other}:
                                domains[r][c] = {other}
                                changed = True

        return True

    def is_solved(domains):
        for r in range(n):
            for c in range(n):
                if len(domains[r][c]) != 1:
                    return False
        return True

    def copy_domains(domains):
        return [[set(d) for d in row] for row in domains]

    def solve_recursive(domains):
        if not propagate(domains):
            return None

        if is_solved(domains):
            return [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]

        # Find undetermined cell with minimum domain size
        min_size = 3
        best_r, best_c = -1, -1
        for r in range(n):
            for c in range(n):
                size = len(domains[r][c])
                if 1 < size < min_size:
                    min_size = size
                    best_r, best_c = r, c
                    if min_size == 2:
                        break
            if min_size == 2:
                break

        if best_r == -1:
            return None

        for val in ['B', 'W']:
            if val not in domains[best_r][best_c]:
                continue
            new_domains = copy_domains(domains)
            new_domains[best_r][best_c] = {val}
            result = solve_recursive(new_domains)
            if result is not None:
                return result

        return None

    return solve_recursive(domains)

