def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    # Precompute value positions for conflict detection
    row_val_pos = [{} for _ in range(n)]
    col_val_pos = [{} for _ in range(m)]
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v not in row_val_pos[r]:
                row_val_pos[r][v] = []
            row_val_pos[r][v].append(c)
            if v not in col_val_pos[c]:
                col_val_pos[c][v] = []
            col_val_pos[c][v].append(r)

    # Propagation: assign value and cascade constraints
    def propagate(state, r, c, val):
        from collections import deque
        new_state = [row[:] for row in state]
        q = deque([(r, c, val)])

        while q:
            cr, cc, cval = q.popleft()
            if new_state[cr][cc] != -1:
                if new_state[cr][cc] != cval:
                    return None
                continue
            new_state[cr][cc] = cval

            if cval == 1:  # Black: neighbors must be white
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < n and 0 <= nc < m:
                        if new_state[nr][nc] == 1:
                            return None
                        if new_state[nr][nc] == -1:
                            q.append((nr, nc, 0))
            else:  # White: same values in row/col must be black
                v = grid[cr][cc]
                if v in row_val_pos[cr]:
                    for ncc in row_val_pos[cr][v]:
                        if ncc != cc:
                            if new_state[cr][ncc] == 0:
                                return None
                            if new_state[cr][ncc] == -1:
                                q.append((cr, ncc, 1))
                if v in col_val_pos[cc]:
                    for nrr in col_val_pos[cc][v]:
                        if nrr != cr:
                            if new_state[nrr][cc] == 0:
                                return None
                            if new_state[nrr][cc] == -1:
                                q.append((nrr, cc, 1))
        return new_state

    # Check if current state is valid (no adjacent blacks, no duplicate whites)
    def is_valid_state(state):
        for r in range(n):
            for c in range(m):
                if state[r][c] == 1:
                    for dr, dc in [(0,1),(1,0)]:  # Check right and down only
                        nr, nc = r+dr, c+dc
                        if nr < n and nc < m and state[nr][nc] == 1:
                            return False
                elif state[r][c] == 0:
                    v = grid[r][c]
                    # Check row to right
                    for cc in range(c+1, m):
                        if state[r][cc] == 0 and grid[r][cc] == v:
                            return False
                    # Check col down
                    for rr in range(r+1, n):
                        if state[rr][c] == 0 and grid[rr][c] == v:
                            return False
        return True

    # Check connectivity: all white cells must be in one component of non-black cells
    def is_connected(state):
        whites = []
        non_black = set()
        for r in range(n):
            for c in range(m):
                if state[r][c] == 0:
                    whites.append((r, c))
                if state[r][c] != 1:
                    non_black.add((r, c))

        if not whites:
            return True

        # BFS from first white through non-black cells
        start = whites[0]
        visited = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in non_black and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        for cell in whites:
            if cell not in visited:
                return False
        return True

    # Select next cell: prefer forced cells (adjacent to black), then most constrained
    def select_cell(state):
        # First, find forced cells (adjacent to black -> must be white)
        for r in range(n):
            for c in range(m):
                if state[r][c] == -1:
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < n and 0 <= nc < m and state[nr][nc] == 1:
                            return (r, c, 0)  # Forced white

        # Find most constrained: high conflict count
        best_r, best_c = -1, -1
        max_conflicts = -1
        for r in range(n):
            for c in range(m):
                if state[r][c] == -1:
                    v = grid[r][c]
                    conflicts = 0
                    if v in row_val_pos[r]:
                        conflicts += len(row_val_pos[r][v]) - 1
                    if v in col_val_pos[c]:
                        conflicts += len(col_val_pos[c][v]) - 1
                    if conflicts > max_conflicts:
                        max_conflicts = conflicts
                        best_r, best_c = r, c
        if best_r == -1:
            return None
        return (best_r, best_c, None)

    # Recursive search with backtracking
    def search(state):
        # Check if complete
        complete = True
        for r in range(n):
            for c in range(m):
                if state[r][c] == -1:
                    complete = False
                    break
            if not complete:
                break

        if complete:
            if is_valid_state(state) and is_connected(state):
                return state
            return None

        if not is_valid_state(state) or not is_connected(state):
            return None

        sel = select_cell(state)
        if sel is None:
            return None
        r, c, forced = sel

        if forced is not None:
            new_state = propagate(state, r, c, forced)
            if new_state is not None:
                return search(new_state)
            return None
        else:
            # Try white first (0), then black (1)
            # Heuristic: cells with high conflict score are better white (eliminates many conflicts)
            for val in [0, 1]:
                new_state = propagate(state, r, c, val)
                if new_state is not None:
                    result = search(new_state)
                    if result is not None:
                        return result
            return None

    init_state = [[-1 for _ in range(m)] for _ in range(n)]
    result = search(init_state)

    if result is None:
        return "No Solution"

    # Convert to output format: 'B' for black, None for white
    output = []
    for r in range(n):
        row = []
        for c in range(m):
            if result[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        output.append(row)
    return output

