def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(region_map)

    # Build region structures
    regions = {}  # region_id -> set of (r, c)
    region_clue = {}  # region_id -> int or None
    cell_to_region = {}  # (r, c) -> region_id

    for r in range(n):
        for c in range(n):
            rid = region_map[r][c]
            cell_to_region[(r, c)] = rid
            if rid not in regions:
                regions[rid] = set()
            regions[rid].add((r, c))
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]

    num_regions = len(regions)

    # Solver state: 0=unknown, 1=black, 2=white
    grid = [[0] * n for _ in range(n)]

    # Precompute neighbors
    neighbors = {}
    for r in range(n):
        for c in range(n):
            neighs = []
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    neighs.append((nr, nc))
            neighbors[(r, c)] = neighs

    # Constraint propagation
    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule 1: Region constraints
            for rid, cells in regions.items():
                if rid not in region_clue:
                    continue
                target = region_clue[rid]
                black_count = sum(1 for (r, c) in cells if grid[r][c] == 1)
                white_count = sum(1 for (r, c) in cells if grid[r][c] == 2)
                unknown = [pos for pos in cells if grid[pos[0]][pos[1]] == 0]

                if black_count > target:
                    return False  # Overfilled
                if black_count == target:
                    # All unknown must be white
                    for (r, c) in unknown:
                        grid[r][c] = 2
                        changed = True
                elif black_count + len(unknown) == target:
                    # All unknown must be black
                    for (r, c) in unknown:
                        grid[r][c] = 1
                        changed = True

            # Rule 2: Black cells force neighbors white
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == 1:
                        for (nr, nc) in neighbors[(r, c)]:
                            if grid[nr][nc] == 1:
                                return False  # Adjacent black
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 2
                                changed = True

            # Rule 3: Line constraint propagation (immediate threats)
            # If U is between W1 and W2 in a line, and regions are all different, U must be black
            # Check rows
            for r in range(n):
                for c in range(1, n-1):
                    if grid[r][c] == 0:
                        left_reg = None
                        right_reg = None
                        # Look left for nearest non-unknown
                        for lc in range(c-1, -1, -1):
                            if grid[r][lc] == 1:
                                break
                            if grid[r][lc] == 2:
                                left_reg = cell_to_region[(r, lc)]
                                break
                        # Look right for nearest non-unknown
                        for rc in range(c+1, n):
                            if grid[r][rc] == 1:
                                break
                            if grid[r][rc] == 2:
                                right_reg = cell_to_region[(r, rc)]
                                break
                        if left_reg is not None and right_reg is not None:
                            cur_reg = cell_to_region[(r, c)]
                            if len({left_reg, cur_reg, right_reg}) == 3:
                                grid[r][c] = 1
                                changed = True

            # Check columns
            for c in range(n):
                for r in range(1, n-1):
                    if grid[r][c] == 0:
                        up_reg = None
                        down_reg = None
                        for ur in range(r-1, -1, -1):
                            if grid[ur][c] == 1:
                                break
                            if grid[ur][c] == 2:
                                up_reg = cell_to_region[(ur, c)]
                                break
                        for dr in range(r+1, n):
                            if grid[dr][c] == 1:
                                break
                            if grid[dr][c] == 2:
                                down_reg = cell_to_region[(dr, c)]
                                break
                        if up_reg is not None and down_reg is not None:
                            cur_reg = cell_to_region[(r, c)]
                            if len({up_reg, cur_reg, down_reg}) == 3:
                                grid[r][c] = 1
                                changed = True

        return True

    # Check line constraint validity for current state
    def check_line_constraint():
        # Check all row segments
        for r in range(n):
            c = 0
            while c < n:
                if grid[r][c] == 1:
                    c += 1
                    continue
                # Start of white/unknown segment
                seg_regs = set()
                start = c
                while c < n and grid[r][c] != 1:
                    if grid[r][c] == 2:
                        seg_regs.add(cell_to_region[(r, c)])
                    c += 1
                # If segment is all determined (no unknowns), check count
                all_determined = all(grid[r][i] != 0 for i in range(start, c))
                if all_determined and len(seg_regs) > 2:
                    return False
                # If segment contains white cells and unknowns, check if it's possible to satisfy
                # This is partial check
        return True

    # Check connectivity of white cells
    def check_connectivity():
        white_cells = set()
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 2:
                    white_cells.add((r, c))

        if not white_cells:
            return True

        # BFS from one white cell
        start = next(iter(white_cells))
        queue = [start]
        visited = {start}
        frontier = 0
        while frontier < len(queue):
            r, c = queue[frontier]
            frontier += 1
            for (nr, nc) in neighbors[(r, c)]:
                if grid[nr][nc] == 2 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        if len(visited) != len(white_cells):
            return False

        # Check that unknowns can potentially connect everything
        # Find all unknowns adjacent to white
        return True

    # Full validity check
    def is_valid():
        # Check regions
        for rid, cells in regions.items():
            if rid in region_clue:
                target = region_clue[rid]
                black_count = sum(1 for (r, c) in cells if grid[r][c] == 1)
                if black_count > target:
                    return False

        # Check adjacency
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 1:
                    for (nr, nc) in neighbors[(r, c)]:
                        if grid[nr][nc] == 1:
                            return False

        # Check line constraint
        if not check_line_constraint():
            return False

        # Check connectivity
        if not check_connectivity():
            return False

        return True

    def is_complete():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    def copy_grid():
        return [row[:] for row in grid]

    def restore_grid(g):
        for r in range(n):
            for c in range(n):
                grid[r][c] = g[r][c]

    # MRV heuristic: find cell in most constrained region or with fewest options
    def select_cell():
        min_options = 10
        best_cell = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    # Check if region is constrained
                    rid = cell_to_region[(r, c)]
                    if rid in region_clue:
                        target = region_clue[rid]
                        cells = regions[rid]
                        black_count = sum(1 for (cr, cc) in cells if grid[cr][cc] == 1)
                        unknown_count = sum(1 for (cr, cc) in cells if grid[cr][cc] == 0)
                        if black_count == target:
                            continue  # will be set to white by propagation
                        if unknown_count == 1:
                            return (r, c, [1])  # must be black
                        if black_count + unknown_count == target:
                            return (r, c, [1])  # must be black
                    # Prefer cells with black neighbor (forced white propagation)
                    has_black_neighbor = any(grid[nr][nc] == 1 for (nr, nc) in neighbors[(r, c)])
                    score = unknown_count - (2 if has_black_neighbor else 0)
                    if score < min_options:
                        min_options = score
                        best_cell = (r, c)
        if best_cell:
            return (best_cell[0], best_cell[1], [1, 2])  # Try black first, then white
        return None

    # Initial propagation
    if not propagate():
        return None

    def search():
        if not is_valid():
            return None

        if is_complete():
            # Return solution
            result = []
            for r in range(n):
                row = []
                for c in range(n):
                    if grid[r][c] == 1:
                        row.append('B')
                    else:
                        row.append(None)
                result.append(row)
            return result

        cell_info = select_cell()
        if cell_info is None:
            return None

        r, c, values = cell_info

        for val in values:
            saved = copy_grid()
            grid[r][c] = val

            if propagate():
                result = search()
                if result is not None:
                    return result

            restore_grid(saved)

        return None

    return search()

