def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(data)

    # Initialize grid and tracking sets
    grid = [[0 for _ in range(n)] for _ in range(n)]
    rows = [set() for _ in range(n)]
    cols = [set() for _ in range(n)]
    regions = [set() for _ in range(n)]

    # Fill in givens
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is not None:
                grid[r][c] = val
                rows[r].add(val)
                cols[c].add(val)
                rid = region_map[r][c]
                regions[rid].add(val)

    # Initialize candidates for empty cells
    candidates = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                rid = region_map[r][c]
                cand = set(range(1, n+1)) - rows[r] - cols[c] - regions[rid]
                if not cand:
                    return "No Solution"
                candidates[r][c] = cand

    # Precompute cell lists for each unit
    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]
    region_cells = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rid = region_map[r][c]
            region_cells[rid].append((r, c))

    all_units = row_cells + col_cells + region_cells

    def propagate():
        """Constraint propagation using naked and hidden singles"""
        changed = True
        while changed:
            changed = False

            # Naked singles
            for r in range(n):
                for c in range(n):
                    if grid[r][c] != 0:
                        continue
                    if len(candidates[r][c]) == 0:
                        return False
                    if len(candidates[r][c]) == 1:
                        val = next(iter(candidates[r][c]))
                        # Assign value
                        grid[r][c] = val
                        rows[r].add(val)
                        cols[c].add(val)
                        rid = region_map[r][c]
                        regions[rid].add(val)
                        candidates[r][c] = set()

                        # Propagate to peers
                        for nr, nc in row_cells[r]:
                            if grid[nr][nc] == 0 and val in candidates[nr][nc]:
                                candidates[nr][nc].remove(val)
                                if len(candidates[nr][nc]) == 0:
                                    return False
                                changed = True
                        for nr, nc in col_cells[c]:
                            if grid[nr][nc] == 0 and val in candidates[nr][nc]:
                                candidates[nr][nc].remove(val)
                                if len(candidates[nr][nc]) == 0:
                                    return False
                                changed = True
                        for nr, nc in region_cells[rid]:
                            if grid[nr][nc] == 0 and val in candidates[nr][nc]:
                                candidates[nr][nc].remove(val)
                                if len(candidates[nr][nc]) == 0:
                                    return False
                                changed = True

            # Hidden singles
            for unit in all_units:
                # Find which values are already placed
                used = set()
                pos_map = {}  # value -> list of cells
                for r, c in unit:
                    if grid[r][c] != 0:
                        used.add(grid[r][c])
                    else:
                        for val in candidates[r][c]:
                            if val not in pos_map:
                                pos_map[val] = []
                            pos_map[val].append((r, c))

                # Check each missing value
                for val in range(1, n+1):
                    if val in used:
                        continue
                    if val not in pos_map or len(pos_map[val]) == 0:
                        return False
                    if len(pos_map[val]) == 1:
                        r, c = pos_map[val][0]
                        # Assign hidden single
                        grid[r][c] = val
                        rows[r].add(val)
                        cols[c].add(val)
                        rid = region_map[r][c]
                        regions[rid].add(val)
                        candidates[r][c] = set()

                        # Remove from all peers
                        for nr, nc in row_cells[r]:
                            if grid[nr][nc] == 0 and val in candidates[nr][nc]:
                                candidates[nr][nc].remove(val)
                                if len(candidates[nr][nc]) == 0:
                                    return False
                                changed = True
                        for nr, nc in col_cells[c]:
                            if grid[nr][nc] == 0 and val in candidates[nr][nc]:
                                candidates[nr][nc].remove(val)
                                if len(candidates[nr][nc]) == 0:
                                    return False
                                changed = True
                        for nr, nc in region_cells[rid]:
                            if grid[nr][nc] == 0 and val in candidates[nr][nc]:
                                candidates[nr][nc].remove(val)
                                if len(candidates[nr][nc]) == 0:
                                    return False
                                changed = True
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Check if solved
    def is_solved():
        return all(grid[r][c] != 0 for r in range(n) for c in range(n))

    if is_solved():
        return grid

    # Backtracking with MRV heuristic
    def solve_recursive():
        # Find cell with minimum candidates (MRV)
        min_options = n + 1
        target_cell = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    cnt = len(candidates[r][c])
                    if cnt < min_options:
                        min_options = cnt
                        target_cell = (r, c)
                        if cnt == 1:
                            break
            if target_cell and min_options == 1:
                break

        if target_cell is None:
            return True

        r, c = target_cell
        vals = list(candidates[r][c])
        rid = region_map[r][c]

        for val in vals:
            # Save state
            old_grid = grid[r][c]
            old_row = rows[r].copy()
            old_col = cols[c].copy()
            old_reg = regions[rid].copy()

            # Save candidate snapshots for affected cells
            affected = []
            peers = set(row_cells[r] + col_cells[c] + region_cells[rid])
            for pr, pc in peers:
                if grid[pr][pc] == 0:
                    affected.append(((pr, pc), candidates[pr][pc].copy()))

            # Assign
            grid[r][c] = val
            rows[r].add(val)
            cols[c].add(val)
            regions[rid].add(val)
            candidates[r][c] = set()

            # Update peers
            valid = True
            for pr, pc in row_cells[r]:
                if grid[pr][pc] == 0:
                    if val in candidates[pr][pc]:
                        candidates[pr][pc].remove(val)
                        if len(candidates[pr][pc]) == 0:
                            valid = False
            for pr, pc in col_cells[c]:
                if grid[pr][pc] == 0:
                    if val in candidates[pr][pc]:
                        candidates[pr][pc].remove(val)
                        if len(candidates[pr][pc]) == 0:
                            valid = False
            for pr, pc in region_cells[rid]:
                if grid[pr][pc] == 0:
                    if val in candidates[pr][pc]:
                        candidates[pr][pc].remove(val)
                        if len(candidates[pr][pc]) == 0:
                            valid = False

            if valid and propagate():
                if solve_recursive():
                    return True

            # Restore state
            grid[r][c] = old_grid
            rows[r] = old_row
            cols[c] = old_col
            regions[rid] = old_reg
            for (pr, pc), cands in affected:
                candidates[pr][pc] = cands

        return False

    if solve_recursive():
        return grid
    else:
        return "No Solution"

