def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(region_map)
    m = len(region_map[0]) if n > 0 else 0

    # Build region data structures
    region_cells = {}
    region_clue = {}
    for i in range(n):
        for j in range(m):
            rid = region_map[i][j]
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append((i, j))
            if data[i][j] is not None:
                if rid in region_clue and region_clue[rid] != data[i][j]:
                    # Contradiction: two different clues in same region
                    pass
                region_clue[rid] = data[i][j]

    region_ids = list(region_cells.keys())
    num_regions = len(region_ids)

    # State: -1 = unknown, 0 = white, 1 = black
    grid = [[-1 for _ in range(m)] for _ in range(n)]

    # Precompute adjacencies
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        res = []
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                res.append((nr, nc))
        return res

    # Helper to count blacks and unknowns in region
    def region_stats(rid):
        cells = region_cells[rid]
        black = 0
        white = 0
        unknown = 0
        unknown_cells = []
        for (r, c) in cells:
            if grid[r][c] == 1:
                black += 1
            elif grid[r][c] == 0:
                white += 1
            else:
                unknown += 1
                unknown_cells.append((r, c))
        return black, white, unknown, unknown_cells

    # Check if current state is valid
    def is_valid():
        # Check 1: Region counts
        for rid in region_ids:
            clue = region_clue.get(rid)
            if clue is not None:
                black, white, unknown, _ = region_stats(rid)
                if black > clue:
                    return False
                if black + unknown < clue:
                    return False

        # Check 2: Black cells not adjacent
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] == 1:
                            return False

        # Check 3: Line constraint - white segments span at most 2 regions
        # Check rows
        for r in range(n):
            c = 0
            while c < m:
                if grid[r][c] == 1:  # black
                    c += 1
                    continue
                # Start of white segment
                seg_start = c
                regions_in_seg = set()
                while c < m and grid[r][c] != 1:
                    if grid[r][c] == 0:
                        regions_in_seg.add(region_map[r][c])
                    c += 1
                # If there are unknowns, we can't fully check yet
                # But if all are determined and > 2 regions, invalid
                # Actually, check the determined part
                if len(regions_in_seg) > 2:
                    # Check if the segment could be split by unknowns becoming black
                    # If the segment is continuous white/unknown, and determined whites span >2 regions, invalid
                    pass
        # More strict: for each maximal segment of (white or unknown), if all white, check regions
        # Actually, implement for fully determined segments
        for r in range(n):
            seg_regions = set()
            seg_has_unknown = False
            for c in range(m):
                if grid[r][c] == 1:
                    if len(seg_regions) > 2 and not seg_has_unknown:
                        return False
                    seg_regions = set()
                    seg_has_unknown = False
                else:
                    if grid[r][c] == -1:
                        seg_has_unknown = True
                    else:
                        seg_regions.add(region_map[r][c])
            if len(seg_regions) > 2 and not seg_has_unknown:
                return False

        # Check cols
        for c in range(m):
            seg_regions = set()
            seg_has_unknown = False
            for r in range(n):
                if grid[r][c] == 1:
                    if len(seg_regions) > 2 and not seg_has_unknown:
                        return False
                    seg_regions = set()
                    seg_has_unknown = False
                else:
                    if grid[r][c] == -1:
                        seg_has_unknown = True
                    else:
                        seg_regions.add(region_map[r][c])
            if len(seg_regions) > 2 and not seg_has_unknown:
                return False

        return True

    def is_complete():
        for r in range(n):
            for c in range(m):
                if grid[r][c] == -1:
                    return False
        return True

    def check_connectivity():
        # BFS from first white cell
        start = None
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 0:
                    start = (r, c)
                    break
            if start:
                break
        if not start:
            return False  # No white cells

        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        # Check all white cells are visited
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 0 and (r, c) not in visited:
                    return False
        return True

    def check_line_constraint_strict():
        # Check all white cells form segments spanning <= 2 regions
        for r in range(n):
            c = 0
            while c < m:
                # Skip black
                while c < m and grid[r][c] == 1:
                    c += 1
                if c >= m:
                    break
                # White segment
                seg_start = c
                regions = set()
                while c < m and grid[r][c] != 1:
                    if grid[r][c] == -1:
                        return True  # Unknown, can't check fully
                    regions.add(region_map[r][c])
                    c += 1
                if len(regions) > 2:
                    return False

        for c in range(m):
            r = 0
            while r < n:
                while r < n and grid[r][c] == 1:
                    r += 1
                if r >= n:
                    break
                regions = set()
                while r < n and grid[r][c] != 1:
                    if grid[r][c] == -1:
                        return True
                    regions.add(region_map[r][c])
                    r += 1
                if len(regions) > 2:
                    return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            # Rule: Region counting
            for rid in region_ids:
                clue = region_clue.get(rid)
                if clue is None:
                    continue
                black, white, unknown, unknown_cells = region_stats(rid)
                if black == clue and unknown > 0:
                    # All unknown must be white
                    for (r, c) in unknown_cells:
                        grid[r][c] = 0
                        changed = True
                elif black + unknown == clue:
                    # All unknown must be black
                    for (r, c) in unknown_cells:
                        grid[r][c] = 1
                        changed = True

            if not is_valid():
                return False

            # Rule: Black adjacency - neighbors of black are white
            for r in range(n):
                for c in range(m):
                    if grid[r][c] == 1:
                        for nr, nc in get_neighbors(r, c):
                            if grid[nr][nc] == -1:
                                grid[nr][nc] = 0
                                changed = True
                            elif grid[nr][nc] == 1:
                                return False

            if not is_valid():
                return False

            # Rule: Line constraint forcing
            # If a white cell has neighbors in 2 different regions in a line,
            # and extending further would hit a third, the next must be black or edge
            # This is complex; skip for propagation, check in validation

        return True

    def solve_recursive():
        if not is_valid():
            return False

        if not check_line_constraint_strict():
            return False

        # Check completeness
        if is_complete():
            return check_connectivity() and check_line_constraint_strict()

        # Find best cell to branch on
        # Heuristic: cell in region with clue, or high degree
        best_cell = None
        best_score = -1

        for r in range(n):
            for c in range(m):
                if grid[r][c] == -1:
                    rid = region_map[r][c]
                    clue = region_clue.get(rid)
                    score = 0
                    if clue is not None:
                        black, _, _, _ = region_stats(rid)
                        score = 10 - abs(clue - black)  # Prefer regions close to filled
                    if score > best_score:
                        best_score = score
                        best_cell = (r, c)

        if not best_cell:
            return check_connectivity() and check_line_constraint_strict()

        r, c = best_cell

        # Try black first (usually more constrained)
        for val in [1, 0]:
            grid[r][c] = val

            # Save state
            snapshot = [row[:] for row in grid]

            if propagate():
                if solve_recursive():
                    return True

            # Restore
            for i in range(n):
                for j in range(m):
                    grid[i][j] = snapshot[i][j]

        grid[r][c] = -1
        return False

    # Initial propagation
    if not propagate():
        return "No Solution"

    if solve_recursive():
        # Format output
        result = [[None for _ in range(m)] for _ in range(n)]
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    result[r][c] = 'B'
                else:
                    result[r][c] = None
        return result
    else:
        return "No Solution"

