def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(region_map)
    m = len(region_map[0]) if n > 0 else 0

    # Build region info
    num_regions = max(max(row) for row in region_map) + 1
    region_cells = [[] for _ in range(num_regions)]
    region_clue = [None] * num_regions

    for r in range(n):
        for c in range(m):
            rid = region_map[r][c]
            region_cells[rid].append((r, c))
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]

    # State: 0=unknown, 1=black, 2=white
    # Use list of lists, mutable
    # For backtracking, use tuple of tuples or deepcopy

    def get_region_stats(state):
        # Returns list of (total, clue, black_count, white_count, unknown_cells)
        stats = []
        for rid in range(num_regions):
            cells = region_cells[rid]
            total = len(cells)
            clue = region_clue[rid]
            black = 0
            white = 0
            unknowns = []
            for (r, c) in cells:
                v = state[r][c]
                if v == 1:
                    black += 1
                elif v == 2:
                    white += 1
                else:
                    unknowns.append((r, c))
            stats.append((total, clue, black, white, unknowns))
        return stats

    def check_no_adjacent_black(state):
        for r in range(n):
            for c in range(m):
                if state[r][c] == 1:
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and state[nr][nc] == 1:
                            return False
        return True

    def check_white_segments(state):
        # Rule 3: any straight white segment passes through at most 2 regions
        # Check rows
        for r in range(n):
            c = 0
            while c < m:
                # Skip non-white
                while c < m and state[r][c] != 2:
                    c += 1
                if c >= m:
                    break
                # Start of white segment
                regions_in_seg = set()
                while c < m and state[r][c] == 2:
                    regions_in_seg.add(region_map[r][c])
                    c += 1
                if len(regions_in_seg) > 2:
                    return False

        # Check columns
        for c in range(m):
            r = 0
            while r < n:
                while r < n and state[r][c] != 2:
                    r += 1
                if r >= n:
                    break
                regions_in_seg = set()
                while r < n and state[r][c] == 2:
                    regions_in_seg.add(region_map[r][c])
                    r += 1
                if len(regions_in_seg) > 2:
                    return False
        return True

    def check_white_connectivity(state):
        # Rule 4: all white cells orthogonally connected
        white_cells = set()
        for r in range(n):
            for c in range(m):
                if state[r][c] == 2:
                    white_cells.add((r, c))

        if not white_cells:
            return True

        # BFS from one white cell
        start = next(iter(white_cells))
        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in white_cells and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(white_cells)

    def is_complete(state):
        for r in range(n):
            for c in range(m):
                if state[r][c] == 0:
                    return False
        return True

    def propagate(state):
        # Constraint propagation
        # Returns (new_state, is_valid, changed)
        # Make a copy to avoid modifying input
        new_state = [row[:] for row in state]
        changed = True

        while changed:
            changed = False
            stats = get_region_stats(new_state)

            # Rule 1: Region black cell count
            for rid, (total, clue, black, white, unknowns) in enumerate(stats):
                if clue is not None:
                    if black > clue:
                        return new_state, False, False
                    if black + len(unknowns) < clue:
                        return new_state, False, False
                    if black == clue and unknowns:
                        # All unknowns become white
                        for (r, c) in unknowns:
                            new_state[r][c] = 2
                            changed = True
                    elif black + len(unknowns) == clue:
                        # All unknowns become black
                        for (r, c) in unknowns:
                            new_state[r][c] = 1
                            changed = True

            # Rule 2: No adjacent black cells
            for r in range(n):
                for c in range(m):
                    if new_state[r][c] == 1:
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < m:
                                if new_state[nr][nc] == 1:
                                    return new_state, False, False
                                elif new_state[nr][nc] == 0:
                                    # Neighbor of black must be white
                                    new_state[nr][nc] = 2
                                    changed = True

            # Check segment rule
            if not check_white_segments(new_state):
                return new_state, False, False

        return new_state, True, True

    def solve_recursive(state):
        # Propagate
        state, valid, _ = propagate(state)
        if not valid:
            return None

        if is_complete(state):
            if check_white_connectivity(state):
                return state
            return None

        # Find unknown cell with most constraints (heuristic: region with fewest unknowns)
        stats = get_region_stats(state)
        best_cell = None
        best_score = float('inf')

        for rid, (total, clue, black, white, unknowns) in enumerate(stats):
            if clue is None:
                continue
            remaining = clue - black
            if remaining < 0 or remaining > len(unknowns):
                return None
            if unknowns:
                # Prefer regions with fewer choices
                score = len(unknowns)
                if score < best_score:
                    best_score = score
                    best_cell = unknowns[0]

        if best_cell is None:
            # Pick any unknown
            for r in range(n):
                for c in range(m):
                    if state[r][c] == 0:
                        best_cell = (r, c)
                        break
                if best_cell:
                    break

        if best_cell is None:
            return None

        r, c = best_cell

        # Try black first (usually more constrained)
        for val in [1, 2]:
            new_state = [row[:] for row in state]
            new_state[r][c] = val
            result = solve_recursive(new_state)
            if result is not None:
                return result

        return None

    # Initial state
    initial_state = [[0]*m for _ in range(n)]

    # Pre-fill known constraints (clue 0 means all white)
    for rid, clue in enumerate(region_clue):
        if clue == 0:
            for (r, c) in region_cells[rid]:
                initial_state[r][c] = 2

    result = solve_recursive(initial_state)

    if result is None:
        return "No Solution"

    # Convert to output format: 'B' for black, None for white
    output = []
    for r in range(n):
        row = []
        for c in range(m):
            if result[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        output.append(row)

    return output

