def opposite(color):
    return 'W' if color == 'B' else 'B'

def parse_key(key):
    # Parse '(r,c)' into floats
    key = key.strip('()')
    parts = key.split(',')
    return float(parts[0]), float(parts[1])

def propagate(grid, h_cons, v_cons, n):
    """Apply constraint propagation. Return False if contradiction found."""
    changed = True
    target = n // 2

    # Pre-parse constraints for efficiency
    h_parsed = []
    for key, val in h_cons.items():
        r, c = parse_key(key)
        c_left = int(c - 0.5)
        h_parsed.append((int(r), c_left, c_left + 1, val))

    v_parsed = []
    for key, val in v_cons.items():
        r, c = parse_key(key)
        r_top = int(r - 0.5)
        v_parsed.append((r_top, int(c), r_top + 1, val))

    while changed:
        changed = False

        # Check row counts
        for r in range(n):
            row = grid[r]
            b_count = sum(1 for x in row if x == 'B')
            w_count = sum(1 for x in row if x == 'W')

            if b_count > target or w_count > target:
                return False

            if b_count == target:
                for c in range(n):
                    if row[c] is None:
                        grid[r][c] = 'W'
                        changed = True
            elif w_count == target:
                for c in range(n):
                    if row[c] is None:
                        grid[r][c] = 'B'
                        changed = True

        # Check column counts
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            b_count = sum(1 for x in col if x == 'B')
            w_count = sum(1 for x in col if x == 'W')

            if b_count > target or w_count > target:
                return False

            if b_count == target:
                for r in range(n):
                    if grid[r][c] is None:
