                    grid[r][c+1] = 'W'
                    changed = True
                elif v1 == v3 == 'W' and v2 is None:
                    grid[r][c+1] = 'B'
                    changed = True

        # Check no-three consecutive in columns
        for c in range(n):
            for r in range(n - 2):
                v1, v2, v3 = grid[r][c], grid[r+1][c], grid[r+2][c]
                if v1 == v2 == 'B' and v3 is None:
                    grid[r+2][c] = 'W'
