                elif v1 == v2 == 'W' and v3 is None:
                    grid[r+2][c] = 'W'
                    changed = True
                elif v2 == v3 == 'B' and v1 is None:
                    grid[r][c] = 'W'
                    changed = True
                elif v2 == v3 == 'W' and v1 is None:
                    grid[r][c] = 'W'
                    changed = True
                elif v1 == v3 == 'B' and v2 is None:
                    grid[r+1][c] = 'W'
                    changed = True
                elif v1 == v3 == 'W' and v2 is None:
                    grid[r+1][c] = 'B'
                    changed = True

        # Apply horizontal constraints
        for r, c1, c2, cons in h_parsed:
            v1, v2 = grid[r][c1], grid[r][c2]
            if v1 is not None and v2 is None:
                if cons == '=':
                    grid[r][c2] = v1
                else:
                    grid[r][c2] = opposite(v1)
                changed = True
            elif v2 is not None and v1 is None:
                if cons == '=':
                    grid[r][c1] = v2
                else:
                    grid[r][c1] = opposite(v2)
                changed = True
            elif v1 is not None and v2 is not None:
                if cons == '=' and v1 != v2:
                    return False
                if cons == 'x' and v1 == v2:
                    return False

        # Apply vertical constraints
        for r1, c, r2, cons in v_parsed:
