                if cons == '=':
                    grid[r1][c] = v2
                else:
                    grid[r1][c] = opposite(v2)
                changed = True
            elif v1 is not None and v2 is not None:
                if cons == '=' and v1 != v2:
                    return False
                if cons == 'x' and v1 == v2:
                    return False

    return True

def is_complete(grid):
    return all(cell is not None for row in grid for cell in row)

def get_empty_cell(grid):
    # Find cell with fewest possibilities (MRV heuristic)
    # For binary puzzles, all empty cells have 2 possibilities theoretically
    # But we can check constraints to find forced cells
    n = len(grid)
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                return r, c
    return None

def copy_grid(grid):
    return [row[:] for row in grid]

def solve_recursive(grid, h_cons, v_cons, n):
    if not propagate(grid, h_cons, v_cons, n):
        return None

    if is_complete(grid):
        return grid

    cell = get_empty_cell(grid)
    if cell is None:
        return grid

    r, c = cell

    for val in ['B', 'W']:
        new_grid = copy_grid(grid)
        new_grid[r][c] = val
        result = solve_recursive(new_grid, h_cons, v_cons, n)
        if result is not None:
            return result

    return None

def solve(observation):
    data = observation['data']
    n = len(data)

    # Initialize grid
    grid = [row[:] for row in data]
    h_cons = observation.get('horizontal', {})
    v_cons = observation.get('vertical', {})

    result = solve_recursive(grid, h_cons, v_cons, n)

    if result is None:
        return "No Solution"
    else:
        return result

