            # Col peers
            for r2 in range(n):
                if r2 != r:
                    peer_set.add((r2, c))
            # Region peers
            rid = region_map[r][c]
            for (r2, c2) in region_cells[rid]:
                if (r2, c2) != (r, c):
                    peer_set.add((r2, c2))
            peers[(r, c)] = peer_set

    # Initialize grid and domains
    grid = [[0]*n for _ in range(n)]
    domains = [[set() for _ in range(n)] for _ in range(n)]

    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]
                domains[r][c] = {data[r][c]}
            else:
                domains[r][c] = set(ALL_VALS)

    def propagate(gr, dom):
        """Constraint propagation. Modifies gr and dom in place. Returns False if contradiction."""
        changed = True
        while changed:
            changed = False
            # Naked singles
            for r in range(n):
                for c in range(n):
                    if gr[r][c] == 0 and len(dom[r][c]) == 1:
                        val = next(iter(dom[r][c]))
                        gr[r][c] = val
                        changed = True
                        for (pr, pc) in peers[(r, c)]:
                            if gr[pr][pc] == 0:
                                if val in dom[pr][pc]:
                                    dom[pr][pc].remove(val)
                                    if len(dom[pr][pc]) == 0:
                                        return False
            # Hidden singles in rows, cols, regions
            units = []
            for r in range(n):
                units.append([(r, c) for c in range(n)])
            for c in range(n):
                units.append([(r, c) for r in range(n)])
            units.extend(region_cells)

            for unit in units:
                for val in range(1, n+1):
                    possible = []
                    for (r, c) in unit:
                        if gr[r][c] == val:
                            possible = None
                            break
                        if gr[r][c] == 0 and val in dom[r][c]:
                            possible.append((r, c))
                    if possible is None:
                        continue
                    if len(possible) == 0:
                        return False
                    if len(possible) == 1:
