    def is_solved(gr):
        for r in range(n):
            for c in range(n):
                if gr[r][c] == 0:
                    return False
        return True

    if is_solved(grid):
        return grid

    def select_cell(gr, dom):
        """MRV heuristic"""
        min_opts = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                if gr[r][c] == 0:
                    cnt = len(dom[r][c])
                    if cnt < min_opts:
                        min_opts = cnt
                        best = (r, c)
                        if cnt == 1:
                            return best
        return best

    def backtrack(gr, dom):
        if is_solved(gr):
            return gr

        cell = select_cell(gr, dom)
        if cell is None:
            return gr if is_solved(gr) else None
        r, c = cell

        vals = list(dom[r][c])
        for val in vals:
            # Deep copy
            new_gr = [row[:] for row in gr]
            new_dom = [[set(s) for s in row] for row in dom]

            # Assign
            new_gr[r][c] = val
            new_dom[r][c] = {val}

            # Remove from peers
            valid = True
            for (pr, pc) in peers[(r, c)]:
                if new_gr[pr][pc] == 0 and val in new_dom[pr][pc]:
                    new_dom[pr][pc].remove(val)
                    if len(new_dom[pr][pc]) == 0:
                        valid = False
                        break

            if valid and propagate(new_gr, new_dom):
                result = backtrack(new_gr, new_dom)
                if result is not None:
                    return result
        return None

    result = backtrack(grid, domains)
    return result if result is not None else "No Solution"

