OBSERVATION = {'region': [[0, 1, 1, 1, 2, 2, 3], [0, 4, 1, 1, 2, 2, 3], [0, 4, 4, 1, 2, 5, 3], [0, 4, 6, 6, 2, 5, 3], [0, 4, 6, 6, 5, 5, 3], [0, 6, 6, 5, 5, 5, 3], [0, 6, 6, 6, 6, 3, 3]], 'data': [[3, None, None, None, None, 5, None], [5, 6, None, None, None, None, None], [4, None, None, 7, None, None, None], [None, None, None, None, None, None, None], [None, None, None, 4, None, None, 2], [None, None, None, None, None, 7, 5], [None, 5, None, None, None, None, 6]]}

def solve(observation):
    region_map = observation['region']
    data = observation['data']
    n = len(data)

    # Build region to cells mapping
    region_to_cells = {}
    cell_to_region = {}
    for r in range(n):
        for c in range(n):
            reg = region_map[r][c]
            if reg not in region_to_cells:
                region_to_cells[reg] = []
            region_to_cells[reg].append((r, c))
            cell_to_region[(r, c)] = reg

    # Initialize domains
    # domains[r][c] = set of possible values
    domains = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    # Apply givens
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                val = data[r][c]
                if not assign(domains, r, c, val, n, region_to_cells, cell_to_region):
                    return "No Solution"

    # Solve using backtracking with constraint propagation
    solution = [row[:] for row in data]

    def get_neighbors(r, c):
        """Get all cells in same row, column, or region"""
        neighbors = set()
        # Same row
        for cc in range(n):
            if cc != c:
                neighbors.add((r, cc))
        # Same column
        for rr in range(n):
            if rr != r:
                neighbors.add((rr, c))
        # Same region
        reg = cell_to_region[(r, c)]
        for rr, cc in region_to_cells[reg]:
            if (rr, cc) != (r, c):
                neighbors.add((rr, cc))
        return neighbors

    def propagate(domains, queue):
        """AC-3 like propagation"""
        while queue:
            r, c = queue.pop()
            if not domains[r][c]:  # Empty domain
                return False

            # If domain is singleton, remove this value from neighbors
            if len(domains[r][c]) == 1:
                val = next(iter(domains[r][c]))
                for nr, nc in get_neighbors(r, c):
                    if val in domains[nr][nc]:
                        domains[nr][nc].remove(val)
                        queue.add((nr, nc))

            # Check for hidden singles in row, col, region
            # Row
            for val in list(domains[r][c]):
                count = sum(1 for cc in range(n) if val in domains[r][cc])
                if count == 0:
                    return False
                if count == 1 and val not in domains[r][c]:
                    return False  # Should not happen
                if count == 1 and val in domains[r][c] and len(domains[r][c]) > 1:
                    if not assign_to_cell(domains, r, c, val, queue):
                        return False
                    break

            # Col
            for val in list(domains[r][c]):
                count = sum(1 for rr in range(n) if val in domains[rr][c])
                if count == 0:
                    return False
                if count == 1 and val in domains[r][c] and len(domains[r][c]) > 1:
                    if not assign_to_cell(domains, r, c, val, queue):
                        return False
                    break

            # Region
            reg = cell_to_region[(r, c)]
            for val in list(domains[r][c]):
                count = sum(1 for rr, cc in region_to_cells[reg] if val in domains[rr][cc])
                if count == 0:
                    return False
                if count == 1 and val in domains[r][c] and len(domains[r][c]) > 1:
                    if not assign_to_cell(domains, r, c, val, queue):
                        return False
                    break

        return True

    def assign_to_cell(domains, r, c, val, queue):
        """Assign value to cell and add to queue for propagation"""
        domains[r][c] = {val}
        queue.add((r, c))
        return True

    def assign(domains, r, c, val, n, region_to_cells, cell_to_region):
        """Assign value and propagate"""
        if val not in domains[r][c]:
            return False
        domains[r][c] = {val}
        queue = {(r, c)}
        return propagate(domains, queue)

    def copy_domains(domains):
        return [[set(domains[r][c]) for c in range(n)] for r in range(n)]

    def solve_recursive(domains, solution):
        # Find cell with minimum remaining values (MRV)
        min_options = n + 1
        best_cell = None
        for r in range(n):
            for c in range(n):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_options:
                        min_options = len(domains[r][c])
                        best_cell = (r, c)
                    if min_options == 2:
                        break
            if min_options == 2:
                break

        if best_cell is None:
            # All cells assigned, check consistency
            for r in range(n):
                for c in range(n):
                    if len(domains[r][c]) != 1:
                        return False
                    solution[r][c] = next(iter(domains[r][c]))
            return True

        r, c = best_cell
        values = sorted(domains[r][c])  # Try values in order

        for val in values:
            new_domains = copy_domains(domains)
            if assign(new_domains, r, c, val, n, region_to_cells, cell_to_region):
                if solve_recursive(new_domains, solution):
                    return True
        return False

    # Make initial copy for solving
    initial_domains = copy_domains(domains)
    if not solve_recursive(initial_domains, solution):
        return "No Solution"

    return solution

